INSERT INTO `Questions` VALUES (1,1,0,1,'Dať prednosť v jazde sa rozumie','',2,1,'povinnosť účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde, nemusel náhle zmeniť smer alebo rýchlosť jazdy,','povinnosť účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde, nemusel zmeniť smer jazdy, môže však zmeniť rýchlosť jazdy,','povinnosť účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde, nemusel zmeniť rýchlosť jazdy, môže však zmeniť smer jazdy.');
