INSERT INTO `Questions` VALUES (4,4,0,1,'Ak jazdné pruhy nie sú na vozovke vyznačené, jazdným pruhom sa rozumie časť vozovky dovoľujúca jazdu vozidiel','',2,1,'s troma a viacerými kolesami v jazdnom prúde za sebou','najmenej s dvoma kolesami v jazdnom prúde za sebou','len s dvoma kolesami v jazdnom prúde za sebou');
INSERT INTO `Questions` VALUES (5,5,0,1,'Vodič predchádzaného vozidla nesmie','',2,2,'okrem zvyšovania rýchlosti jazdy nijako brániť predchádzaniu','zvyšovať rýchlosť jazdy ani inak brániť predchádzaniu','znižovať rýchlosť jazdy');
INSERT INTO `Questions` VALUES (6,6,0,1,'Vodič smie jazdiť len primeranou rýchlosťou, aby bol schopný zastaviť vozidlo na vzdialenosť','',2,3,'20 m, na diaľnici a na rýchlostnej ceste 50 m','30 m','na ktorú ma rozhľad');
