INSERT INTO `Questions` VALUES (9,9,0,1,'Účastník dopravnej nehody','',2,3,'nesmie urobiť žiadne opatrenia na záchranu osoby, ak by to bolo na ujmu vyšetrenia dopravnej nehody','je povinný umožniť obnovenie cestnej premávky len vtedy, ak dopravnú nehodu zavininl','je povinný urobiť potrebné opatrenia na záchranu osoby alebo majetku ohrozeného dopravnou nehodou');
