INSERT INTO `Questions` VALUES (28,28,0,1,'Chodníkom sa rozumie:','',2,3,'len komunikácia alebo časť cesty označená príslušnou dopravnou značkou (č. C 8) .','pravá krajnica, kde krajnica nie je, rozumie sa chodníkom pravý okraj vozovky široký jeden meter.','komunikácia alebo časť cesty určená pre chodcov, ktorá je spravidla oddelená od vozovky výškovo alebo iným spôsobom.');
INSERT INTO `Questions` VALUES (29,29,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza, vodič motorového vozidla kategórie M1 a N1 môže takéto vozidlo použiť v cestnej premávke, len ak:','',2,1,'je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené na hnacej náprave zimnými pneumatikami,','má uzatvorené havarijné poistenie.');
INSERT INTO `Questions` VALUES (30,30,0,1,'Vodič je povinný pri obchádzaní stojaceho vozidla pravidelnej verejnej dopravy osôb prihliadnuť na možnosť vbehnutia osôb na vozovku a:','',2,3,'za týmto účelom jazdiť vždy rýchlosťou najviac 15 km/h,','za týmto účelom vždy zastaviť vozidlo,','jazdu prispôsobiť tak, aby neboli ohrozené.');
INSERT INTO `Questions` VALUES (31,31,0,1,'Vodič nesmie predchádzať, ak vodič pred ním idúceho vozidla dáva znamenie o zmene smeru jazdy:','',2,3,'vpravo,','vľavo a to za žiadnych okolností,','vľavo a ak ho nemožno predísť vpravo, prípadne ak ho nemožno predísť v ďalšom voľnom jazdnom pruhu v tom istom smere jazdy vyznačenom na vozovke.');
INSERT INTO `Questions` VALUES (32,32,0,1,'Vodič je povinný za vozidlom idúcim pred nim dodržiavať :','',2,3,'vzdialenosť minimálne 10m,','takú vzdialenosť, aká je potrebná na zastavenie vozidla z rýchlosti 60km/h','takú vzdialenosť, aby mohol včas znížiť rýchlosť jazdy, prípadne zastaviť vozidlo, ak vodič vozidla jazdiaceho pred ním zníži rýchlosť jazdy alebo zastaví.');
INSERT INTO `Questions` VALUES (33,33,0,1,'Vodič motorového vozidla i nemotorového vozidla odbočujúci vpravo je povinný dať prednosť v jazde :','',2,2,'protiidúcim vozidlám pravidelnej verejnej dopravy osôb, ak tieto odbočujú vľavo,','električke, ak je povolená jazda pozdĺž električky vľavo,','prvému vozidlu idúcemu za ním.');
