INSERT INTO `Questions` VALUES (37,37,0,1,'Vodič nesmie predchádzať, ak:','',2,1,'by pri predchádzaní svojou výrazne nižšou rýchlosťou obmedzil za ním idúce vozidlo, ktoré začalo úkon predchádzania skôr,','pred ním jazdí zvláštne motorové vozidlo,','na to v obci neupozornil vodiča predchádzaného vozidla zvukovým výstražným znamením.');
INSERT INTO `Questions` VALUES (38,38,0,1,'V motorovom vozidle, ktoré je určené na dopravu osôb, sa smú na miestach na to vyhradených prepravovať osoby:','',2,3,'staršie ako 15 rokov s telesnou výškou väčšou ako 160 cm,','len do prípustnej užitočnej hmotnosti vozidla, pritom počet prepravovaných osôb môže byť vyšší, ako je počet miest uvedených v osvedčení o evidencii,','len do prípustnej užitočnej hmotnosti vozidla, pritom počet prepravovaných osôb nesmie byť vyšší, ako je počet miest uvedených v osvedčení o evidencii,');
