INSERT INTO `Questions` VALUES (42,42,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak:','',1,1,'niektorá časť výfukového systému je netesná, takže výfukové plyny vnikajú do priestoru pre cestujúcich, vodiča alebo nákladu alebo sú zdrojom nadmerného zvuku','sa z miesta vodiča nedá nastaviť pravé predné zrkadlo','nedosahuje rýchlosť najmenej 80 km/h');
