INSERT INTO `Questions` VALUES (57,57,0,1,'Osoba sediaca na sedadle vozidla povinne vybavenom bezpečnostným pásom alebo iným zadržiavacím zariadením je povinná toto zariadenie použiť; to neplatí pre','',2,2,'osobu staršiu ako 65 rokov','osobu, ktorá to nemôže urobiť zo zdravotných dôvodov; takáto osoba sa musí preukázať osvedčením o oslobodení od použitia bezpečnostných systémov vozidla','vodiča počas jazdy na účelovej komunikácii');
