INSERT INTO `Questions` VALUES (59,59,0,1,'Ak vodič autobusu alebo trolejbusu vychádza z vyhradeného jazdného pruhu do priľahlého jazdného pruhu','',2,1,'nesmie ohroziť vodičov ostatných vozidiel','nie je povinný dávať znamenie o zmene smeru jazdy','vodič jazdiaci v tomto pruhu nie je povinný mu dať prednosť v jazde');
INSERT INTO `Questions` VALUES (60,60,0,1,'Vodičovi vozidla pravidelnej verejnej dopravy osôb v obci vodiči ostatných vozidiel','',2,3,'nie sú povinní umožniť vyjdenie zo zástavky','sú povinní umožniť vyjdenie zo zastávky, len ak sú v tomto vozidle prepravované deti','sú povinní umožniť vyjdenie zo zastávky alebo zo zastávkového pruhu, a to znížením rýchlosti jazdy, prípadne i zastavením vozidla');
INSERT INTO `Questions` VALUES (61,61,0,1,'Ak sa spúšťajú, ak sú spustené alebo ak sa zdvíhajú závory, vodič','',2,3,'smie vchádzať na železničné priecestie, ak to rozmery jeho vozidla dovolujú','smie vchádzať na železničné priecestie, ak nie je vidieť vlak','nesmie vchádzať na železničné priecestie');
INSERT INTO `Questions` VALUES (62,62,0,1,'Vodič nesmie použiť diaľkové svetlomety, ak','',2,2,'by mohol byť oslnený vodič protiidúceho vozidla; na prípadné oslnenie vodiča idúceho pred ním nemusí brať odľad','by mohol byť oslnený vodič protiidúceho vozidla alebo vodič vozidla idúceho pred ním','s tým nevyslovili súhlas všetci jeho spolucestujúci');
INSERT INTO `Questions` VALUES (63,63,0,1,'Na diaľnici a na rýchlostnej ceste je vodičovi zastavenie a státie','',2,2,'dovolené všade tam, kde neohrozí vodičov nemotorových vozidiel','zakázané na inom mieste, než na mieste označenom ako parkovisko s výnimkou núdzového státia','dovolené na parkovisku a na pripájacom a na odbočovacom pruhu');
INSERT INTO `Questions` VALUES (64,64,0,1,'Náklad musí byť na vozidle riadne umiestnený, rozložený a upevnený, aby','',2,1,'neohrozoval bezpečnosť a plynulosť cestnej premávky, neznečisťoval ani nepoškodzoval cestu ani jej okolie, nespôsoboval nadmerný hluk a neznečisťoval ovzdušie','neohrozoval bezpečnosť cestnej premávky a nepoškodzoval cestu; spôsobovať nadmerný hluk nesmie len v nočnej dobe','neobmedzoval plynulosť cestnej premávky; ak by pritom poškodzoval cestu alebo spôsoboval nadmerný hluk, môže vozidlo ísť rýchlosťou najviac 40 km/h');
INSERT INTO `Questions` VALUES (65,65,0,1,'Ak pri jazde vozidla v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným, alebo ak vznikne dopravná nehoda vrátane požiaru, je vodič po zastavení vozidla povinný bezodkladne','',2,3,'vypnúť stretávacie svetlomety','oznámiť zastavenie vozidla príslušnému obvodnému úradu','vypnúť motor');
