INSERT INTO `Questions` VALUES (70,70,1,1,'Táto dopravná značka upozorňuje na','a4b',2,2,'pripájací jazdný pruh,','miesto kde je zúžená vozovka (z jednej strany), kde sa približuje koľaj električky k chodníku a podobne,','miesto, kde sa znižuje počet jazdných pruhov z jednej strany.');
