INSERT INTO `Questions` VALUES (73,73,1,1,'Táto dopravná značka s dodatkovou tabuľkou','spec86',2,1,'vyznačuje vzdialenosť k značke "Stoj, daj prednosť v jazde!", pre ktorú je zároveň predbežnou značkou,','prikazuje vodičovi zastaviť vozidlo do vzdialenosti 150 m,','upozorňuje vodiča, že vo vzdialenosti 150 m bude mať prednosť v jazde.');
