INSERT INTO `Questions` VALUES (78,78,2,1,'V poradí druhé prejde cez križovatku','78',3,3,'žlté vozidlo','zelené vozidlo','červené vozidlo');
INSERT INTO `Questions` VALUES (79,79,2,1,'Vozidlá prejdú okolo prekážky v tomto poradí:','79',3,1,'1. červené, 2. modré, 3. žlté, 4. zelené','1. modré, 2. zelené, 3. červené, 4. žlté','1. modré, 2. červené, 3. žlté, 4. zelené');
INSERT INTO `Questions` VALUES (80,80,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','80',3,1,'1. červené súčasne so zeleným, 2. vaše vozidlo,','1. vaše vozidlo, 2. červené súčasne so zeleným,','1. zelené, 2. vaše vozidlo, 3. červené');
