INSERT INTO `Questions` VALUES (82,82,0,1,'Hranicou križovatky sa rozumie','',2,1,'miesto vyznačené príslušnou vodorovnou dopravnou značkou; kde takáto vodorovná dopravná značka nie je, hranicu križovatky tvorí kolmica na os vozovky v mieste, kde sa pre križovatku začína zakrivenie vozovky,','kolmica na os vozovky vo vzdialenosti desať metrov od miesta, kde sa pre križovatku začína zakrivenie vozovky,','kolmica na os vozovky vedená stredom priechodu pre chodcov');
INSERT INTO `Questions` VALUES (83,83,0,1,'Státím sa rozumie','',2,1,'uvedenie vozidla do pokoja na dlhšie, ako je čas dovolený na zastavenie','prerušenie jazdy na čas nevyhnutne potrebný na urýchlené nastúpenie alebo vystúpenie prepravovaných osôb alebo na urýchlené naloženie alebo zloženie nákladu','len také uvedenie vozidla do pokoja, ktoré nepresiahna čas 15 minút');
INSERT INTO `Questions` VALUES (84,84,0,1,'Vodič nesmie použiť','',2,2,'zvukové výstražné znamenie na odvrátenie hroziaceho nebezpečenstva v obci','na jazdu vozidlo, ktoré svojím farebným vyhotovením a označením sa dá zameniť s vozidlom Policajného zboru, Vojenskej polície, Železničnej polície, obecnej polície, Hasičského a záchranného zboru alebo ostatných hasičských jednotiek,','zimné pneumatiky v období od 15. marca do 15. októbra');
INSERT INTO `Questions` VALUES (85,85,0,1,'Vodič motocykla je počas jazdy povinný vhodným spôsobom chrániť si zrak','',2,3,'okuliarmi a ochranným štítom za každých okolností,','okuliarmi len pri snežení alebo v daždi,','najmä okuliarmi alebo ochranným štítom, ak sa tým nezníži bezpečnosť jazdy, najmä v hmle, pri snežení alebo v daždi');
INSERT INTO `Questions` VALUES (86,86,0,1,'Ak sa vodič motorového vozidla, ktoré je povinne vybavené bezpečnostným odevom, zdržiava na vozovke mimo vozidla počas núdzového státia, najmä pri prerušení jazdy pre chybu na vozidle alebo v dôsledku dopravnej nehody, je povinný','',2,2,'umiestniť 20 m za vozidlo biele neoslnujúce svetlo bielej farby','mať bezpečnostný odev oblečený','bezodkladne privolať odťahovú službu');
INSERT INTO `Questions` VALUES (87,87,0,1,'Ak pri súbežnej jazde vodič vozidla idúceho vo voľnom jazdnom pruhu umožňuje vodičovi prvého vozidla nachádzajúceho sa v jazdnom pruhu, v ktorom je prekážka, jej obídenie, vodič obchádzajúci prekážku nesmie','',2,3,'dávať znamenie o zmene smeru jazdy,','jazdiť za žiadnych okolností rýchlosťou vyššou ako 15 km/h,','ohroziť vodiča jazdiaceho vo voľnom jazdnom pruhu');
