INSERT INTO `Questions` VALUES (93,93,0,1,'Rozsvietené číslo na rýchlostnom signáli s viacerými signálnymi znakmi označuje','',2,1,'rýchlosť v km/h, pri ktorej dodržaní dôjde vozidlo k nasledujúcemu svetelnému signalizačnému zariadeniu v čase, keď na ňom svieti signál so zeleným svetlom "Voľno",','najnižšiu dovolenú rýchlosť v km/h,','rýchlosť v km/h, pri ktorej dodržaní dôjde vozidlo na križovatku v čase, keď na nej svieti signál s červeným svetlom "STOJ"');
