INSERT INTO `Questions` VALUES (109,109,0,1,'Krajnicou sa rozumie','',2,1,'časť cesty od kraja vozovky po kraj cesty','trávnatý pás medzi smerovo rozdelenými cestami','časť cesty určená na premávku motorových vozidiel');
