INSERT INTO `Questions` VALUES (111,111,0,1,'Vodič je povinný','',2,2,'sledovať situáciu v cestnej premávke len počas jazdy na diaľnici, na rýchlostnej ceste, na ceste I. triedy a obci','venovať sa plne vedeniu vozidla a sledovať situáciu v cestnej premávke','venovať sa plne vedeniu vozidla, sledovať situáciu v cestnej premávke je povinný len v niektorých osobitných prípadoch, najmä počas jazdy vyššou rýchlosťou a prepravy nebezpečných vecí');
INSERT INTO `Questions` VALUES (112,112,0,1,'Vodič pri prechádzaní z jedného jazdného pruhu do druhého jazdného pruhu','',2,2,'nie je povinný dávať znamenie o zmene smeru jazdy,','je povinný dávať znamenie o zmene smeru jazdy,','môže ohroziť vodiča jazdiaceho v jazdnom pruhu, do ktorého prechádza');
