INSERT INTO `Questions` VALUES (114,114,0,1,'Vodič nesmie zastaviť a stáť na zastávke vozidla pravidelnej verejnej dopravy osôb v úseku, ktorý sa začína dopravnou značkou pre zastávku a končí sa','',2,3,'20 m za označníkom zastávky,','10 m za označníkom zastávky,','5 m za označníkom zastávky, a tam, kde taká dopravná značka nie je, vo vzdialenosti kratšej ako 30 m pred označníkom zastávky a 5 m za ním');
