INSERT INTO `Questions` VALUES (116,116,0,1,'Vodičovi motorového vozidla je na diaľnici a na rýchlostnej ceste otáčanie a cúvanie','',2,1,'zakázané,','dovolené,','dovolené, tam, kde je stredný deliaci pás prerušený');
INSERT INTO `Questions` VALUES (117,117,0,1,'Vodič vozidla, ktorý pri obchádzaní vozidla, ktoré zastavilo alebo stojí, vybočuje zo smeru svojej jazdy,','',2,3,'môže obmedziť protiidúcich vodičov,','nie je povinný dávať znamenie o zmene smeru jazdy,','je povinný dávať znamenie o zmene smeru jazdy');
INSERT INTO `Questions` VALUES (118,118,0,1,'Vodič, ktorý sa zúčastnil na dopravnej nehode, je povinný','',2,2,'zastaviť vozidlo len vtedy, ak pri dopravnej nehode boli zranené osoby,','bezodkladne zastaviť vozidlo,','bezodkladne zastaviť vozidlo len vtedy, ak ho o to požiadal iný účastník dopravnej nehody');
INSERT INTO `Questions` VALUES (119,119,0,1,'Vodič po zastavení vozidla je povinný bezodkladne vypnúť motor, a ak je na vykurovanie vozidla použité nezávislé kúrenie, vypnúť aj toto kúrenie, ak','',2,2,'zastavil vozidlo pred železničným priecestím, kde sa dáva výstraha dvoma červenými striedavo prerušovanými svetlami priecestného zabezpečovacieho zariadenia,','pri jazde vozidla v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným,','vodič zastavil na parkovisku');
INSERT INTO `Questions` VALUES (120,120,0,1,'V školskej zóne','',2,2,'nemožno stáť,','možno stáť, ak tým nie je obmedzený pohyb chodcov,','možno stáť bez obmedzenia');
INSERT INTO `Questions` VALUES (121,121,0,1,'Pokyny policajta','',1,2,'nie sú nadradené svetelným signálom,','sú nadradené všeobecnej úprave cestnej premávky, dopravným značkám a svetelným signálom,','nie sú nadradené všeobecnej úprave cestnej premávky, avšak sú nadradené dopravným značkám a svetelným signálom');
INSERT INTO `Questions` VALUES (122,122,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách ak','',1,2,'dodatočne namontované svetelné zariadenia narúšajú výhľad z miesta spolujazdca,','je poškodený alebo deformovaný podvozok, rám alebo karoséria,','vozidlo nie je vybavené zariadením na spájanie vozidiel');
INSERT INTO `Questions` VALUES (123,123,0,1,'Ak zjavne uniká palivo, olej, mazivo alebo iné prevádzkové náplne z vozidla,','',1,2,'vodič je povinný po ukončení jazdy oznámiť to držiteľovi vozidla,','považuje sa vozidlo za technicky nespôsobilé na premávku na pozemných komunikáciách,','smie sa takéto vozidlo, okrem diaľnice a rýchlostnej cesty, používať v cestnej premávke');
INSERT INTO `Questions` VALUES (124,124,1,1,'Táto dopravná značka','a23',2,2,'zakazuje predchádzanie vozidiel idúcich v kolóne,','upozorňuje na úsek cesty, kde sa vytvárajú kolóny vozidiel, najmä pri veľkej intenzite premávky v dlhých stúpaniach, na horských priechodoch a podobne,','zakazuje súbežnú jazdu osobným motorovým vozidlám');
