INSERT INTO `Questions` VALUES (130,130,1,1,'Táto dopravná značka znamená:','ip33',2,2,'Odporúčané rýchlosti,','Všeobecné najvyššie dovolené rýchlosti,','Obmedzenie v jazdných pruhoch');
INSERT INTO `Questions` VALUES (131,131,1,1,'Táto dodatková tabuľka umiestnená pod zákazovou značkou','e6',2,2,'obmedzuje platnosť značky na vozidlo, ktorého najväčšia prípustná celková hmotnosť je menšia ako údaj uvedený na tabuľke,','obmedzuje platnosť zákazu na vozidlo, ktorého najväčšia prípustná celková hmotnosť presahuje údaj uvedený na tabuľke; pri jazdnej súprave rozhoduje súčet najväčších pripustných celkových hmotností vozidiel,','vyznačuje najvyššie dovolené zaťaženie vozidla pripadajúce na dvojnápravu');
INSERT INTO `Questions` VALUES (132,132,2,1,'Modré vozidlo prejde cez križovatku ako','132',3,2,'prvé,','druhé,','posledné');
INSERT INTO `Questions` VALUES (133,133,2,1,'Vodič červeného vozidla smie','133',3,3,'na signál zelenej šípky pokračovať v jazde vpravo; pritom má prednosť pred zeleným vozidlom, ale musí dať prednosť chodcom prechádzajúcim vo voľnom smere,','prejsť cez križovatku súčasne s vodičom modrého vozidla; pritom nesmie ohroziť vodiča zeleného vozidla idúceho vo voľnom smere a nesmie obmedziť chodcov,','na signál zelenej doplnkovej šípky odbočiť vpravo; pritom musí dať prednosť v jazde vozidlám idúcim vo voľnom smere, ako aj prednosť chodcom prechádzajúcim vo voľnom smere');
INSERT INTO `Questions` VALUES (134,134,2,1,'Ako posledné prejde cez križovatku','134',3,1,'vaše vozidlo,','modré vozidlo,','zelené vozidlo');
INSERT INTO `Questions` VALUES (135,135,2,1,'Ako prvé prejdú cez križovatku','135',3,3,'vaše vozidlo súčasne s električkou prichádzajúcou sprava,','vaše vozidlo súčasne s modrým vozidlom,','obidve električky súčasne');
INSERT INTO `Questions` VALUES (136,136,0,1,'Motorovým vozidlom sa rozumie','',2,2,'koľajové a nekoľajové vozidlo poháňané vlastným motorom,','nekoľajové vozidlo poháňané vlastným motorom s výnimkou mechanického alebo elektrického motorového vozíka pre zdravotne postihnuté osoby a trolejbus,','vozidlo poháňané vlastným motorom s výnimkou motocykla, traktora a motorového ručného vozíka');
INSERT INTO `Questions` VALUES (137,137,0,1,'Neohrozením sa rozumie povinnosť účastníka cestnej premávky','',2,2,'počínať si tak, aby inému účastníkovi cestnej premávky nijako neprekážal,','počínať si tak, aby inému účastníkovi cestnej premávky nevzniklo nijaké nebezpečenstvo,','neobchádzať ani nepredchádzať vozidlo prepravujúce nebezpečné veci a jazdiť za takýmto vozidlom vo vzdialenosti najmenej 50 m');
INSERT INTO `Questions` VALUES (138,138,0,1,'Vodič vozidla, ktoré je povinne vybavené prenosným výstražným trojuholníkom, je povinný tento trojuholník použiť počas','',2,2,'prepravy nebezpečného nákladu,','núdzového státia, ak také vozidlo tvorí prekážku cestnej premávky,','jazdy na diaľnici rýchlosťou nižšou ako 80 km/h');
