INSERT INTO `Questions` VALUES (140,140,0,1,'Predné svetlomety do hmly a zadné svietidlá do hmly vodič smie použiť','',2,3,'len za hmly; za sneženia a dažďa je povinný použiť diaľkové svetlomety,','vždy za zníženej viditeľnosti,','len za hmly, sneženia alebo za dažďa');
INSERT INTO `Questions` VALUES (141,141,0,1,'Vlečenie motorového vozidla s prívesom je','',2,3,'zakázané; vliecť sa nesmie ani motorové vozidlo s návesom,','dovolené, ak najväčšia prípustná celková hmotnosť vlečeného vozidla a prívesu nepresahuje 3500 kg,','zakázané; smie sa však vliecť motorové vozidlo s návesom');
