INSERT INTO `Questions` VALUES (144,144,0,1,'Osoby sa môžu pohybovať po vozovke v tuneli len','',2,1,'v súvislosti so zaisťovaním bezpečnosti cestnej premávky, ak majú na sebe reflexný bezpečnostný odev,','po pravej krajnici,','v čase od 00.00 hod. do 04.00 hod.');
INSERT INTO `Questions` VALUES (145,145,0,1,'Do pešej zóny je povolený vjazd','',2,2,'len bicyklom a motocyklom,','len vozidlám, ktorým to umožňuje dopravná značka,','všetkým vozidlám, ak nejazdia rýchlosťou vyššou ako 20 km/h');
INSERT INTO `Questions` VALUES (146,146,0,1,'Pokyny policajta','',2,2,'nie sú nadradené pokynom vyplývajúcim z dopravných značiek a dopravných zariadení,','sú nadradené pokynom vyplývajúcim z dopravných značiek a dopravných zariadení,','sú nadradené pokynom vyplývajúcim z dopravných značiek, ale nie sú nadradené pokynom vyplývajúcim z dopravných zariadení');
INSERT INTO `Questions` VALUES (147,147,0,1,'Pri jazde po kruhovom objazde vodič dáva znamenie o zmene smeru jazdy, ak','',2,3,'do takejto križovatky vchádza,','dôjde k núdzovému zastaveniu vozidla alebo k dopravnej nehode,','z takej križovatky vychádza');
INSERT INTO `Questions` VALUES (148,148,0,1,'Výstražné značky','',1,3,'upozorňujú na miesto, kde vodič motorového vozidla musí spomaliť a prípadne aj zastaviť vozidlo,','informujú účastníkov cestnej premávky o zmene organizácie dopravy,','upozorňujú na miesta, kde účastníkovi cestnej premávky hrozí nebezpečenstvo a kde musí dbať na zvýšenú opatrnosť');
