INSERT INTO `Questions` VALUES (150,150,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,2,'na zvukovom výstražnom zariadení došlo k zmene tónu,','výhľad z miesta vodiča je obmedzený alebo znemožnený,','nie je na čelnom skle zatemňovací pás, ktorý umožňuje najmenej 50 % priepustnosti svetla');
INSERT INTO `Questions` VALUES (151,151,1,1,'Táto dopravná značka znamená:','a11',2,2,'Zákaz státia na krajnici,','Odletujúci štrk,','Nebezpečenstvo poškodenia pneumatík');
