INSERT INTO `Questions` VALUES (163,163,0,1,'Nemotorovým vozidlom sa rozumie','',2,1,'prípojne vozidlo, vozidlo pohybujúce sa pomocou ľudskej sily alebo zvieracej sily s výnimkou mechanického alebo elektrického vozíka pre osoby so zdravotným postihnutím,','vozidlo pohybujúce sa pomocou ľudskej sily alebo zvieracej sily, električka a trolejbus,','aj motorové vozidlo, ktorého pohotovostná hmotnosť nepresahuje 400 kg');
INSERT INTO `Questions` VALUES (164,164,0,1,'Neobmedzením sa rozumie povinnosť účastníka cestnej premávky','',2,1,'počínať si tak, aby inému účastníkovi cestnej premávky neprekážal,','nerozptyľovať pozornosť vodiča hlasitým hovorom, telefonovaním, pitím nápojov alebo inou obdobnou činnosťou,','za žiadnych okolností nevyrušovať vodiča predchádzaného vozidla dávaním zvukového výstražného znamenia alebo svetelného výstražného znamenia');
INSERT INTO `Questions` VALUES (165,165,0,1,'Na ceste s troma jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy je vodič prechádzajúci','',2,2,'z pravého jazdného pruhu do stredného jazdného pruhu je povinný dať prednosť v jazde vodičovi prechádzajúcemu do stredného jazdného pruhu z ľavého jazdného pruhu,','z ľavého jazdného pruhu do stredného jazdného pruhu je povinný dať prednosť v jazde vodičovi prechádzajúcemu do stredného jazdného pruhu z pravého jazdného pruhu,','z ľavého jazdného pruhu do stredného jazdného pruhu smie ohroziť vodiča prechádzajúceho do stredného jazdného pruhu z pravého jazdného pruhu');
INSERT INTO `Questions` VALUES (166,166,0,1,'Pozdĺž nástupného ostrovčeka alebo ochranného ostrovčeka sa jazdí','',2,1,'vpravo; vľavo sa smie jazdiť len vtedy, ak jazde vpravo bráni prekážka alebo ak je to bezpečnejšie s ohľadom na rozmery vozidla alebo nákladu,','vľavo; vpravo sa smie jazdiť len vtedy, ak jazde vľavo bráni prekážka,','za každých okolností vľavo');
INSERT INTO `Questions` VALUES (167,167,0,1,'Vodič, ktorý prichádza na križovatku po ceste neoznačenej dopravnou značkou ako vedľajšia cesta alebo ako hlavná cesta, je povinný dať prednosť v jazde vozidlu prichádzajúcemu','',2,2,'zľava,','sprava,','po jednosmernej ceste');
INSERT INTO `Questions` VALUES (168,168,0,1,'Vodič sa nesmie otáčať','',2,2,'na železničnom priecestí a vo vzdialenosti 200 m pred ním,','na železničnom priecestí a v jeho tesnej blízkosti,','na žiadnej križovatke');
INSERT INTO `Questions` VALUES (169,169,0,1,'Vodič smie zastaviť a stáť na','',2,2,'moste,','jednosmernej ceste vľavo aj vpravo,','električkovom koľajovom páse');
INSERT INTO `Questions` VALUES (170,170,0,1,'Ak osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva znamenie na zastavenie vozidla za zníženej viditeľnosti krúžením červeným svetlom v hornom polkruhu, vodič','',2,1,'nesmie vchádzať na železničné priecestie,','smie vchádzať na železničné priecestie,','je povinný vchádzať na železničné priecestie zvýšenou rýchlosťou');
INSERT INTO `Questions` VALUES (171,171,0,1,'Na upozornenie vodiča predchádzaného vozidla v obci vodič smie dávať','',2,1,'svetelné výstražné znamenie,','zvukové výstražné znamenie,','zvukové výstražné znamenie a svetelné výstražné znamenie');
INSERT INTO `Questions` VALUES (172,172,0,1,'Ak dôjde k zastaveniu vozidla na železničnom priecestí, vodič je povinný','',2,1,'odstrániť vozidlo zo železničnej trate; ak tak nemôže urobiť, musí bezodkladne vykonať také opatrenia, aby bol vodič koľajového vozidla pred nebezpečenstvom včas varovaný,','oznámiť zastavenie vozidla príslušnému obvodnému úradu,','použiť zariadenie proti neoprávnenému použitiu vozidla');
INSERT INTO `Questions` VALUES (173,173,0,1,'Za motorovým vozidlom s prívesom sa','',2,3,'smie vliecť len jedno motorové vozidlo,','smie vliecť len motocykel,','nesmie vliecť iné motorové vozidlo');
INSERT INTO `Questions` VALUES (174,174,0,1,'Pri riadení cestnej premávky na križovatke znamená pre vodiča signál so súčasne svietiacim červeným a žltým svetlom „POZOR!“ povinnosť','',2,2,'dbať na zvýšenú opatrnosť voči chodcom,','pripraviť sa na jazdu,','zastaviť vozidlo');
INSERT INTO `Questions` VALUES (175,175,0,1,'Ak náklad na vozidle prečnieva do strany musí byť prečnievajúci koniec nákladu označený','',1,2,'žltou zástavkou s rozmermi najmenej 40 x 40 cm; za zníženej viditeľnosti vpredu aj vzadu žltou odrazkou,','reflexným označením s červenými a bielymi pruhmi širokými 70 až 100 mm a smerujúcimi od pozdĺžnej strednej roviny vozidla pod uhlom 45° nadol,','vždy žltými a čiernymi pruhmi');
