INSERT INTO `Questions` VALUES (244,244,0,1,'Prekážkou cestnej premávky sa rozumie','',2,2,'každé vozidlo, ktoré prepravuje náklad, ktorý presahuje celkovú dĺžku alebo šírku takéhoto vozidla,','všetko, čo môže ohroziť alebo obmedziť jazdu vozidiel a pohyb chodcov,','chodec prechádzajúci cez priechod pre chodcov');
INSERT INTO `Questions` VALUES (245,245,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza, vodič motorového vozidla kategórie M1 a N1 môže takéto vozidlo použiť v cestnej premávke, len ak','',2,1,'je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené na hnacej náprave zimnými pneumatikami,','má uzatvorené havarijné poistenie');
