INSERT INTO `Questions` VALUES (247,247,0,1,'Ak vodič autobusu alebo trolejbusu vychádza z vyhradeného jazdného pruhu do priľahlého jazdného pruhu, vodič jazdiaci v tomto pruhu','',2,3,'je povinný vždy zastaviť vozidlo,','nie je povinný mu dať prednosť v jazde,','je povinný mu dať prednosť v jazde');
