INSERT INTO `Questions` VALUES (249,249,0,1,'Vodič nesmie zastaviť a stáť','',2,2,'na železničnom priecestí a v tuneli a vo vzdialenosti kratšej ako 80 m pred nimi,','na železničnom priecestí, v podjazde a v tuneli a vo vzdialenosti kratšej ako 15 m pred nimi a 15 m za nimi,','kolmo na okraj cesty v obci');
INSERT INTO `Questions` VALUES (250,250,0,1,'Vodič nesmie vchádzať na železničné priecestie, ak','',2,2,'svieti prerušované biele svetlo,','sa dáva výstraha dvoma červenými striedavo prerušovanými svetlami priecestného zabezpečovacieho zariadenia,','osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva pokyn vodorovným kývaním ruky s červenou alebo so žltou zástavkou cez stred tela');
