INSERT INTO `Questions` VALUES (256,256,0,1,'Ak náklad prečnieva vozidlo vpredu alebo vzadu viac ako','',1,2,'o 1 m, musí byť prečnievajúci koniec nákladu označený žltou zástavkou s rozmermi najmenej 20 x 20 cm; za zníženej viditeľnosti vpredu aj vzadu žltou odrazkou,','o 40 cm, musí byť prečnievajúci koniec nákladu označený reflexným označením s červenými a bielymi pruhmi širokými 70 až 100 mm a smerujúcimi od pozdĺžnej strednej roviny vozidla pod uhlom 45° nadol,','o 50 cm, musí byť vždy označený červenou odrazkou');
INSERT INTO `Questions` VALUES (257,257,0,1,'Prevádzkovateľ nesmie v premávke na pozemných komunikáciách prevádzkovať vozidlo,','',1,3,'ktorého celková prípustná šírka vozidla presahuje 2200 mm,','ktoré nebolo v lehote jedného mesiaca po jeho prvom prihlásení do evidencie podrobené emisnej kontrole,','ktoré bolo pri kontrole originality vozidla, ak takejto kontrole podlieha, hodnotené výsledkom nespôsobilé na premávku na pozemných komunikáciách');
