INSERT INTO `Questions` VALUES (259,259,1,1,'Táto dopravná značka upozorňuje na','a9',2,2,'úsek cesty, ktorej povrch je znečistený a za mokra klzký,','úsek cesty, na ktorom sa nachádza ujazdený a zľadovatený sneh alebo na ktorom hrozí nebezpečenstvo poľadovice,','povinnosť použiť pri jazde snehové reťaze');
