INSERT INTO `Questions` VALUES (270,270,2,1,'Vaše vozidlo prejde cez križovatku ako','270',3,3,'druhé,','prvé,','posledné súčasne so žltým vozidlom.');
INSERT INTO `Questions` VALUES (271,271,0,1,'Hranicou križovatky sa rozumie','',2,3,'kolmica na os vozovky vedená stredom priechodu pre chodcov,','kolmica na os vozovky vo vzdialenosti desať metrov od miesta, kde sa pre križovatku začína zakrivenie vozovky,','miesto vyznačené príslušnou vodorovnou dopravnou značkou; kde takáto vodorovná dopravná značka nie je, hranicu križovatky tvorí kolmica na os vozovky v mieste, kde sa pre križovatku začína zakrivenie vozovky');
INSERT INTO `Questions` VALUES (272,272,0,1,'Zastavením vozidla sa rozumie','',2,2,'každé prerušenie jazdy,','prerušenie jazdy z dôvodu nezávislého od vôle vodiča,','uvedenie motorového vozidla do pokoja na čas nevyhnutne potrebný na urýchlené nastúpenie alebo vystúpenie prepravovaných osôb, najviac však na tri minúty');
INSERT INTO `Questions` VALUES (273,273,0,1,'Vodič je povinný','',2,3,'prekážať v jazde rýchlejšie idúcim vozidlám za zníženej viditeľnosti,','zabezpečiť vozidlo a prepravované veci proti odcudzeniu prostriedkami montovanými do vozidla jeho výrobcom, ak sa vzdiali od vozidla na dobu, ktorá presiahne 30 minút,','zabezpečiť vozidlo a prepravované veci proti odcudzeniu prostriedkami montovanými do vozidla jeho výrobcom, ak sa vzdiali od vozidla mimo jeho dohľad');
INSERT INTO `Questions` VALUES (274,274,0,1,'Vodič motocykla je počas jazdy povinný vhodným spôsobom chrániť si zrak','',2,3,'okuliarmi a ochranným štítom za každých okolností,','okuliarmi len pri snežení alebo v daždi,','najmä okuliarmi alebo ochranným štítom, ak sa tým nezníži bezpečnosť jazdy, najmä v hmle, pri snežení alebo v daždi');
INSERT INTO `Questions` VALUES (275,275,0,1,'Za vozidlom pravidelnej verejnej dopravy osôb, ktoré zastavilo v obci na zastávke bez nástupného ostrovčeka alebo bez nástupišťa na zvýšenom električkovom koľajovom páse, je vodič iného vozidla povinný','',2,1,'zastaviť vozidlo; ak je na zastávke viac vozidiel, vodič je povinný zastaviť vozidlo za posledným z nich,','zastaviť len vtedy, ak autobus, prípadne trolejbus zastaví pri okraji vozovky,','zastaviť len na pokyn vodiča takého vozidla');
INSERT INTO `Questions` VALUES (276,276,0,1,'Vodič motorového vozidla s najväčšou prípustnou celkovou hmotnosťou neprevyšujúcou 3500 kg, smie jazdiť rýchlosťou najviac','',2,1,'90 km/h; na diaľnici a na rýchlostnej ceste smie jazdiť rýchlosťou najviac 130 km/h,','110 km/h; na diaľnici a na rýchlostnej ceste nemá rýchlosť jazdy obmedzenú,','80 km/h');
