INSERT INTO `Questions` VALUES (278,278,0,1,'Vodič nesmie vchádzať na železničné priecestie, ak za zníženej viditeľnosti','',2,3,'osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva znamenie kývaním ruky s bielym svetlom cez stred tela,','svieti prerušované biele svetlo,','osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva znamenie krúžením červeným svetlom v hornom polkruhu');
INSERT INTO `Questions` VALUES (279,279,0,1,'Pred vjazdom do priebežných jazdných pruhov na diaľnici vodič','',2,1,'je povinný použiť pripájací jazdný pruh; tam, kde pripájací jazdný pruh nie je, vodič musí dať prednosť v jazde vozidlám idúcim v priebežných jazdných pruhoch,','je povinný použiť pripájací jazdný pruh; tam, kde pripájací jazdný pruh nie je, vodič má prednosť v jazde pred vozidlami idúcimi v priebežných jazdných pruhoch,','osobného motorového vozidla nie je povinný použiť existujúci pripájací jazdný pruh');
