INSERT INTO `Questions` VALUES (281,281,0,1,'Za dopravnú nehodu sa považuje aj škodová udalosť, ak','',2,1,'sa účastníci škodovej udalosti nedohodli na jej zavinení,','ku škodovej udalosti došlo na diaľnici alebo rýchlostnej ceste,','v niektorom zo zúčastnených vozidiel došlo k poškodeniu prepravovaných vecí');
INSERT INTO `Questions` VALUES (282,282,0,1,'Osoba, ktorá sa pohybuje po chodníku na lyžiach, korčuliach alebo na obdobnom športovom vybavení,','',2,1,'smie používať pravú stranu chodníka, pričom nesmie ohroziť ani obmedziť ostatné osoby používajúce chodník,','smie používať chodník v celej šírke,','smie používať ľavú stranu chodníka, pričom smie obmedziť ostatné osoby používajúce chodník');
INSERT INTO `Questions` VALUES (283,283,0,1,'Ak pohonič ide vedľa záprahového vozidla, je povinný ísť po','',1,1,'pravej strane,','ľavej strane,','ľavej strane a najviac jeden meter od vozidla');
