INSERT INTO `Questions` VALUES (287,287,1,1,'Táto dopravná značka znamená:','b32b',2,1,'Koniec zákazu zvukových výstražných znamení,','Koniec zákazu zvukových a svetelných výstražných znamení,','Zákaz zvukových výstražných znamení');
