INSERT INTO `Questions` VALUES (291,291,1,1,'Táto dopravná značka znamená:','ip13c',2,1,'Parkovisko - parkovacie miesta s pozdĺžnym státím,','Parkovisko - parkovacie miesta s kolmým státím,','Parkovisko - parkovacie miesta s pozdĺžnym státím na chodníku');
INSERT INTO `Questions` VALUES (292,292,1,1,'Táto dopravná značka znamená:','c23a',2,1,'Obmedzenie v jazdných pruhoch,','Jazdný pruh vyhradený pre pomalé vozidlá,','Prikázaný smer jazdy pre pomalé vozidlá');
