INSERT INTO `Questions` VALUES (299,299,0,1,'Ak vodič zníži rýchlosť jazdy alebo ak zastaví vozidlo pred priechodom pre cyklistov, aby umožnil prejsť cez cestu cyklistom, vodiči ostatných vozidiel idúcich rovnakým smerom sú','',2,3,'povinní podstatne zvýšiť rýchlosť jazdy,','takisto povinní znížiť rýchlosť jazdy alebo zastaviť vozidlo, len ak sú cyklisti mladší ako 12 rokov,','takisto povinní znížiť rýchlosť jazdy alebo zastaviť vozidlo; to neplatí pre vodiča električky');
INSERT INTO `Questions` VALUES (300,300,0,1,'Ak vodič autobusu alebo trolejbusu vychádza z vyhradeného jazdného pruhu do priľahlého jazdného pruhu, vodič jazdiaci v tomto pruhu','',2,2,'je povinný vždy zastaviť vozidlo,','je povinný mu dať prednosť v jazde,','nie je povinný mu to umožniť');
