INSERT INTO `Questions` VALUES (303,303,0,1,'Na motocykli je zakázané','',2,3,'prepravovať osoby mladšie ako 18 rokov,','používanie okuliarov prepravovanými osobami,','bočné sedenie prepravovaných osôb');
INSERT INTO `Questions` VALUES (304,304,0,1,'Vodič, ktorý sa zúčastnil na dopravnej nehode je povinný','',2,1,'bezodkladne zastaviť vozidlo,','bezodkladne privolať odťahovú službu,','bezodkladne ohlásiť dopravnú nehodu príslušnej poisťovni');
INSERT INTO `Questions` VALUES (305,305,0,1,'Kde cestička pre cyklistov nie je alebo nie je zjazdná, jazdí sa na bicykli','',2,2,'po chodníku alebo po pravej krajnici,','pri pravom okraji vozovky; ak sa tým neohrozujú ani neobmedzujú chodci, smie sa jazdiť po pravej krajnici vozovky,','po chodníku, ak sa tým neohrozujú chodci');
INSERT INTO `Questions` VALUES (306,306,0,1,'V obytnej, pešej a školskej zóne chodci','',2,2,'nie sú povinní umožniť vozidlám jazdu,','sú povinní umožniť vozidlám jazdu; to platí aj pre deti, ktoré sa hrajú v obytnej zóne,','sú povinní umožniť jazdu len vozidlám pravidelnej verejnej dopravy osôb; to platí aj pre deti, ktoré sa hrajú na ceste');
INSERT INTO `Questions` VALUES (307,307,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza, vodič motorového vozidla kategórie M1 a N1 môže takéto vozidlo použiť v cestnej premávke, len ak','',2,1,'je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené na hnacej náprave zimnými pneumatikami,','má uzatvorené havarijné poistenie');
INSERT INTO `Questions` VALUES (308,308,0,1,'Pri jazde po kruhovom objazde vodič dáva znamenie o zmene smeru jazdy, ak','',2,3,'do takejto križovatky vchádza,','dôjde k núdzovému zastaveniu vozidla, alebo k dopravnej nehode,','z takej križovatky vychádza');
INSERT INTO `Questions` VALUES (309,309,0,1,'Vodič nesmie použiť','',2,3,'zimné pneumatiky v období od 15. novembra do 31. marca,','zvukové výstražné znamenie,','použiť na jazdu vozidlo, ktoré svojim farebným vyhotovením a označením sa dá zameniť s vozidlom Policajného zboru, Vojenskej polície, Železničnej polície, obecnej polície, Hasičského a záchranného zboru, alebo ostatných hasičských jednotiek');
INSERT INTO `Questions` VALUES (310,310,0,1,'Pre smer, ku ktorému stojí policajt pri riadení premávky na križovatke čelom, alebo chrbtom, znamená tento pokyn','',1,3,'„Voľno”, ak má obe ruky pripažené,','povinnosť odbočiť vpravo, alebo vľavo,','„Stoj!”; vodič je povinný zastaviť vozidlo pred hranicou križovatky');
INSERT INTO `Questions` VALUES (311,311,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,2,'najmenej dvojlitrová zásoba náplne do ostrekovačov skiel,','kľúč na matice, alebo skrutky kolies,','odrazové sklo oranžovej farby, ktoré je možné umiestniť na vozovku v prípade núdzového státia');
INSERT INTO `Questions` VALUES (312,312,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'je vybavené pneumatikami rôznych rozmerov a konštrukcií,','najnižší bod činnej svietiacej plochy brzdových svetiel je vyššie ako 350 mm nad rovinou vozovky,','nie je funkčné počítadlo prejdenej vzdialenosti');
INSERT INTO `Questions` VALUES (313,313,1,1,'Táto dopravná značka znamená','a1a',2,3,'Zákaz odbočovania vpravo,','Nebezpečné stúpanie,','Zákruta vpravo');
INSERT INTO `Questions` VALUES (314,314,1,1,'Táto dopravná značka','a7',2,1,'upozorňuje na zníženú, nespevnenú alebo inak nebezpečnú krajnicu,','upozorňuje na zvýšený alebo inak nebezpečný ľavý obrubník,','umožňuje pozdĺžne parkovanie na chodníku na ľavej strane jednosmernej cesty');
INSERT INTO `Questions` VALUES (315,315,1,1,'Táto dopravná značka označuje','a30b',2,2,'dve železničné priecestia vo vzdialenosti 80 m,','železničné priecestie viackoľajové,','miesto, kde sú v tesnej blízkosti dve križovatky');
INSERT INTO `Questions` VALUES (316,316,1,1,'Táto dopravná značka znamená','ip23a',2,1,'Diaľnica,','Podjazd alebo nadjazd,','Hlavná cesta');
INSERT INTO `Questions` VALUES (317,317,1,1,'Táto dopravná značka informuje o','is4',2,3,'názvoch najbližších výjazdov z diaľnice a o vzdialenosti k nim,','smere príjazdu na diaľnicu s uvedením cieľa,','o cieľoch a počtoch jazdných pruhov v priamom smere');
INSERT INTO `Questions` VALUES (318,318,1,1,'Táto dodatková tabuľka vyznačuje','e4',2,1,'dĺžku úseku, pre ktorý platí značka, pod ktorou je tabuľka umiestnená,','vzdialenosť k miestu, od ktorého platí značka, pod ktorou je tabuľka umiestnená,','vzdialenosť k najbližšej križovatke');
INSERT INTO `Questions` VALUES (319,319,1,1,'Ak sú touto dopravnou značkou oddelené jazdné pruhy s protismernou premávkou,','v3',2,1,'vodič sa riadi významom pravej čiary z tejto dvojice čiar,','vodič sa riadi významom ľavej čiary z tejto dvojice čiar,','riadi sa premávka v jazdných pruhoch svetelnými signálmi');
INSERT INTO `Questions` VALUES (320,320,1,1,'Táto dopravná značka','v9a',2,1,'vyznačuje spôsob radenia do jazdných pruhov a určený smer jazdy križovatkou,','vyznačuje jazdné pruhy vyhradené pre pomalé vozidlá,','je predbežnou značkou pre zmenu smeru jazdy');
INSERT INTO `Questions` VALUES (321,321,2,1,'Prednosť v jazde má vodič','321',3,1,'červeného vozidla, pretože vchádza do kruhového objazdu,','modrého vozidla, pretože prichádza zľava,','modrého vozidla, pretože ide po kruhovom objazde');
INSERT INTO `Questions` VALUES (322,322,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','322',3,1,'1. zelené, 2. modré, 3. žlté,','1. modré, 2. zelené, 3. žlté,','1. žlté, 2. zelené, 3. modré');
INSERT INTO `Questions` VALUES (323,323,2,1,'V poradí posledné prejde cez križovatku','323',3,3,'vaše vozidlo súčasne s modrým,','zelené vozidlo,','modré vozidlo súčasne s červeným');
INSERT INTO `Questions` VALUES (324,324,2,1,'Vozidlá prejdú cez križovatku v tomto poradí','324',3,2,'1. zelené, 2. vaše vozidlo súčasne so žltým, 3. červené,','1.červené, 2. zelené, 3. vaše vozidlo súčasne so žltým,','1. vaše vozidlo súčasne so žltým, 2. zelené, 3. červené.');
INSERT INTO `Questions` VALUES (325,325,0,1,'Električkovým koľajovým pásom sa rozumie','',2,1,'časť cesty určená predovšetkým na premávku električky,','časť cesty, na ktorej je povolená len premávka električky a nemotorových vozidiel,','časť cesty určená na premávku električky, vlaku a iného dráhového vozidla.');
INSERT INTO `Questions` VALUES (326,326,0,1,'Státím sa rozumie','',2,3,'prerušenie jazdy na čas nevyhnutne potrebný na urýchlené nastúpenie alebo vystúpenie prepravovaných osôb alebo na urýchlené naloženie alebo zloženie nákladu,','len také uvedenie vozidla do pokoja, ktoré nepresiahne čas 15 minút,','uvedenie vozidla do pokoja na dlhšie, ako je čas dovolený na zastavenie');
INSERT INTO `Questions` VALUES (327,327,0,1,'Vodič nesmie','',2,1,'ohroziť chodcov prechádzajúcich cez cestu, na ktorú vodič odbočuje, pri odbočovaní na miesto mimo cesty, pri vchádzaní na cestu a pri otáčaní alebo pri cúvaní,','dať prednosť chodcom prechádzajúcim cez priechod pre chodcov, ak by na ten účel musel zastaviť vozidlo,','zastaviť a stáť na účelovej komunikácii mimo obce.');
INSERT INTO `Questions` VALUES (328,328,0,1,'Pozdĺž nástupného ostrovčeka alebo ochranného ostrovčeka sa jazdí','',2,3,'vľavo; vpravo sa smie jazdiť len vtedy, ak jazde vľavo bráni prekážka,','za každých okolností vľavo,','vpravo; vľavo sa smie jazdiť len vtedy, ak jazde vpravo bráni prekážka alebo ak je to bezpečnejšie s ohľadom na rozmery vozidla alebo nákladu.');
INSERT INTO `Questions` VALUES (329,329,0,1,'V obci vodič smie jazdiť rýchlosťou najviac','',2,1,'50 km/h a ak ide po diaľnici v obci alebo po rýchlostnej ceste v obci, najviac 90 km/h,','60 km/h a ak ide po diaľnici v obci, najviac 110 km/h,','80 km/h a ak ide po diaľnici v obci, najviac 100 km/h');
INSERT INTO `Questions` VALUES (330,330,0,1,'Vodič sa nesmie otáčať a cúvať','',2,3,'na parkovisku,','v obytnej zóne,','na križovatke s riadenou premávkou; otáčať sa smie, ak to dovoľuje dopravná značka alebo dopravné zariadenie.');
INSERT INTO `Questions` VALUES (331,331,0,1,'Vodič vozidla, ktoré zastavilo alebo stálo a opäť vychádza od okraja cesty alebo od chodníka, nesmie','',2,2,'obmedziť vodičov motorových vozidiel,','ohroziť ostatných účastníkov cestnej premávky,','dávať znamenie o zmene smeru jazdy.');
INSERT INTO `Questions` VALUES (332,332,0,1,'Vodič nesmie vchádzať na železničné priecestie, ak','',2,1,'osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva znamenie na zastavenie vozidla krúžením červenou alebo žltou zástavkou,','osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva znamenie vodorovným kývaním ruky s červenou alebo so žltou zástavkou,','svieti prerušované biele svetlo');
INSERT INTO `Questions` VALUES (333,333,0,1,'Pri vlečení motorového vozidla sa smie jazdiť rýchlosťou najviac','',2,3,'70 km/h,','80 km/h,','60 km/h');
INSERT INTO `Questions` VALUES (334,334,0,1,'Ak na stojacom vozidle svieti zvláštne výstražné svetlo modrej alebo červenej farby, prípadne ich kombinácia','',2,2,'musí vodič iného vozidla znížiť rýchlosť jazdy; nesmú však za žiadnych okolností zastaviť vozidlo,','musí vodič iného vozidla zvýšiť opatrnosť, znížiť rýchlosť jazdy, prípadne zastaviť vozidlo,','nesmie vodič iného vozidla za žiadnych okolností znížiť rýchlosť jazdy ani zastaviť vozidlo');
INSERT INTO `Questions` VALUES (335,335,0,1,'Ak sa vodič motorového vozidla, ktoré je povinne vybavené bezpečnostným odevom, zdržiava na vozovke mimo vozidla počas núdzového státia, najmä pri prerušení jazdy pre chybu na vozidle alebo v dôsledku dopravnej nehody, je povinný','',2,2,'umiestniť 20 m za vozidlo biele neoslňujúce svetlo bielej farby,','mať bezpečnostný odev oblečený,','bezodkladne privolať odťahovú službu.');
INSERT INTO `Questions` VALUES (336,336,0,1,'Vodič vchádzajúci do kruhového objazdu','',2,1,'má prednosť v jazde, ak dopravnou značkou nie je ustanovené inak,','má vždy prednosť v jazde,','môže ohroziť vodiča jazdiaceho po kruhovom objazde.');
INSERT INTO `Questions` VALUES (337,337,0,1,'Ak sa chodec nachádza na vozovke a prichádzajú vozidlá s právom prednostnej jazdy,','',1,3,'nesmú ho ich vodiči obmedziť, ak prechádza cez priechod pre chodcov,','má prednosť pred týmito vozidlami, ak prechádza cez priechod pre chodcov,','musí vozidlám bez meškania uvoľniť priestor na prejazd.');
INSERT INTO `Questions` VALUES (338,338,0,1,'Povinnou výbavou motorového vozidla kategórie M, N, T, C a PS sú','',1,3,'náhradné žiarovky na vnútorné osvetlenie batožinového priestoru,','matice a skrutky na výrobcom predpísaný rozmer kolesa,','homologizovaný prenosný výstražný trojuholník');
INSERT INTO `Questions` VALUES (339,339,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'je katalyzátor výfukových plynov po lehote kalibrácie,','nie je na čelnom skle zatemňovací pás, ktorý umožňuje najmenej 50 % priepustnosti svetla,','niektorá časť výfukového systému je netesná, takže výfukové plyny vnikajú do priestoru pre cestujúcich, vodiča alebo nákladu alebo sú zdrojom nadmerného zvuku.');
INSERT INTO `Questions` VALUES (340,340,1,1,'Táto dopravná značka znamená:','a2a',2,2,'Spôsob obchádzania prekážky,','Dvojitá zákruta, prvá vpravo,','Nebezpečenstvo šmyku.');
INSERT INTO `Questions` VALUES (341,341,1,1,'Táto dopravná značka znamená:','ip3b',2,3,'Návestná smerová tabuľa,','Prikázaný smer jazdy,','Jednosmerná premávka.');
INSERT INTO `Questions` VALUES (342,342,1,1,'Táto dopravná značka znamená:','ip14b',2,1,'Parkovisko - parkovacie miesta s pozdĺžnym státím na chodníku,','Zákaz státia na chodníku,','Zvýšená krajnica.');
INSERT INTO `Questions` VALUES (343,343,1,1,'Táto dopravná značka','is1a',2,3,'informuje o názve najbližšej obce a o vzdialenosti k nej,','je návesťou pred obchádzkou,','informuje o názve a vzdialeností k najbližšej diaľničnej križovatke s uvedením čísel križujúcich komunikácií.');
INSERT INTO `Questions` VALUES (344,344,1,1,'Táto dopravná značka','c23a',2,3,'vyznačuje jazdné pruhy pre vozidlá podľa ich maximálnej konštrukčnej rýchlosti,','určuje najnižšie dovolené rýchlosti, ktorými smú jazdiť vozidlá v príslušných jazdných pruhoch,','obmedzuje najvyššie dovolené rýchlosti v príslušných jazdných pruhoch.');
INSERT INTO `Questions` VALUES (345,345,1,1,'Táto dodatková tabuľka vyznačuje','e8c',2,2,'začiatok úseku, pre ktorý platí značka, pod ktorou je tabuľka umiestnená,','koniec úseku, pre ktorý platí značka, pod ktorou je tabuľka umiestnená,','koniec úseku s jednosmernou premávkou.');
INSERT INTO `Questions` VALUES (346,346,1,1,'Táto dopravná značka','v2a',2,2,'vyznačuje okraj cesty,','vyznačuje jazdné pruhy, predchádza značke „Pozdĺžna súvislá čiara” alebo upozorňuje na nebezpečné miesta (zákrutu, križovatku a podobne),','vyznačuje úsek, kde je zakázané zastavenie a státie');
INSERT INTO `Questions` VALUES (347,347,1,1,'Táto dopravná značka vyznačuje','v12a',2,1,'priestor, kde je zakázané státie,','priestor, kde je zakázané zastavenie,','zastávku vozidiel pravidelnej verejnej dopravy osôb');
INSERT INTO `Questions` VALUES (348,348,2,1,'V poradí druhé prejde okolo prekážky','348',3,3,'žlté vozidlo,','modré vozidlo,','červené vozidlo');
INSERT INTO `Questions` VALUES (349,349,2,1,'Na tento pokyn policajta','349',3,1,'je vodič čierneho a vodič zeleného vozidla povinný zastaviť vozidlo pred hranicou križovatky,','je vodič modrého, vodič červeného a vodič žltého vozidla povinný zastaviť vozidlo pred hranicou križovatky,','smie vodič čierneho a vodič zeleného vozidla pokračovať v jazde; ak títo vodiči dodržia ustanovenia o odbočovaní, môžu odbočiť vpravo alebo vľavo');
INSERT INTO `Questions` VALUES (350,350,2,1,'Ako posledné prejde cez križovatku','350',3,1,'vaše vozidlo,','zelené vozidlo,','červené vozidlo');
INSERT INTO `Questions` VALUES (351,351,2,1,'Ako prvé prejde cez križovatku','351',3,1,'vaše vozidlo súčasne s modrým vozidlom,','vaše vozidlo súčasne so zeleným vozidlom,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (352,352,0,1,'Nemotorovým vozidlom sa rozumie','',2,2,'vozidlo pohybujúce sa pomocou ľudskej sily alebo zvieracej sily, električka a trolejbus,','vozidlo pohybujúce sa pomocou ľudskej sily alebo zvieracej sily,','aj motorové vozidlo, ktorého pohotovostná hmotnosť nepresahuje 400 kg.');
INSERT INTO `Questions` VALUES (353,353,0,1,'Vodič motocykla je povinný počas jazdy oboma rukami držať riadidlá motocykla s výnimkou prípadu, keď','',2,1,'dáva znamenie o zmene smeru jazdy,','jazdí rýchlosťou nižšou ako 50 km/h,','má dostatočnú prax vo vedení motocykla.');
INSERT INTO `Questions` VALUES (354,354,0,1,'Vodič smie dávať zvukové výstražné znamenie','',2,3,'vždy vtedy, ak je to potrebné na zabezpečenie plynulej jazdy jeho vozidla, najmä na upozornenie vodiča predchádzaného vozidla v obci,','len v obci na upozornenie vodiča predchádzaného vozidla,','len vtedy, ak je to potrebné na odvrátenie hroziaceho nebezpečenstva, a mimo obce aj na upozornenie vodiča predchádzaného vozidla');
INSERT INTO `Questions` VALUES (355,355,0,1,'Vodič nesmie použiť diaľkové svetlomety','',2,1,'ak je vozovka dostatočne a súvisle osvetlená,','pri jazde mimo obce,','za zníženej viditeľností');
INSERT INTO `Questions` VALUES (356,356,0,1,'Na diaľnici mimo obce smie vodič motorového vozidla jazdiť rýchlosťou najmenej','',2,1,'80 km/h,','60 km/h,','90 km/h');
INSERT INTO `Questions` VALUES (357,357,0,1,'Vodič motorového vozidla nesmie na diaľnici predchádzať iné motorové vozidlo','',2,2,'ak nemá rozhľad na vzdialenosť najmenej 200 m,','ak by pri predchádzaní svojou výrazne nižšou rýchlosťou obmedzil iné motorové vozidlo,','za hmly, sneženia a hustého dažďa.');
INSERT INTO `Questions` VALUES (358,358,0,1,'Vodič iného vozidla je povinný vozidlu s právom prednostnej jazdy a vozidlu, ktoré sprevádza, umožniť bezpečný a plynulý prejazd,','',2,1,'a ak je to potrebné, aj zastaviť vozidlo na takom mieste, aby im neprekážalo,','len ak ho na to upozornia zapínaním diaľkových svetlometov,','len ak tak urobia aj pred ním jazdiaci vodiči.');
INSERT INTO `Questions` VALUES (359,359,0,1,'Prekážka cestnej premávky sa označuje','',2,3,'len za zníženej viditeľnosti,','len vtedy, ak ju tvorí motorové vozidlo,','najmä zábranou na označenie uzávierky, výstražným svetlom oranžovej farby, za zníženej viditeľnosti aj červeným svetlom alebo reflexnou červenou zastávkou.');
INSERT INTO `Questions` VALUES (360,360,0,1,'Za prepravu detí alebo osôb, ktoré pre poruchu zdravia nezodpovedajú za svoje konanie, zodpovedá','',2,1,'osoba, ktorá ich sprevádza,','zákonný zástupca,','osoba pribratá na zaistenie bezpečnosti a plynulosti cestnej premávky alebo niektorých jazdných úkonov.');
INSERT INTO `Questions` VALUES (361,361,0,1,'Vodič, ktorý sa zúčastnil na dopravnej nehode, je povinný','',2,2,'zdržať sa požitia alkoholu alebo inej návykovej látky do príchodu odťahovej služby,','zdržať sa požitia alkoholu alebo inej návykovej látky po nehode v čase, keď by to bolo na ujmu zistenia, či pred jazdou alebo počas jazdy požil alkohol alebo inú návykovú látku,','zdržať sa požitia alkoholu alebo inej návykovej látky do príchodu odbornej zdravotníckej pomoci.');
INSERT INTO `Questions` VALUES (362,362,0,1,'Sprievodca vedených alebo hnaných zvierat je oprávnený dávať pokyny na zastavenie vozidla,','',2,2,'len ak vedie viac ako 50 zvierat,','ak to vyžaduje bezpečnosť cestnej premávky,','ak to vyžaduje plynulosť cestnej premávky alebo ak potrebuje získať informácie od protijazdiacich vodičov o situácii na ceste pred ním.');
INSERT INTO `Questions` VALUES (363,363,0,1,'Ak policajt vztýči ruku alebo predlaktie pravej ruky so smerovkou, znamená tento pokyn','',2,3,'„Stoj!” pre smer, ku ktorému stojí čelom alebo chrbtom,','„Voľno" pre smer, ku ktorému stojí bokom,','„Pozor!”; vodič vozidla idúceho zo smeru, v ktorom bola predtým premávka zastavená, je povinný pripraviť sa na jazdu; vodič vozidla idúceho v smere, ktorý bol predtým voľný, je povinný zastaviť vozidlo pred hranicou križovatky; ak je už tak blízko, že by ');
