INSERT INTO `Questions` VALUES (381,381,0,1,'Ak vodič zníži rýchlosť jazdy alebo ak zastaví vozidlo pred priechodom pre chodcov, aby umožnil prejsť cez cestu chodcom, vodiči ostatných vozidiel idúcich rovnakým smerom sú','',2,2,'povinní dávať zvukové výstražné znamenia počas jazdy cez takýto priechod v obci,','takisto povinní znížiť rýchlosť jazdy alebo zastaviť vozidlo; to neplatí pre vodiča električky,','takisto povinní znížiť rýchlosť jazdy, len ak cez priechod prechádzajú osoby s ťažkým zdravotným postihnutím alebo staré osoby');
