INSERT INTO `Questions` VALUES (407,407,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza, vodič motorového vozidla kategórie Mi a Ni môže takéto vozidlo použiť v cestnej premávke, len ak','',2,3,'má uzatvorené havarijné poistenie,','je toto vybavené na hnacej náprave zimnými pneumatikami,','je toto vybavené na všetkých nápravách zimnými pneumatikami.');
INSERT INTO `Questions` VALUES (408,408,0,1,'Tam, kde sa dva jazdné pruhy zbiehajú do jedného jazdného pruhu tak, že nie je zrejmé, ktorý z nich je priebežný,','',2,2,'vodič jazdiaci v pravom jazdnom pruhu je povinný dať prednosť v jazde vodičovi jazdiacemu v ľavom jazdnom pruhu,','vodič jazdiaci v ľavom jazdnom pruhu je povinný dať prednosť vjazde vodičovi v pravom jazdnom pruhu; to neplatí, ak ide o striedavé radenie upravené príslušnou dopravnou značkou,','má prednosť v jazde vozidlo idúce vyššou rýchlosťou.');
