INSERT INTO `Questions` VALUES (412,412,0,1,'Vodič nesmie vchádzať na železničné priecestie, ak','',2,1,'osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva znamenie na zastavenie vozidla krúžením červenou alebo žltou zastávkou,','osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva znamenie vodorovným kývaním ruky s červenou alebo žltou zástavkou,','svieti prerušované biele svetlo.');
