INSERT INTO `Questions` VALUES (415,415,0,1,'Ak motorové vozidlo povinne vybavené prenosným výstražným trojuholníkom počas núdzového státia na diaľnici alebo na rýchlostnej ceste stojí na krajnici alebo na vozovke, vodič je povinný trojuholník','',2,2,'umiestniť vo vzdialenosti najmenej 50 m za vozidlom,','umiestniť vo vzdialenosti najmenej 100 m za vozidlom,','umiestniť vo vzdialenosti 100 m za vozidlom len za zníženej viditeľnosti.');
INSERT INTO `Questions` VALUES (416,416,0,1,'V motorovom vozidle alebo jeho prípojnom vozidle, ktoré je určené na dopravu osôb, smú sa na miestach na to vyhradených prepravovať osoby','',2,2,'len do prípustnej užitočnej hmotnosti, pričom počet prepravovaných osôb starších ako 21 rokov nesmie byť vyšší, ako je počet miest uvedených v osvedčení o evidencii,','len do prípustnej užitočnej hmotnosti vozidla, pritom počet prepravovaných osôb nesmie byť vyšší, ako je počet miest uvedených v osvedčení o evidencii,','staršie ako 15 rokov.');
INSERT INTO `Questions` VALUES (417,417,0,1,'Ak pri jazde vozidla v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným, alebo ak vznikne dopravná nehoda vrátane požiaru, je vodič po zastavení vozidla povinný bezodkladne','',2,1,'vypnúť motor,','oznámiť zastavenie vozidla príslušnému obvodnému úradu,','vypnúť stretávacie svetlomety.');
INSERT INTO `Questions` VALUES (418,418,0,1,'Cyklisti smú jazdiť','',1,3,'najviac dvaja vedľa seba,','bez držania riadidiel, ak v blízkosti nie sú motorové vozidlá,','len jednotlivo za sebou.');
INSERT INTO `Questions` VALUES (419,419,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,3,'ťažná tyč s minimálnou dĺžkou 6 m určená na vlečenie vozidiel,','ťažné lano; to platí aj pre jednostopové motorové vozidlá,','príručný zdvihák s nosnosťou rovnajúcou sa aspoň zaťaženiu najviac zaťaženej nápravy vozidla alebo rovnajúcou sa hmotnosti zdvíhanej časti vozidla z najväčšej prípustnej celkovej hmotnosti vozidla pri zdvíhaní tejto časti spôsobom určeným výrobcom na použ');
INSERT INTO `Questions` VALUES (420,420,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'je na zadnom skle použitá schválená fólia,','mazivo používané vo vozidle nie je schválené výrobcom,','zjavne uniká palivo, olej, mazivo alebo iné prevádzkové náplne z vozidla.');
INSERT INTO `Questions` VALUES (421,421,1,1,'Táto dopravná značka upozorňuje na','a21',2,1,'úsek cesty, kde je rozdiel od predchádzajúceho úseku v príslušnej časti vozovky dočasná alebo trvalá premávka v oboch smeroch','úsek cesty, kde je premávka riadená striedavo','miesto, kde má vodič prednosť pred protiidúcim vodičom');
INSERT INTO `Questions` VALUES (422,422,1,1,'Táto dopravná značka upozorňuje, ak je to potrebné v záujme bezpečnosti cestnej premávky,','a22',2,1,'najmä na miesto, kde električka križuje smer jazdy ostatných vozidiel,','na konečnú zastávku električky,','na zastávku električky bez nástupného ostrovčeka.');
INSERT INTO `Questions` VALUES (423,423,1,1,'Táto dopravná značka znamená:','b2',2,3,'Zákaz vjazdu nemotorových vozidiel,','Zúžená vozovka,','Zákaz vjazdu všetkých vozidiel.');
INSERT INTO `Questions` VALUES (424,424,1,1,'Táto dopravná značka prikazuje vodičovi','c17',2,1,'na takto označenom úseku rozsvietiť na idúcom vozidle ustanovené osvetlenie,','použiť svetelné výstražné znamenie,','pri zastavení alebo státí použiť výstražnú funkciu smerových svietidiel.');
INSERT INTO `Questions` VALUES (425,425,1,1,'Táto dopravná značka znamená:','is31',2,1,'Medzinárodná trasa.','Najvyššia dovolená rýchlosť.','Cesta II. triedy.');
INSERT INTO `Questions` VALUES (426,426,1,1,'Táto dopravná značka znamená:','c30',2,3,'Dopravná nehoda,','Zníženie počtu jazdných pruhov,','Striedavé radenie.');
INSERT INTO `Questions` VALUES (427,427,1,1,'Táto dopravná značka znamená:','is33',2,2,'Označenie začiatku obce,','Hranica kraja,','Návesť pred križovatkou.');
INSERT INTO `Questions` VALUES (428,428,1,1,'Táto dopravná značka znamená:','ip32',2,2,'Nebezpečenstvo hmly,','Bezpečná vzdialenosť,','Optická psychologická brzda.');
INSERT INTO `Questions` VALUES (429,429,2,1,'Ako druhé vojde do križovatky','429',3,2,'modré vozidlo','zelené vozidlo','červené vozidlo');
INSERT INTO `Questions` VALUES (430,430,2,1,'Ako posledné prejde cez križovatku','430',3,1,'žlté vozidlo','zelené vozidlo','modré vozidlo');
INSERT INTO `Questions` VALUES (431,431,2,1,'Vaše vozidlo prejde cez križovatku ako','431',3,3,'prvé,','posledné,','druhé.');
INSERT INTO `Questions` VALUES (432,432,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','432',3,3,'1. vaše vozidlo, 2, červené, 3. zelené, 4. modré,','1. červené, 2. vaše vozidlo, 3. zelené, 4. modré,','1. vaše vozidlo, 2. červené, 3. modré, 4. zelené.');
INSERT INTO `Questions` VALUES (433,433,0,1,'Vozovkou sa rozumie','',2,1,'spevnená časť cesty určená predovšetkým na premávku motorových vozidiel,','časť cesty určená len na premávku nemotorových vozidiel,','cesta vrátane krajnice a chodníka.');
INSERT INTO `Questions` VALUES (434,434,0,1,'Motorové vozidlo musí mať počas jazdy rozsvietené','',2,3,'svetlá vo vnútri vozidla,','diaľkové svetlomety,','stretávacie svetlomety alebo im na roveň postavené osvetlenie.');
INSERT INTO `Questions` VALUES (435,435,0,1,'Vodič nesmie viesť vozidlo','',2,2,'po požití lieku v čase, keď liek môže znížiť jeho schopnosť viesť vozidlo; to neplatí, ak je jeho spolujazdcom lekár,','po požití lieku v čase, keď liek môže znížiť jeho schopnosť viesť vozidlo,','ak nemá pri sebe lieky, ktoré pravidelne užíva.');
INSERT INTO `Questions` VALUES (436,436,0,1,'Osoba sediaca na sedadle povinne vybavenom bezpečnostným pásom alebo iným zadržiavacím zariadením','',2,3,'je povinná toto zariadenie použiť pri jazde mimo obce,','je povinná toto zariadenie použiť pri jazde rýchlosťou vyššou ako 40 km/h,','je povinná toto zariadenie použiť.');
INSERT INTO `Questions` VALUES (437,437,0,1,'Vodič nesmie pri predchádzaní ohroziť ani obmedziť vodičov vozidiel, pred ktoré sa po predídení zaraďuje; pritom je povinný dávať','',2,2,'v obci zvukové výstražné znamenie na upozornenie vodiča predchádzaného vozidla,','znamenie o zmene smeru jazdy,','znamenie o zmene smeru jazdy len za zníženej viditeľnosti.');
INSERT INTO `Questions` VALUES (438,438,0,1,'Pred odbočovaním vľavo vodič je povinný zaradiť sa','',2,1,'čo najďaľej vľavo v časti vozovky určenej pre jeho smer jazdy s ohľadom na rozmery vozidla alebo nákladu a šírku vozovky,','čo najďalej vpravo v častí vozovky určenej pre jeho smer jazdy,','na pravú krajnicu.');
INSERT INTO `Questions` VALUES (439,439,0,1,'Pri zastavení musí zostať voľný aspoň jeden jazdný pruh široký najmenej','',2,1,'3 m pre oba smery jazdy,','3 m pre každý smer jazdy,','2 m.');
INSERT INTO `Questions` VALUES (440,440,0,1,'Vodič nesmie vchádzať na železničné priecestie, ak','',2,2,'protiidúci vodič dáva zvukové výstražné znamenie,','sa dáva výstraha prerušovaným zvukom húkačky alebo zvončeka priecestného zabezpečovacieho zariadenia,','osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva pokyn vodorovným kývaním ruky s červenou alebo žltou zástavkou');
INSERT INTO `Questions` VALUES (441,441,0,1,'Znamenie o zmene smeru jazdy vodič je povinný dávať','',2,3,'len pri zmene smeru jazdy; vodič, ktorý pri predchádzaní vybočuje zo smeru svojej jazdy, nie je povinný dávať znamenie o zmene smeru svojej jazdy,','vždy pri prechádzaní cez železničné priecestie,','vždy pri zmene smeru jazdy alebo vybočovaní z neho alebo ak to vyžaduje bezpečnosť alebo plynulosť cestnej premávky.');
INSERT INTO `Questions` VALUES (442,442,0,1,'Ak ten, kto prekážku cestnej premávky spôsobil, ju bezodkladne neodstráni, je povinný ju označiť','',2,3,'len za zníženej viditeľnosti,','len vtedy, ak prekážku spôsobil na diaľnici alebo na rýchlostnej ceste,','a oznámiť to policajtovi.');
INSERT INTO `Questions` VALUES (443,443,0,1,'Vodič vchádzajúci do kruhového objazdu','',2,1,'má prednosť v jazde, ak dopravnou značkou nieje ustanovené inak,','má vždy prednosť v jazde,','môže ohroziť vodiča jazdiaceho po kruhovom objazde.');
INSERT INTO `Questions` VALUES (444,444,0,1,'V motorovom vozidle, ktoré je určené na dopravu osôb, smú sa na miestach na to vyhradených prepravovať osoby','',2,3,'staršie ako 15 rokov s telesnou výškou väčšou ako 160 cm,','len do prípustnej užitočnej hmotnosti vozidla, pritom počet prepravovaných osôb môže byť vyšší, ako je počet miest uvedených v osvedčení o evidencii,','len do prípustnej užitočnej hmotnosti vozidla, pritom počet prepravovaných osôb nesmie byť vyšší, ako je počet miest uvedených v osvedčení o evidencii.');
INSERT INTO `Questions` VALUES (445,445,0,1,'Osoba, ktorá tlačí bicykel alebo motocykel,','',1,3,'smie použiť chodník, len ak v blízkosti nie sú žiadni chodci,','nesmie použiť chodník a musí použiť ľavú krajnicu,','smie použiť chodník, len ak neohrozí ani neobmedzí chodcov; inak musí použiť pravú krajnicu alebo pravý okraj vozovky.');
INSERT INTO `Questions` VALUES (446,446,0,1,'Povinnou výbavou motorového vozidla sú','',1,3,'najmenej dvojlitrová zásoba maziva a najmenej dvojlitrová zásoba chladiacej kvapaliny v osobitných nádobách; to neplatí pre jednostopové motorové vozidlá,','matice a skrutky umožňujúce upevnenie výstražného zariadenia na vozidle,','v závislosti od kategórie vozidla predpísaná motolekárnička alebo autolekárnička, ktoré musia byť v stave použiteľnosti.');
INSERT INTO `Questions` VALUES (447,447,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'sú poškodené lapače nečistôt,','nie je funkčné počítadlo prejdenej vzdialenosti,','sú na tej istej náprave použité pneumatiky, ktoré nie sú zhodné.');
INSERT INTO `Questions` VALUES (448,448,1,1,'Tieto dopravné značky upozorňujú na','spec31',2,2,'železničné priecestie so závorami vo vzdialenosti 180 m,','železničné priecestie so závorami vo vzdialenosti 240 m,','železničné priecestie bez závor vo vzdialenosti 200 m.');
INSERT INTO `Questions` VALUES (449,449,1,1,'Táto dopravná značka zakazuje vjazd','b21',2,1,'vozidlám prepravujúcim výbušniny, ľahko horľavé alebo inak nebezpečné veci,','obytným automobilom,','skriňovým vozidlám.');
INSERT INTO `Questions` VALUES (450,450,1,1,'Táto dopravná značka znamená:','b19',2,1,'Zákaz jazdy motorových vozidiel vo vzdialenosti kratšej ako je vyznačené,','Zákaz státia motorových vozidiel, ktoré nedodržia vyznačený odstup,','Prikázaná jazda vozidiel v kolóne.');
INSERT INTO `Questions` VALUES (451,451,1,1,'Táto dopravná značka označuje','p2',2,3,'zastávku pravidelnej verejnej dopravy osôb,','slepú cestu,','vedľajšiu cestu; na príkaz tejto značky je vodič povinný zastaviť vozidlo na takom mieste, odkiaľ má na križovatku náležitý rozhľad.');
INSERT INTO `Questions` VALUES (452,452,1,1,'Táto dopravná značka znamená:','ip23b',2,3,'Zákaz otáčania sa na diaľnici,','Koniec hlavnej cesty,','Koniec diaľnice.');
INSERT INTO `Questions` VALUES (453,453,1,1,'Táto dopravná značka','is3',2,3,'vyznačuje zníženie počtu jazdných pruhov,','je návesťou pred obchádzkou,','informuje na diaľnici a rýchlostnej ceste o smeroch k vyznačeným cieľom a o počte a usporiadaní jazdných pruhov.');
INSERT INTO `Questions` VALUES (454,454,1,1,'Táto dopravná značka znamená:','is25',2,3,'Smerová tabuľa na vyznačenie príjazdu k rýchlostnej ceste,','Smerová tabuľa na vyznačenie jednosmernej premávky,','Smerová tabuľa na vyznačenie obchádzky.');
INSERT INTO `Questions` VALUES (455,455,1,1,'Táto dopravná značka','v5c',2,1,'vyznačuje miesto, kde je vodič povinný zastaviť vozidlo na príkaz značky "Stoj, daj prednosť v jazde!",','vyznačuje parkovisko s pozdĺžnym státím,','prikazuje vodičovi motorového vozidla vypnúť motor.');
INSERT INTO `Questions` VALUES (456,456,2,1,'Červené vozidlo prejde cez križovatku ako','456',3,2,'posledné,','druhé,','prvé.');
INSERT INTO `Questions` VALUES (457,457,2,1,'Ako prvé prejde cez križovatku','457',3,1,'zelené vozidlo,','modré vozidlo,','červené vozidlo,');
INSERT INTO `Questions` VALUES (458,458,2,1,'Ako posledné prejde cez križovatku','458',3,3,'žlté vozidlo,','vaše vozidlo,','červené vozidlo.');
INSERT INTO `Questions` VALUES (459,459,2,1,'V poradí druhé prejde cez križovatku','459',3,1,'červené vozidlo,','vaše vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (460,460,0,1,'Križovatkou sa rozumie','',2,1,'miesto, v ktorom sa cesty pretínajú alebo spájajú,','mimoúrovňové kríženie cesty so železnicou,','miesto, v ktorom cesta mení smer.');
INSERT INTO `Questions` VALUES (461,461,0,1,'Zastavením vozidla sa rozumie','',2,3,'každé prerušenie jazdy,','uvedenie motorového vozidla do pokoja na čas nevyhnutne potrebný na urýchlené nastúpenie alebo vystúpenie prepravovaných osôb,','prerušenie jazdy z dôvodu nezávislého od vôle vodiča.');
INSERT INTO `Questions` VALUES (462,462,0,1,'Vodič je povinný','',2,2,'dať prednosť v jazde cyklistovi jazdiacemu po priechode pre cyklistov, len ak je takýto priechod vybavený svetelným signalizačným zariadením,','dať prednosť v jazde cyklistovi jazdiacemu po priechode pre cyklistov,','prekážať v jazde rýchlejšie idúcim vozidlám,');
INSERT INTO `Questions` VALUES (463,463,0,1,'Vozidlá môžu ísť súbežne vedľa seba,','',2,3,'len ak jazdia po jednosmernej ceste s dvoma jazdnými pruhmi v obci,','len ak jazdia po diaľnici a po rýchlostnej ceste,','ak je na ceste s dvoma alebo s viacerými jazdnými pruhmi v jednom smere jazdy taká hustá premávka, že sa utvoria súvislé prúdy vozidiel, v ktorých vodič motorového vozidla môže jazdiť');
INSERT INTO `Questions` VALUES (464,464,0,1,'Vodič v úseku zastávky vozidiel pravidelnej verejnej dopravy osôb','',2,1,'je povinný dbať na zvýšenú opatrnosť,','je povinný zastaviť vozidlo,','je povinný zapnúť zariadenie umožňujúce výstražnú funkciu smerových svietidiel.');
INSERT INTO `Questions` VALUES (465,465,0,1,'Ak sa vodiči protiidúcich vozidiel nemôžu bezpečne vyhnúť, prednosť v jazde je povinný dať ten vodič,','',2,1,'na ktorého strane jazdy je prekážka alebo zúžená vozovka,','na ktorého strane nie je zúžená vozovka,','ktorý prichádza k prekážke nižšou rýchlosťou.');
INSERT INTO `Questions` VALUES (466,466,0,1,'Vodič pri vchádzaní na cestu z obytnej zóny alebo pešej zóny','',2,2,'nie je povinný dať prednosť v jazde vozidlu idúcemu po ceste,','je povinný dať prednosť v jazde vozidlu idúcemu po ceste,','je povinný dať prednosť v jazde len vozidlu idúcemu po ceste zľava.');
INSERT INTO `Questions` VALUES (467,467,0,1,'Osoby sa môžu pohybovať po vozovke v tuneli len','',2,3,'v čase od 00.00 hod. do 04.00 hod.','po pravej krajnici,','v súvislosti so zaisťovaním bezpečnosti cestnej premávky, ak majú na sebe reflexný bezpečnostný odev.');
INSERT INTO `Questions` VALUES (468,468,0,1,'Účastník dopravnej nehody je povinný','',2,2,'zotrvať na mieste dopravnej nehody, to neplatí, ak preukázal svoju totožnosť ostatným účastníkom dopravnej nehody,','zotrvať na mieste dopravnej nehody až do príchodu policajta alebo sa na toto miesto bezodkladne vrátiť po poskytnutí alebo privolaní pomoci, alebo po ohlásení dopravnej nehody,','zotrvať na mieste dopravnej nehody až do príchodu odťahovej služby.');
INSERT INTO `Questions` VALUES (469,469,0,1,'Chodci, ktorí prechádzajú cez priechod určený pre chodcov,','',2,3,'majú prednosť pred vozidlami s právom prednostnej jazdy,','nesmú fajčiť,','musia brať ohľad na vodičov prichádzajúcich vozidiel najmä tým, že neprechádzajú jednotlivo, ale v skupinách.');
INSERT INTO `Questions` VALUES (470,470,0,1,'Dávať pokyny na zastavenie vozidla je oprávnený','',2,3,'chodec idúci po pravej krajnici,','pracovník obvodného úradu,','osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia.');
INSERT INTO `Questions` VALUES (471,471,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza, vodič motorového vozidla kategórie M1 a N1 môže takéto vozidlo použiť v cestnej premávke, len ak','',2,3,'má uzatvorené havarijné poistenie,','je toto vybavené na hnacej náprave zimnými pneumatikami,','je toto vybavené na všetkých nápravách zimnými pneumatikami.');
INSERT INTO `Questions` VALUES (472,472,0,1,'Ak policajt pri riadení premávky dáva pokyn kývaním ruky hore a dolu, znamená to','',1,2,'zastaviť vozidlo,','spomaliť jazdu,','zrýchliť jazdu.');
INSERT INTO `Questions` VALUES (473,473,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'niektoré svetelné zariadenie dôležité pre bezpečnosť premávky na pozemných komunikáciách chýba alebo je nesprávne umiestnené, nesvieti alebo nespĺňa ustanovené podmienky, takže hrozí bezprostredné nebezpečenstvo,','najvyšší bod činnej svietiacej plochy brzdových svetiel je nižšie ako 1500 mm nad rovinou vozovky,','nie je vybavené zariadením na spájanie vozidiel.');
INSERT INTO `Questions` VALUES (474,474,0,1,'Povinnou výbavou motorového vozidla kategórie M, N, T, C a PS sú','',1,3,'najmenej desaťlitrová zásoba pohonných hmôt a najmenej dvojlitrová zásoba chladiacej kvapaliny v osobitných nádobách; to neplatí pre jednostopové motorové vozidlá,','matice a skrutky na výrobcom predpísaný rozmer kolesa,','homologizovaný prenosný výstražný trojuholník,');
INSERT INTO `Questions` VALUES (475,475,1,1,'Táto dopravná značka s dodatkovou tabuľkou znamená:','spec6',2,2,'Spôsob obchádzania štyroch prekážok,','Štyri zákruty, prvá vpravo,','Nebezpečenstvo šmyku v úseku 4 km.');
INSERT INTO `Questions` VALUES (476,476,1,1,'Táto dopravná značka znamená:','b23',2,3,'Zákaz státia vozidiel, ktorých šírka presahuje vyznačenú hranicu; pritom je rozhodujúca okamžitá šírka vrátane nákladu,','Zákaz vjazdu vozidiel užších ako 2,5 m,','Zákaz vjazdu vozidiel, ktorých šírka presahuje vyznačenú hranicu; pritom je rozhodujúca okamžitá šírka vrátane nákladu.');
INSERT INTO `Questions` VALUES (477,477,1,1,'Táto dopravná značka znamená:','b28',2,1,'Zákaz otáčania,','Koniec zákazu otáčania,','Prikázaný smer jazdy.');
INSERT INTO `Questions` VALUES (478,478,1,1,'Táto dopravná značka znamená:','c13',2,1,'Cestička pre vyznačených užívateľov; prikazuje chodcom a cyklistom použiť v predmetnom smere takto označený spoločný pruh alebo cestičku; chodci a cyklisti sa nesmú navzájom ohroziť,','Zákaz vstupu chodcov a cyklistov,','Cestička k predajni bicyklov.');
INSERT INTO `Questions` VALUES (479,479,1,1,'Táto dopravná značka znamená:','ip22b',2,2,'Koniec parkoviska,','Koniec rýchlostnej cesty,','Koniec vyhradeného jazdného pruhu.');
INSERT INTO `Questions` VALUES (480,480,1,1,'Táto dopravná značka','is16',2,1,'informuje o smere a priebehu obchádzky alebo odklonovej trasy z dôvodu uzavretia pozemnej komunikácie,','vyznačuje zónu s dopravným obmedzením začínajúcu od tejto dopravnej značky,','informuje o dopravnom obmedzení v časti obce.');
INSERT INTO `Questions` VALUES (481,481,1,1,'Táto dopravná značka znamená:','v10c',2,2,'Zákaz státia,','Parkovacie miesta s pozdĺžnym státím,','Zastávka autobusov alebo trolejbusov.');
INSERT INTO `Questions` VALUES (482,482,1,1,'Táto dodatková tabulka označuje:','e15',2,2,'vyhradené parkovacie miesto pre vozidlá vedené osobou sluchovo postihnutú,','vyhradené parkovacie miesto pre osobu so zdravotným postihnutím,','obytnú zónu.');
INSERT INTO `Questions` VALUES (483,483,2,1,'Zelené vozidlo prejde cez križovatku ako','483',3,3,'tretie,','druhé,','prvé.');
