INSERT INTO `Questions` VALUES (485,485,2,1,'Ako posledné prejde cez križovatku','485',3,1,'červené vozidlo,','vaše vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (486,486,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','486',3,1,'1. červené, 2, vaše vozidlo, 3. žlté, 4. zelené,','1. vaše vozidlo, 2. červené, 3. žlté, 4. zelené,','1. žlté, 2. zelené, 3. červené, 4. vaše vozidlo.');
INSERT INTO `Questions` VALUES (487,487,0,1,'Autobusom sa rozumie','',2,1,'motorové vozidlo na dopravu osôb, ktoré má okrem miesta pre vodiča viac ako osem miest na sedenie,','motorové a nemotorové vozidlo, ktoré má okrem miesta pre vodiča viac ako tri miesta na sedenie,','každé vozidlo určené na dopravu viac ako štyroch osôb.');
INSERT INTO `Questions` VALUES (488,488,0,1,'Motorové vozidlo musi mať počas jazdy rozsvietené','',2,1,'stretávacie svetlomety alebo im na roveň postavené osvetlenie,','diaľkové svetlomety,','svetlá vo vnútri vozidla.');
INSERT INTO `Questions` VALUES (489,489,0,1,'Ak vodič počas jazdy zisti, že vozidlo, náklad alebo upevnenie nákladu nespĺňajú ustanovené podmienky,','',2,1,'je povinný chybu odstrániť na mieste; ak to nemôže urobiť, smie v jazde pokračovať primeranou rýchlosťou len do najbližšieho miesta, kde možno chybu odstrániť,','je povinný zapnúť predné svetlomety do hmly,','smie pokračovať v jazde k najbližšej čerpacej stanici.');
INSERT INTO `Questions` VALUES (490,490,0,1,'Vodič vozidla, ktorý pri obchádzaní vozidla, ktoré zastavilo alebo stojí, vybočuje zo smeru svojej jazdy,','',2,1,'je povinný dávať znamenie o zmene smeru jazdy,','môže obmedziť protiidúcich vodičov,','nie je povinný dávať znamenie o zmene smeru jazdy.');
INSERT INTO `Questions` VALUES (491,491,0,1,'Vodič je povinný za vozidlom idúcim pred ním','',2,3,'jazdiť vo vzdialenosti najmenej 40 m,','dodržiavať takú vzdialenosť, aby zreteľne videl v ňom sediace osoby,','dodržiavať takú vzdialenosť, aby mohol včas znížiť rýchlosť jazdy, prípadne zastaviť vozidlo, ak vodič vozidla jazdiaceho pred ním zníži rýchlosť jazdy alebo zastaví.');
INSERT INTO `Questions` VALUES (492,492,0,1,'Vodič nesmie zastaviť a stáť','',2,1,'v neprehľadnej zákrute a v jej tesnej blízkosti,','v žiadnej zákrute a v jej tesnej blízkosti,','v obci na križovatke tvaru "T" na náprotivnej strane vyúsťujúcej cesty.');
INSERT INTO `Questions` VALUES (493,493,0,1,'Ak osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva pokyn na jazdu cez železničné priecestie vodorovným kývaním ruky s červenou alebo so žltou zástavkou a za zníženej viditeľnosti bielym svetlom cez stred tela, vodič','',2,2,'nie je povinný ju poslúchnuť,','je povinný ju poslúchnuť,','je povinný pred vojdením na železničné priecestie vždy zastaviť pri tejto osobe.');
INSERT INTO `Questions` VALUES (494,494,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza, vodič motorového vozidla kategórie M1 a N1 môže takéto vozidlo použiť v cestnej premávke, len ak','',2,1,'je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené na hnacej náprave zimnými pneumatikami,','má uzatvorené havarijné poistenie.');
INSERT INTO `Questions` VALUES (495,495,0,1,'Ak na stojacom vozidle svieti zvláštne výstražné svetlo modrej alebo červenej farby, prípadne ich kombinácia musí vodič iného vozidla','',2,3,'zvýšiť rýchlosť jazdy,','bezodkladne zastaviť vozidlo,','zvýšiť opatrnosť, znížiť rýchlosť jazdy, prípadne zastaviť vozidlo.');
INSERT INTO `Questions` VALUES (496,496,0,1,'Vodič motorového vozidla nesmie predchádzať iné motorové vozidlo na diaľnici,','',2,2,'ak by pri predchádzaní neobmedzil iné motorové vozidlo idúce po diaľnici,','ak by pri predchádzaní svojou výrazne nižšou rýchlosťou obmedzil iné motorové vozidlo idúce po diaľnici,','ak nemá rozhľad na vzdialenosť 200 metrov.');
INSERT INTO `Questions` VALUES (497,497,0,1,'Vodič je povinný bezodkladne vypnúť motor, a ak je na vykurovanie vozidla použité nezávislé kúrenie, vypnúť aj toto kúrenie, ak','',2,3,'zastavil vozidlo pred železničným priecestím, kde sa dáva výstraha dvoma červenými striedavo prerušovanými svetlami priecestného zabezpečovacieho zariadenia,','zastavil na parkovisku,','pri jazde v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným.');
INSERT INTO `Questions` VALUES (498,498,0,1,'Do pešej zóny je povolený vjazd len vozidlám,','',2,2,'ktorých najväčšia prípustná celková hmotnosť nepresahuje 3 500 kg,','ktorým to umožňuje dopravná značka,','vedených vodičom začiatočníkom.');
INSERT INTO `Questions` VALUES (499,499,0,1,'Ak sa pri vlečení motorového vozidla použije lano,','',1,1,'nesmie byť vzdialenosť medzi vozidlami menšia ako 2,5 m,','nesmie byť vzdialenosť medzi vozidlami menšia ako 2 m,','jeho dĺžka nesmie byť menšia ako 1,5 m.');
INSERT INTO `Questions` VALUES (500,500,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,3,'doplnkové zabezpečovacie elektronické alebo mechanické zariadenie,','doplnkové výstražné zariadenie umiestnené v zadnej časti vozidla,','v závislosti od kategórie vozidla predpísaná autolekárnička.');
INSERT INTO `Questions` VALUES (501,501,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,2,'je poškodený lak na zadnom nárazníku,','výhľad z miesta vodiča je obmedzený alebo znemožnený,','sa z miesta vodiča nedá nastaviť pravé predné zrkadlo.');
INSERT INTO `Questions` VALUES (502,502,1,1,'Tieto dopravné značky upozorňujú na','spec32',2,3,'železničné priecestie bez závor vo vzdialenosti 180 m,','železničné priecestie so závorami vo vzdialenosti 200 m,','železničné priecestie bez závor vo vzdialenosti 240 m.');
INSERT INTO `Questions` VALUES (503,503,1,1,'Táto dopravná značka znamená:','b32a',2,3,'Koniec zákazu zvukových výstražných znamení,','Zákaz vjazdu vozidiel spôsobujúcich nadmerný hluk,','Zákaz zvukových výstražných znamení.');
INSERT INTO `Questions` VALUES (504,504,1,1,'Táto dopravná značka','b38',2,2,'zakazuje vojsť do hraničného pásma,','zakazuje pokračovať v jazde bez zastavenia vozidla na cestnom hraničnom priechode,','prikazuje vodičovi podrobiť sa colnej kontrole.');
INSERT INTO `Questions` VALUES (505,505,1,1,'Táto dopravná značka','is14',2,3,'vyznačuje hlavnú cestu,','vyznačuje spôsob radenia sa pred križovatkou,','informuje o križovatke, na ktorej je zakázané odbočovať vľavo.');
INSERT INTO `Questions` VALUES (506,506,1,1,'Táto dopravná značka znamená:','is20a',2,2,'Rýchlostná cesta,','Smerová tabuľa pre príjazd k rýchlostnej ceste,','Zákaz vjazdu osobných automobilov.');
INSERT INTO `Questions` VALUES (507,507,1,1,'Táto dopravná značka vyznačuje','c22b',2,3,'prikázaný smer jazdy,','spôsob zaraďovania sa vozidiel pred križovatkou,','úsek cesty, kde dochádza k zníženiu počtu jazdných pruhov v smere jazdy.');
INSERT INTO `Questions` VALUES (508,508,1,1,'Táto dopravná značka znamená:','is37b',2,3,'Označenie hranice kraja v jazyku národnostnej menšiny,','Označenie konca hranice okresu v jazyku národnostnej menšiny,','Označenie konca obce v jazyku národnostnej menšiny.');
INSERT INTO `Questions` VALUES (509,509,1,1,'Táto dodatková tabuľka','p14',2,2,'vyznačuje tvar kríženia cesty so železnicou.','vyznačuje skutočný tvar križovatky a aj hlavnú a vedľajšiu cestu,','zakazuje na diaľnici a na rýchlostnej ceste prechádzať stredný deliaci pás.');
INSERT INTO `Questions` VALUES (510,510,2,1,'Ako posledné prejde cez križovatku','510',3,1,'červené vozidlo súčasne s modrým,','zelené vozidlo súčasne s červeným,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (511,511,2,1,'V poradi tretie prejde okolo prekážky','511',3,3,'zelené vozidlo,','červené vozidlo,','žlté vozidlo.');
INSERT INTO `Questions` VALUES (512,512,2,1,'Vaše vozidlo, odbočujúce vľavo, prejde cez križovatku ako','512',3,3,'prvé,','tretie,','druhé.');
INSERT INTO `Questions` VALUES (513,513,2,1,'Ako prvé prejde cez križovatku','513',3,3,'zelené vozidlo,','vaše vozidlo súčasne so žltým vozidlom,','červené vozidlo.');
INSERT INTO `Questions` VALUES (514,514,0,1,'Krajnicou sa rozumie','',2,3,'časť cesty vyhradená na premávku vozidiel s najvyššou celkovou prípustnou hmotnosťou prevyšujúcou 3 500 kg','miesto mimo cesty, na ktoré smie vojsť len vodič nemotorového vozidla','časť cesty od kraja vozovky po kraj cesty');
INSERT INTO `Questions` VALUES (515,515,0,1,'Vodičom sa rozumie','',2,1,'osoba, ktorá vedie vozidlo','osoba, ktorá najmä vedie motorové alebo nemotorové vozidlo, tlačí motocykel, pohybuje sa na lyžiach alebo kolieskových korčuliach, ťahá alebo tlačí sánky','len osoba, ktorá vedie motorové vozidlo');
INSERT INTO `Questions` VALUES (516,516,0,1,'Vodič','',2,3,'smie viesť vozidlo v takom čase po požití alkoholu alebo návykovej látky, keď sa alkohol alebo iná návyková látka ešte môžu nachádzať v organizme, ak to dovoľuje situácia v cestnej premávke, najmä v nočnej dobe','môže viesť vozidlo najviac 30 minút po požití alkoholu','nesmie viesť vozidlo v takom čase po požití alkoholu alebo inej návykovej látky, keď sa alkohol alebo iná návyková látka ešte môžu nachádzať v jeho organizme');
INSERT INTO `Questions` VALUES (517,517,0,1,'Na električkový koľajový pás v úrovni vozovky sa smie vojsť','',2,2,'len pri obchádzaní a predchádzaní','len pri obchádzaní, predchádzaní, odbočovaní, otáčaní, vchádzaní na cestu, alebo ak to dovoľuje dopravná značka alebo ak to vyžadujú mimoriadne okolnosti','za každých okolností');
INSERT INTO `Questions` VALUES (518,518,0,1,'Vodič nesmie predchádzať, ak','',2,1,'by sa nemohol bezpečne zaradiť pred vozidlo alebo pred vozidlá, ktoré chce predísť','pred ním jazdí zvláštne motorové vozidlo','na to v obci neupozornil vodiča predchádzaného vozidla zvukovým výstražným znamením');
INSERT INTO `Questions` VALUES (519,519,0,1,'Vodič vždy pri zmene smeru jazdy alebo pri vybočovaní z neho je povinný','',2,1,'dávať znamenie o zmene smeru jazdy','použiť osobitné zariadenie umožňujúce výstražnú funkciu smerových svietidiel','zaradiť druhý prevodový stupeň');
INSERT INTO `Questions` VALUES (520,520,0,1,'Vodič nesmie pri cúvaní','',2,2,'za zníženej viditeľnosti rozsvietiť stretávacie svetlomety','ohroziť ostatných účastníkov cestnej premávky','obmedziť vodičov motorových vozidiel');
INSERT INTO `Questions` VALUES (521,521,0,1,'Ak pri jazde vozidla v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným, alebo ak vznikne dopravná nehoda vrátane požiaru, je vodič po zastavení vozidla povinný bezodkladne','',2,3,'opustiť tunel a dopravnú nehodu oznámiť najbližšiemu príslušníkovi obecnej polície','zariadiť odtiahnutie vozidla z tunela','oznámiť telefonicky alebo iným vhodný spôsobom zastavenie vozidla osobe vykonávajúcej dohľad nad prevádzkou tunela');
INSERT INTO `Questions` VALUES (522,522,0,1,'Pred želeničným priecestím je vodič povinný','',2,2,'dať zvukové výstražné znamenie na upozornenie osoby pribratej na zaistenie bezpečnej prevádzky železničného priecestia','počínať si mimoriadne opatrne, najmä sa presvedčiť, či môže bezpečne prejsť cez železničné priecestie','vždy zastaviť vozidlo');
INSERT INTO `Questions` VALUES (523,523,0,1,'Motorové vozidlo musí mať počas jazdy rozsvietené','',2,1,'stretávacie svetlomety','diaľkové svetlomety','svetlá vo vnútri vozidla');
INSERT INTO `Questions` VALUES (524,524,0,1,'Náklad musí byť na vozidle riadne umiestnený, rozložený a upevenený, aby','',2,1,'nezakrýval svetlomety a svietidlá vozidla, odrazové sklá, tabuľku s evidenčným číslom a vyznačenie najvyššej povolenej rýchlosti','nezakrýval svetlomety a svietidlá vozidla a tabuľku s evidenčným číslom; to neplatí pri jazde na diaľnici a rýchlostnej ceste','nezakrýval názov a sídlo držiteľa vozidla uvedeného na vozdila');
INSERT INTO `Questions` VALUES (525,525,0,1,'Dopravná nehoda je','',2,2,'každá udalosť, pri ktorej dôjde k poškodeniu vozidla ľubovoľným spôsobom','udalosť v cestnej premávke, ktorá sa stane v priamej súvislosti s premávkou vozidla a pri ktorej sa usmrtí alebo zraní osoba, poškodí cesta alebo všeobecne prospešné zariadenie, unikú nebezpečné veci alebo vznikne škoda prevyšujúca jeden a pol násobok väčšej škody podľa Trestného zákona','udalosť v cestnej premávke, pri ktorej dôjde k stretu aspoň dvoch vozidiel');
INSERT INTO `Questions` VALUES (526,526,0,1,'Ak sa pri vlečení motorového vozidla použije tyč, musí byť zreteľne označená','',1,2,'priečnymi žltými a čiernymi pruhmi so šírkou najmenej 10 cm','priečnymi červenými a bielymi pruhmi so šírkou 7,5 cm','šikmými červenými pruhmi');
INSERT INTO `Questions` VALUES (527,527,0,1,'Prevádzkovateľ vozidla nesmie v premávke na pozemných komunikáciách prevádzkovať vozidlo, ktoré','',1,2,'nemá tabuľku s evidenčným číslom čitateľnú zo vzdialenosti 50m','nemá identifikačné číslo vozidla VIN zhodné s identifikačným číslom vozidla VIN uvedeným v osvedčení o evidencii alebo technickom osvedčení vozidla, ak bolo také číslo vozidlu pridelené','nie je vybavené zariadením na spájanie vozidiel');
INSERT INTO `Questions` VALUES (528,528,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,1,'homologizovaný prenosný výstražný trojuholník','červená zástavka s rozmermi najmenej 30 x 30 cm','výstražný trojuholník ľubovoľného typu');
INSERT INTO `Questions` VALUES (529,529,1,1,'Táto dopravná značka upozorňuje na','a29b',2,3,'sklon vozovky vpravo','železničné priecestie vo vzdialenosti 140 m','železničné priecestie vo vzdialenosti 80 m');
INSERT INTO `Questions` VALUES (530,530,1,1,'Táto dopravná značka znamená','b15',2,2,'zákaz vjazdu nemotorových vozidile','zákaz vjadzu záprahových vozidiel','cesta pre záprahové vozidlá');
INSERT INTO `Questions` VALUES (531,531,1,1,'Táto dopravná značka','b36',2,3,'umožňuje státie v párnych dňoch','zakazuje zastavenie za značkou v nepárnych dňoch v mesiaci','zakazuje státie v párnych kalendárnych dňoch v mesiaci');
INSERT INTO `Questions` VALUES (532,532,1,1,'Táto dopravná značka znamená','ip15b',2,3,'nebezpečenstvo šmyku','zvýšená krajnica','parkovisko - parkovacie miesta s pozdĺžným čiastočným státím na chodníku');
INSERT INTO `Questions` VALUES (533,533,1,1,'Táto dopravná značka','is10',2,3,'je návesťou pred obchádzkou','informuje o názve najbližšej obce a o vzdialenosti k nej','informuje o smere k vyznačeným cieľom z najbližšieho kruhového objazdu, prípadne aj o vzdialenosti k nemu');
INSERT INTO `Questions` VALUES (534,534,1,1,'Táto dopravná značka znamená','is26',2,1,'smerová tabuľa na vyznačenie obchádzky','iné nebezpečenstvo','prikázaný smer jazdy');
INSERT INTO `Questions` VALUES (535,535,1,1,'Táto dodatková tabuľka vyznačuje','p13',2,1,'skutočný tvar križovatky a aj hlavnú aj vedľajšiu cestu','tvar križovatky ciest nerozlíšených dopravnými značkami','tvar kríženia cesty so železnicou');
INSERT INTO `Questions` VALUES (536,536,1,1,'Takéto označenie sa môže použiť na vozidle','o4',2,3,'vybavenom zvláštnymi výstražnými znameniami','s právom prednostnej jazdy','vedenom vodičom začiatočníkom');
INSERT INTO `Questions` VALUES (537,537,2,1,'Červené vozidlo prejde cez križovatku ako','537',3,2,'posledné','druhé','prvé');
INSERT INTO `Questions` VALUES (538,538,2,1,'Vozidlá prejdú okolo prekážky v tomto poradí','538',3,3,'1. modré, 2. zelené, 3. červené, 4. žlté','1. modré, 2. červené, 3. žlté, 4. zelené','1. červené, 2. modré, 3. žlté, 4. zelené');
INSERT INTO `Questions` VALUES (539,539,2,1,'Ako prvé prejde cez križovatku','539',3,2,'modré vozidlo','vaše vozidlo','červené vozidlo');
INSERT INTO `Questions` VALUES (540,540,2,1,'Vaše vozidlo prejde cez križovatku ako','540',3,2,'tretie','prvé súčasne s modrým vozidlom','štvrté súčasne so zeleným vozidlom');
INSERT INTO `Questions` VALUES (541,541,0,1,'Hranicou križovatky sa rozumie','',2,3,'kolmica na os vozovky vedená stredom priechodu pre chodcov,','kolmica na os vozovky vo vzdialenosti desať metrov od miesta, kde sa pre križovatku začína zakrivenie vozovky,','miesto vyznačené príslušnou vodorovnou dopravnou značkou; kde takáto vodorovná dopravná značka nie je, hranicu križovatky tvorí kolmica na os vozovky v mieste, kde sa pre križovatku začína zakrivenie vozovky');
INSERT INTO `Questions` VALUES (542,542,0,1,'Zastavením vozidla sa rozumie','',2,1,'prerušenie jazdy z dôvodu nezávislého od vôle vodiča,','každé prerušenie jazdy,','uvedenie motorového vozidla do pokoja na čas nevyhnutne potrebný na urýchlené nastúpenie alebo vystúpenie prepravovaných osôb.');
INSERT INTO `Questions` VALUES (543,543,0,1,'Osoba sediaca na sedadle vozidla povinne vybavenom bezpečnostným pásom alebo iným zadržiavacím zariadením je povinná toto zariadenie použiť; to neplatí pre','',2,2,'spolujazdca sediaceho na zadnom sedadle vozidla,','osobu, ktorá nemôže byť pripútaná zo zdravotných dôvodov; takáto osoba sa musí preukázať osvedčením o oslobodení od použitia bezpečnostných systémov vozidla,','vodiča počas jazdy v obci.');
INSERT INTO `Questions` VALUES (544,544,0,1,'Vodič je povinný zaistiť bezpečné otáčanie alebo cúvanie pomocou spôsobilej a náležíte poučenej osoby, ak','',2,2,'sa otáča alebo cúva v tuneli a v jeho tesnej blízkosti,','to vyžadujú okolnosti, najmä nedostatočný rozhľad,','sa otáča alebo cúva na priechode pre chodcov alebo na priechode pre cyklistov.');
INSERT INTO `Questions` VALUES (545,545,0,1,'Vodič nesmie zastaviť a stáť','',2,2,'na priechode pre chodcov a vo vzdialenosti kratšej ako 25 m pred ním,','na priechode pre chodcov alebo na priechode pre cyklistov a vo vzdialenosti kratšej ako 5 m pred nimi,','na jednosmernej ceste vľavo.');
INSERT INTO `Questions` VALUES (546,546,0,1,'Pred železničným priecestím, pri ktorom je umiestnená dopravná značka "Stoj, daj prednosť v jazde!", vodič je povinný zastaviť vozidlo','',2,1,'na takom mieste, z ktorého má náležitý rozhľad na trať,','vo vzdialenosti najmenej 80 m pred železničným priecestím,','len vtedy, ak prichádzajú vozidlá v protismere.');
INSERT INTO `Questions` VALUES (547,547,0,1,'Vodič nesmie použiť diaľkové svetlomety, ak','',2,2,'jazdí za zníženej viditeľnosti,','je vozovka dostatočne a súvislé osvetlená alebo ak by mohol byť oslnený vodič protiidúceho vozidla, vodič vozidla idúceho pred ním alebo iný účastník cestnej premávky, strojvedúci vlaku alebo vodič iného dráhového vozidla, alebo vodič plavidla,','jazdí za zníženej viditeľnosti v obci.');
INSERT INTO `Questions` VALUES (548,548,0,1,'Motocykel bez postranného vozíka sa','',2,1,'nesmie vliecť ani použiť ako vlečné vozidlo,','smie vliecť alebo použiť ako vlečné vozidlo,','smie vliecť, ale nesmie sa použiť ako vlečné vozidlo.');
INSERT INTO `Questions` VALUES (549,549,0,1,'Do skupiny tvorenej vozidlami s právom prednostnej jazdy a vozidlami, ktoré sprevádzajú, sa vodič iného vozidla','',2,3,'nesmie zaraďovať; to neplatí pri jazde v obci,','smie zaraďovať.','nesmie zaraďovať.');
INSERT INTO `Questions` VALUES (550,550,0,1,'Ak prichádza vozidlo s právom prednostnej jazdy, chodec','',2,1,'nesmie vstupovať na vozovku,','smie vstupovať na vozovku len na priechode pre chodcov,','má prednosť pred týmito vozidlami ak prechádza cez priechod pre chodcov.');
INSERT INTO `Questions` VALUES (551,551,0,1,'Osoba, ktorá vykonáva na ceste prácu spojenú s jej údržbou, opravou alebo výstavbou, alebo inú pracovnú činnosť, na ktorú je oprávnená,','',2,2,'nemusí dodržiavať žiadne ustanovenia pravidiel cestnej premávky,','nemusí dodržiavať tie ustanovenia pravidiel cestnej premávky, pri ktorých to povaha vykonávanej práce vylučuje,','musí vždy dodržiavať všetky ustanovenia pravidiel cestnej premávky.');
INSERT INTO `Questions` VALUES (552,552,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza, vodič motorového vozidla kategórie M1 a N1 môže takéto vozidlo použiť v cestnej premávke, len ak','',2,3,'má uzatvorené havarijné poistenie,','je toto vybavené na hnacej náprave zimnými pneumatikami,','je toto vybavené na všetkých nápravách zimnými pneumatikami.');
INSERT INTO `Questions` VALUES (553,553,0,1,'Osoba, ktorá tlačí alebo ťahá ručný vozík s celkovou šírkou väčšou ako 600 mm, je povinná ísť','',1,1,'pri pravom okraji vozovky; ak sa tým neohrozujú ani neobmedzujú chodci, smie ísť po pravej krajnici,','pri ľavom okraji vozovky alebo po ľavej krajnici,','po chodníku, ak sa tým neohrozujú chodci.');
INSERT INTO `Questions` VALUES (554,554,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'sú na tej istej náprave použité pneumatiky, ktoré nie sú zhodné,','je zhodný účinok prevádzkovej brzdy na kolesách tej istej nápravy,','nieje vybavené klimatizačným systémom.');
INSERT INTO `Questions` VALUES (555,555,0,1,'Ak zjavne uniká palivo, olej, mazivo alebo iné prevádzkové náplne z vozidla,','',1,2,'vodič je povinný to po ukončení jazdy oznámiť držiteľovi vozidla,','považuje sa vozidlo za technicky nespôsobilé na premávku na pozemných komunikáciách,','smie sa takéto vozidlo, okrem diaľnice a rýchlostnej cesty, používať v cestnej premávke.');
INSERT INTO `Questions` VALUES (556,556,1,1,'Táto dopravná značka znamená:','a8',2,2,'Dvojitá zákruta, prvá vľavo.','Nebezpečenstvo šmyku,','Nerovnosť vozovky.');
INSERT INTO `Questions` VALUES (557,557,1,1,'Táto dopravná značka','a15',2,1,'upozorňuje na miesto, kde sa v blízkosti cesty zhromažďujú alebo často vozovku prechádzajú deti (v blízkosti školy, detského ihriska a podobne),','zakazuje vstup detí,','upozorňuje vopred na miesto, kde sú dovolené hry detí na ceste.');
INSERT INTO `Questions` VALUES (558,558,1,1,'Táto dopravná značka zakazuje vjazd','b6',2,3,'automobilov s najväčšou prípustnou celkovou hmotnosťou neprevyšujúcou 3500 kg,','všetkých motorových vozidiel,','nákladných automobilov vrátane ťahača prívesu, ťahača návesu a špeciálnych automobilov odvodených od nákladného automobilu');
INSERT INTO `Questions` VALUES (559,559,1,1,'Táto dopravná značka znamená:','c4b',2,2,'Zvýšenie počtu jazdných pruhov,','Prikázaný smer jazdy priamo a vpravo,','Zákruta vpravo.');
INSERT INTO `Questions` VALUES (560,560,1,1,'Táto dopravná značka označuje','ip1',2,3,'hlavnú cestu, a to najmä v obci,','stĺpy verejného osvetlenia, ktoré sú v blízkosti okraja vozovky,','okruh zriadený na obchádzanie obce alebo jej časti.');
INSERT INTO `Questions` VALUES (561,561,1,1,'Táto dopravná značka vyznačuje','ip15a',2,1,'a určuje dovolený spôsob státia vozidiel na chodníku','prekážku na ceste,','miesto, kde je zakázané parkovanie osobných automobilov.');
INSERT INTO `Questions` VALUES (562,562,1,1,'Táto dopravná značka','c27',2,3,'informuje o spôsobe obchádzania prekážky na ceste,','označuje uzávierku električkovej trate,','označuje miesto, kde možno vľavo obchádzať električku, ktorá stojí na zastávke.');
INSERT INTO `Questions` VALUES (563,563,1,1,'Táto dopravná značka vyznačuje','v13',2,2,'šikmý priechod pre chodcov,','priestor, do ktorého je zakázané vchádzať alebo doň nákladom zasahovať, ak to nie je potrebné na obchádzanie, odbočovanie na miesto ležiace mimo cesty alebo na vchádzanie na cestu z miesta ležiaceho mimo cesty,','priestor, do ktorého je zakázané vchádzať, ak to nie je potrebné na otáčanie vozidiel na križovatke.');
INSERT INTO `Questions` VALUES (564,564,2,1,'Ako prvé prejde cez križovatku:','564',3,3,'modré vozidlo,','červené vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (565,565,2,1,'Tento pokyn policajta znamená','565',3,1,'"voľno" pre vodiča červeného a vodiča modrého vozidla a "Stoj!" pre vodiča žltého vozidla; vodič zeleného vozidla smie odbočiť vpravo,','"voľno" pre vodiča zeleného a vodiča žltého vozidla a "Stoj!" pre vodiča modrého a vodiča červeného vozidla,','"voľno" pre vodiča červeného a vodiča žltého vozidla a "Stoj!" pre vodiča modrého a vodiča zeleného vozidla.');
INSERT INTO `Questions` VALUES (566,566,2,1,'Ako posledné prejde cez križovatku','566',3,3,'vaše vozidlo,','modré vozidlo,','červené vozidlo.');
INSERT INTO `Questions` VALUES (567,567,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','567',3,2,'1. červené, 2. zelené, 3. vaše vozidlo súčasne s modrým,','1. červené, 2. vaše vozidlo súčasne s modrým, 3. zelené,','1. modré, 2. červené, 3. zelené, 4. vaše vozidlo. vaše vozidlo');
INSERT INTO `Questions` VALUES (568,568,0,1,'Chodcom sa rozumie účastník cestnej premávky pohybujúci sa pešo; chodcom je aj','',2,3,'pohonič záprahového vozidla a osoba, ktorá tlačí alebo ťahá ručný vozík s celkovou šírkou nepresahujúcou 150 cm,','vodič každého nemotorového vozidla, ktoré sa pohybuje rýchlosťou menšou ako 30 km/h','osoba, ktorá tlačí alebo ťahá ručný vozík s celkovou šírkou nepresahujúcou 600 mm.');
INSERT INTO `Questions` VALUES (569,569,0,1,'Vodičom sa rozumie','',2,1,'osoba, ktorá vedie vozidlo,','osoba, ktorá najmä vedie motorové alebo nemotorové vozidlo, tlačí motocykel, pohybuje sa na lyžiach alebo kolieskových korčuliach, ťahá alebo tlačí sánky,','len osoba, ktorá vedie motorové vozidlo.');
INSERT INTO `Questions` VALUES (570,570,0,1,'Vodič motocykla a jeho spolujazdec sú povinní počas jazdy používať','',2,1,'na hlave riadne upevnenú ochrannú prilbu určenú pre motocyklistov,','akúkoľvek prilbu alebo obdobnú pokrývku hlavy,','ochranný štít.');
INSERT INTO `Questions` VALUES (571,571,0,1,'Vodič vozidla, ktoré zastavilo alebo stálo a opäť vychádza od okraja cesty alebo od chodníka,','',2,3,'nie je povinný dávať znamenie o zmene smeru jazdy,','je povinný dávať znamenie o zmene smeru jazdy len mimo obce,','je povinný dávať znamenie o zmene smeru jazdy.');
INSERT INTO `Questions` VALUES (572,572,0,1,'Vodič nesmie zastaviť a stáť','',2,2,'v obci kolmo, prípadne šikmo na okraj vozovky,','na moste,','vľavo na jednosmernej ceste.');
INSERT INTO `Questions` VALUES (573,573,0,1,'Vodič je povinný dávať znamenie o zmene smeru jazdy','',2,1,'včas pred začatím takéhoto jazdného úkonu,','až po začatí takéhoto jazdného úkonu,','až po ukončení takéhoto jazdného úkonu.');
INSERT INTO `Questions` VALUES (574,574,0,1,'Ak je vozovka dostatočne a súvislé osvetlená, vodič','',2,2,'smie použiť diaľkové svetlomety,','nesmie použiť diaľkové svetlomety,','smie použiť diaľkové svetlomety, ak vo vzdialenosti najmenej 50 m pred ním nejde žiadne vozidlo.');
INSERT INTO `Questions` VALUES (575,575,0,1,'Na diaľnici smie vodič motorového vozidla jazdiť rýchlosťou najmenej','',2,2,'60 km/h','80 km/h','90 km/h');
INSERT INTO `Questions` VALUES (576,576,0,1,'Ak na stojacom vozidle svieti zvláštne výstražné svetlo modrej alebo červenej farby, prípadne ich kombinácia musí vodič iného vozidla','',2,1,'zvýšiť opatrnosť, znížiť rýchlosť jazdy, prípadne zastaviť vozidlo,','zvýšiť rýchlosť jazdy,','bezodkladne zastaviť vozidlo.');
INSERT INTO `Questions` VALUES (577,577,0,1,'Pred vstupom na vozovku chodec','',2,3,'musí prestať jesť, piť a fajčiť,','sa nemusí presvedčiť, či tak môže urobiť bez nebezpečenstva, ak vstupuje na vozovku v obci,','sa musí presvedčiť, či tak môže urobiť bez nebezpečenstva.');
INSERT INTO `Questions` VALUES (578,578,0,1,'Osoba, ktorá vykonáva na ceste prácu spojenú s jej údržbou, opravou alebo výstavbou, alebo inú pracovnú činnosť, na ktorú je oprávnená, musí byť','',2,1,'zreteľne označená,','zreteľne označená len za zníženej viditeľnosti,','označená len vtedy, ak jej na to dal príkaz jej zamestnávateľ.');
INSERT INTO `Questions` VALUES (579,579,0,1,'Jazdci na zvieratách smú ísť','',2,2,'najviac dvaja vedľa seba,','len jednotlivo za sebou,','najviac traja vedľa seba.');
INSERT INTO `Questions` VALUES (580,580,0,1,'Policajt v rovnošate dáva znamenie na zastavenie vozidla','',1,1,'vztýčením ruky alebo zastavovacieho terča a za zníženej viditeľnosti červeným svetlom, ktorým pohybuje v hornom polkruhu,','kývaním ruky hore a dolu,','vodorovným kývaním ruky cez stred tela; na zdôraznenie tohto pokynu môže použiť znamenie píšťalkou.');
INSERT INTO `Questions` VALUES (581,581,0,1,'Povinnou výbavou motorového vozidla kategórie M, N, T, C a PS sú','',1,2,'náhradné stierače,','homologizovaný prenosný výstražný trojuholník,','protisklzové reťaze.');
INSERT INTO `Questions` VALUES (582,582,0,1,'Prevádzkovateľ vozidla, ktoré je v premávke na pozemných komunikáciách, je povinný','',1,1,'zabezpečiť, aby vozidlo bolo vybavené povinnou výbavou,','zabezpečiť, aby vozidlo bolo vybavené zariadením na spájanie vozidiel,','zabezpečiť, aby vozidlo bolo vybavené zvláštnym výstražným svetlom oranžovej farby.');
INSERT INTO `Questions` VALUES (583,583,1,1,'Táto dopravná značka znamená:','a2b',2,3,'Spôsob obchádzania prekážky,','Nebezpečenstvo šmyku,','Dvojitá zákruta, prvá vľavo.');
INSERT INTO `Questions` VALUES (584,584,1,1,'Táto dopravná značka','a16',2,2,'zakazuje vjazd cyklistom,','upozorňuje na miesto, kde cyklisti prechádzajú vozovku alebo na ňu vchádzajú,','prikazuje cyklistom zastaviť.');
INSERT INTO `Questions` VALUES (585,585,1,1,'Táto dopravná značka znamená:','b3',2,1,'Zákaz vjazdu všetkých motorových vozidiel,','Vjazd osobným automobilom a motocyklom povolený,','Zákaz vjazdu osobných automobilov a motocyklov.');
INSERT INTO `Questions` VALUES (586,586,1,1,'Táto dopravná značka znamená:','p8',2,2,'Rýchlostná cesta,','Hlavná cesta,','Vedľajšia cesta.');
INSERT INTO `Questions` VALUES (587,587,1,1,'Táto dopravná značka znamená','ip11',2,2,'Odstavná plocha pre vozidlá s nadrozmerným nákladom,','Núdzová odstavná plocha,','Parkovisko.');
INSERT INTO `Questions` VALUES (588,588,1,1,'Táto dopravná značka','is23b',2,3,'informuje o vzdialenosti k najbližšej obci,','informuje o názve najbližšej križovatky,','informuje vhodným nápisom, symbolom alebo siluetou o smere, prípadne o vzdialenosti k vyznačenému kultúrnemu alebo turistickému cieľu');
INSERT INTO `Questions` VALUES (589,589,1,1,'Táto dopravná značka vyznačuje','v10b',2,1,'miesto, kde je dovolené zastavenie a státie a určený spôsob státia šikmo na okraj vozovky,','miesto, kde je zakázané zastavenie a státie.','miesto, kde je dovolené zastavenie a státie pozdĺž okraja cesty.');
INSERT INTO `Questions` VALUES (590,590,1,1,'Takéto označenie sa môže použiť na vozidle','o1',2,3,'patriacom telekomunikáciám,','vedenom osobou s ťažkým zdravotným postihnutím odkázanú na individuálnu prepravu,','vedenom osobou sluchovo postihnutou.');
INSERT INTO `Questions` VALUES (591,591,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','591',3,2,'1, červené, 2. žlté, 3. zelené,','1. žité, 2. červené, 3. zelené,','1. zelené, 2. červené, 3. žlté.');
INSERT INTO `Questions` VALUES (592,592,2,1,'Vodič modrého vozidla','592',3,1,'je povinný umožniť vodičovi červeného vozidla obídenie prekážky,','má pred vodičom červeného a vodičom žltého vozidla prednosť, pretože v ich jazdnom pruhu sa nachádza prekážka,','je povinný umožniť vodičovi červeného a vodičovi žltého vozidla obídenie prekážky.');
INSERT INTO `Questions` VALUES (593,593,2,1,'V poradí druhé prejde cez križovatku','593',3,2,'červené vozidlo','vaše vozidlo','zelené vozidlo');
INSERT INTO `Questions` VALUES (594,594,2,1,'Ako posledné prejde cez križovatku','594',3,3,'električka č. 1 súčasne s vaším vozidlom','vaše vozidlo súčasne s električkou č. 2','električka č. 1 súčasne s električkou č. 2');
INSERT INTO `Questions` VALUES (595,595,0,1,'Zastavením sa rozumie','',2,1,'uvedenie vozidla do pokoja na čas nevyhnutne potrebný na urýchlené nastúpenie a vystúpenie prepravovaných osôb alebo na urýchlené naloženie alebo zloženie nákladu,','uvedenie vozidla do pokoja na čas presahujúci 5 minút,','prerušenie jazdy pre poruchu na vozidle, pre ktorú sa toto vozidlo stalo nepojazdným.');
INSERT INTO `Questions` VALUES (596,596,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza, vodič motorového vozidla kategórie M1 a N1 môže takéto vozidlo použiť v cestnej premávke, len ak','',2,1,'je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené na hnacej náprave zimnými pneumatikami,','má uzatvorené havarijné poistenie.');
INSERT INTO `Questions` VALUES (597,597,0,1,'Vodič nesmie požiť alkohol ani inú návykovú látku','',2,2,'najmenej 12 hodín po skončení vedenia vozidla,','počas vedenia vozidla,','len počas vedenia motocykla a vozidla, ktorého najväčšia celková hmotnosť presahuje 3500 kg.');
INSERT INTO `Questions` VALUES (598,598,0,1,'Osoba sediaca na sedadle vozidla povinne vybavenom bezpečnostným pásom alebo iným zadržiavacím zariadením','',2,1,'je povinná toto zariadenie použiť,','je povinná toto zariadenie použiť len počas jazdy mimo obce,','nieje povinná toto zariadenie použiť, ak sedí na zadnom sedadle.');
INSERT INTO `Questions` VALUES (599,599,0,1,'Vodič je povinný na vozovke alebo v jazdnom pruhu jazdiť','',2,1,'vpravo, pri pravom okraji vozovky alebo jazdného pruhu,','vpravo, po pravej krajnici,','vľavo, pri ľavom okraji vozovky alebo jazdného pruhu.');
INSERT INTO `Questions` VALUES (600,600,0,1,'Vodič nesmie predchádzať, ak','',2,1,'by pri predchádzaní svojou výrazne nižšou rýchlosťou obmedzil za ním idúce vozidlo, ktoré začalo úkon predchádzania skôr,','pred ním jazdí zvláštne motorové vozidlo,','na to v obci neupozornil vodiča predchádzaného vozidla zvukovým výstražným znamením.');
INSERT INTO `Questions` VALUES (601,601,0,1,'Vodič motorového vozidla s najväčšou prípustnou celkovou hmotnosťou neprevyšujúcou 3 500 kg smie jazdiť rýchlosťou najviac','',2,3,'100 km/h, na diaľnici a na rýchlostnej ceste najviac 160 km/h','80 km/h, na diaľnici a na rýchlostnej ceste najviac 120 km/h','90 km/h, na diaľnici a na rýchlostnej ceste najviac 130 km/h');
INSERT INTO `Questions` VALUES (602,602,0,1,'Pred odbočovaním vpravo vodič je povinný','',2,2,'pred zaradením sa k pravému okraju vozovky dávať vždy zvukové výstražné znamenie,','zaradiť sa čo najbližšie k pravému okraju vozovky; ak pritom musí s ohľadom na rozmery vozidla alebo nákladu vybočiť zo smeru svojej jazdy vľavo, vždy dáva len znamenie o zmene smeru jazdy vpravo,','zaradiť sa vždy do stredu vozovky.');
INSERT INTO `Questions` VALUES (603,603,0,1,'Vodič smie zastaviť a stáť len','',2,3,'na jednosmernej ceste,','na krajnici,','vpravo v smere jazdy čo najbližšie k okraju cesty a na jednosmernej ceste vpravo i vľavo.');
INSERT INTO `Questions` VALUES (604,604,0,1,'Svetelné výstražné znamenie sa dáva prerušovaným zapínaním','',2,3,'parkovacích svietidiel,','smerových svietidiel alebo predných svetlometov do hmly,','stretávacích svetlometov alebo diaľkových svetlometov.');
INSERT INTO `Questions` VALUES (605,605,0,1,'Účastník dopravnej nehody je povinný','',2,3,'zotrvať na mieste dopravnej nehody až do príchodu odťahovej služby.','je povinný zotrvať na mieste dopravnej nehody, to neplatí, ak preukázal svoju totožnosť ostatným účastníkom dopravnej nehody,','zotrvať na mieste dopravnej nehody až do príchodu policajta alebo sa na toto miesto bezodkladne vrátiť po poskytnutí alebo privolaní pomoci, alebo po ohlásení dopravnej nehody.');
INSERT INTO `Questions` VALUES (606,606,0,1,'Pri prechádzaní cez cestu chodec','',2,2,'nieje povinný prednostne použiť priechod pre chodcov, nadchod alebo podchod,','je povinný prednostne použiť priechod pre chodcov, nadchod alebo podchod,','je povinný použiť priechod pre chodcov, nadchod alebo podchod len za nezníženej viditeľnosti.');
INSERT INTO `Questions` VALUES (607,607,0,1,'Osoba, ktorá tlačí alebo ťahá ručný vozík s celkovou šírkou väčšou ako 600 mm, je povinná ísť','',1,1,'pri pravom okraji vozovky; ak sa tým neohrozujú ani neobmedzujú chodci, smie ísť po pravej krajnici,','po chodníku, ak sa tým neohrozujú chodci,','pri ľavom okraji vozovky alebo po ľavej krajnici.');
INSERT INTO `Questions` VALUES (608,608,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'na zvukovom výstražnom zariadení došlo k zmene tónu,','najnižší bod činnej svietiacej plochy stretávacích svetiel je nižšie ako 1200 mm nad rovinou vozovky,','niektoré svetelné zariadenie dôležité pre bezpečnosť premávky na pozemných komunikáciách chýba alebo je nesprávne umiestnené, nesvieti alebo nespĺňa ustanovené podmienky, takže hrozí bezprostredné nebezpečenstvo.');
INSERT INTO `Questions` VALUES (609,609,0,1,'Povinnou výbavou motorového vozidla kategórie M, N, T, C a PS sú','',1,2,'dve náhradné uzavreté matice nábojov kolies,','homologizovaný prenosný výstražný trojuholník,','krieda a meracie pásmo na vyznačenie stôp a postavenia vozidla v prípade dopravnej nehody.');
INSERT INTO `Questions` VALUES (610,610,1,1,'Táto dopravná značka s dodatkovou tabuľkou znamená:','spec6',2,1,'Štyri zákruty, prvá vpravo,','Spôsob obchádzania štyroch prekážok,','Nebezpečenstvo šmyku v úseku 4 km.');
INSERT INTO `Questions` VALUES (611,611,1,1,'Táto dopravná značka znamená:','b7',2,1,'Zákaz vjazdu autobusov,','Vjazd autobusom povolený,','Jazdný pruh vyhradený pre autobusy.');
INSERT INTO `Questions` VALUES (612,612,1,1,'Táto dopravná značka zrušuje platnosť','b39',2,3,'všetkých predchádzajúcich zákazových dopravných značiek,','značiek Zákaz státia a Zákaz zastavenia,','značiek Zákaz predchádzania, Zákaz predchádzania pre nákladné automobily, Najvyššia dovolená rýchlosť a Najnižšia dovolená rýchlosť, ak sú použité najmenej dve z týchto značiek spoločne.');
INSERT INTO `Questions` VALUES (613,613,1,1,'Táto dopravná značka znamená:','ip12',2,2,'Pešia zóna,','Parkovisko,','Polícia.');
INSERT INTO `Questions` VALUES (614,614,1,1,'Táto dopravná značka znamená:','ii7b',2,3,'Jazdný pruh vyhradený pre vozidlá pravidelnej verejnej dopravy osôb,','Parkovisko vyhradené pre trolejbusy,','Zastávka trolejbusu.');
INSERT INTO `Questions` VALUES (615,615,1,1,'Táto dopravná značka znamená:','ip30',2,2,'Práca na ceste,','Zmena miestnej úpravy,','Zóna s dopravným obmedzením.');
INSERT INTO `Questions` VALUES (616,616,1,1,'Táto dopravná značka informuje','c26',2,3,'o mieste, kde možno obchádzať vľavo električku, ktorá stojí na zastávke,','o možnosti jazdy pozdĺž električky vľavo,','najmä o zmene smeru jazdy do protismeru na smerovo rozdelenej ceste.');
INSERT INTO `Questions` VALUES (617,617,1,1,'Táto dopravná značka vyznačuje','v5b',2,1,'hranicu križovatky; to neplatí, ak sa táto značka použije ako pomocná čiara na zastavenie vozidla v priestore križovatky,','začiatok vedľajšej cesty,','miesto, kde musí vodič vždy zastaviť vozidlo.');
INSERT INTO `Questions` VALUES (618,618,2,1,'Ako posledné prejde cez križovatku','618',3,2,'modré vozidlo,','červené vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (619,619,2,1,'Vodič červeného vozidla','619',3,1,'je povinný umožniť vodičovi modrého vozidla obídenie prekážky,','má pred vodičom modrého vozidla prednosť, pretože v jeho jazdnom pruhu sa nachádza prekážka,','je povinný umožniť vodičovi modrého vozidla aj vodičovi zeleného vozidla obídenie prekážky.');
INSERT INTO `Questions` VALUES (620,620,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','729',3,2,'1. vaše vozidlo, 2. červené, 3. zelené,','1. zelené, 2. vaše vozidlo, 3. červené,','1. červené, 2. zelené, 3. vaše vozidlo.');
INSERT INTO `Questions` VALUES (621,621,2,1,'Vaše vozidlo prejde cez križovatku ako','621',3,1,'prvé súčasne so zeleným vozidlom','tretie súčasne so zeleným vozidlom','posledné');
INSERT INTO `Questions` VALUES (622,622,0,1,'Dať prednosť v jazde sa rozumie','',2,1,'povinnosť účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde nemusel náhle zmeniť smer alebo rýchlosť jazdy,','povinnosť účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde nemusel zmeniť smer jazdy, môže však zmeniť rýchlosť jazdy,','povinnosť účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde nemusel zmeniť rýchlosť jazdy, môže však zmeniť smer jazdy.');
INSERT INTO `Questions` VALUES (623,623,0,1,'Električkovým koľajovým pásom sa rozumie','',2,3,'vozovka určená na premávku električky, vlaku a iného dráhového vozidla,','časť cesty, na ktorej je povolená len premávka električky a nemotorových vozidiel,','časť cesty určená predovšetkým na premávku električky.');
INSERT INTO `Questions` VALUES (624,624,0,1,'Vodič malého motocykla alebo bicykla','',2,3,'nesmie jazdiť po pravej krajnici za žiadnych okolností,','smie jazdiť po pravej krajnici len pri obchádzaní a vyhýbaní,','smie jazdiť po pravej krajnici len, ak sa tým neohrozí a neobmedzí pohyb chodcov.');
INSERT INTO `Questions` VALUES (625,625,0,1,'Mimo obce na ceste s dvoma alebo s viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy sa jazdí','',2,1,'v pravom jazdnom pruhu; v ostatných jazdných pruhoch sa smie jazdiť, ak je to potrebné na obchádzanie, predchádzanie, otáčanie alebo na odbočovanie,','v ľavom jazdnom pruhu,','v ktoromkoľvek jazdnom pruhu.');
INSERT INTO `Questions` VALUES (626,626,0,1,'Električkový koľajový pás zvýšený nad úroveň vozovky alebo znížený pod jej úroveň, alebo ktorý je od vozovky inak oddelený, najmä obrubníkom, sa smie prechádzať','',2,1,'len priečne, a to na mieste na to prispôsobenom,','na ktoromkoľvek mieste, a to vždy priečne,','na ktoromkoľvek mieste, ak nie je v blízkosti električka.');
INSERT INTO `Questions` VALUES (627,627,0,1,'Vodič nesmie predchádzať','',2,3,'na križovatke a 200 m pred ňou,','vozidlo, ktoré mení smer jazdy vľavo a už nie je pochybnosť o ďalšom smere jeho jazdy,','pri jazde cez železničné priecestie.');
INSERT INTO `Questions` VALUES (628,628,0,1,'Vodič smie v obci jazdiť rýchlosťou najviac','',2,2,'60 km/h a ak ide po diaľnici v obci alebo po rýchlostnej ceste v obci, najviac 110 km/h','50 km/h, a ak ide po diaľnici v obci alebo po rýchlostnej ceste v obci, najviac 90 km/h','80 km/h');
INSERT INTO `Questions` VALUES (629,629,0,1,'Vodič nesmie zastaviť a stáť na zastávke vozidla pravidelnej verejnej dopravy osôb v úseku, ktorý sa začína','',2,1,'dopravnou značkou pre zastávku a končí sa 5 m za označníkom zastávky,','vo vzdialenosti 15 m pred označníkom zastávky a končí sa označníkom zastávky,','dopravnou značkou pre zastávku a končí sa pri označníku zastávky.');
INSERT INTO `Questions` VALUES (630,630,0,1,'Na kruhovom objazde je státie','',2,3,'dovolené,','dovolené, ak je to potrebné na urýchlené nastúpenie alebo vystúpenie prepravovaných osôb,','aj zastavenie zakázané.');
INSERT INTO `Questions` VALUES (631,631,0,1,'Pri poruche osvetlenia alebo inej poruche nedovoľujúcej použitie osvetlenia, musia byť na vlečenom vozidle za zníženej viditeľnosti rozsvietené','',2,1,'svetlá na strane k stredu vozovky vpredu bielym neoslňujúcim svetlom a vzadu aspoň jedným červeným svetlom,','dve červené svetlá vpredu aj vzadu,','svetlá vo vnútri vozidla.');
INSERT INTO `Questions` VALUES (632,632,0,1,'Náklad musí byť na vozidle riadne umiestnený, rozložený a upevnený, aby','',2,1,'nezakrýval svetlomety a svietidlá vozidla, odrazové sklá, tabuľku s evidenčným číslom a vyznačenie najvyššej povolenej rýchlosti,','nezakrýval svetlomety a svietidlá vozidla a tabuľku s evidenčným číslom; to neplatí pri jazde na diaľnici a rýchlostnej ceste,','nezakrýval názov a sídlo držiteľa vozidla uvedeného na vozidle.');
INSERT INTO `Questions` VALUES (633,633,0,1,'Ak je nesúlad medzí zvislými dopravnými značkami a vodorovnými dopravnými značkami,','',2,1,'zvislé dopravné značky sú nadradené vodorovným dopravným značkám,','vodorovné dopravné značky sú nadradené zvislým dopravným značkám,','účastník cestnej premávky je povinný oznámiť to príslušnému úradu.');
INSERT INTO `Questions` VALUES (634,634,0,1,'Ak sa pri vlečení motorového vozidla použije tyč','',1,2,'nesmie byť vzdialenosť medzi vozidlami menšia ako 0,5 m,','nesmie byť vzdialenosť medzi vozidlami menšia ako 1 m,','jej dĺžka musí byť väčšia ako 3 m.');
INSERT INTO `Questions` VALUES (635,635,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,3,'náhradný stierač,','žiarovka používaná na vnútorné osvetlenie batožinového priestoru,','kľúč na matice alebo skrutky kolies.');
INSERT INTO `Questions` VALUES (636,636,0,1,'Ak zjavne uniká palivo, olej, mazivo alebo iné prevádzkové náplne z vozidla','',1,2,'možno s takýmto vozidlom jazdiť iba rýchlosťou neprevyšujúcou 60 km/h','považuje sa takéto vozidlo za technicky nespôsobilé na premávku na pozemných komunikáciách,','možno také vozidlo používať len na účelových komunikáciách.');
INSERT INTO `Questions` VALUES (637,637,1,1,'Táto dopravná značka upozorňuje na miesto, kde','a18',2,3,'sa často, prípadne pravidelne ženie dobytok po ceste (v blízkosti poľnohospodárskych objektov, pastvín a podobne),','sa často, prípadne pravidelne loví zver (v blízkosti lesných porastov, v horských oblastiach a podobne),','voľne žijúca zver vo väčšom množstve prebieha cez cestu alebo kde tiahnú drobné živočíchy (v lesoch, horských oblastiach, zverníkoch a podobne).');
INSERT INTO `Questions` VALUES (638,638,1,1,'Táto dopravná značka označuje','a30a',2,1,'železničné priecestie jednokoľajové,','križovatku dvoch ciest rovnakého významu,','železničné priecestie vo vzdialenosti 80 m.');
INSERT INTO `Questions` VALUES (639,639,1,1,'Táto dopravná značka znamená:','b10',2,2,'Zákaz vjazdu všetkých dvojkolesových vozidiel,','Zákaz vjazdu malých motocyklov,','Cestička pre malé motocykle.');
INSERT INTO `Questions` VALUES (640,640,1,1,'Táto dopravná značka','c4a',2,3,'upozorňuje na križovatku tvaru "T",','označuje zvýšenie počtu jazdných pruhov,','prikazuje jazdu smerom, ktorým šípky ukazujú.');
INSERT INTO `Questions` VALUES (641,641,1,1,'Táto dopravná značka znamená:','ip10',2,3,'Obmedzenie najvyššej dovolenej rýchlosti; vyjadruje číslom na značke najvyššiu dovolenú rýchlosť na mokrej vozovke,','Cesta 1. triedy; informuje o čísle cesty 1. triedy,','Odporúčaná rýchlosť; vyjadruje číslom alebo číslami uvedenými na značke odporúčanú rýchlosť v kilometroch za hodinu');
INSERT INTO `Questions` VALUES (642,642,1,1,'Táto dopravná značka znamená:','is1b',2,1,'Návesť pred križovatkou,','Rýchlostná cesta,','Diaľková návesť.');
INSERT INTO `Questions` VALUES (643,643,1,1,'Táto dopravná značka vyznačuje','c24a',2,2,'zákaz vjazdu autobusov do pravého jazdného pruhu,','jazdný pruh vyhradený pre autobusy pravidelnej verejnej dopravy osôb alebo pre trolejbusy a jeho situovanie vo vzťahu k ostatným','symboly vozidiel, ktorým je zakázané jazdiť v pravom jazdnom pruhu.');
INSERT INTO `Questions` VALUES (644,644,1,1,'Táto dodatková tabuľka','e10',2,3,'vyznačuje druh vozidla, na ktoré sa nevzťahuje značka, pod ktorou je tabuľka umiestnená,','vyznačuje parkovisko pre nákladné automobily,','obmedzuje platnosť značky, pod ktorou je umiestnená, na vyznačený druh vozidla.');
INSERT INTO `Questions` VALUES (645,645,2,1,'Ako prvé prejde cez križovatku','645',3,1,'zelené vozidlo,','červené vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (646,646,2,1,'Na tento pokyn policajta','646',3,2,'je vodič modrého, vodič červeného a vodič žltého vozidla povinný zastaviť vozidlo pred hranicou križovatky,','je vodič čierneho a vodič zeleného vozidla povinný zastaviť vozidlo pred hranicou križovatky,','smie vodič čierneho a vodič zeleného vozidla pokračovať v jazde; ak títo vodiči dodržia ustanovenia o odbočovaní, môžu odbočiť vpravo alebo vľavo.');
INSERT INTO `Questions` VALUES (647,647,2,1,'Vaše vozidlo prejde cez križovatku ako','647',3,2,'druhé,','prvé,','posledné.');
INSERT INTO `Questions` VALUES (648,648,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','648',3,1,'1. vaše vozidlo súčasne s modrým, 2. žlté, 3. zelené,','1. vaše vozidlo súčasne s modrým. 2. zelené, 3, žlté,','1. zelené, 2. žlté, 3. vaše vozidlo súčasne s modrým.');
INSERT INTO `Questions` VALUES (649,649,0,1,'Krajnicou sa rozumie','',2,1,'časť cesty od kraja vozovky po kraj cesty,','časť cesty určená predovšetkým na premávku motorových vozidiel,','časť cesty, ktorá je spravidla oddelená od vozovky výškovo alebo iným spôsobom.');
INSERT INTO `Questions` VALUES (650,650,0,1,'Hranicou križovatky sa rozumie','',2,3,'kolmica na os vozovky vedená stredom priechodu pre chodcov,','kolmica na os vozovky vo vzdialenosti desať metrov od miesta, kde sa pre križovatku začína zakrivenie vozovky,','miesto vyznačené príslušnou vodorovnou dopravnou značkou; kde takáto vodorovná dopravná značka nie je, hranicu križovatky tvorí kolmica na os vozovky v mieste, kde sa pre križovatku začína zakrivenie vozovky.');
INSERT INTO `Questions` VALUES (651,651,0,1,'Ak vodič zníži rýchlosť jazdy alebo ak zastaví vozidlo pred priechodom pre chodcov, aby umožnil prejsť cez cestu chodcom, vodiči ostatných vozidiel idúcich rovnakým smerom sú','',2,2,'povinní dávať zvukové výstražné znamenia počas jazdy cez takýto priechod v obci,','takisto povinní znížiť rýchlosť jazdy alebo zastaviť vozidlo; to neplatí pre vodiča električky,','takisto povinní znížiť rýchlosť jazdy, len ak cez priechod prechádzajú osoby s ťažkým zdravotným postihnutím alebo staré osoby.');
INSERT INTO `Questions` VALUES (652,652,0,1,'Na ceste s troma jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy je vodič prechádzajúci','',2,1,'z ľavého jazdného pruhu do stredného jazdného pruhu je povinný dať prednosť v jazde vodičovi prechádzajúcemu do stredného jazdného pruhu z pravého jazdného pruhu,','z pravého jazdného pruhu do stredného jazdného pruhu je povinný dať prednosť v jazde vodičovi prechádzajúcemu do stredného jazdného pruhu z ľavého jazdného pruhu,','z ľavého jazdného pruhu do stredného jazdného pruhu smie ohroziť vodiča prechádzajúceho do stredného jazdného pruhu z pravého jazdného pruhu.');
INSERT INTO `Questions` VALUES (653,653,0,1,'Pozdĺž električky sa jazdí','',2,3,'vľavo, ak nie je dopravnou značkou povolená jazda vpravo','za každých okolností vľavo','vpravo, ak nie je dopravnou značkou povolená jazda vľavo');
INSERT INTO `Questions` VALUES (654,654,0,1,'Vodič motocykla smie jazdiť rýchlosťou najviac','',2,1,'90 km/h, na diaľnici a na rýchlostnej ceste 130 km/h','110 km/h','80 km/h, na diaľnici a na rýchlostnej ceste 120 km/h');
INSERT INTO `Questions` VALUES (655,655,0,1,'Vodič sa nesmie otáčať','',2,3,'na ceste 1. triedy,','na žiadnej križovatke,','na jednosmernej ceste.');
INSERT INTO `Questions` VALUES (656,656,0,1,'Vodič nesmie zastaviť a stáť na mieste, kde by vozidlo zakrývalo','',2,2,'akúkoľvek vodorovnú dopravnú značku,','vodorovnú dopravnú značku vyznačujúcu spôsob radenia do jazdných pruhov a určený smer jazdy cez križovatku alebo vyjadrujúcu doplňujúci údaj nápisom alebo svetelné signály,','stĺp elektrického osvetlenia.');
INSERT INTO `Questions` VALUES (657,657,0,1,'Ak svieti prerušované biele svetlo, vodič je povinný','',2,3,'80 m pred železničným priecestím jazdiť rýchlosťou najviac 60 km/h','zastaviť vozidlo pred železničným priecestím,','50 m pred železničným priecestím a pri jeho prechádzaní jazdiť rýchlosťou najviac 50 km/h');
INSERT INTO `Questions` VALUES (658,658,0,1,'Ak vozidlo nie je vybavené smerovými svietidlami alebo ak majú poruchu, dáva sa znamenie o zmene smeru jazdy','',2,1,'upažením; rukou ohnutou v lakti hore sa dáva znamenie o zmene smeru jazdy na opačnú stranu,','predpažením; zapažením sa dáva znamenie o zmene smeru jazdy na opačnú stranu,','mimo obce svetelným výstražným znamením a v obci zvukovým výstražným znamením počas celého jazdného úkonu.');
INSERT INTO `Questions` VALUES (659,659,0,1,'Vodič','',2,2,'môže dovoliť, aby sa prekročil povolený počet prepravovaných osôb, ak s tým vopred vyslovili súhlas všetky prepravované osoby,','nesmie dovoliť, aby sa prekročil povolený počet prepravovaných osôb,','môže dovoliť, aby sa prekročil povolený počet prepravovaných osôb, najviac však o 20 %.');
INSERT INTO `Questions` VALUES (660,660,0,1,'Vedúci organizovaného útvaru školskej mládeže alebo organizovanej skupiny detí, ktoré nepodliehajú povinnej školskej dochádzke, alebo sprievodca osôb so zdravotným postihnutím pri prechádzaní cez vozovku','',2,1,'je oprávnený dávať pokyny na zastavenie vozidla,','je oprávnený dávať pokyny na zastavenie vozidla len ak je starší ako 25 rokov,','je oprávnený dávať pokyny na zastavenie vozidla v obci v čase od 7.00 hod. do 15,00 hod.');
INSERT INTO `Questions` VALUES (661,661,0,1,'Ak sa pri vlečení motorového vozidla použije tyč, musí byť zreteľne označená','',1,1,'priečnymi červenými a bielymi pruhmi so šírkou 7,5 cm,','priečnymi žltými a čiernymi pruhmi so šírkou najmenej 10 cm,','šikmými červenými pruhmi.');
INSERT INTO `Questions` VALUES (662,662,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,3,'najmenej desaťlitrová zásoba pohonných hmôt v osobitnej nádobe,','ťažná tyč s dĺžkou najmenej 3 m, určená na vlečenie vozidiel,','príručný zdvihák s nosnosťou rovnajúcou sa aspoň zaťaženiu najviac zaťaženej nápravy vozidla alebo rovnajúcou sa hmotnosti zdvíhanej časti vozidla z najväčšej prípustnej celkovej');
INSERT INTO `Questions` VALUES (663,663,0,1,'Ak zjavne uniká palivo, olej, mazivo alebo iné prevádzkové náplne z vozidla,','',1,2,'musí to vodič po skončení jazdy oznámiť držiteľovi vozidla,','považuje sa vozidlo za technicky nespôsobilé na premávku na pozemných komunikáciách,','smie sa takéto vozidlo, okrem diaľnice a rýchlostnej cesty, používať v cestnej premávke.');
INSERT INTO `Questions` VALUES (664,664,1,1,'Táto dopravná značka upozorňuje na','a19',2,2,'miesto, kde sa nachádza skládka posypového materiálu,','prácu na ceste, prípadne jej súčastiach, ktorá by mohla ohroziť bezpečnosť cestnej premávky,','zákaz práce na ceste.');
INSERT INTO `Questions` VALUES (665,665,1,1,'Táto dopravná značka znamená:','p6',2,2,'križovatka, na ktorej platí zákaz odbočovania vpravo,','križovatka s vedľajšou cestou,','kríženie cesty sprava s lesnou alebo poľnou cestou.');
INSERT INTO `Questions` VALUES (666,666,1,1,'Táto dopravná značka znamená:','b17',2,3,'Vjazd motorových vozidiel s prívesmi povolený,','Zákaz parkovania prívesov,','Zákaz vjazdu motorových vozidiel s prívesmi.');
INSERT INTO `Questions` VALUES (667,667,1,1,'Táto dopravná značka s dodatkovou tabuľkou označuje','spec87',2,1,'vedľajšiu cestu, vyznačuje skutočný tvar križovatky a aj hlavnú a vedľajšiu cestu,','miesto kríženia cesty s diaľnicou,','prikázaný smer jazdy cez križovatku.');
INSERT INTO `Questions` VALUES (668,668,1,1,'Táto dopravná značka znamená:','ip8',2,3,'Tunel,','Vyjazdené koľaje,','Spomaľovací prah.');
INSERT INTO `Questions` VALUES (669,669,1,1,'Táto dopravná značka znamená:','c30',2,3,'Zníženie počtu jazdných pruhov,','Dopravná nehoda,','Striedavé radenie.');
INSERT INTO `Questions` VALUES (670,670,1,1,'Táto dopravná značka znamená:','is34',2,1,'Hranica okresu,','Diaľková návesť,','Návesť pred križovatkou.');
INSERT INTO `Questions` VALUES (671,671,1,1,'Táto dopravná značka vyznačuje','v11a',2,3,'zákaz zastavenia a státia pre autobusy alebo trolejbusy,','parkovisko vyhradené pre autobusy alebo trolejbusy,','priestor zastávky autobusu alebo trolejbusu.');
INSERT INTO `Questions` VALUES (672,672,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','672',3,2,'1. červené, 2. modré, 3. zelené,','1. červené vojde do križovatky a dá prednosť v jazde protiidúcemu modrému, 2. zelené, 3. modré, 4. červené dokončí odbočovanie vľavo,','1. modré, 2. červené, 3. zelené.');
INSERT INTO `Questions` VALUES (673,673,2,1,'Ako prvé prejde cez križovatku','673',3,3,'modré vozidlo,','červené vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (674,674,2,1,'V poradí druhé prejde cez križovatku','674',3,3,'zelené vozidlo,','modré vozidlo,','vaše vozidlo.');
INSERT INTO `Questions` VALUES (675,675,2,1,'Vaše vozidlo prejde cez križovatku ako','675',3,1,'prvé,','druhé,','posledné.');
INSERT INTO `Questions` VALUES (676,676,0,1,'Križovatkou sa rozumie','',2,3,'miesto, v ktorom cesta mení smer,','mimoúrovňové kríženie cesty so železnicou,','miesto, v ktorom sa cesty pretínajú alebo spájajú.');
INSERT INTO `Questions` VALUES (677,677,0,1,'Účastník cestnej premávky','',2,3,'je povinný dbať na výstražné dopravné značky, zákazové dopravné značky a svetelné signály; na iné dopravné značky a dopravné zariadenia je povinný dbať len vodič motorového vozidla,','nie je povinný dbať na dopravné zariadenia,','je povinný poslúchnuť pokyn vyplývajúci z dopravnej značky alebo dopravného zariadenia.');
INSERT INTO `Questions` VALUES (678,678,0,1,'Osoba sediaca na sedadle vozidla povinne vybavenom bezpečnostným pásom alebo iným zadržiavacím zariadením je povinná toto zariadenie použiť; to neplatí pre','',2,1,'osobu, ktorá nemôže byť pripútaná zo zdravotných dôvodov; takáto osoba sa musí preukázať osvedčením o oslobodení od použitia bezpečnostných systémov vozidla,','osobu staršiu ako 65 rokov,','vodiča počas jazdy na účelovej komunikácii.');
INSERT INTO `Questions` VALUES (679,679,0,1,'Vodič nesmie predchádzať, ak','',2,1,'nemá pred sebou rozhľad na takú vzdialenosť, ktorá je potrebná na bezpečné predchádzanie,','by bol pritom nútený vojsť na električkový koľajový pás v úrovni vozovky,','pred ním jazdí vozidlo pravidelnej verejnej dopravy osôb.');
INSERT INTO `Questions` VALUES (680,680,0,1,'Vodič motocykla smie jazdiť rýchlosťou najviac','',2,1,'90 km/h, na diaľnici a na rýchlostnej ceste 130 km/h','110 km/h','100 km/h, na diaľnici a na rýchlostnej ceste 160 km/h');
INSERT INTO `Questions` VALUES (681,681,0,1,'Ak nie je ohrozená bezpečnosť a plynulosť cestnej premávky, vodič smie','',2,1,'v obci zastaviť a stáť kolmo, prípadne šikmo na okraj cesty,','mimo obce zastaviť a stáť šikmo na okraj cesty,','v obci aj mimo obce zastaviť a stáť kolmo na okraj cesty.');
INSERT INTO `Questions` VALUES (682,682,0,1,'Pred vjazdom na cestu z miesta mimo cesty, alebo na vyhradenom parkovisku, ak nejde o vozidlo, pre ktoré je parkovisko vyhradené, vodič','',2,2,'môže zastaviť a stáť, ak zastavenie ani státie nepresiahne päť minút a neohrozí pritom vodičov motorových vozidiel,','nesmie zastaviť a stáť,','nesmie zastaviť a stáť; to neplatí, ak ide o zastavenie a státie, ktoré nepresiahne tri minúty.');
INSERT INTO `Questions` VALUES (683,683,0,1,'Na upozornenie vodiča predchádzaného vozidla mimo obce vodič smie dávať','',2,3,'svetelné výstražné znamenie zapnutím výstražnej funkcie smerových svietidiel,','znamenie kývaním ruky,','zvukové výstražné znamenie.');
INSERT INTO `Questions` VALUES (684,684,0,1,'Vozidlom s právom prednostnej jazdy je vozidlo,','',2,3,'ktoré je vybavené zvláštnym výstražným svetlom zelenej farby,','ktoré prepravuje nebezpečný náklad,','ktorého vodič pri plnení špeciálnych úloh používa typické zvukové znamenie doplnené zvláštnym výstražným modrým svetlom alebo červeným svetlom, prípadne ich kombináciou.');
INSERT INTO `Questions` VALUES (685,685,0,1,'Prepravované osoby nesmú','',2,3,'obsluhovať telefónny pristroj,','jesť, piť ani fajčiť,','svojím správaním ohrozovať bezpečnosť cestnej premávky.');
INSERT INTO `Questions` VALUES (686,686,0,1,'Účastník dopravnej nehody je povinný poskytnúť podľa svojich schopností a možností zranenej osobe','',2,2,'potrebnú prvú pomoc len vtedy, ak je vážne ohrozený život viacerých osôb,','potrebnú prvú pomoc a bezodkladne privolať záchrannú zdravotnú službu,','prvú pomoc a privolať záchrannú zdravotnú službu len vtedy, ak dopravnú nehodu zavinil.');
INSERT INTO `Questions` VALUES (687,687,0,1,'Mimo priechodu pre chodcov sa smie cez vozovku prechádzať len','',2,2,'v obytnej a školskej zóne a kolmo na os vozovky,','kolmo na jej os,','mimo obce.');
INSERT INTO `Questions` VALUES (688,688,0,1,'Jazdci na zvieratách smú ísť','',1,1,'len jednotlivo za sebou,','najviac dvaja vedľa seba,','najviac traja vedľa seba.');
INSERT INTO `Questions` VALUES (689,689,0,1,'Hĺbka hlavných drážok v stredovej časti povrchu dezénu pneumatiky, ktorý pokrýva približne tri štvrtiny šírky povrchu dezénu jazdnej plochy pneumatiky, nesmie byť menej ako','',1,2,'1,5 mm na osobnom automobile,','1,6 mm na osobnom automobile,','1,7 mm na osobnom automobile.');
INSERT INTO `Questions` VALUES (690,690,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'dodatočne namontované svetelné zariadenia narúšajú výhľad z miesta spolujazdca,','najnižší bod činnej svietiacej plochy brzdových svetiel je vyššie ako 350 mm nad rovinou vozovky,','niektoré svetelné zariadenie dôležité pre bezpečnosť premávky na pozemných komunikáciách chýba alebo je nesprávne umiestnené, nesvieti alebo nespĺňa ustanovené podmienky, takže hrozí bezprostredné nebezpečenstvo.');
INSERT INTO `Questions` VALUES (691,691,1,1,'Táto dopravná značka znamená:','a1b',2,2,'Nebezpečné stúpanie,','Zákruta vľavo,','Zákaz odbočovania vľavo.');
INSERT INTO `Questions` VALUES (692,692,1,1,'Táto dopravná značka upozorňuje na','a3a',2,1,'miesto, kde klesanie cesty presahuje 10 % alebo kde miestne podmienky robia klesanie nebezpečným,','priklonenú strmú stráň zľava,','miesto, kde priečny sklon vozovky presahuje 10 %.');
INSERT INTO `Questions` VALUES (693,693,1,1,'Táto dopravná značka upozorňuje na','p5',2,2,'rýchlostnú cestu,','križovatku s vedľajšou cestou mimo obce a označuje hlavnú cestu,','kríženie cesty s lesnou alebo poľnou cestou.');
INSERT INTO `Questions` VALUES (694,694,1,1,'Tieto dopravné značky upozorňujú na','spec32',2,1,'železničné priecestie bez závor vo vzdialenosti 240 m,','železničné priecestie bez závor vo vzdialenosti 180 m,','železničné priecestie so závorami vo vzdialenosti 200 m.');
INSERT INTO `Questions` VALUES (695,695,1,1,'Táto dopravná značka znamená:','ip17a',2,1,'Platené parkovisko,','Zákaz parkovania v párnych dňoch,','Parkovisko s parkovacím kotúčom.');
INSERT INTO `Questions` VALUES (696,696,1,1,'Táto dopravná značka','ip21a',2,1,'označuje blízkosť vjazdu do tunela, kde platia pravidlá cestnej premávky pre správanie sa v tuneli,','informuje o povinnosti pred vjazdom do tunela zapnúť stretávacie svetlomety,','označuje blízkosť vjazdu do tunela pre koľajové vozidlá.');
INSERT INTO `Questions` VALUES (697,697,1,1,'Táto dopravná značka znamená:','is18a',2,1,'Smerová tabuľa (s dvoma cieľmi),','Diaľková návesť,','Návesť pred križovatkou.');
INSERT INTO `Questions` VALUES (698,698,1,1,'Tieto žlté a čierne pruhy označujú','z2c',2,2,'čiastočnú uzávierku cesty,','trvalú prekážku, (pilier, stenu a podobne),','dočasnú prekážku cestnej premávky (materiál na ceste a podobne).');
INSERT INTO `Questions` VALUES (699,699,2,1,'Vodič modrého vozidla','699',3,3,'má pred vodičom červeného a vodičom žltého vozidla prednosť, pretože v ich jazdnom pruhu sa nachádza prekážka,','je povinný umožniť vodičovi červeného a vodičovi žltého vozidla obídenie prekážky,','je povinný umožniť vodičovi červeného vozidla obídenie prekážky.');
INSERT INTO `Questions` VALUES (700,700,2,1,'Ak svieti signál na opustenie križovatky umiestnený v protiľahlom rohu križovatky','700',3,2,'vodiči obidvoch električiek majú prednosť pred ostatnými vozidlami,','vodič červeného vozidla odbočujúceho vľavo má prednosť vjazde pred protiidúcim zeleným a žltým vozidlom a obidvoma električkami,','vodič červeného vozidla odbočujúceho vľavo je povinný dať prednosť protiidúcemu zelenému a žltému vozidlu a obidvom električkám.');
INSERT INTO `Questions` VALUES (701,701,2,1,'Vaše vozidlo prejde cez križovatku ako','701',3,3,'druhé,','prvé,','posledné.');
INSERT INTO `Questions` VALUES (702,702,2,1,'Vaše vozidlo prejde cez križovatku ako','702',3,3,'tretie,','prvé,','druhé.');
INSERT INTO `Questions` VALUES (703,703,0,1,'Križovatkou s riadenou premávkou sa rozumie','',2,3,'každé miesto, v ktorom sa cesty pretínajú alebo spájajú,','miesto, na ktorom je premávka riadená policajtom alebo inou osobou oprávnenou dávať pokyny na zastavenie vozidla,','križovatka, na ktorej je premávka riadená dopravnými zariadeniami alebo policajtom, prípadne inou oprávnenou osobou.');
INSERT INTO `Questions` VALUES (704,704,0,1,'Motorové vozidlo musí mať počas jazdy rozsvietené','',2,1,'stretávacie svetlomety alebo im na roveň postavené osvetlenie,','diaľkové svetlomety,','svetlá vo vnútri vozidla.');
INSERT INTO `Questions` VALUES (705,705,0,1,'Vodič nesmie','',2,1,'viesť vozidlo po požití lieku v čase, keď liek môže znížiť jeho schopnosť viesť vozidlo,','viesť vozidlo po požití lieku v čase, keď liek môže znížiť jeho schopnosť viesť vozidlo; to neplatí, ak sa vo vozidle nachádza spolujazdec,','viesť vozidlo po miestnych komunikáciách v čase od 0.00 hod. do 4.00 hod.');
INSERT INTO `Questions` VALUES (706,706,0,1,'Mimo obce na ceste s troma alebo s viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy smie vodič motocykla s najväčšou konštrukčnou rýchlosťou do 45 km/h použiť na jazdu','',2,1,'výhradne dva jazdné pruhy najbližšie k pravému okraju vozovky; v ostatných jazdných pruhoch vodič smie jazdiť, ak je to potrebné na obchádzanie, otáčanie alebo na odbočovanie','výhradne pravý jazdný pruh; v ostatných jazdných pruhoch nesmie jazdiť za žiadnych okolností,','len ľavý jazdný pruh.');
INSERT INTO `Questions` VALUES (707,707,0,1,'Ak je to nevyhnutne potrebné najmä na zaradenie do radu stojacich vozidiel alebo na vyjdenie z neho, vodič smie cúvať','',2,3,'na priechode pre chodcov,','na križovatke s riadenou premávkou,','na jednosmernej ceste.');
INSERT INTO `Questions` VALUES (708,708,0,1,'Vodič nesmie zastaviť a stáť na železničnom priecestí, v podjazde a v tuneli a vo vzdialenosti kratšej ako','',2,2,'80 m pred nimi a 80 m za nimi,','15 m pred nimi a 15 m za nimi,','160 m pred nimi a 160 m za nimi.');
INSERT INTO `Questions` VALUES (709,709,0,1,'Znamenie o zmene smeru jazdy rukou sa dáva','',2,3,'počas celého jazdného úkonu,','po začatí jazdného úkonu,','len pred začatím jazdného úkonu.');
INSERT INTO `Questions` VALUES (710,710,0,1,'Vlečenie motorového vozidla na diaľnici je','',2,1,'dovolené len vtedy, ak je to nevyhnutné na jeho odstránenie z diaľnice,','dovolené, len ak je vlečeným vozidlom osobné motorové vozidlo,','zakázané za každých okolností.');
INSERT INTO `Questions` VALUES (711,711,0,1,'V úseku diaľnice prechádzajúcom cez obec smie vodič motorového vozidla jazdiť rýchlosťou najmenej','',2,3,'45 km/h','85 km/h','65 km/h');
INSERT INTO `Questions` VALUES (712,712,0,1,'Účastník dopravnej nehody je povinný preukázať svoju totožnosť na požiadanie','',2,3,'každej osoby, ktorá sa nachádza na mieste dopravnej nehody,','len policajta,','iného účastníka dopravnej nehody.');
INSERT INTO `Questions` VALUES (713,713,0,1,'Ak na stojacom vozidle svieti zvláštne výstražné svetlo modrej alebo červenej farby, prípadne ich kombinácia musí vodič iného vozidla','',2,2,'zvýšiť rýchlosť jazdy,','zvýšiť opatrnosť, znížiť rýchlosť jazdy, prípadne zastaviť vozidlo,','bezodkladne zastaviť vozidlo.');
INSERT INTO `Questions` VALUES (714,714,0,1,'Osoba vykonávajúca práce spojené s jej údržbou, opravou alebo s výstavbou cesty je oprávnená dávať pokyny na zastavenie vozidla,','',2,2,'ak to vyžaduje plynulosť cestnej premávky; pritom musí pri sebe mať vodičský preukaz,','ak to vyžaduje bezpečnosť cestnej premávky,','len ak ju tým poveril orgán Policajného zboru.');
INSERT INTO `Questions` VALUES (715,715,0,1,'Cyklista musí mať za zníženej viditeľnosti','',1,2,'oblečený odev s nápisom "CYKLISTA",','pri jazde po krajnici alebo po okraji vozovky na sebe viditeľne umiestnené reflexné prvky alebo oblečený reflexný bezpečnostný odev,','pri jazde v pešej zóne, obytnej zóne a školskej zóne oblečený reflexný bezpečnostný odev.');
INSERT INTO `Questions` VALUES (716,716,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,2,'najmenej dvojlitrová zásoba maziva v osobitnej nádobe,','bezpečnostný odev (bezpečnostná reflexná vesta, overal, nohavice, bunda alebo pláštenka) umiestnený v dosahu zo sedadla vodiča vozidla,','krieda na vyznačenie stôp a postavenia vozidiel v prípade dopravnej nehody.');
INSERT INTO `Questions` VALUES (717,717,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'poškodený lak na zadnom nárazníku,','miesta vodiča nie je možné nastaviť pravé spätné zrkadlo.','výhľad z miesta vodiča je obmedzený alebo znemožnený.');
