INSERT INTO `Questions` VALUES (719,719,1,1,'Táto dopravná značka znamená:','p10',2,3,'Prednosť pred protiidúcimi vozidlami,','Obojsmerná premávka,','Prednosť protiidúcich vozidiel.');
INSERT INTO `Questions` VALUES (720,720,1,1,'Táto dopravná značka znamená:','b13',2,2,'Priechod pre chodcov,','Zákaz vstupu chodcov,','Pešia zóna.');
