INSERT INTO `Questions` VALUES (723,723,1,1,'Táto dopravná značka','is7a',2,2,'prikazuje jazdu smerom, ktorým šípka ukazuje,','informuje o cieli v smere odbočenia,','informuje o uzávierke cesty a vyznačuje smer obchádzky.');
INSERT INTO `Questions` VALUES (724,724,1,1,'Táto dopravná značka znamená:','v6a',2,1,'Priechod pre chodcov,','Priechod pre cyklistov,','Priechod pre jazdcov na koni.');
INSERT INTO `Questions` VALUES (725,725,1,1,'Táto dodatková tabuľka vyznačuje','e2',2,1,'vzdialenosť k miestu, od ktorého platí značka, pod ktorou je tabuľka umiestnená,','dĺžku úseku, pre ktorý platí značka, pod ktorou je tabuľka umiestnená,','vzdialenosť od začiatku cesty.');
INSERT INTO `Questions` VALUES (726,726,2,1,'Prednosť v jazde má vodič','726',3,2,'modrého vozidla, pretože ide po kruhovom objazde','modrého vozidla, pretože prichádza na križovatku po ceste označenej ako hlavná,','červeného vozidla, pretože prichádza na križovatku sprava.');
INSERT INTO `Questions` VALUES (727,727,2,1,'Ako prvé prejde cez križovatku','727',3,1,'červené vozidlo súčasne s modrým vozidlom,','modré vozidlo súčasne s obidvoma električkami,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (728,728,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','728',3,2,'1. vaše vozidlo, 2. zelené, 3, modré,','1. zelené, 2. modré, 3. vaše vozidlo,','1. modré, 2. vaše vozidlo, 3. zelené.');
