INSERT INTO `Questions` VALUES (730,730,0,1,'Zastavením vozidla sa rozumie','',2,1,'prerušenie jazdy z dôvodu nezávislého od vôle vodiča,','každé prerušenie jazdy,','uvedenie motorového vozidla do pokoja na čas nevyhnutne potrebný na urýchlené nastúpenie alebo vystúpenie prepravovaných osôb, najviac však na tri minúty.');
INSERT INTO `Questions` VALUES (731,731,0,1,'Vodičom sa rozumie','',2,3,'osoba, ktorá najmä vedie motorové alebo nemotorové vozidlo, tlačí motocykel, pohybuje sa na lyžiach alebo kolieskových korčuliach, ťahá alebo tlačí sánky,','len osoba, ktorá vedie motorové vozidlo,','osoba, ktorá vedie vozidlo.');
INSERT INTO `Questions` VALUES (732,732,0,1,'Ak vozidlo vrátane nákladu alebo jeho upevnenia nespĺňa ustanovené podmienky, prevádzkovateľ vozidla','',2,2,'so súhlasom vodiča môže dovoliť, aby sa vozidlo použilo na jazdu,','nesmie prikázať ani dovoliť, aby sa vozidlo použilo na jazdu,','môže prikázať, aby sa vozidlo použilo na jazdu v obci.');
INSERT INTO `Questions` VALUES (733,733,0,1,'Pozdĺž električky sa jazdí','',2,1,'vpravo, ak nie je dopravnou značkou povolená jazda vľavo,','vľavo, ak nie je dopravnou značkou povolená jazda vpravo,','za každých okolností vľavo.');
INSERT INTO `Questions` VALUES (734,734,0,1,'Vodič pri odbočovaní nesmie','',2,2,'dávať znamenie o zmene smeru jazdy,','ohroziť vodiča idúceho za ním,','dávať znamenie o zmene smeru jazdy, ak odbočuje na miesto mimo cesty.');
INSERT INTO `Questions` VALUES (735,735,0,1,'Vodič sa nesmie otáčať a cúvať','',2,1,'na železničnom priecestí a v jeho tesnej blízkosti,','na železničnom priecestí a vo vzdialenosti 500 m pred ním,','v obytnej zóne.');
INSERT INTO `Questions` VALUES (736,736,0,1,'Pri státí musí zostať voľný aspoň jeden jazdný pruh široký najmenej','',2,1,'3 m pre každý smer jazdy,','3 m pre oba smery jazdy,','2,5 m.');
INSERT INTO `Questions` VALUES (737,737,0,1,'Vodič, ktorý sa chce vzdialiť od vozidla tak, že nebude môcť okamžite zasiahnuť, je povinný urobiť také opatrenia, aby vozidlo nemohlo ohroziť bezpečnosť a plynulosť cestnej premávky a aby ho nemohla neoprávnene použiť iná osoba. Ak je vozidlo povinne vybavené zariadením proti neoprávnenému použitiu, vodič','',2,3,'nie je povinný ho použiť v obci,','je povinný ho použiť, len ak vo vozidle zostali cenné veci,','je povinný ho použiť.');
INSERT INTO `Questions` VALUES (738,738,0,1,'Ak je vozidlo vybavené osobitným zariadením, ktoré umožňuje výstražnú funkciu smerových svietidiel, vodič je povinný ho použiť','',2,1,'počas núdzového státia, aspoň v čase, kým umiestni prenosný výstražný trojuholník na vozovke,','počas cúvania na križovatke s riadenou premávkou,','počas otáčania na priechode pre chodcov.');
INSERT INTO `Questions` VALUES (739,739,0,1,'Na pripájacom alebo na odbočovacom pruhu vodič','',2,3,'môže zastaviť a stáť,','môže len zastaviť, nesmie však stáť,','nesmie zastaviť a stáť.');
INSERT INTO `Questions` VALUES (740,740,0,1,'Ak pri jazde vozidla v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným, alebo ak vznikne dopravná nehoda vrátane požiaru, je vodič po zastavení vozidla povinný bezodkladne','',2,2,'vypnúť stretávacie svetlomety,','vypnúť motor,','oznámiť zastavenie vozidla príslušnému obvodnému úradu.');
INSERT INTO `Questions` VALUES (741,741,0,1,'Ak policajt pri riadení premávky dáva pokyn kývaním ruky hore a dolu, znamená to','',2,3,'zastaviť vozidlo,','zrýchliť jazdu,','spomaliť jazdu.');
INSERT INTO `Questions` VALUES (742,742,0,1,'Ak náklad na vozidle prečnieva do strany musí byť prečnievajúci koniec nákladu označený','',1,1,'reflexným označením s červenými a bielymi pruhmi širokými 70 až 100 mm a smerujúcimi od pozdĺžnej strednej roviny vozidla pod uhlom 45 nadol,','červenou zástavkou s rozmermi najmenej 30 x 30 cm.','vždy žltými a čiernymi pruhmi.');
INSERT INTO `Questions` VALUES (743,743,0,1,'Hĺbka hlavných drážok v stredovej časti povrchu dezénu pneumatiky, ktorý pokrýva približne tri štvrtiny šírky povrchu dezénu jazdnej plochy pneumatiky, nesmie byť menej ako','',1,2,'1,5 mm na osobnom automobile,','1,6 mm na osobnom automobile,','1,7 mm na osobnom automobile.');
INSERT INTO `Questions` VALUES (744,744,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'niektoré svetelné zariadenie dôležité pre bezpečnosť premávky na pozemných komunikáciách chýba alebo je nesprávne umiestnené, nesvieti alebo nespĺňa ustanovené podmienky, takže hrozí bezprostredné nebezpečenstvo,','je katalyzátor výfukových plynov po lehote kalibrácie,','najvyšší bod činnej svietiacej plochy brzdových svetiel je nižšie ako 1500 mm nad rovinou vozovky.');
INSERT INTO `Questions` VALUES (745,745,1,1,'Táto dopravná značka znamená:','b17',2,2,'Vjazd motorových vozidiel s prívesmi povolený,','Zákaz vjazdu motorových vozidiel s prívesmi,','Zákaz parkovania prívesov.');
