INSERT INTO `Questions` VALUES (751,751,1,1,'Táto dodatková tabuľka vyznačuje','e8b',2,3,'koniec úseku, pre ktorý platí značka, pod ktorou je tabuľka umiestnená,','priebeh úseku s jednosmernou premávkou,','priebeh úseku, pre ktorý platí značka, pod ktorou je tabuľka umiestnená.');
INSERT INTO `Questions` VALUES (752,752,1,1,'Táto dopravná značka znamená:','v7',2,3,'Miesto vjazdu vozidiel na cestu z miesta ležiaceho mimo cesty,','Dovolené zastavenie a státie kolmo alebo šikmo na okraj vozovky,','Priechod pre cyklistov.');
INSERT INTO `Questions` VALUES (753,753,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','753',3,2,'1. červené, 2. žlté, 3. zelené,','1. žlté, 2. červené, 3. zelené,','1. zelené, 2. červené, 3. žlté.');
