INSERT INTO `Questions` VALUES (757,757,0,1,'Križovatkou s riadenou premávkou sa rozumie','',2,3,'každé miesto, v ktorom sa cesty pretínajú alebo spájajú,','miesto, na ktorom je premávka riadená policajtom alebo inou osobou oprávnenou dávať pokyny na zastavenie vozidla,','križovatka, na ktorej je premávka riadená dopravnými zariadeniami alebo policajtom, prípadne inou oprávnenou osobou.');
INSERT INTO `Questions` VALUES (758,758,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza, vodič motorového vozidla kategórie M1 a N1 môže takéto vozidlo použiť v cestnej premávke, len ak','',2,1,'je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené na hnacej náprave zimnými pneumatikami,','má uzatvorené havarijné poistenie.');
INSERT INTO `Questions` VALUES (759,759,0,1,'Vodič nesmie odovzdať vedenie vozidla osobe, ktorá','',2,2,'nemá najmenej trojročnú prax vo vedení takéhoto vozidla alebo je pod značným vplyvom alkoholu,','nespĺňa podmienky na vedenie vozidla ustanovené zákonom o cestnej premávke, osobe, ktorá je pod vplyvom alkoholu alebo inej návykovej látky, alebo osobe, ktorej schopnosť viesť vozidlo je inak znížená,','spĺňa podmienky ustanovené zákonom o cestnej premávke, je však mladšia ako 23 rokov.');
INSERT INTO `Questions` VALUES (760,760,0,1,'Vodič motocykla je povinný počas jazdy oboma rukami držať riadidlá motocykla okrem prípadu, keď','',2,2,'jazdí rýchlosťou nižšou ako 50 km/h','dáva znamenie o zmene smeru jazdy,','má dostatočnú prax vo vedení motocykla.');
INSERT INTO `Questions` VALUES (761,761,0,1,'Mimo obce na ceste s dvoma alebo s viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy sa jazdí','',2,3,'v ktoromkoľvek jazdnom pruhu,','v ľavom jazdnom pruhu; ostatné jazdné pruhy smie používať len vodič nemotorového vozidla,','v pravom jazdnom pruhu; v ostatných jazdných pruhoch sa smie jazdiť, ak je to potrebné na obchádzanie, predchádzanie, otáčanie alebo na odbočovanie.');
INSERT INTO `Questions` VALUES (762,762,0,1,'Ak sa vodič nemôže vyhnúť protiidúcej električke vpravo,','',2,2,'nesmie sa jej vyhýbať vľavo,','vyhýba sa jej vľavo,','môže na vyhýbanie použiť aj chodník.');
INSERT INTO `Questions` VALUES (763,763,0,1,'Vodič nesmie zastaviť a stáť','',2,1,'pred neprehľadným vrcholom stúpania cesty, na ňom a za ním,','na účelovej komunikácii za zníženej viditeľnosti,','na jednosmernej ceste vpravo.');
INSERT INTO `Questions` VALUES (764,764,0,1,'Vozidlá pred železničným priecestím','',2,2,'musia vždy zastaviť,','sa radia za sebou v poradí, v ktorom prišli,','musia zastaviť, ak svieti prerušované biele svetlo.');
INSERT INTO `Questions` VALUES (765,765,0,1,'Vlečenie viacerých motorových vozidiel je','',2,2,'dovolené, ak sa vlečú dve osobné motorové vozidlá,','zakázané,','dovolené, ak sa vlečú motocykle bez postranného vozíka.');
INSERT INTO `Questions` VALUES (766,766,0,1,'Kto spôsobil prekážku cestnej premávky,','',2,3,'je povinný ju odstrániť, len ak ju spôsobil na diaľnici; na ostatných cestách ju smie odstrániť len správca cesty ,','nesmie ju odstrániť; takúto prekážku cestnej premávky je povinný odstrániť správca cesty,','je povinný ju bezodkladne odstrániť; ak to neurobí, je povinný ju bezodkladne odstrániť na jeho náklady správca cesty.');
INSERT INTO `Questions` VALUES (767,767,0,1,'Ak pri jazde vozidla v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným, alebo ak vznikne dopravná nehoda vrátane požiaru, je vodič po zastavení vozidla povinný bezodkladne','',2,1,'vypnúť motor,','oznámiť zastavenie vozidla príslušnému obvodnému úradu,','vypnúť stretávacie svetlomety.');
INSERT INTO `Questions` VALUES (768,768,0,1,'V obytnej zóne, pešej zóne a školskej zóne vodič smie jazdiť rýchlosťou najviac','',2,3,'30 km/h','50 km/h','20 km/h');
INSERT INTO `Questions` VALUES (769,769,0,1,'Ak sa pri vlečení motorového vozidla použije lano, musí byť zreteľne označené','',1,3,'žltou zástavkou a štítkom s rozmermi najmenej 25 x 25 cm,','za zníženej viditeľnosti červeným neoslňujúcim svetlom,','červenou zástavkou alebo štítkom s rozmermi najmenej 20 x 20 cm.');
INSERT INTO `Questions` VALUES (770,770,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,3,'krieda na vyznačenie stôp a postavenia vozidla v prípade dopravnej nehody,','ťažná tyč s dĺžkou najmenej 3 m, určená na vlečenie vozidiel,','kľúč na matice alebo skrutky kolies.');
INSERT INTO `Questions` VALUES (771,771,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,2,'na zvukovom výstražnom zariadení došlo k zmene tónu,','výhľad z miesta vodiča je obmedzený alebo znemožnený,','sú poškodené lapače nečistôt.');
INSERT INTO `Questions` VALUES (772,772,1,1,'Tieto dopravné značky s dodatkovou tabuľkou upozorňujú na','spec42',2,2,'vlečkové priecestie vnútri závodu,','železničné priecestie bez závor na odbočujúcej ceste vo vzdialenosti 240 m,','smer jazdy vlaku na železničnom priecestí.');
INSERT INTO `Questions` VALUES (773,773,1,1,'Táto dopravná značka znamená:','b31a',2,1,'Najvyššia dovolená rýchlosť,','Najnižšia dovolená rýchlosť,','Odporúčaná rýchlosť.');
INSERT INTO `Questions` VALUES (774,774,1,1,'Táto dopravná značka znamená:','ip10',2,1,'Odporúčaná rýchlosť; vyjadruje číslom alebo číslami uvedenými na značke odporúčanú rýchlosť v kilometroch za hodinu za normálnych podmienok,','Obmedzenie najvyššej dovolenej rýchlosti; vyjadruje číslom na značke najvyššiu dovolenú rýchlosť na mokrej vozovke,','Cesta 1. triedy; informuje o čísle cesty 1. triedy.');
INSERT INTO `Questions` VALUES (775,775,1,1,'Táto dopravná značka informuje o','ii4',2,2,'blízkosti nemocnice,','mieste, kde sa poskytuje zdravotnícka prvá pomoc,','nepretržitom záchrannom systéme.');
