INSERT INTO `Questions` VALUES (778,778,1,1,'Táto dopravná značka informuje','ip29',2,3,'o blízkosti odpočívadla so sociálnym zariadením,','pred križovatkou o ceste, ktorá končí, alebo ktorou nemožno ďalej pokračovať v jazde,','o možnosti núdzového zastavenia vozidla v únikovej zóne v prípade technickej poruchy.');
INSERT INTO `Questions` VALUES (779,779,1,1,'Táto vodiaca tabuľa označuje','z3a',2,1,'najmä nebezpečnú zákrutu,','úsek cesty s nebezpečným stúpaním,','úplnú uzávierku cesty.');
INSERT INTO `Questions` VALUES (780,780,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','780',3,2,'1. červené súčasne s modrým, 2. zelené,','1. zelené, 2. červené súčasne s modrým,','1, modré, 2. zelené, 3. červené. (3 body)');
INSERT INTO `Questions` VALUES (781,781,2,1,'Modré vozidlo prejde cez križovatku ako','781',3,1,'druhé,','prvé,','posledné.');
