INSERT INTO `Questions` VALUES (783,783,2,1,'Ako prvé prejde cez križovatku','783',3,2,'červené vozidlo,','vaše vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (784,784,0,1,'Neohrozením sa rozumie povinnosť vodiča','',2,1,'počínať si tak, aby inému účastníkovi cestnej premávky nevzniklo nijaké nebezpečenstvo,','počínať si tak, aby inému účastníkovi cestnej premávky nijako neprekážal,','neobchádzať ani nepredchádzať vozidlo prepravujúce nebezpečné veci a jazdiť za takýmto vozidlom vo vzdialenosti najmenej 50 m.');
INSERT INTO `Questions` VALUES (785,785,0,1,'Vodič','',2,3,'môže počas vedenia vozidla obsluhovať telefónny prístroj,','nesmie počas vedenia vozidla počúvať rádio,','nesmie počas vedenia vozidla používať telefónny prístroj, okrem telefonovania s použitím systému "voľné ruky".');
INSERT INTO `Questions` VALUES (786,786,0,1,'Prevádzkovateľ vozidla je povinný zabezpečiť, aby sa farebné vyhotovenie a označenie vozidla nedalo zameniť s farebným vyhotovením a označením vozidiel','',2,3,'cudzích zastupiteľských úradov so sídlom na území Slovenskej republiky,','určených pre predsedov vyšších územných celkov,','Policajného zboru, Vojenskej polície, Železničnej polície, Obecnej polície, Hasičského a záchranného zboru alebo ostatných hasičských jednotiek.');
INSERT INTO `Questions` VALUES (787,787,0,1,'Pri vchádzaní na električkový koľajový pás a pri jeho prechádzaní vodič','',2,2,'môže podľa okolností obmedziť električku v jazde, nesmie ju však ohroziť,','nesmie ohroziť ani obmedziť električku vjazde,','môže prekážať v jazde električke len v rozsahu nevyhnutnom na vykonanie jazdného úkonu.');
INSERT INTO `Questions` VALUES (788,788,0,1,'Vodič motorového vozidla i nemotorového vozidla odbočujúci vpravo je povinný dať prednosť v jazde','',2,3,'protiidúcim vozidlám pravidelnej verejnej dopravy osôb, ak tieto odbočujú vľavo,','prvému vozidlu idúcemu za ním,','električke, ak je povolená jazda pozdĺž električky vľavo.');
INSERT INTO `Questions` VALUES (789,789,0,1,'Pri vchádzaní z miesta mimo cesty na cestu vodič','',2,3,'nie je povinný dať prednosť v jazde vozidlu idúcemu po ceste,','je povinný dať prednosť v jazde len vozidlu idúcemu po ceste sprava,','je povinný dať prednosť v jazde vozidlu idúcemu po ceste.');
INSERT INTO `Questions` VALUES (790,790,0,1,'Vodič vozidla, ktorý je povinne vybavené prenosným výstražným trojuholníkom, je povinný tento trojuholník použiť počas núdzového státia, ak také vozidlo tvorí prekážku cestnej premávky. Vodič je povinný trojuholník umiestniť na okraji vozovky tak, aby ho ','',2,2,'30 m za vozidlom mimo obce a na diaľnici a rýchlostnej ceste najmenej 60 m za vozidlom,','50 m za vozidlom a na diaľnici a rýchlostnej ceste najmenej 100 m za vozidlom; v obci môže byť táto vzdialenosť, ak to vyžadujú okolnosti, kratšia,','30 m za vozidlom v obci aj mimo obce.');
INSERT INTO `Questions` VALUES (791,791,0,1,'Vodič nesmie zastaviť a stáť na mieste, kde by vozidlo zakrývalo','',2,2,'zvislú dopravnú značku a akúkoľvek vodorovnú dopravnú značku,','zvislú dopravnú značku a svetelné signály,','reklamné zariadenie.');
INSERT INTO `Questions` VALUES (792,792,0,1,'Vozidlo musí mať počas jazdy rozsvietené','',2,1,'stretávacie svetlomety alebo im na roveň postavené osvetlenie, to neplatí pre nemotorové vozidlo, ktoré musí mať rozsvietené svietidlá počas zníženej viditeľnosti,','diaľkové svetlomety,','svetlá vo vnútri vozidla.');
INSERT INTO `Questions` VALUES (793,793,0,1,'Vozidlo s právom prednostnej jazdy a vozidlo, ktoré sprevádza,','',2,2,'majú pri čerpaní pohonných látok prednosť, len ak pritom používajú zvláštne výstražné znamenie,','majú pri čerpaní pohonných látok prednosť; pritom nemusia používať zvláštne výstražné znamenie,','nesmú čerpať pohonné látky na čerpacej stanici, ktorá je prístupná aj ostatným účastníkom cestnej premávky.');
INSERT INTO `Questions` VALUES (794,794,0,1,'Na motocykli sa nesmie prepravovať','',2,2,'osoba staršia ako 60 rokov,','osoba mladšia ako 12 rokov,','osoba mladšia ako 21 rokov.');
INSERT INTO `Questions` VALUES (795,795,0,1,'Účastník dopravnej nehody je povinný','',2,1,'zotrvať na mieste dopravnej nehody až do príchodu policajta alebo sa na toto miesto bezodkladne vrátiť po poskytnutí alebo privolaní pomoci, alebo po ohlásení dopravnej nehody,','je povinný zotrvať na mieste dopravnej nehody; to neplatí, ak preukázal svoju totožnosť ostatným účastníkom dopravnej nehody,','zotrvať na mieste dopravnej nehody až do príchodu odťahovej služby.');
INSERT INTO `Questions` VALUES (796,796,0,1,'Hry detí na ceste sú dovolené','',1,1,'len v obytnej zóne,','len v pešej zóne,','v obytnej a pešej zóne.');
INSERT INTO `Questions` VALUES (797,797,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'sú prekročené emisné limity motora určené výrobcom; ak ich výrobca neurčil, tak ustanovené emisné limity motora,','je katalyzátor výfukových plynov po lehote kalibrácie,','nieje vybavené riadeným katalyzátorom.');
INSERT INTO `Questions` VALUES (798,798,0,1,'Povinnou výbavou motorového vozidla kategórie M, N, T, C a PS sú','',1,3,'najmenej jeden zakladací klin pre každú nápravu motorového vozidla,','krieda na vyznačenie stôp a postavenia vozidla v prípade dopravnej nehody,','homologizovaný prenosný výstražný trojuholník.');
INSERT INTO `Questions` VALUES (799,799,1,1,'Táto dopravná značka znamená:','b4',2,3,'Zákaz vjazdu všetkých nemotorových vozidiel a električiek,','Zákaz vjazdu osobných automobilov,','Zákaz vjazdu všetkých motorových vozidiel s výnimkou motocyklov bez postranného vozíka.');
INSERT INTO `Questions` VALUES (800,800,1,1,'Táto dopravná značka znamená:','b29b',2,2,'Zákaz predchádzania osobných automobilov,','Koniec zákazu predchádzania,','Koniec zákazu obchádzania.');
INSERT INTO `Questions` VALUES (801,801,1,1,'Táto dopravná značka označuje','p2',2,1,'vedľajšiu cestu; na príkaz tejto značky je vodič povinný zastaviť vozidlo na takom mieste, odkiaľ má na križovatku náležitý rozhľad,','slepú ulicu,','zastávku vozidla pravidelnej verejnej dopravy osôb.');
INSERT INTO `Questions` VALUES (802,802,1,1,'Táto dopravná značka znamená:','c4c',2,3,'Zákruta vľavo,','Návesť pred obchádzkou,','Prikázaný smer jazdy.');
INSERT INTO `Questions` VALUES (803,803,1,1,'Táto dopravná značka znamená:','p8',2,1,'Hlavná cesta,','Rýchlostná cesta,','Vedľajšia cesta.');
INSERT INTO `Questions` VALUES (804,804,1,1,'Táto dopravná značka znamená:','ip16',2,2,'Zákaz parkovania,','Parkovisko - parkovacie miesta s vyhradeným státím,','Vyhradené parkovisko.');
INSERT INTO `Questions` VALUES (805,805,1,1,'Táto dopravná značka znamená:','is4',2,1,'Návesť pred križovatkou,','Rýchlostná cesta,','Diaľková návesť.');
INSERT INTO `Questions` VALUES (806,806,1,1,'Táto zábrana vyznačuje','z2a',2,3,'uzávierku časti šírky cesty,','trvalú prekážku na ceste,','uzávierku celej šírky cesty.');
INSERT INTO `Questions` VALUES (807,807,2,1,'Vodič modrého vozidla','807',3,1,'nesmie ohroziť vodiča červeného vozidla jazdiaceho v priebežnom jazdnom pruhu, do ktorého prechádza,','má pred vodičom červeného vozidla prednosť, pretože ide v jazdnom pruhu určenom na predchádzanie,','má pred vodičom červeného vozidla prednosť, pretože ide v jazdnom pruhu pre pomalé vozidlá.');
INSERT INTO `Questions` VALUES (808,808,2,1,'Ak má policajt pravú ruku predpaženú a ľavú upaženú, znamená to "Stoj!" pre','808',3,1,'vodiča červeného a vodiča žltého vozidla,','vodiča zeleného vozidla,','chodcov prechádzajúcich za chrbtom policajta.');
INSERT INTO `Questions` VALUES (809,809,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','809',3,2,'1. modré, 2 .zelené, 3. vaše vozidlo,','všetky tri súčasne,','1. vaše vozidlo, 2. zelené, 3. modré.');
INSERT INTO `Questions` VALUES (810,810,2,1,'Vozidlá prejdú cez križovatku v poradí:','810',3,1,'1. obidve električky súčasne, 2. vaše vozidlo súčasne s modrým,','1. vaše vozidlo, 2. modré, 3. obidve električky súčasne,','1. modré, 2. vaše vozidlo, 3. obidve električky súčasne.');
INSERT INTO `Questions` VALUES (811,811,0,1,'Vodičom sa rozumie','',2,1,'osoba, ktorá vedie vozidlo,','osoba, ktorá vedie najmä motorové alebo nemotorové vozidlo, tlačí motocykel, pohybuje sa na lyžiach alebo kolieskových korčuliach, ťahá alebo tlači sánky,','len osoba, ktorá vedie motorové vozidlo.');
INSERT INTO `Questions` VALUES (812,812,0,1,'Vodič malého motocykla','',2,3,'nesmie jazdiť po pravej krajnici za žiadnych okolností,','smie jazdiť po pravej krajnici len pri obchádzaní a vyhýbaní,','smie jazdiť po pravej krajnici, len ak tým neohrozí a neobmedzí pohyb chodcov.');
INSERT INTO `Questions` VALUES (813,813,0,1,'Vodič sa nesmie otáčať','',2,3,'na ceste 1. triedy,','na žiadnej križovatke,','na jednosmernej ceste.');
INSERT INTO `Questions` VALUES (814,814,0,1,'Vodič smie zastaviť a stáť','',2,2,'na pripájacom alebo na odbočovacom pruhu,','v obci na križovatke tvaru "T" na náprotivnej strane vyúsťujúcej cesty,','na vnútornom jazdnom pruhu.');
INSERT INTO `Questions` VALUES (815,815,0,1,'Vodič nesmie vchádzať na železničné priecestie, ak','',2,3,'svieti prerušované biele svetlo,','osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva pokyn vodorovným kývaním ruky s červenou zástavkou cez stred tela,','sa dáva výstraha dvoma červenými striedavo prerušovanými svetlami priecestného zabezpečovacieho zariadenia.');
INSERT INTO `Questions` VALUES (816,816,0,1,'Znamenie dávané smerovými svietidlami vodič ponechá len v čase, kým','',2,2,'nezačne meniť smer jazdy,','mení smer jazdy, vybočuje z neho alebo kým vozidlo nezaujme miesto v jazdnom pruhu, do ktorého prechádza,','nezačne vybočovať zo smeru jazdy.');
INSERT INTO `Questions` VALUES (817,817,0,1,'Vlečenie motorového vozidla na diaľnici je dovolené','',2,1,'len vtedy, ak je to nevyhnutné na jeho odstránenie z diaľnice','rýchlosťou najmenej 70 km/h','len na lane');
INSERT INTO `Questions` VALUES (818,818,0,1,'Do skupiny vozidiel tvorenej vozidlami s právom prednostnej jazdy a vozidlami, ktoré sprevádzajú, sa vodič iného vozidla','',2,2,'smie zaraďovať, len ak to dovoľuje situácia v cestnej premávke,','nesmie zaraďovať,','smie zaraďovať, ak dokáže prispôsobiť rýchlosť jazdy svojho vozidla rýchlosti jazdy takýchto vozidiel.');
INSERT INTO `Questions` VALUES (819,819,0,1,'V motorovom vozidle smú sa na miestach na to vyhradených prepravovať osoby','',2,3,'len do prípustnej užitočnej hmotnosti vozidla, pritom počet prepravovaných osôb starších ako 12 rokov nesmie byť vyšší, ako je počet miest uvedených v osvedčení o evidencii,','staršie ako 15 rokov,','len do prípustnej užitočnej hmotnosti vozidla, pritom počet prepravovaných osôb nesmie byť vyšší, ako je počet miest uvedených v osvedčení o evidencii.');
INSERT INTO `Questions` VALUES (820,820,0,1,'Chodci smú isť po krajnici alebo po okraji vozovky, ak tým, najmä za zníženej viditeľnosti alebo za zvýšenej premávky, neohrozia alebo neobmedzia cestnú premávku, najviac','',2,3,'traja vedľa seba,','piati vedľa seba,','dvaja vedľa seba.');
INSERT INTO `Questions` VALUES (821,821,0,1,'Sprievodca vedených alebo hnaných zvierat je oprávnený dávať pokyny na zastavenie vozidla,','',2,3,'len ak má pri sebe vodičský preukaz,','len za zníženej viditeľnosti,','ak to vyžaduje bezpečnosť cestnej premávky.');
INSERT INTO `Questions` VALUES (822,822,0,1,'Pri riadení cestnej premávky na križovatke znamená pre vodiča signál so zelenou smerovou šípkou alebo signál s kombinovanými zelenými smerovými šípkami rôznych smerov','',2,2,'možnosť pokračovať v jazde ktorýmkoľvek smerom,','možnosť pokračovať v jazde len v smere, ktorým uvedená šípka alebo šípky ukazujú,','povinnosť opustiť križovatku; to neplatí ak ide cez križovatku priamo.');
INSERT INTO `Questions` VALUES (823,823,0,1,'Ak sa pri vlečení motorového vozidla použije lano,','',1,3,'jeho dĺžka nesmie byť menšia ako 1,5 m,','nesmie byť vzdialenosť medzi vozidlami menšia ako 2 m,','nesmie byť vzdialenosť medzi vozidlami menšia ako 2,5 m.');
INSERT INTO `Questions` VALUES (824,824,0,1,'Pneumatika nesmie mať na svojom vonkajšom obvode, napr. v oblasti koruny, boku a pätky pneumatiky','',1,2,'trhliny ani poškodenia, ktoré narúšajú kordovú kostru; jej obnaženie však nieje závadou,','trhliny ani poškodenia, ktoré obnažujú kordovú kostru alebo ju narúšajú,','trhliny, ktoré obnažujú kordovú kostru; jej poškodenie však nieje závadou.');
INSERT INTO `Questions` VALUES (825,825,0,1,'Prevádzkovateľ vozidla nesmie v premávke na pozemných komunikáciách prevádzkovať vozidlo, ktoré','',1,2,'nedosahuje na rovine rýchlosť najmenej 50 km/h','poškodzuje pozemné komunikácie nad prípustnú mieru,','nebolo v lehote jedného mesiaca po jeho prvom prihlásení do evidencie podrobené kontrole technického stavu.');
INSERT INTO `Questions` VALUES (826,826,1,1,'Táto dopravná značka upozorňuje na','a3b',2,3,'miesto, kde priečny sklon vozovky presahuje 10%','priklonenú strmú stráň sprava','miesto, kde stúpanie cesty presahuje 10% alebo kde miestne podmienky robia stúpanie nebezpečným');
INSERT INTO `Questions` VALUES (827,827,1,1,'Táto dopravná značka upozorňuje na','a28b',2,3,'železničné priecestie vo vzdialenosti 90 m,','sklon vozovky vľavo,','železničné priecestie vo vzdialenosti 160 m.');
INSERT INTO `Questions` VALUES (828,828,1,1,'Táto dopravná značka znamená:','b1',2,2,'Slepá ulica,','Zákaz vjazdu všetkých vozidiel (v oboch smeroch),','Zákaz vjazdu motorových vozidiel.');
INSERT INTO `Questions` VALUES (829,829,1,1,'Táto dopravná značka znamená:','ip5',2,1,'Návesť pred slepou cestou,','Návesť pred križovatkou,','Zákaz odbočovania vpravo.');
INSERT INTO `Questions` VALUES (830,830,1,1,'Táto dopravná značka znamená:','ii7a',2,3,'Jazdný pruh vyhradený pre vozidlá pravidelnej verejnej dopravy osôb,','Parkovisko vyhradené pre autobusy,','Zastávka autobusu');
INSERT INTO `Questions` VALUES (831,831,1,1,'Táto dopravná značka znamená','is36a',2,3,'obytná zóna','smerová tabuľa k miestnemu cieľu','obec');
INSERT INTO `Questions` VALUES (832,832,1,1,'Táto dopravná značka vyznačuje','ip24a',2,2,'oblasť, v ktorej platia ustanovenia o premávke v obytnej zóne,','oblasť (časť obce a podobne), kde platí zákaz státia,','vyznačuje územie, v ktorom platia ustanovenia o premávke v pešej zóne.');
INSERT INTO `Questions` VALUES (833,833,1,1,'Táto dopravná značka','v5a',2,3,'vyznačuje okraj vozovky,','vyznačuje cestičku pre cyklistov,','vyznačuje hranicu križovatky; to neplatí, ak sa táto značka použije ako pomocná čiara na zastavenie vozidla v priestore križovatky.');
INSERT INTO `Questions` VALUES (834,834,2,1,'V poradí druhé prejde cez križovatku:','834',3,3,'žlté vozidlo,','zelené vozidlo,','červené vozidlo.');
INSERT INTO `Questions` VALUES (835,835,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','835',3,3,'1. červené, 2. modré, 3. zelené,','1. zelené, 2. červené, 3. modré,','1. zelené, 2, modré, 3. červené.');
INSERT INTO `Questions` VALUES (836,836,2,1,'Ako posledné prejde cez križovatku','836',3,3,'červené vozidlo prichádzajúce sprava,','protiidúce modré vozidlo,','vaše vozidlo.');
INSERT INTO `Questions` VALUES (837,837,2,1,'V poradí tretie prejde cez križovatku','837',3,1,'žlté vozidlo,','červené vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (838,838,0,1,'Zastavením sa rozumie','',2,2,'prerušenie jazdy motorového vozidla z dôvodu nezávislého od vôle vodiča,','uvedenie vozidla do pokoja na čas nevyhnutne potrebný na urýchlené nastúpenie alebo na vystúpenie prepravovaných osôb alebo na urýchlené naloženie alebo na zloženie nákladu,','len také uvedenie vozidla do pokoja, ktoré nepresiahne čas tri minúty.');
INSERT INTO `Questions` VALUES (839,839,0,1,'Vodič nesmie','',2,1,'znížiť rýchlosť jazdy alebo zastaviť, ak tým ohrozí bezpečnosť alebo plynulosť cestnej premávky,','zastaviť vľavo na jednosmernej ceste,','znížiť náhle rýchlosť jazdy za žiadnych okolností.');
INSERT INTO `Questions` VALUES (840,840,0,1,'Vodič motocykla a jeho spolujazdec sú povinní počas jazdy používať','',2,1,'na hlave riadne upevnenú ochrannú prilbu určenú pre motocyklistov,','akúkoľvek prilbu alebo obdobnú pokrývku hlavy,','ochranný štít.');
INSERT INTO `Questions` VALUES (841,841,0,1,'Na krajnicu smie vodič motorového vozidia vojsť','',2,2,'pri otáčaní a cúvaní,','len pri zastavení a státí alebo, pri obchádzaní a vyhýbaní sa prekážke cestnej premávky,','vždy, ak je to potrebné na vykonanie akéhokoľvek jazdného úkonu.');
INSERT INTO `Questions` VALUES (842,842,0,1,'Vodič pri prechádzaní z jedného jazdného pruhu do druhého jazdného pruhu','',2,1,'je povinný dať prednosť v jazde vodičovi jazdiacemu v jazdnom pruhu, do ktorého prechádza pritom je povinný dávať znamenie o zmene smeru jazdy,','môže ohroziť vodiča jazdiaceho v jazdnom pruhu, do ktorého prechádza,','nedáva znamenie o zmene smeru jazdy.');
INSERT INTO `Questions` VALUES (843,843,0,1,'Električkový koľajový pás zvýšený nad úroveň vozovky alebo znížený pod jej úroveň, alebo ktorý je od vozovky inak oddelený, najmä obrubníkom, smie sa prechádzať','',2,3,'na ktoromkoľvek mieste, a to vždy priečne,','na ktoromkoľvek mieste, ak nie je v blízkosti električka,','len priečne, a to na mieste prispôsobenom na to.');
INSERT INTO `Questions` VALUES (844,844,0,1,'Ak ide vozidlo vo vyhradenom jazdnom pruhu inou rýchlosťou ako ostatné vozidlá idúce rovnakým smerom,','',2,2,'ide o vzájomné predchádzanie,','nejde o vzájomné predchádzanie,','ide o vzájomné predchádzanie, ak ostatné vozidlá jazdia rýchlejšie.');
INSERT INTO `Questions` VALUES (845,845,0,1,'Vodič, ktorý pri predchádzaní vybočuje zo smeru svojej jazdy,','',2,2,'môže ohroziť vodičov jazdiacich za ním len v malom rozsahu,','je povinný dávať znamenie o zmene smeru jazdy,','nie je povinný dávať znamenie o zmene smeru jazdy.');
INSERT INTO `Questions` VALUES (846,846,0,1,'Predné svetlomety do hmly a zadné svietidlá do hmly vodič smie použiť','',2,3,'len za hmly; za sneženia a dažďa je povinný použiť diaľkové svetlomety,','vždy za zníženej viditeľnosti,','len za hmly, sneženia alebo za dažďa.');
INSERT INTO `Questions` VALUES (847,847,0,1,'Prepravované osoby nesmú','',2,1,'svojím správaním ohrozovať bezpečnosť cestnej premávky,','jesť, piť ani fajčiť,','obsluhovať telefónny pristroj.');
INSERT INTO `Questions` VALUES (848,848,0,1,'Nakladanie a skladanie nákladu na ceste je dovolené len','',2,2,'vtedy, ak na to dal súhlas obvodný úrad,','vtedy, ak to nemožno urobiť mimo cesty,','na miestnej komunikácii a na účelovej komunikácii.');
INSERT INTO `Questions` VALUES (849,849,0,1,'Účastník dopravnej nehody je povinný','',2,3,'zabezpečiť, aby ostatní účastníci dopravnej nehody nepožili alkohol,','zdržať sa jedenia, pitia a fajčenia,','zdržať sa konania, ktoré by bolo na ujmu vyšetrenia dopravnej nehody, najmä premiestnenia vozidiel.');
INSERT INTO `Questions` VALUES (850,850,0,1,'Ak náklad prečnieva vozidlo vpredu alebo vzadu viac ako','',1,2,'o 1 m, musí byť prečnievajúci koniec nákladu označený žltou zástavkou s rozmermi najmenej 20 x 20 cm; za zníženej viditeľnosti vpredu aj vzadu žltou odrazkou,','o 40 cm, musí byť prečnievajúci koniec nákladu označený reflexným označením s červenými a bielymi pruhmi širokými 70 až 100 mm a smerujúcimi od pozdĺžnej strednej roviny vozidla pod uhlom 45 nadol,','o 0,5 m, musí byť vždy označený červenou odrazkou.');
INSERT INTO `Questions` VALUES (851,851,0,1,'Pneumatika nesmie mať na svojom vonkajšom obvode, napr. oblasti koruny, boku a pätky pneumatiky','',1,2,'trhliny ani poškodenia, ktoré narúšajú kordovú kostru; jej obnaženie nie je závadou,','trhliny ani poškodenia, ktoré obnažujú kordovú kostru alebo ju narúšajú,','trhliny, ktoré obnažujú kordovú kostru; jej poškodenie však nieje závadou.');
INSERT INTO `Questions` VALUES (852,852,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'sú poškodené lapače nečistôt,','vozidlo nie je vybavené zariadením na spájanie vozidiel,','pneumatika alebo disk kolesa je nadmerne poškodený.');
INSERT INTO `Questions` VALUES (853,853,1,1,'Táto dopravná značka znamená;','b2',2,2,'Zákaz vjazdu nemotorových vozidiel,','Zákaz vjazdu všetkých vozidiel,','Zúžená vozovka.');
INSERT INTO `Questions` VALUES (854,854,1,1,'Táto dopravná značka znamená:','b11',2,3,'Vjazd cyklistom povolený,','Zákaz vjazdu všetkých dvojkolesových motorových vozidiel,','Zákaz vjazdu bicyklov.');
INSERT INTO `Questions` VALUES (855,855,1,1,'Táto dopravná značka zakazuje vodičovi','b37',2,1,'prejsť takto označeným úsekom bez toho, aby jazdu prerušil','vojsť do takto označeného úseku,','zastaviť v takto označenom úseku.');
INSERT INTO `Questions` VALUES (856,856,1,1,'Táto dopravná značka sa používa na mieste, kde','spec91',2,1,'v sporných alebo iných prípadoch treba prikázať vodičovi dať prednosť v jazde električke,','je vodič električky povinný dať prednosť v jazde,','sa nachádza zastávka električky bez nástupného ostrovčeka.');
INSERT INTO `Questions` VALUES (857,857,1,1,'Táto dopravná značka znamená:','p11',2,2,'Zákaz predchádzania,','Prednosť pred protiidúcimi vozidlami,','Prednosť protiidúcich vozidiel.');
INSERT INTO `Questions` VALUES (858,858,1,1,'Táto dopravná značka znamená:','ii7c',2,2,'Električkový koľajový pás,','Zastávka električky,','Jazdný pruh vyhradený pre električky.');
INSERT INTO `Questions` VALUES (859,859,1,1,'Táto dopravná značka znamená:','is5b',2,3,'Obec,','Zvýšenie počtu jazdných pruhov,','Návesť pred križovatkou.');
INSERT INTO `Questions` VALUES (860,860,1,1,'Prechádzať túto značku alebo ju nákladom presahovať','v1a',2,2,'je zakázané, ak to nieje potrebné na otáčanie,','je zakázané, ak to nieje potrebné na obchádzanie, odbočovanie na miesto ležiace mimo cesty alebo na vchádzanie na cestu z miesta ležiaceho mimo cesty,','je vždy zakázané.');
INSERT INTO `Questions` VALUES (861,861,2,1,'Vodič modrého vozidla','861',3,3,'má pred vodičom červeného vozidla prednosť v jazde, pretože ide po kruhovom objazde,','musí dať prednosť v jazde vodičovi červeného vozidla, ktorý prichádza na križovatku sprava,','má pred vodičom červeného vozidla prednosť v jazde, pretože prichádza na križovatku po ceste označenej ako hlavná.');
INSERT INTO `Questions` VALUES (862,862,2,1,'Ako posledné prejde cez križovatku','862',3,1,'žlté vozidlo,','zelené vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (863,863,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','863',3,1,'1. zelené, 2, vaše vozidlo, 3. červené,','1. červené, 2. zelené, 3. vaše vozidlo,','1. vaše vozidlo, 2. červené, 3. zelené.');
INSERT INTO `Questions` VALUES (864,864,2,1,'Ako prvé prejde cez križovatku','864',3,3,'zelené vozidlo súčasne s električkou č. 1,','zelené vozidlo súčasne s električkou č. 1 a električkou č. 2,','vaše vozidlo súčasne so zeleným vozidlom.');
INSERT INTO `Questions` VALUES (865,865,0,1,'Dať prednosť v jazde sa rozumie povinnosť','',2,3,'účastníka cestnej premávky počínať si tak, aby inému účastníkovi cestnej premávky nevzniklo nijaké nebezpečenstvo,','chodca prechádzajúceho na priechode pre chodcov neobmedziť motorové vozidlá prichádzajúce sprava,','účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde, nemusel náhle zmeniť smer alebo rýchlosť jazdy.');
INSERT INTO `Questions` VALUES (866,866,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza, vodič motorového vozidla kategórie M1 a N1 môže takéto vozidlo použiť v cestnej premávke, len ak','',2,3,'má uzatvorené havarijné poistenie','je toto vybavené na hnacej náprave zimnými pneumatikami,','je toto vybavené na všetkých nápravách zimnými pneumatikami.');
INSERT INTO `Questions` VALUES (867,867,0,1,'Vodič nesmie','',2,2,'prekážať v jazde len rýchlejšie idúcim vozidlám pravidelnej verejnej dopravy osôb bezdôvodne pomalou jazdou,','prekážať v jazde rýchlejšie idúcim vozidlám a obmedzovať plynulosť cestnej premávky,','prekážať v jazde rýchlejšie idúcim vozidlám len za zníženej viditeľnosti.');
INSERT INTO `Questions` VALUES (868,868,0,1,'Vodič motocykla a jeho spolujazdec nesmú počas jazdy','',2,1,'jesť, piť ani fajčiť,','hlasito rozprávať,','používať za zníženej viditeľnosti ochrannú prilbu.');
INSERT INTO `Questions` VALUES (869,869,0,1,'Ak sa vodič motorového vozidla, ktoré je povinne vybavené bezpečnostným odevom, zdržiava na vozovke mimo vozidia počas núdzového státia, najmä pri prerušení jazdy pre chybu na vozidle alebo v dôsledku dopravnej nehody, je povinný','',2,2,'umiestniť 20 m za vozidlo biele neoslňujúce svetlo bielej farby,','mať bezpečnostný odev oblečený,','bezodkladne privolať odťahovú službu.');
INSERT INTO `Questions` VALUES (870,870,0,1,'Pri jazde v pripájacom alebo v odbočovacom pruhu sa','',2,3,'nesmie vpravo predchádzať vozidlo idúce v priebežnom pruhu,','nesmie jazdiť vyššou rýchlosťou, ako jazdia vozidlá v priebežnom pruhu,','smie vpravo predchádzať aj vozidlo idúce v priebežnom pruhu.');
INSERT INTO `Questions` VALUES (871,871,0,1,'Vodiči protiidúcich vozidiel sa vyhýbajú','',2,3,'vľavo a tak, aby bola medzi vozidlami vzdialenosť najmenej 1 m,','vždy vľavo,','vpravo, včas a v dostatočnej miere.');
INSERT INTO `Questions` VALUES (872,872,0,1,'Osoby sa môžu pohybovať po vozovke v tuneli len','',2,3,'v čase od 00.00 hod. do 04.00hod,','po pravej krajnici,','v súvislosti so zaisťovaním bezpečnosti cestnej premávky, ak majú na sebe reflexný bezpečnostný odev.');
INSERT INTO `Questions` VALUES (873,873,0,1,'Na cestách 1. triedy a za zníženej viditeľnosti aj na ostatných cestách s výnimkou účelových komunikácií je','',2,3,'mimo obce aj v obci dovolené státie len na mieste označenom ako parkovisko,','mimo obce dovolené len zastavenie,','mimo obce zakázané zastavenie a státie na inom mieste než na mieste označenom ako parkovisko s výnimkou núdzového státia.');
INSERT INTO `Questions` VALUES (874,874,0,1,'Ak je nevyhnutné upozorniť ostatných účastníkov cestnej premávky na hroziace nebezpečenstvo, najmä v prípadoch, keď je nutné náhle znížiť rýchlosť jazdy alebo zastaviť vozidlo,','',2,1,'dáva vodič svetelné výstražné znamenie zapnutím výstražnej funkcie smerových svietidiel,','použije vodič zvukové výstražné znamenie,','dáva vodič svetelné výstražné znamenie prerušovaným zapínaním predných hmlových svietidiel.');
INSERT INTO `Questions` VALUES (875,875,0,1,'Vodič vozidla, ktoré je povinne vybavené prenosným výstražným trojuholníkom, je povinný tento trojuholník umiestniť na krajnici alebo na vozovke počas núdzového státia, ak takéto vozidlo tvorí prekážku cestnej premávky na diaľnici alebo na rýchlostnej ces','',2,3,'vo vzdialenosti najmenej 50 m za vozidlom,','len za zníženej viditeľnosti,','vo vzdialenosti najmenej 100 m za vozidlom.');
INSERT INTO `Questions` VALUES (876,876,0,1,'Vodič je povinný zdržať sa požitia alkoholu alebo inej návykovej látky po nehode','',2,2,'len vtedy, ak dopravnú nehodu zavinil,','v čase, keď by to bolo na ujmu zistenia, či pred jazdou alebo počas jazdy použil alkohol alebo inú návykovú látku,','v čase, pokiaľ neumožnil obnovenie premávky, najmä premávky vozidiel pravidelnej verejnej dopravy osôb.');
INSERT INTO `Questions` VALUES (877,877,0,1,'Chodci smú isť po krajnici alebo po okraji vozovky, ak tým, najmä za zníženej viditeľnosti alebo za zvýšenej premávky, neohrozia alebo neobmedzia cestnú premávku, najviac','',1,3,'traja vedľa seba,','piati vedľa seba,','dvaja vedľa seba.');
INSERT INTO `Questions` VALUES (878,878,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,2,'najmenej desaťlitrová zásoba pohonných hmôt v osobitnej nádobe; to neplatí pre jednostopové motorové vozidlá,','kľúč na matice alebo skrutky kolies,','vlečné lano; to platí aj pre jednostopové motorové vozidlá,');
INSERT INTO `Questions` VALUES (879,879,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách','',1,1,'niektoré svetelné zariadenie dôležité pre bezpečnosť premávky na pozemných komunikáciách chýba alebo je nesprávne umiestnené, nesvieti alebo nespĺňa ustanovené podmienky, takže','najvyšší bod činnej svietiacej plochy stretávacích svetiel je nižšie ako 1200 mm nad rovinou vozovky,','nieje vybavené klimatizačným systémom.');
INSERT INTO `Questions` VALUES (880,880,1,1,'Táto dopravná značka s dodatkovou tabuľkou znamená:','spec6',2,2,'Spôsob obchádzania štyroch prekážok,','Štyri zákruty, prvá vpravo,','Nebezpečenstvo šmyku v úseku 4 km.');
INSERT INTO `Questions` VALUES (881,881,1,1,'Táto dopravná značka upozorňuje na','a29b',2,3,'železničné priecestie vo vzdialenosti 140 m,','sklon vozovky vpravo,','železničné priecestie vo vzdialenosti 80 m.');
INSERT INTO `Questions` VALUES (882,882,1,1,'Táto dopravná značka znamená:','b10',2,3,'Zákaz vjazdu všetkých dvojkolesových vozidiel,','Cestička pre motocykle,','Zákaz vjazdu malých motocyklov.');
INSERT INTO `Questions` VALUES (883,883,1,1,'Táto dopravná značka znamená:','ii14',2,3,'Rezervácia,','Táborisko,','Odpočívadlo.');
INSERT INTO `Questions` VALUES (884,884,1,1,'Táto dopravná značka znamená:','is12',2,1,'Návesť pred križovatkou s obmedzením; značka informuje o obmedzení premávky za najbližšou križovatkou,','Prikázaný smer jazdy,','Zákaz vjazdu traktorov.');
INSERT INTO `Questions` VALUES (885,885,1,1,'Táto dopravná značka znamená:','c22a',2,3,'Jazdný pruh pre pomalé vozidlá,','Zastávkový pruh,','Zvýšenie počtu jazdných pruhov.');
INSERT INTO `Questions` VALUES (886,886,1,1,'Táto dopravná značka vyznačuje','v10a',2,2,'priestor, do ktorého je zakázané vchádzať alebo zasahovať nákladom,','miesto, kde je dovolené zastavenie a státie a určený spôsob státia kolmo na okraj vozovky,','miesto, kde je zakázané zastavenie a státie.');
INSERT INTO `Questions` VALUES (887,887,1,1,'Takéto označenie sa môže použiť na','o2',2,3,'vyznačenie parkoviska sanitných vozidiel,','vozidle červeného kríža,','vozidle lekára pri poskytovaní zdravotnej starostlivosti.');
INSERT INTO `Questions` VALUES (888,888,2,1,'Ako posledné prejde cez križovatku','888',3,3,'červené vozidlo,','žlté vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (889,889,2,1,'Ak svieti signál na opustenie križovatky umiestnený v protiľahlom rohu križovatky, prejdú cez križovatku ako prvé','889',3,3,'protiidúce zelené a žlté vozidlo,','obidve električky,','červené vozidlo súčasne s modrým vozidlom.');
INSERT INTO `Questions` VALUES (890,890,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','890',3,2,'1. žlté, 2 .červené, 3. vaše vozidlo,','1. žlté, 2. vaše vozidlo, 3. červené,','1. červené, 2. žlté, 3. vaše vozidlo.');
INSERT INTO `Questions` VALUES (891,891,2,1,'Ako prvé prejde cez križovatku','891',3,2,'zelené vozidlo súčasne s modrým,','červené vozidlo,','vaše vozidlo súčasne s modrým.');
INSERT INTO `Questions` VALUES (892,892,0,1,'Zníženou viditeľnosťou sa rozumie','',2,2,'taká viditeľnosť, pri ktorej vodič motorového vozidla z dôvodu znečistenia alebo poškodenia skiel dostatočne zreteľne nevidí ostatných účastníkov cestnej premávky,','taká viditeľnosť, pri ktorej sa účastníci cestnej premávky dostatočne zreteľne navzájom nevidia ani keď nevidia predmety na ceste, najmä od súmraku do svitania, za hmly, sneženia, dažďa a v tuneli,','viditeľnosť v čase od 18.00 do 7.00 hodiny a od 1. júla do 31. augusta len od 20.00 do 6.00 hodiny.');
INSERT INTO `Questions` VALUES (893,893,0,1,'Pri jazde po kruhovom objazde vodič dáva znamenie o zmene smeru jazdy, ak','',2,3,'do takejto križovatky vchádza,','dôjde k núdzovému zastaveniu vozidla alebo k dopravnej nehode,','z takej križovatky vychádza.');
INSERT INTO `Questions` VALUES (894,894,0,1,'Vodič nesmie predchádzať','',2,3,'ak je na križovatke a 500 m pred ňou,','ak by pritom musel podstatne zvýšiť rýchlosť jazdy,','pri jazde cez železničné priecestie.');
INSERT INTO `Questions` VALUES (895,895,0,1,'Vodič motorového vozidla s najväčšou prípustnou celkovou hmotnosťou neprevyšujúcou 3 500 kg smie jazdiť rýchlosťou najviac','',2,1,'90 km/h; na diaľnici a na rýchlostnej ceste smie jazdiť rýchlosťou najviac 130 km/h','110 km/h; na diaľnici a na rýchlostnej ceste nemá rýchlosť jazdy obmedzenú,','80 km/h; na diaľnici a na rýchlostnej ceste smie jazdiť rýchlosťou najviac 120 km/h');
INSERT INTO `Questions` VALUES (896,896,0,1,'Vodič, ktorý nechce alebo nemôže prejsť pozdĺž električky vpravo, je povinný','',2,1,'jazdiť za ňou v takej vzdialenosti, aby umožnil prejdenie pozdĺž električky ostatným vodičom,','dať o tom znamenie upažením,','zastaviť na najbližšom odbočovacom pruhu.');
INSERT INTO `Questions` VALUES (897,897,0,1,'Vodič nesmie vojsť na križovatku, ak mu situácia','',2,1,'nedovoľuje pokračovať za križovatkou v jazde, takže by bol nútený zastaviť vozidlo na križovatke, to neplatí, ak vodič zastavuje vozidlo v križovatke z dôvodu dávania prednosti chodcom prechádzajúcim cez vozovku alebo pri odbočovaní doľava,','dovoľuje pokračovať v jazde za križovatkou len zníženou rýchlosťou,','nedovoľuje pokračovať v jazde za križovatkou rýchlosťou vyššou ako 60 km/h');
INSERT INTO `Questions` VALUES (898,898,0,1,'Ak nie je ohrozená bezpečnosť a plynulosť cestnej premávky, vodič smie v obci','',2,3,'stáť v druhom rade,','zastaviť a stáť na priechode pre chodcov,','zastaviť v druhom rade.');
INSERT INTO `Questions` VALUES (899,899,0,1,'Cyklisti smú jazdiť po ceste','',2,3,'najviac dvaja vedľa seba,','bez držania riadidiel, ak v blízkosti nie sú motorové vozidlá,','len jednotlivo za sebou.');
INSERT INTO `Questions` VALUES (900,900,0,1,'Do pešej zóny je povolený vjazd','',2,2,'len bicyklom a motocyklom,','len vozidlám, ktorým to umožňuje dopravná značka,','všetkým vozidlám, ak nejazdia rýchlosťou vyššou ako 20 km/h');
INSERT INTO `Questions` VALUES (901,901,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza, vodič motorového vozidla kategórie a N1 môže takéto vozidlo použiť v cestnej premávke, len ak','',2,1,'je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené na hnacej náprave zimnými pneumatikami,','má uzatvorené havarijné poistenie.');
INSERT INTO `Questions` VALUES (902,902,0,1,'Účastníkovi cestnej premávky je zakázané používanie','',2,1,'technických prostriedkov a zariadení, ktorých činnosť umožňuje odhalenie alebo ovplyvňovanie funkcií technických prostriedkov používaných pri plnení úloh na úseku výkonu dohľadu nad bezpečnosťou a plynulosťou cestnej premávky alebo ich umiestnenie vo vozi','zvukových výstražných znamení,','zimných pneumatík v období od 15. novembra do 31. marca.');
INSERT INTO `Questions` VALUES (903,903,0,1,'Ak policajt pri riadení cestnej premávky dáva pokyn vodorovným kývaním ruky cez stred tela, znamená to','',2,1,'zrýchliť jazdu,','spomaliť jazdu,','povinnosť odbočiť.');
INSERT INTO `Questions` VALUES (904,904,0,1,'Ak náklad prečnieva vozidlo vpredu alebo vzadu viac ako','',1,2,'o 1 m, musí byť prečnievajúci koniec nákladu označený žltou zástavkou s rozmermi najmenej 20 x 20 cm; za zníženej viditeľnosti vpredu aj vzadu žltou odrazkou,','o 40 cm, musí byť prečnievajúci koniec nákladu označený reflexným označením s červenými a bielymi pruhmi širokými 70 až 100 mm a smerujúcimi od pozdĺžnej strednej roviny vozidla pod uhlom 45 nadol,','o 50 cm musí byť vždy označený červenou odrazkou.');
INSERT INTO `Questions` VALUES (905,905,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'mazivo používané vo vozidle nieje schválené výrobcom,','nie je možné uviesť do činnosti osvetlenie batožinového priestoru,','zjavne uniká palivo, olej, mazivo alebo iné prevádzkové náplne z vozidla.');
INSERT INTO `Questions` VALUES (906,906,0,1,'Prívesy za osobné automobily','',1,1,'sa nesmú používať na prepravu osôb,','smú sa používať na prepravu osôb, rýchlosť jazdy však nesmie prekročiť 60 km/h','sa nesmú používať na prepravu osôb; to neplatí pre obytné prívesy za osobné automobily, ktoré sa môžu používať na prepravu osôb.');
INSERT INTO `Questions` VALUES (907,907,1,1,'Táto dopravná značka','c1',2,1,'prikazuje jazdu smerom, ktorým šípka ukazuje,','označuje jednosmernú premávku,','prikazuje obchádzať prekážku v smere, ktorým šípka ukazuje.');
INSERT INTO `Questions` VALUES (908,908,1,1,'Táto dopravná značka znamená:','c8',2,3,'Zákaz vjazdu bicyklov.','Cestička k požičovni bicyklov.','Cestička pre cyklistov; značka prikazuje cyklistom použiť takto označený pruh alebo cestičku.');
INSERT INTO `Questions` VALUES (909,909,1,1,'Táto dopravná značka znamená:','c15',2,3,'Najvyššia dovolená rýchlosť.','Odporúčaná rýchlosť.','Najnižšia dovolená rýchlosť.');
INSERT INTO `Questions` VALUES (910,910,1,1,'Táto dopravná značka prikazuje vodičovi','c17',2,1,'Prikazuje vodičovi na takto označenom úseku rozsvietiť na idúcom vozidle ustanovené osvetlenie,','Označuje úsek, kde je zakázané používať diaľkové svetlomety,','Informuje vodiča o úseku, na ktorom môžu mať protiidúce vozidlá rozsvietené stretávacie svetlomety.');
INSERT INTO `Questions` VALUES (911,911,1,1,'Táto dopravná značka znamená:','ip7',2,3,'Cestička pre cyklistov,','Obytná zóna,','Priechod pre cyklistov.');
INSERT INTO `Questions` VALUES (912,912,1,1,'Táto dopravná značka znamená:','ip24b',2,1,'Koniec zóny s dopravným obmedzením,','Koniec obytnej zóny,','Koniec zóny, kde platí zákaz zastavenia.');
INSERT INTO `Questions` VALUES (913,913,1,1,'Ak sú touto značkou oddelené jazdné pruhy s protismernou premávkou,','v3',2,1,'vodič sa riadi významom pravej čiary z tejto dvojice čiar,','vodič sa riadi významom ľavej čiary z tejto dvojice čiar,','riadi sa premávka v jazdných pruhoch svetelnými signálmi.');
INSERT INTO `Questions` VALUES (914,914,1,1,'Táto dopravná značka','v8b',2,2,'je návesťou pred priechodom pre cyklistov,','vyznačuje na cestičke pre cyklistov určený smer jazdy cyklistov,','vyznačuje priechod precyklistov.');
INSERT INTO `Questions` VALUES (915,915,2,1,'V poradí tretie prejde okolo prekážky','915',3,3,'modré vozidlo,','žlté vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (916,916,2,1,'Ak svieti signál na opustenie križovatky umiestnený v protiľahlom rohu križovatky,','916',3,3,'vodič červeného vozidla odbočujúceho vľavo je povinný dať prednosť v jazde protiidúcemu zelenému a žltému vozidlu a električkám idúcim z obidvoch smerov,','vodiči protiidúceho zeleného a žltého vozidla a protiidúcej električky majú prednosť pred červeným vozidlom,','vodič červeného vozidla odbočujúceho vľavo má prednosť v jazde pred protiidúcim zeleným a žltým vozidlom a obidvoma električkami.');
INSERT INTO `Questions` VALUES (917,917,2,1,'Ako prvé prejde cez križovatku','917',3,3,'červené vozidlo,','vaše vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (918,918,2,1,'Vaše vozidlo prejde cez križovatku ako','918',3,1,'posledné,','druhé,','prvé.');
INSERT INTO `Questions` VALUES (919,919,0,1,'Chodcom sa rozumie účastník cestnej premávky pohybujúci sa pešo; chodcom je aj','',2,2,'pohonič záprahového vozidla a osoba, ktorá tlačí alebo ťahá ručný vozík s celkovou dĺžkou nepresahujúcou 150 cm,','osoba, ktorá tlačí alebo ťahá ručný vozík s celkovou šírkou nepresahujúcou 600 mm,','vodič každého nemotorového vozidla, ktoré sa pohybuje rýchlosťou nižšou ako 30 km/h');
INSERT INTO `Questions` VALUES (920,920,0,1,'Neobmedzením sa rozumie povinnosť','',2,1,'účastníka cestnej premávky počínať si tak, aby inému účastníkovi cestnej premávky neprekážal,','spolujazdca nerozptyľovať pozornosť vodiča hlasitým hovorom, telefonovaním, pitím nápojov alebo inou obdobnou činnosťou,','vodiča za žiadnych okolností nevyrušovať vodiča predchádzaného vozidla dávaním zvukového výstražného znamenia alebo svetelného výstražného znamenia.');
INSERT INTO `Questions` VALUES (921,921,0,1,'Vodič je povinný','',2,1,'dať prednosť chodcovi, ktorý vstúpil na vozovku a prechádza cez priechod pre chodcov, pritom ho nesmie ohroziť,','zastaviť vozidlo pred priechodom pre chodcov aj vtedy, ak sa ňom chodci nenachádzajú,','zastaviť vozidlo pred priechodom pre chodcov len vtedy, ak sa na ňom nachádza skupina chodcov.');
INSERT INTO `Questions` VALUES (922,922,0,1,'Tam, kde sa dva jazdné pruhy zbiehajú do jedného jazdného pruhu tak, že nie je zrejmé, ktorý z nich je priebežný,','',2,3,'vodič jazdiaci v ľavom jazdnom pruhu má prednosť v jazde,','má prednosť v jazde vždy vodič vozidla s vyššou hmotnosťou,','vodič jazdiaci v ľavom jazdnom pruhu je povinný dať prednosť v jazde vodičovi v pravom jazdnom pruhu; to neplatí, ak ide o striedavé radenie upravené príslušnou dopravnou značkou.');
INSERT INTO `Questions` VALUES (923,923,0,1,'Električka, ktorá križuje smer jazdy vozidla idúceho po jej pravej alebo po jej ľavej strane a dáva znamenie o zmene smeru jazdy,','',2,1,'má prednosť v jazde,','nemá prednosť v jazde,','dáva prednosť vjazde vozidlu idúcemu po jej ľavej strane.');
INSERT INTO `Questions` VALUES (924,924,0,1,'Vodičovi vozidla pravidelnej verejnej dopravy osôb sú vodiči ostatných vozidiel povinní umožniť vyjdenie zo zastávky alebo zo zastávkového pruhu, a to znížením rýchlosti jazdy, prípadne i zastavením vozidla,','',2,2,'mimo obce,','v obci,','v obci aj mimo obce.');
INSERT INTO `Questions` VALUES (925,925,0,1,'Vodič nesmie zastaviť a stáť na priechode pre chodcov a vo vzdialenosti kratšej ako','',2,1,'5 m pred ním,','5 m za ním,','5 m pred ním a 5 m za ním.');
INSERT INTO `Questions` VALUES (926,926,0,1,'Ak na priecestnom zabezpečovacom zariadení svieti prerušované biele svetlo, vodič je povinný','',2,3,'vo vzdialenosti 30 m pred železničným priecestím a pri jeho prechádzaní jazdiť rýchlosťou najviac 30 km/h','zastaviť vozidlo,','vo vzdialenosti 50 m pred železničným priecestím a pri jeho prechádzaní jazdiť rýchlosťou najviac 50 km/h');
INSERT INTO `Questions` VALUES (927,927,0,1,'Motocykel bez postranného vozíka sa','',2,1,'nesmie vliecť ani použiť ako vlečné vozidlo,','smie vliecť alebo použiť ako vlečné vozidlo,','smie vliecť, ale nesmie sa použiť ako vlečné vozidlo.');
INSERT INTO `Questions` VALUES (928,928,0,1,'V motorovom vozidle sa smú na miestach na to vyhradených prepravovať osoby','',2,2,'staršie ako 15 rokov s telesnou výškou väčšou ako 160 cm,','len do prípustnej užitočnej hmotnosti vozidla, pritom počet prepravovaných osôb nesmie byť vyšší, ako je počet miest uvedených v osvedčení o evidencii,','len do prípustnej užitočnej hmotnosti vozidla, pritom počet prepravovaných osôb môže byť vyšší, ako je počet miest uvedených v osvedčení o evidencii.');
INSERT INTO `Questions` VALUES (929,929,0,1,'Za dopravnú nehodu sa považuje aj škodová udalosť, ak','',2,1,'sa účastníci škodovej udalosti nedohodli na jej zavinení,','ku škodovej udalosti došlo na diaľnici alebo rýchlostnej ceste,','v niektorom zo zúčastnených vozidiel došlo k poškodeniu prepravovaných vecí.');
INSERT INTO `Questions` VALUES (930,930,0,1,'Na diaľnici mimo obce smie vodič motorového vozidla jazdiť rýchlosťou najmenej','',2,3,'120 km/h','100 km/h','80 km/h');
INSERT INTO `Questions` VALUES (931,931,0,1,'Osoba so zdravotným postihnutím, ktorá sa pohybuje pomocou ručného alebo motorového vozíka určeného pre ňu, smie používať','',1,3,'len pravú krajnicu,','len ľavú krajnicu,','ktorúkoľvek krajnicu alebo ktorýkoľvek okraj vozovky.');
INSERT INTO `Questions` VALUES (932,932,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,2,'najmenej jeden zakladací klin pre každú nápravu motorového vozidla,','bezpečnostný odev (bezpečnostnáreflexná vesta, overal, nohavice, bunda alebo pláštenka) umiestnený v dosahu zo sedadla vodičavozidla,','motolekárnička.');
INSERT INTO `Questions` VALUES (933,933,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,2,'je poškodený lak na zadnom nárazníku,','výhľad z miesta vodiča je obmedzený alebo znemožnený,','z miesta vodiča nieje možné nastaviť pravé predné zrkadlo.');
