INSERT INTO `Questions` VALUES (937,937,1,1,'Táto dopravná značka znamená:','p9',2,1,'Koniec hlavnej cesty; značka informuje o tom, že na najbližšej križovatke táto cesta už nieje hlavná,','Koniec rýchlostnej cesty,','Koniec vedľajšej cesty; značka upozorňuje na to, že na najbližšej križovatke má vodič prednosť v jazde.');
