INSERT INTO `Questions` VALUES (944,944,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','944',3,1,'1. vaše vozidlo, 2. modré, 3. červené,','1. modré, 2. červené, 3. vaše vozidlo,','1. červené, 2. vaše vozidlo, 3. modré.');
