INSERT INTO `Questions` VALUES (946,946,0,1,'Vodičom sa rozumie','',2,2,'osoba, ktorá najmä vedie motorové alebo nemotorové vozidlo, tlačí motocykel, pohybuje sa na lyžiach alebo kolieskových korčuliach, ťahá alebo tlačí sánky,','osoba, ktorá vedie vozidlo,','len osoba, ktorá vedie motorové vozidlo.');
INSERT INTO `Questions` VALUES (947,947,0,1,'Vo vzdialenosti 50 m pred železničným priecestím a pri jeho prechádzaní vodič je povinný jazdiť rýchlosťou najviac','',2,3,'20 km/h,','40 km/h,','30 km/h.');
INSERT INTO `Questions` VALUES (948,948,0,1,'V obci na ceste s dvoma alebo s viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy smie vodič vozidla použiť na jazdu','',2,2,'len pravý jazdný pruh; ostatné jazdné pruhy sa môžu používať len na predchádzanie alebo na odbočovanie,','ktorýkoľvek jazdný pruh; to neplatí pre vodiča nákladného automobilu s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg, vodiča jazdnej súpravy, ktorej celková dĺžka presahuje 7 m, vodiča zvláštneho motorového vozidla a vodič motocykla s naj','len ľavý jazdný pruh; ostatné jazdné pruhy smie používať len vodič nemotorového vozidla.');
INSERT INTO `Questions` VALUES (949,949,0,1,'Ak sa premávke vo vyhradenom jazdnom pruhu riadi osobitnými svetelnými signálmi,','',2,1,'riadi sa nimi len vodič jazdiaci v tomto jazdnom pruhu,','riadia sa nimi vodiči vozidiel pravidelnej verejnej dopravy osôb jazdiaci aj v inom jazdnom pruhu,','riadi sa nimi len vodič električky a trolejbusu a to bez ohľadu na to, v ktorom pruhu jazdí.');
INSERT INTO `Questions` VALUES (950,950,0,1,'Vodič autobusu a vodič motorového vozidla s najväčšou prípustnou celkovou hmotnosťou neprevyšujúcou 3 500 kg smie jazdiť rýchlosťou najviac','',2,3,'80 km/h,','110 km/h,','90 km/h.');
INSERT INTO `Questions` VALUES (951,951,0,1,'Vodič nesmie vojsť na križovatku, ak mu situácia','',2,3,'dovoľuje pokračovať vjazde za križovatkou len zníženou rýchlosťou,','dovoľuje pokračovať vjazde za križovatkou len rýchlosťou nižšou ako 30 km/h,','nedovoľuje pokračovať za križovatkou v jazde, takže by bol nútený zastaviť vozidlo na križovatke.');
INSERT INTO `Questions` VALUES (952,952,0,1,'Na cestách triedy a za zníženej viditeľnosti aj na ostatných cestách s výnimkou účelových komunikácii je','',2,1,'mimo obce zakázané zastavenie a státie na inom mieste než na mieste označenom ako parkovisko s výnimkou núdzového státia,','mimo obce aj v obci dovolené státie len na mieste označenom ako parkovisko,','mimo obce dovolené len zastavenie.');
INSERT INTO `Questions` VALUES (953,953,0,1,'Znamenie o zmene smeru jazdy vodič je povinný dávať','',2,2,'len pri zmene smeru jazdy; vodič, ktorý pri predchádzaní vybočuje zo smeru svojej jazdy, nie je povinný dávať znamenie o zmene smeru svojej jazdy,','vždy aj pri zmene smeru jazdy alebo vybočovaní z neho,','vždy aj pri prechádzaní cez železničné priecestie.');
INSERT INTO `Questions` VALUES (954,954,0,1,'Predné svetlomety do hmly a zadné svietidlá do hmly vodič smie použiť','',2,2,'len za hmly; za sneženia a za dažďa smie použiť len diaľkové svetlomety,','len za hmly, sneženia alebo za dažďa,','vždy za zníženej viditeľnosti.');
INSERT INTO `Questions` VALUES (955,955,0,1,'Osoby sa môžu pohybovať po vozovke v tuneli len','',2,1,'v súvislosti so zaisťovaním bezpečnosti cestnej premávky, ak majú na sebe reflexný bezpečnostný odev,','po pravej krajnici,','v čase od 00.00 hod. do 04.00 hod.');
INSERT INTO `Questions` VALUES (956,956,0,1,'Preprava osôb je zakázaná','',2,1,'v inom prípojnom vozidle ako vo vozidle, ktoré je určené na dopravu osôb s výnimkou ložného priestoru nákladného prívesu traktora,','v ložnom priestore nákladného prívesu traktora,','v kabíne vodiča nákladného automobilu.');
INSERT INTO `Questions` VALUES (957,957,0,1,'Znamenie o zmene smeru jazdy vodič nedáva','',2,2,'pri zmene smeru jazdy,','pri vjazde do kruhového objazdu,','pri prechádzaní z jedného jazdného pruhu do druhého jazdného pruhu.');
INSERT INTO `Questions` VALUES (958,958,0,1,'Týždenný čas jazdy','',1,1,'nesmie presiahnuť 56 hodín,','nesmie presiahnuť 40 hodín,','nesmie presiahnuť 48 hodín.');
INSERT INTO `Questions` VALUES (959,959,0,1,'Povinnou výbavou motorového vozidla s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg a prípojného vozidla s najväčšou prípustnou hmotnosťou prevyšujúcou 750 kg je','',1,1,'najmenej jeden zakladací klin, ktorý účinne zabezpečí vozidlo proti samovoľnému pohybu,','najmenej dvojlitrová zásoba maziva v osobitnej nádobe,','dvojica diaľkových svetlometov natáčaných súčasne s riadiacim mechanizmom vozidla.');
INSERT INTO `Questions` VALUES (960,960,0,1,'Prevádzkovateľ vozidla nesmie v premávke na pozemných komunikáciách prevádzkovať vozidlo, ktoré','',1,3,'je vybavené platnou tabuľkou s osobitným evidenčným číslom,','poškodzuje pozemné komunikácie nad 50 % prípustnej miery,','je dodatočne vybavené neschváleným systémom, komponentom alebo samostatnou technickou jednotkou.');
INSERT INTO `Questions` VALUES (961,961,1,1,'Táto dopravná značka znamená:','a20',2,3,'Nespevnená krajnica,','Odletujúci štrk,','Padajúce kamene.');
