INSERT INTO `Questions` VALUES (963,963,1,1,'Táto dopravná značka znamená:','b31b',2,3,'Koniec najnižšej dovolenej rýchlosti,','Koniec odporúčanej rýchlosti,','Koniec najvyššej dovolenej rýchlosti.');
INSERT INTO `Questions` VALUES (964,964,1,1,'Táto dopravná značka označuje','p1',2,1,'vedľajšiu cestu pred križovatkou s hlavnou cestou, alebo sa používa na mieste, kde je potrebné vodičovi prikázať, zopakovať alebo zdôrazniť povinnosť dať prednosť v jazde,','križovatku dvoch ciest rovnakého významu,','hlavnú cestu.');
