INSERT INTO `Questions` VALUES (971,971,2,1,'Ako prvé prejde cez križovatku','134',3,1,'zelené vozidlo,','modré vozidlo,','vaše vozidlo.');
INSERT INTO `Questions` VALUES (972,972,2,1,'V poradí tretie prejde cez križovatku','486',3,2,'červené vozidlo,','žlté vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (973,973,0,1,'Neohrozením sa rozumie povinnosť vodiča','',2,2,'počínať si tak, aby inému účastníkovi cestnej premávky nijako neprekážal,','počínať si tak, aby inému účastníkovi cestnej premávky nevzniklo nijaké nebezpečenstvo,','neobchádzať ani nepredchádzať vozidlo prepravujúce nebezpečné veci a jazdiť za takýmto vozidlom vo vzdialenosti najmenej 50 m.');
INSERT INTO `Questions` VALUES (974,974,0,1,'Motorovým vozidlo sa rozumie','',2,2,'koľajové a nekoľajové vozidlo poháňané vlastným motorom,','nekoľajové vozidlo poháňané vlastným motorom s výnimkou mechanického alebo elektrického vozíka pre osoby so zdravotným postihnutím a trolejbus,','vozidlo poháňané vlastným motorom s výnimkou malého motocykla, traktora a motorového ručného vozíka.');
INSERT INTO `Questions` VALUES (975,975,0,1,'Osoba sediaca na sedadle vozidla povinne vybavenom bezpečnostným pásom alebo iným zadržiavacím zariadením je povinná toto zariadenie použiť; to neplatí pre','',2,1,'osobu, ktorá nemôže byť pripútaná zo zdravotných dôvodov; takáto osoba sa musí preukázať osvedčením o oslobodení od použitia bezpečnostných systémov vozidla,','osobu staršiu ako 65 rokov,','vodiča počas jazdy na účelovej komunikácii.');
INSERT INTO `Questions` VALUES (976,976,0,1,'Električkový koľajový pás zvýšený nad úroveň vozovky alebo znížený pod jej úroveň, alebo ktorý je od vozovky inak oddelený, najmä obrubníkom, sa smie prechádzať','',2,3,'na ktoromkoľvek mieste, a to vždy priečne,','na ktoromkoľvek mieste, ak nie je v blízkosti električka,','len priečne, a to na mieste na to prispôsobenom.');
INSERT INTO `Questions` VALUES (977,977,0,1,'Vodič nesmie predchádzať,','',2,1,'pri jazde cez železničné priecestie,','ak je na križovatke a 500 m pred ňou,','ak by pritom musel podstatne zvýšiť rýchlosť jazdy.');
INSERT INTO `Questions` VALUES (978,978,0,1,'Vodič smie jazdiť po diaľnici v obci alebo po rýchlostnej ceste v obci rýchlosťou najviac','',2,3,'130 km/h,','80 km/h,','90 km/h.');
INSERT INTO `Questions` VALUES (979,979,0,1,'Vodič môže zastaviť a stáť','',2,2,'na pripájacom alebo na odbočovacom pruhu,','v obci na križovatke tvaru „T“ na náprotivnej strane vyúsťujúcej cesty,','na vnútornom jazdnom pruhu a na vyhradenom jazdnom pruhu.');
INSERT INTO `Questions` VALUES (980,980,0,1,'Vodič motorového vozidla kategórie N, ktorého najväčšia prípustná celková hmotnosť presahuje 7 500 kg alebo vodič jazdnej súpravy, ktorej najväčšia prípustná hmotnosť presahuje 7 500 kg nesmie','',2,3,'mimo obce na ceste s dvoma alebo viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy použiť na jazdu pravý jazdný pruh,','pri jazde po medzinárodnej trase a ceste 1. triedy predchádzať iné motorové vozidlo,','pri jazde po diaľnici a rýchlostnej ceste predchádzať iné motorové vozidlo.');
INSERT INTO `Questions` VALUES (981,981,0,1,'Znamenie o zmene smeru jazdy rukou sa dáva','',2,2,'počas celého jazdného úkonu,','len pred začatím jazdného úkonu,','po začatí jazdného úkonu.');
INSERT INTO `Questions` VALUES (982,982,0,1,'Vodič motorového vozidla nesmie na diaľnici a na rýchlostnej ceste predchádzať iné motorové vozidlo,','',2,3,'ak by pri predchádzaní neobmedzil iné vozidlo idúce po diaľnici alebo po rýchlostnej ceste,','ak nemá rozhľad na vzdialenosť 200 metrov,','ak by pri predchádzaní svojou výrazne nižšou rýchlosťou obmedzil iné vozidlo idúce po diaľnici alebo po rýchlostnej ceste.');
INSERT INTO `Questions` VALUES (983,983,0,1,'Za dopravnú nehodu sa považuje aj škodová udalosť, ak','',2,3,'v niektorom zo zúčastnených vozidiel došlo k poškodeniu prepravovaných vecí,','ku škodovej udalosti došlo na diaľnici alebo rýchlostnej ceste,','sa účastníci škodovej udalosti nedohodli na jej zavinení.');
INSERT INTO `Questions` VALUES (984,984,0,1,'Prerušované žlté svetlo použité samostatne alebo v spojení s dopravnou značkou','',2,3,'znamená povinnosť zastaviť vozidlo pred priechodom pre cyklistov,','znamená povinnosť dať prednosť chodcom na priechode pre chodcov,','upozorňuje na nevyhnutnosť dbať na zvýšenú opatrnosť.');
INSERT INTO `Questions` VALUES (985,985,0,1,'Doba skráteného denného odpočinku','',1,3,'je akákoľvek doba odpočinku trvajúca najmenej 9 hodín, avšak menej ako 12 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 10 hodín, avšak menej ako 9 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 9 hodín, avšak menej ako 11 hodín.');
INSERT INTO `Questions` VALUES (986,986,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'sú poškodené alebo nefunkčné ostrekovače zadného skla, dôsledkom čoho došlo k zhoršeniu výhľadu vodiča z kabíny vozidla,','z miesta vodiča nie je možné nastaviť pravé predné zrkadlo,','náprava alebo nápravy alebo ťažné oje prívesu sú deformované alebo vážne poškodené.');
INSERT INTO `Questions` VALUES (987,987,0,1,'Povinnou výbavou motorového vozidla s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg a prípojného vozidla s najväčšou prípustnou hmotnosťou prevyšujúcou 750 kg je','',1,1,'najmenej jeden zakladací klin, ktorý účinne zabezpečí vozidlo proti samovoľnému pohybu,','dvojica diaľkových svetlometov natáčaných súčasne s riadiacim mechanizmom vozidla,','najmenej dvojlitrová zásoba maziva v osobitnej nádobe.');
INSERT INTO `Questions` VALUES (988,988,1,1,'Táto dopravná značka upozorňuje na','a9',2,1,'úsek cesty, na ktorom sa nachádza ujazdený a zľadovatený sneh alebo na ktorom hrozí nebezpečenstvo poľadovice,','úsek cesty, ktorej povrch je znečistený a za mokra klzký,','povinnosť použiť pri jazde snehové reťaze.');
INSERT INTO `Questions` VALUES (989,989,1,1,'Táto dopravná značka s dodatkovou tabuľkou upozorňuje na','spec41',2,1,'železničné priecestie vo vzdialenosti 80 m a na tvar kríženia cesty so železničnou dráhou,','prekážku cestnej premávky,','mimoúrovňové kríženie cesty so železnicou.');
INSERT INTO `Questions` VALUES (990,990,1,1,'Táto dopravná značka zakazuje','b18',2,3,'vjazd motorovým aj nemotorovým vozidlám,','predchádzanie vozidiel vyznačených druhov,','vjazd vozidlám vyznačených druhov.');
INSERT INTO `Questions` VALUES (991,991,1,1,'Táto dopravná značka zrušuje platnosť','b39',2,3,'všetkých predchádzajúcich zákazových dopravných značiek,','značiek Zákaz státia a Zákaz zastavenia,','značiek Zákaz predchádzania, Zákaz predchádzania pre nákladné automobily, Najvyššia dovolená rýchlosť a Najnižšia dovolená rýchlosť, ak sú použité najmenej dve z týchto značiek spoločne.');
INSERT INTO `Questions` VALUES (992,992,1,1,'Táto dopravná značka sa používa na mieste, kde','spec91',2,2,'je vodič električky povinný dať prednosť v jazde,','v sporných alebo iných prípadoch treba prikázať vodičovi dať prednosť v jazde električke,','sa nachádza zastávka električky bez nástupného ostrovčeka.');
INSERT INTO `Questions` VALUES (993,993,1,1,'Táto dopravná značka znamená:','ip6',2,3,'Zákaz vstupu chodcov,','Pešia zóna,','Priechod pre chodcov.');
INSERT INTO `Questions` VALUES (994,994,1,1,'Táto dopravná značka informuje','is23a',2,1,'vhodným nápisom, symbolom alebo siluetou o smere, prípadne o vzdialenosti k vyznačenému kultúrnemu alebo turistickému cieľu,','o názve miestnej časti obce, prípadne o vzdialenosti k nej,','informuje o smere, prípadne aj o vzdialenosti v kilometroch k vyznačeným cieľom a o čísle cyklistickej trasy.');
INSERT INTO `Questions` VALUES (995,995,1,1,'Táto dopravná značka vyznačuje','v10b',2,2,'miesto, kde je zakázané zastavenie a státie,','miesto, kde je dovolené zastavenie a státie a určený spôsob státia šikmo na okraj vozovky,','miesto, kde je dovolené zastavenie a státie pozdĺž okraja vozovky.');
INSERT INTO `Questions` VALUES (996,996,2,1,'Ako prvé vojde do križovatky','754',3,3,'zelené vozidlo,','modré vozidlo,','červené vozidlo.');
INSERT INTO `Questions` VALUES (997,997,2,1,'Ako posledné prejde cez križovatku','888',3,2,'červené vozidlo,','zelené vozidlo,','žlté vozidlo.');
INSERT INTO `Questions` VALUES (998,998,2,1,'V poradí druhé prejde cez križovatku','269',3,2,'zelené vozidlo,','vaše vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (999,999,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','296',3,1,'1. vaše vozidlo, 2. zelené, 3. modré súčasne s červeným,','1. modré súčasne s vaším vozidlom, 2. zelené, 3. červené,','1. zelené, 2. červené, 3. modré, 4. vaše vozidlo.');
INSERT INTO `Questions` VALUES (1000,1000,0,1,'Vozidlom sa rozumie','',2,3,'len motorové vozidlo,','motorové a nemotorové vozidlo okrem zvláštneho motorového vozidla a bicykla,','motorové vozidlo, nemotorové vozidlo a električka.');
INSERT INTO `Questions` VALUES (1001,1001,0,1,'Zníženou viditeľnosťou sa rozumie','',2,1,'viditeľnosť, pri ktorej sa účastníci cestnej premávky dostatočne zreteľne navzájom nevidia, ani keď nevidia predmety na ceste, najmä od súmraku do svitania, za hmly, sneženia, dažďa a v tuneli,','taká viditeľnosť, keď vodič motorového vozidla z dôvodu znečistenia alebo poškodenia skiel nevidí dostatočne zreteľne ostatných účastníkov cestnej premávky,','viditeľnosť v čase od 18.00 do 7.00 hodiny a od 1. júla do 31. augusta len od 20.00 do 6.00 hodiny.');
INSERT INTO `Questions` VALUES (1002,1002,0,1,'Vodič pri prechádzaní z jedného jazdného pruhu do druhého jazdného pruhu','',2,3,'môže ohroziť vodiča jazdiaceho v jazdnom pruhu, do ktorého prechádza,','mimo obce nie je povinný dávať znamenie o zmene smeru jazdy,','je povinný dať prednosť vjazde vodičovi jazdiacemu v jazdnom pruhu, do ktorého prechádza.');
INSERT INTO `Questions` VALUES (1003,1003,0,1,'Vodič je povinný pri obchádzaní stojaceho vozidla pravidelnej verejnej dopravy osôb prihliadnuť na možnosť vbehnutia osôb na vozovku a','',2,3,'za tým účelom jazdiť vždy rýchlosťou najviac 15 km/h,','za tým účelom vždy zastaviť vozidlo,','jazdu prispôsobiť tak, aby neboli ohrozené.');
INSERT INTO `Questions` VALUES (1004,1004,0,1,'Vodič smie jazdiť len primeranou rýchlosťou, aby bol schopný zastaviť vozidlo','',2,3,'na vzdialenosť 100 m,','na vzdialenosť 20 m, a ak ide po diaľnici alebo po rýchlostnej ceste na vzdialenosť 50 m,','na vzdialenosť, na ktorú má rozhľad.');
INSERT INTO `Questions` VALUES (1005,1005,0,1,'Pri vchádzaní na cestu z miesta mimo cesty vodič','',2,2,'nie je povinný dať prednosť v jazde vozidlu idúcemu po ceste,','je povinný dať prednosť vjazde vozidlu idúcemu po ceste,','je povinný dať prednosť vjazde len vozidlu idúcemu po ceste sprava.');
INSERT INTO `Questions` VALUES (1006,1006,0,1,'Na vyhradenom parkovisku, ak nejde o vozidlo, pre ktoré je parkovisko vyhradené, vodič','',2,3,'môže zastaviť a stáť vždy v čase od 22.00 do 5.00 hodiny,','môže stáť, ak ide o státie, ktoré nepresiahne pätnásť minút,','nesmie zastaviť a stáť.');
INSERT INTO `Questions` VALUES (1007,1007,0,1,'Vodič vozidla, ktoré je povinne vybavené prenosným výstražným trojuholníkom, je povinný tento trojuholník použiť počas núdzového státia, ak takéto vozidlo tvorí prekážku cestnej premávky. Na diaľnici a na rýchlostnej ceste je vodič povinný trojuholník','',2,1,'umiestniť vo vzdialenosti najmenej 100 m za vozidlom,','umiestniť vo vzdialenosti najmenej 50 m za vozidlom,','umiestniť len za zníženej viditeľnosti.');
INSERT INTO `Questions` VALUES (1008,1008,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza a v období od novembra do marca môže vodič motorového vozidla kategórie M2, M3, N2 a N; použiť takéto vozidlo v cestnej premávke, len ak','',2,1,'je toto vybavené aspoň na jednej z hnacích náprav zimnými pneumatikami,','je toto vybavené na všetkých nápravách zimnými pneumatikami,','je držiteľom medzinárodnej poisťovacej karty.');
INSERT INTO `Questions` VALUES (1009,1009,0,1,'Ak ten, kto prekážku cestnej premávky spôsobil, ju bezodkladne neodstráni, je povinný ju označiť','',2,2,'len za zníženej viditeľnosti,','a oznámiť to policajtovi,','len vtedy, ak prekážku spôsobil na diaľnici alebo na rýchlostnej ceste.');
INSERT INTO `Questions` VALUES (1010,1010,0,1,'Nakladanie a skladanie nákladu na ceste je dovolené len','',2,3,'so súhlasom správcu cesty,','na miestnej komunikácii a na účelovej komunikácii,','vtedy, ak to nemožno urobiť mimo cesty.');
INSERT INTO `Questions` VALUES (1011,1011,0,1,'Za dopravnú nehodu sa považuje aj škodová udalosť, ak','',2,3,'v niektorom zo zúčastnených vozidiel došlo k poškodeniu prepravovaných veci,','ku škodovej udalosti došlo na diaľnici alebo rýchlostnej ceste,','je vodič zúčastneného vozidla pod vplyvom alkoholu alebo inej návykovej látky.');
INSERT INTO `Questions` VALUES (1012,1012,0,1,'Doba pravidelného týždenného odpočinku','',1,1,'je akákoľvek doba odpočinku trvajúca najmenej 45 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 40 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 50 hodín.');
INSERT INTO `Questions` VALUES (1013,1013,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,2,'najmenej dvojlitrová zásoba maziva v osobitnej nádobe,','bezpečnostný odev (bezpečnostná reflexná vesta, overal, nohavice, bunda alebo pláštenkumiestnený v dosahu zo sedadla vodiča vozidla,','sada protisklzových reťazí.');
INSERT INTO `Questions` VALUES (1014,1014,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'je zhodný účinok prevádzkovej brzdy na kolesách tej istej nápravy,','nie je vybavené na každej strane aspoň jedným bočným odrazovým svetlom oranžovej farby,','na ňom boli vykonané nepovolené úpravy alebo zabudovaný neschválený komponent alebo samostatná technická jednotka.');
INSERT INTO `Questions` VALUES (1015,1015,1,1,'Táto dopravná značka znamená:','p6',2,1,'Križovatka s vedľajšou cestou,','Križovatka, na ktorej platí zákaz odbočovania vľavo,','Kríženie cesty zľava s Iesnou alebo poľnou cestou.');
INSERT INTO `Questions` VALUES (1016,1016,1,1,'Táto dopravná značka upozorňuje na','a32',2,3,'úsek cesty, na ktorom sa vykonávajú meteorologické merania,','blízkosť letiska,','úsek cesty, kde prudký bočný alebo nárazový vietor môže ohroziť bezpečnosť cestnej premávky.');
INSERT INTO `Questions` VALUES (1017,1017,1,1,'Táto dopravná značka','b38',2,3,'prikazuje vodičovi podrobiť sa colnej kontrole,','zakazuje vojsť do hraničného pásma,','zakazuje pokračovať v jazde bez zastavenia vozidla na cestnom hraničnom priechode.');
INSERT INTO `Questions` VALUES (1018,1018,1,1,'Táto dopravná značka','c4a',2,1,'prikazuje jazdu smerom, ktorým šípky ukazujú,','upozorňuje na križovatku tvaru „T“','označuje zvýšenie počtu jazdných pruhov.');
INSERT INTO `Questions` VALUES (1019,1019,1,1,'Táto dopravná značka znamená:','ip16',2,2,'Zákaz parkovania,','Parkovisko - parkovacie miesta s vyhradeným státím,','Parkovisko - parkovacie miesta s plateným státím.');
INSERT INTO `Questions` VALUES (1020,1020,1,1,'Táto dopravná značka:','ii3',2,2,'informuje o úseku cesty, v ktorom je povinnosť mať hasiaci prístroj vo vozidle,','informuje o mieste, kde je umiestnený hasiaci prístroj,','zakazuje používať hasiaci prístroj.');
INSERT INTO `Questions` VALUES (1021,1021,1,1,'Táto dopravná značka znamená:','ip28a',2,1,'Obytná zóna,','Pozor deti,','Označenie začiatku obce.');
INSERT INTO `Questions` VALUES (1022,1022,1,1,'Táto dodatková tabuľka umiestnená pod zákazovou značkou','e6',2,2,'obmedzuje platnosť značky na vozidlo, ktorého najväčšia prípustná celková hmotnosť je menšia ako údaj uvedený na tabuľke,','obmedzuje platnosť zákazu na vozidlo, ktorého najväčšia prípustná celková hmotnosť presahuje údaj uvedený na tabuľke; pri jazdnej súprave rozhoduje súčet najväčších prípustných hmotnosti vozidiel súpravy,','vyznačuje najvyššie dovolené zaťaženie vozidla pripadajúce na dvojnápravu.');
INSERT INTO `Questions` VALUES (1023,1023,2,1,'Ako prvé prejde cez križovatku','402',3,1,'modré vozidlo,','červené vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (1024,1024,2,1,'Ako posledné prejde cez križovatku','537',3,1,'zelené vozidlo,','červené vozidlo,','žlté vozidlo.');
INSERT INTO `Questions` VALUES (1025,1025,2,1,'Vaše vozidlo prejde cez križovatku ako','729',3,1,'druhé,','prvé,','posledné.');
INSERT INTO `Questions` VALUES (1026,1026,2,1,'V poradí posledné prejde cez križovatku','675',3,1,'modré vozidlo súčasne s červeným,','vaše vozidlo súčasne s modrým,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (1027,1027,0,1,'chodníkom sa rozumie','',2,2,'len komunikácia alebo časť cesty označená príslušnou dopravnou značkou,','komunikácia alebo časť cesty určená pre chodcov, ktorá je spravidla oddelená od vozovky výškovo alebo iným spôsobom ,','pravá krajnica; kde krajnica nie je, rozumie sa chodníkom pravý okraj vozovky široký jeden meter.');
INSERT INTO `Questions` VALUES (1028,1028,0,1,'Vodič nesmie predchádzať, ak','',2,3,'na to v obci neupozornil vodiča predchádzaného vozidla zvukovým výstražným znamením,','pred nim jazdí zvláštne motorové vozidlo,','by pri predchádzaní svojou výrazne nižšou rýchlosťou obmedzil za nim idúce vozidlo, ktoré začalo úkon predchádzania skôr.');
INSERT INTO `Questions` VALUES (1029,1029,0,1,'Vodič motorového vozidla kategórie N, ktorého najväčšia prípustná celková hmotnosť presahuje 7 500 kg alebo vodič jazdnej súpravy, ktorej najväčšia prípustná hmotnosť presahuje 7 500 kg nesmie','',2,2,'pri jazde po medzinárodnej trase a ceste 1. triedy predchádzať iné motorové vozidlo,','pri jazde po diaľnici predchádzať iné motorové vozidlo,','mimo obce na ceste s dvoma alebo viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy použiť na jazdu pravý jazdný pruh.');
INSERT INTO `Questions` VALUES (1030,1030,0,1,'Mimo obce na ceste s troma alebo s viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy smie vodič nákladného automobilu s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg použiť na jazdu','',2,3,'len ľavý jazdný pruh,','len pravý jazdný pruh,','výhradne dva jazdné pruhy najbližšie K pravému okraju vozovky; v ostatných jazdných pruhoch smie jazdiť, ak je to potrebné na obchádzanie, otáčanie alebo na odbočovanie.');
INSERT INTO `Questions` VALUES (1031,1031,0,1,'Pozdĺž nástupného ostrovčeka alebo ochranného ostrovčeka sa jazdí','',2,3,'vľavo; vpravo sa smie jazdiť len vtedy, ak jazde vľavo bráni prekážka,','za každých okolností vľavo,','vpravo; vľavo sa smie jazdiť len vtedy, ak jazde vpravo bráni prekážka alebo ak je to bezpečnejšie s ohľadom na rozmery vozidla alebo nákladu.');
INSERT INTO `Questions` VALUES (1032,1032,0,1,'Vodič pri odbočovaní nesmie','',2,1,'ohroziť vodiča idúceho za ním,','dávať znamenie o zmene smeru jazdy,','dávať znamenie o zmene smeru jazdy, ak odbočuje na miesto mimo cesty.');
INSERT INTO `Questions` VALUES (1033,1033,0,1,'Ak je to nevyhnutne potrebné najmä na zaradenie do radu stojacich vozidiel alebo na vyjdenie z neho, vodič smie cúvať','',2,1,'na jednosmernej ceste,','na priechode pre chodcov,','na každej križovatke.');
INSERT INTO `Questions` VALUES (1034,1034,0,1,'Na kruhovom objazde je státie','',2,3,'dovolené,','dovolené, ak je to potrebné na urýchlené nastúpenie alebo vystúpenie prepravovaných osôb,','aj zastavenie zakázané.');
INSERT INTO `Questions` VALUES (1035,1035,0,1,'Vodič nesmie zastaviť a stáť na mieste, kde by vozidlo zakrývalo','',2,1,'zvislú dopravnú značku, vodorovnú dopravnú značku vyznačujúcu spôsob radenia do jazdných pruhov a určený smer jazdy cez križovatku alebo vyjadrujúcu doplňujúci údaj nápisom alebo svetelné signály,','zvislú dopravnú značku a akúkoľvek vodorovnú dopravnú značku,','reklamné zariadenie.');
INSERT INTO `Questions` VALUES (1036,1036,0,1,'Vlečenie viacerých motorových vozidiel je','',2,3,'dovolené, ak sa vlečú dve osobné motorové vozidlá,','dovolené, ak sa vlečú motocykle bez postranného vozíka,','zakázané.');
INSERT INTO `Questions` VALUES (1037,1037,0,1,'Osoby prepravované v ložnom priestore nákladného prívesu traktora','',2,2,'môžu počas jazdy stáť,','musia počas jazdy sedieť na podlahe alebo na sedadlách pripevnených o podlahu,','nesmú počas jazdy jesť, piť ani fajčiť.');
INSERT INTO `Questions` VALUES (1038,1038,0,1,'Pre smer, ku ktorému stoji policajt pri riadení cestnej premávky na križovatke čelom alebo chrbtom znamená tento pokyn','',2,2,'„Voľno", ak má obe ruky pripažené,','„Stoj!"; vodič je povinný zastaviť vozidlo pred hranicou križovatky,','povinnosť odbočiť vpravo alebo vľavo.');
INSERT INTO `Questions` VALUES (1039,1039,0,1,'Doba denného odpočinku','',1,2,'je akákoľvek denná doba, počas ktorej môže vodič voľne disponovať svojím časom a zahŕňa „dobu pravidelného denného odpočinku",','je akákoľvek denná doba, počas ktorej môže vodič voľne disponovať svojím časom a zahŕňa „dobu pravidelného denného odpočinku" a „dobu skráteného denného odpočinku",','je akákoľvek denná doba, počas ktorej môže vodič voľne disponovať svojím časom a zahŕňa „dobu skráteného denného odpočinku“.');
INSERT INTO `Questions` VALUES (1040,1040,0,1,'Povinnou výbavou motorového vozidla kategórie M1 a N je','',1,2,'doplnkové zabezpečovacie elektronické alebo mechanické zariadenie,','autolekárnička,','doplnkové výstražné zariadenie umiestnené v zadnej časti vozidla.');
INSERT INTO `Questions` VALUES (1041,1041,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'sú poškodené alebo nefunkčné ostrekovače zadného skla, dôsledkom čoho došlo k zhoršeniu výhľadu vodiča z kabíny vozidla,','je nefunkčný stierač zadného skla,','má pneumatika na svojom vonkajšom obvode trhliny alebo poškodenia, ktoré obnažujú kordovú kostru alebo ju narúšajú.');
INSERT INTO `Questions` VALUES (1042,1042,1,1,'Táto dopravná značka upozorňuje','p5',2,2,'na rýchlostnú cestu,','vždy mimo obce na križovatku s vedľajšou cestou a označuje hlavnú cestu,','na kríženie cesty s lesnou alebo poľnou cestou.');
INSERT INTO `Questions` VALUES (1043,1043,1,1,'Táto dopravná značka znamená:','b4',2,2,'Zákaz vjazdu všetkých nemotorových vozidiel a električiek,','Zákaz vjazdu všetkých motorových vozidiel s výnimkou motocyklov bez postranného vozíka,','Zákaz vjazdu osobných automobilov.');
INSERT INTO `Questions` VALUES (1044,1044,1,1,'Táto dopravná značka zakazuje','b30a',2,3,'vodičovi skriňového automobilu predchádzať osobný automobil,','vodičovi nákladného automobilu s najvyššou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg predchádzať akékoľvek iné vozidlo,','vodičovi nákladného automobilu s najvyššou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg predchádzať motorové vozidlo vľavo; motocykel bez postranného vozíka možno predchádzať.');
INSERT INTO `Questions` VALUES (1045,1045,1,1,'Táto dopravná značka označuje','p2',2,3,'slepú ulicu,','zastávku vozidiel pravidelnej verejnej dopravy osôb,','vedľajšiu cestu; na príkaz tejto značky je vodič povinný zastaviť vozidlo na takom mieste, odkiaľ má na križovatku náležitý rozhľad.');
INSERT INTO `Questions` VALUES (1046,1046,1,1,'Táto dopravná značka znamená:','ip13c',2,2,'Parkovisko - parkovacie miesta s kolmým státím,','Parkovisko - parkovacie miesta s pozdĺžnym státím,','Parkovisko - parkovacie miesta s pozdĺžnym státím na chodníku.');
INSERT INTO `Questions` VALUES (1047,1047,1,1,'Táto dopravná značka znamená:','is20b',2,3,'Smerová tabuľa na vyznačenie obchádzky,','Rýchlostná cesta,','Smerová tabuľa pre príjazd k rýchlostnej ceste.');
INSERT INTO `Questions` VALUES (1048,1048,1,1,'Táto dopravná značka','c27',2,3,'informuje o spôsobe obchádzania prekážky na ceste,','označuje uzávierku električkovej trate,','označuje miesto, kde možno vľavo obchádzať električku, ktorá stojí na zastávke.');
INSERT INTO `Questions` VALUES (1049,1049,1,1,'Táto dodatková tabuľka','p14',2,3,'vyznačuje tvar kríženia cesty so železnicou,','zakazuje na diaľnici a na rýchlostnej ceste prechádzať stredný deliaci pás,','vyznačuje skutočný tvar križovatky a aj hlavnú a vedľajšiu cestu.');
INSERT INTO `Questions` VALUES (1050,1050,2,1,'Modré vozidlo prejde cez križovatku ako','835',3,3,'prvé,','posledné,','druhé.');
INSERT INTO `Questions` VALUES (1051,1051,2,1,'Ako posledné prejde cez križovatku','240',3,3,'zelené vozidlo,','modré vozidlo,','žlté vozidlo.');
INSERT INTO `Questions` VALUES (1052,1052,2,1,'Vaše vozidlo prejde cez križovatku ako','215',3,1,'posledné,','druhé,','prvé.');
INSERT INTO `Questions` VALUES (1053,1053,2,1,'V poradí druhé prejde cez križovatku','27',3,2,'električka,','zelené vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (1054,1054,0,1,'Električkovým koľajovým pásom sa rozumie','',2,1,'časť cesty určená predovšetkým na premávku električky,','časť cesty, na ktorej je povolená len premávka električky,','vozovka určená na premávku električky, vlaku a iného dráhového vozidla.');
INSERT INTO `Questions` VALUES (1055,1055,0,1,'Státím sa rozumie','',2,3,'prerušenie jazdy na čas nevyhnutne potrebný na urýchlené nastúpenie alebo vystúpenie prepravovaných osôb alebo na urýchlené naloženie alebo zloženie nákladu,','len také uvedenie vozidla do pokoja, ktoré nepresiahne čas 15 minút,','uvedenie vozidla do pokoja na dlhšie, ako je čas dovolený na zastavenie.');
INSERT INTO `Questions` VALUES (1056,1056,0,1,'Vodič je povinný pribrať potrebný počet spôsobilých osôb, ak','',2,2,'hmotnosť prepravovaného nákladu prekročí užitočnú hmotnosť vozidla,','to vyžaduje bezpečnosť cestnej premávky, a na tento účel ich náležite poučiť,','v potrebnom rozsahu neovláda predpisy o cestnej premávke.');
INSERT INTO `Questions` VALUES (1057,1057,0,1,'Vodič nesmie','',2,1,'znížiť náhle rýchlosť jazdy alebo náhle zastaviť, ak to nevyžaduje bezpečnosť cestnej premávky,','zastaviť v pravo v smere jazdy rovnobežne s okrajom cesty, čo najbližšie k okraju cesty,','znížiť rýchlosť jazdy za žiadnych okolnosti.');
INSERT INTO `Questions` VALUES (1058,1058,0,1,'Vodič, ktorý pri predchádzaní vybočuje zo smeru svojej jazdy,','',2,1,'je povinný dávať znamenie o zmene smeru jazdy,','môže ohroziť vodičov jazdiacich za ním len v malom rozsahu.','nie je povinný dávať znamenie o zmene smeru jazdy.');
INSERT INTO `Questions` VALUES (1059,1059,0,1,'Vodič, ktorý nechce alebo nemôže prejsť pozdĺž električky vpravo, je povinný','',2,3,'dať o tom znamenie upažením,','zastaviť na najbližšom odbočovacom pruhu,','jazdiť za ňou v takej vzdialenosti, aby umožnil prejazd pozdĺž električky ostatným vodičom.');
INSERT INTO `Questions` VALUES (1060,1060,0,1,'Vodič nesmie cúvať','',2,1,'na križovatke s riadenou premávkou,','v obytnej zóne,','za žiadnych okolností na jednosmernej ceste.');
INSERT INTO `Questions` VALUES (1061,1061,0,1,'Vodič nesmie zastaviť a stáť','',2,2,'v obci kolmo, pripadne šikmo na okraj cesty,','na platenom parkovisku, ak vozidlo nemá zaplatený poplatok za parkovanie,','na jednosmernej ceste vpravo a vľavo.');
INSERT INTO `Questions` VALUES (1062,1062,0,1,'Vlečenie viacerých motorových vozidiel je','',2,3,'dovolené, ak sa vlečú dve osobné motorové vozidlá,','dovolené, ak sa vlečú motocykle bez postranného vozíka,','zakázané.');
INSERT INTO `Questions` VALUES (1063,1063,0,1,'Vodič','',2,2,'môže dovoliť, aby sa prekročil povolený počet prepravovaných osôb, ak s tým vopred vyslovili súhlas všetky prepravované osoby,','nesmie dovoliť, aby sa prekročil povolený počet prepravovaných osôb,','môže dovoliť, aby sa prekročil povolený počet prepravovaných osôb, najviac však o 20 %.');
INSERT INTO `Questions` VALUES (1064,1064,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza a v období od novembra do marca môže vodič motorového vozidla kategórie M2, M3, N2 a N3 použiť takéto vozidlo v cestnej premávke, len ak','',2,2,'je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené aspoň na jednej z hnacích náprav zimnými pneumatikami,','je držiteľom medzinárodnej poisťovacej karty.');
INSERT INTO `Questions` VALUES (1065,1065,0,1,'Ak policajt pri riadení cestnej premávky dáva pokyn vodorovným kývaním ruky cez stred tela, znamená to','',2,3,'spomaliť jazdu,','povinnosť odbočiť,','zrýchliť jazdu.');
INSERT INTO `Questions` VALUES (1066,1066,0,1,'Doba denného odpočinku','',1,2,'sa môže predĺžiť na dobu pravidelného týždenného odpočinku,','sa môže predĺžiť na dobu pravidelného týždenného alebo na dobu skráteného týždenného odpočinku,','sa môže predĺžiť na dobu skráteného týždenného odpočinku.');
INSERT INTO `Questions` VALUES (1067,1067,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'je nefunkčné počítadlo prejdenej vzdialenosti,','nie je možné uviesť do činnosti osvetlenie batožinového priestoru,','je vybavené pneumatikami rôznych rozmerov a konštrukcií alebo na tej istej náprave sú použité pneumatiky, ktoré nie sú zhodné.');
INSERT INTO `Questions` VALUES (1068,1068,0,1,'Ak zjavne uniká palivo, olej, mazivo alebo iné prevádzkové náplne z vozidla,','',1,1,'považuje sa takéto vozidlo za technicky nespôsobilé na premávku na pozemných komunikáciách,','vodič je povinný to po ukončení jazdy oznámiť držiteľovi vozidla,','smie sa takéto vozidlo, okrem diaľnice a rýchlostnej cesty, používať v cestnej premávke.');
INSERT INTO `Questions` VALUES (1069,1069,1,1,'Táto dopravná značka znamená:','a1b',2,3,'Nebezpečné stúpanie,','Zákaz odbočovania vľavo,','Zákruta vľavo.');
INSERT INTO `Questions` VALUES (1070,1070,1,1,'Táto dopravná značka znamená:','b17',2,3,'Vjazd motorových vozidiel s prívesmi povolený,','Zákaz parkovania prívesov,','Zákaz vjazdu motorových vozidiel s prívesmi.');
INSERT INTO `Questions` VALUES (1071,1071,1,1,'Táto dopravná značka','b36',2,3,'zakazuje zastavenie za značkou v nepárnych dňoch v mesiaci,','umožňuje státie v párnych dňoch,','zakazuje státie v párnych kalendárnych dňoch v mesiaci.');
INSERT INTO `Questions` VALUES (1072,1072,1,1,'Táto dopravná značka znamená:','c4c',2,2,'Zákruta vľavo,','Prikázaný smer jazdy priamo a vľavo,','Návesť pred obchádzkou.');
INSERT INTO `Questions` VALUES (1073,1073,1,1,'Táto dopravná značka s dodatkovou tabuľkou označuje','spec113',2,2,'križovatku, na ktorej nie je prednosť v jazde upravená dopravnými značkami,','hlavnú cestu najmä v obci a vyznačuje skutočný tvar križovatky a aj hlavnú a vedľajšiu cestu,','vedľajšiu cestu a križovatku.');
INSERT INTO `Questions` VALUES (1074,1074,1,1,'Táto dopravná značka znamená:','is2',2,2,'Smerová tabuľa na vyznačenie obchádzky,','Návesť pred križovatkou,','Zvýšenie počtu jazdných pruhov.');
INSERT INTO `Questions` VALUES (1075,1075,1,1,'Táto dopravná značka znamená:','is34',2,2,'Diaľková návesť,','Hranice okresu,','Návesť pred križovatkou.');
INSERT INTO `Questions` VALUES (1076,1076,1,1,'Táto zábrana vyznačuje','z2b',2,2,'uzávierku celej šírky cesty,','uzavretie časti šírky cesty; šípky smerujú k voľnej časti cesty,','úsek cesty s jednosmernou premávkou.');
INSERT INTO `Questions` VALUES (1077,1077,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','402',3,1,'1. modré, 2. zelené, 3. červené,','1. červené, 2. modré, 3. zelené,','1. zelené. 2. modré. 3. červené.');
INSERT INTO `Questions` VALUES (1078,1078,2,1,'Ako prvé prejde cez križovatku','106',3,3,'modré vozidlo súčasne s obidvoma električkami,','zelené vozidlo,','červené vozidlo súčasne s modrým vozidlom.');
INSERT INTO `Questions` VALUES (1079,1079,2,1,'Vaše vozidlo prejde cez križovatku ako','701',3,1,'posledné,','druhé,','prvé.');
INSERT INTO `Questions` VALUES (1080,1080,2,1,'Ako posledné prejde cez križovatku','540',3,1,'zelené vozidlo,','žlté vozidlo,','vaše vozidlo súčasne s modrým.');
INSERT INTO `Questions` VALUES (1081,1081,0,1,'Autobusom sa rozumie','',2,3,'každé vozidlo určené na prepravu viac ako štyroch osôb,','motorové a nemotorové vozidlo, ktoré má okrem miesta vodiča viac ako tri miesta na sedenie,','motorové vozidlo na dopravu osôb, ktoré má okrem miesta vodiča viac ako osem miest na sedenie.');
INSERT INTO `Questions` VALUES (1082,1082,0,1,'Prevádzkovateľ vozidla je povinný zabezpečiť, aby sa na jazdu pribral potrebný počet spôsobilých a náležite poučených osôb, ak je mu vopred známe, že','',2,3,'vo vozidle budú prepravované nebezpečné veci alebo živé zvieratá,','vodič v potrebnom rozsahu neovláda predpisy o cestnej premávke,','to bude vyžadovať bezpečnosť cestnej premávky.');
INSERT INTO `Questions` VALUES (1083,1083,0,1,'Vodič je povinný pri obchádzaní stojaceho vozidla pravidelnej verejnej dopravy osôb prihliadnuť na možnosť vbehnutia osôb na vozovku a jazdu prispôsobiť tak, aby neboli ohrozené; to','',2,3,'neplatí pre vodiča vozidla jazdiaceho v protismere,','neplatí pre vodiča motocykla a vodiča nemotorového vozidla,','platí aj pre vodiča vozidla jazdiaceho v protismere.');
INSERT INTO `Questions` VALUES (1084,1084,0,1,'Vodič predchádzaného vozidla nesmie','',2,1,'zvyšovať rýchlosť jazdy ani inak brániť predchádzaniu,','okrem zvyšovania rýchlosti jazdy nijako brániť predchádzaniu,','znižovať rýchlosť jazdy.');
INSERT INTO `Questions` VALUES (1085,1085,0,1,'Vodič autobusu smie jazdiť rýchlosťou najviac','',2,1,'90 km/h, na diaľnici a na rýchlostnej ceste najviac 100 km/h,','80 km/h, na diaľnici a na rýchlostnej ceste najviac 110 km/h,','70 km/h.');
INSERT INTO `Questions` VALUES (1086,1086,0,1,'Pred odbočovaním vľavo vodič je povinný zaradiť sa','',2,2,'čo najďalej vpravo v časti vozovky určenej pre jeho smer jazdy s ohľadom na rozmery vozidla alebo nákladu a šírku vozovky,','čo najďalej vľavo v časti vozovky určenej pre jeho smer jazdy s ohľadom na rozmery vozidla alebo nákladu a šírku vozovky,','na pravú krajnicu.');
INSERT INTO `Questions` VALUES (1087,1087,0,1,'Vodič vozidla, ktoré zastavilo alebo stálo a opäť vychádza od okraja cesty alebo od chodníka','',2,3,'nie je povinný dávať znamenie o zmene smeru jazdy,','je povinný dávať znamenie o zmene smeru jazdy len mimo obce,','je povinný dávať znamenie o zmene smeru jazdy.');
INSERT INTO `Questions` VALUES (1088,1088,0,1,'Vodič nesmie zastaviť a stáť na priechode pre cyklistov a vo vzdialenosti kratšej ako','',2,2,'10 m za ním,','5 m pred ním,','10 m pred ním a 5 m za ním.');
INSERT INTO `Questions` VALUES (1089,1089,0,1,'Pred železničným priecestím, pri ktorom je umiestnená dopravná značka „Stoj, daj prednosť v jazde!", vodič je povinný zastaviť vozidlo','',2,1,'na takom mieste, z ktorého má náležitý rozhľad na trať,','vo vzdialenosti najmenej 80 m pred železničným priecestím,','len vtedy, ak prichádzajú vozidlá v protismere.');
INSERT INTO `Questions` VALUES (1090,1090,0,1,'Znamenie o zmene smeru jazdy vodič nedáva','',2,2,'pri zmene smeru jazdy,','pri vjazde do kruhového objazdu,','pri prechádzaní z jedného jazdného pruhu do druhého jazdného pruhu.');
INSERT INTO `Questions` VALUES (1091,1091,0,1,'Vodič vozidla vybaveného zvláštnym výstražným svetlom oranžovej farby je povinný toto svetlo používať','',2,3,'len vtedy, ak jazdí vyššou rýchlosťou ako 90 km.h''1,','za každých okolností,','ak by mohol svojou jazdou alebo pracovnou činnosťou ohroziť bezpečnosť alebo plynulosť cestnej premávky alebo na označenie prekážky v cestnej premávke.');
INSERT INTO `Questions` VALUES (1092,1092,0,1,'Prepravované osoby nesmú','',2,2,'svojím správaním obmedzovať bezpečnosť cestnej premávky, jesť, piť ani fajčiť,','svojím správaním ohrozovať bezpečnosť cestnej premávky,','obsluhovať telefónny prístroj.');
INSERT INTO `Questions` VALUES (1093,1093,0,1,'Doba skráteného denného odpočinku','',1,3,'je akákoľvek doba odpočinku trvajúca najmenej 9 hodín, avšak menej ako 12 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 10 hodín, avšak menej ako 9 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 9 hodín, avšak menej ako 11 hodín.');
INSERT INTO `Questions` VALUES (1094,1094,0,1,'Činná plocha pneumatiky v prevádzke musí mať po celom obvode a celej šírke vrchného behúňa dezén s hĺbkou dezénových drážok','',1,2,'u vozidiel kategórie L1 a L2 najmenej 1,5 mm,','u vozidiel kategórie L1 a L2 najmenej 1,0 mm,','u všetkých kategórií vozidiel 1,6 mm.');
INSERT INTO `Questions` VALUES (1095,1095,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'je vybavené platnou tabuľkou alebo tabuľkami s evidenčným číslom iného štátu,','nedosahuje na rovine rýchlosť najmenej 100 km/h,','niektoré svetelné zariadenie dôležité pre bezpečnosť premávky na pozemných komunikáciách chýba alebo je nesprávne umiestnené, nesvieti alebo nespĺňa ustanovené podmienky, takže hrozí bezprostredne nebezpečenstvo.');
INSERT INTO `Questions` VALUES (1096,1096,1,1,'Táto dopravná značka upozorňuje na','a3a',2,1,'miesto, kde klesanie cesty presahuje 10 % alebo kde miestne podmienky robia klesanie nebezpečným,','priklonenú strmú stráň zľava,','miesto, kde priečny sklon vozovky presahuje 10 %.');
INSERT INTO `Questions` VALUES (1097,1097,1,1,'Táto dopravná značka znamená:','a4a',2,1,'Zúžená vozovka (z oboch strán),','Zníženie počtu jazdných pruhov (z oboch strán),','Koniec rýchlostnej cesty.');
INSERT INTO `Questions` VALUES (1098,1098,1,1,'Táto dopravná značka upozorňuje vopred na','a13',2,3,'podchod alebo nadchod,','blízkosť školy,','priechod pre chodcov.');
INSERT INTO `Questions` VALUES (1099,1099,1,1,'Táto dopravná značka','is1a',2,1,'informuje na diaľnici a rýchlostnej ceste o názve najbližšej križovatky a vzdialenosti k nej s uvedením čísel križujúcich komunikácií,','informuje na diaľnici a rýchlostnej ceste o názve najbližšej obce a o vzdialenosti k nej,','je návesťou pred obchádzkou.');
INSERT INTO `Questions` VALUES (1100,1100,1,1,'Táto dopravná značka znamená:','is22a',2,3,'Lietadlá,','Smerová tabula na vyznačenie obchádzky,','Smerová tabula k inému cieľu.');
INSERT INTO `Questions` VALUES (1101,1101,1,1,'Táto dopravná značka','ip31b',2,2,'zakazuje vodičovi prekročiť rýchlosť v kilometroch za hodinu vyjadrenú číslom na značke,','odporúča maximálnu rýchlosť v kilometroch za hodinu za zníženej viditeľnosti z dôvodu najmä výskytu hmly alebo dymu,','označuje viditeľnosť v metroch pri hmle.');
INSERT INTO `Questions` VALUES (1102,1102,1,1,'Táto dopravná značka znamená:','is25',2,1,'Smerová tabuľa na vyznačenie obchádzky,','Smerová tabuľa na vyznačenie príjazdu k rýchlostnej ceste,','Smerová tabuľa na vyznačenie jednosmernej premávky.');
INSERT INTO `Questions` VALUES (1103,1103,1,1,'Táto dodatková tabuľka znamená:','e5b',2,1,'Úsek platnosti,','Smer a vzdialenosť k miestam, od ktorých platí značka, pod ktorou je tabuľka umiestnená,','Smerové šípky.');
INSERT INTO `Questions` VALUES (1104,1104,2,1,'V poradí tretie prejde okolo prekážky','348',3,1,'zelené vozidlo,','modré vozidlo,','žlté vozidlo.');
INSERT INTO `Questions` VALUES (1105,1105,2,1,'Ako prvé prejde cez križovatku:','835',3,3,'modré vozidlo,','červené vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (1106,1106,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','836',3,2,'1. vaše vozidlo, 2. modré, 3. červené,','1. modré, 2.červené, 3. vaše vozidlo,','1. modré. 2. vaše vozidlo, 3. červené.');
INSERT INTO `Questions` VALUES (1107,1107,2,1,'Vaše vozidlo prejde cez križovatku ako','54',3,1,'prvé,','tretie,','druhé.');
INSERT INTO `Questions` VALUES (1108,1108,0,1,'Krajnicou sa rozumie','',2,3,'časť cesty, ktorá je spravidla oddelená od vozovky výškovo alebo iným spôsobom,','časť cesty určená predovšetkým na premávku motorových vozidiel,','časť cesty od kraja vozovky po kraj cesty.');
INSERT INTO `Questions` VALUES (1109,1109,0,1,'Ak sa na vozovke nachádza súvislá snehové vrstva, ľad alebo námraza a v období od novembra do marca môže vodič motorového vozidla kategórie M2, M3, N2 a N3 použiť takéto vozidlo v cestnej premávke, len ak','',2,3,'je držiteľom medzinárodnej poisťovacej karty,','je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené aspoň na jednej z hnacích náprav zimnými pneumatikami.');
INSERT INTO `Questions` VALUES (1110,1110,0,1,'Vodič nesmie požiť alkohol ani inú návykovú látku','',2,3,'len počas vedenia motocykla a vozidla, ktorého najväčšia prípustná celková hmotnosť prevyšuje 3 500 kg,','len počas vedenia vozidla na diaľnici, rýchlostnej ceste a ceste l. triedy,','počas vedenia vozidla.');
INSERT INTO `Questions` VALUES (1111,1111,0,1,'Motorové vozidlo musí mať počas jazdy rozsvietené','',2,1,'stretávacie svetlomety alebo im na roveň postavené osvetlenie,','diaľkové svetlomety,','svetlá vo vnútri vozidla.');
INSERT INTO `Questions` VALUES (1112,1112,0,1,'Prevádzkovateľ vozidla nesmie zveriť vedenie vozidla osobe, ktorá','',2,2,'je mladšia ako 25 rokov, aj keď spĺňa ustanovené podmienky,','nespĺňa podmienky na jeho vedenie ustanovené zákonom o cestnej premávke alebo osobitným predpisom,','nemá najmenej dvojročnú prax vo vedení motorových vozidiel.');
INSERT INTO `Questions` VALUES (1113,1113,0,1,'Ak v obci na ceste s dvoma alebo s viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy idú vozidlá pri súbežnej jazde v jednom z jazdných pruhov rýchlejšie ako vozidlá v inom jazdnom pruhu,','',2,3,'považuje sa to za predchádzanie,','dopúšťa sa vodič rýchlejšie idúceho vozidla priestupku,','nepovažuje sa to za predchádzanie.');
INSERT INTO `Questions` VALUES (1114,1114,0,1,'Vodič v úseku zastávky vozidiel pravidelnej verejnej dopravy osôb','',2,1,'je povinný dbať na zvýšenú opatrnosť,','je povinný zastaviť vozidlo,','je povinný zapnúť zariadenie umožňujúce výstražnú funkciu smerových svietidiel.');
INSERT INTO `Questions` VALUES (1115,1115,0,1,'Ak vodič autobusu alebo trolejbusu vychádza z vyhradeného jazdného pruhu do priľahlého jazdného pruhu,','',2,2,'nesmie obmedziť vodičov ostatných vozidiel,','je povinný dávať znamenie o zmene smeru jazdy,','nie je povinný dávať znamenie o zmene smeru jazdy.');
INSERT INTO `Questions` VALUES (1116,1116,0,1,'Vodič vozidla, ktorý pri obchádzaní vozidla, ktoré zastavilo alebo stojí, vybočuje zo smeru svojej jazdy,','',2,3,'môže obmedziť protiidúcich vodičov,','nie je povinný dávať znamenie o zmene smeru jazdy,','je povinný dávať znamenie o zmene smeru jazdy.');
INSERT INTO `Questions` VALUES (1117,1117,0,1,'Najväčšiu konštrukčnú rýchlosť vozidla, a ak ide o jazdnú súpravu, ani najväčšiu konštrukčnú rýchlosť nijakého z vozidiel súpravy, vodič','',2,3,'nesmie prekročiť; to neplatí, ak ide po diaľnici alebo rýchlostnej ceste,','môže prekročiť najviac o 20 %,','nesmie prekročiť.');
INSERT INTO `Questions` VALUES (1118,1118,0,1,'Pred odbočovaním vpravo vodič je povinný','',2,3,'zaradiť sa vždy do stredu vozovky,','zaradiť sa čo najbližšie k ľavému okraju vozovky,','zaradiť sa čo najbližšie k pravému okraju vozovky; ak pritom musí s ohľadom na rozmery vozidla alebo nákladu vybočiť zo smeru svojej jazdy vľavo, vždy dáva len znamenie o zmene smeru jazdy vpravo.');
INSERT INTO `Questions` VALUES (1119,1119,0,1,'Pri preprave živých zvierat','',2,1,'nesmie byt'' ohrozená bezpečnosť vodiča a prepravovaných osôb, bezpečnosť prepravovaných zvierat ani bezpečnosť cestnej premávky,','musia byť na vozidle vždy rozsvietené predné svetlomety do hmly,','sa nesmie na jazdu použiť diaľnica a rýchlostná cesta.');
INSERT INTO `Questions` VALUES (1120,1120,0,1,'Doba pravidelného týždenného odpočinku','',1,3,'je akákoľvek doba odpočinku trvajúca najmenej 50 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 40 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 45 hodín.');
INSERT INTO `Questions` VALUES (1121,1121,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'je vybavené pneumatikami rôznych rozmerov a konštrukcii,','najnižší bod činnej svietiace] plochy brzdových svetiel je vyššie ako 350 mm nad rovinou vozovky,','je zhodný účinok prevádzkovej brzdy na kolesách tej istej nápravy.');
INSERT INTO `Questions` VALUES (1122,1122,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,1,'bezpečnostný odev (bezpečnostná reflexná vesta, overal, nohavice, bunda alebo pláštenkumiestnený v dosahu zo sedadla vodiča vozidla,','náhradným stieračom,','najmenej desaťlitrová zásoba pohonných hmôt v osobitnej nádobe.');
INSERT INTO `Questions` VALUES (1123,1123,1,1,'Táto dopravná značka znamená:','a2b',2,3,'Spôsob obchádzania prekážky,','Nebezpečenstvo šmyku,','Dvojitá zákruta, prvá vľavo.');
INSERT INTO `Questions` VALUES (1124,1124,1,1,'Táto dopravná značka označuje','a30a',2,3,'križovatku dvoch ciest rovnakého významu,','železničné priecestie vo vzdialenosti 80 m,','železničné priecestie jednokoľajové. -');
INSERT INTO `Questions` VALUES (1125,1125,1,1,'Táto dopravná značka znamená:','b7',2,2,'Vjazd autobusom povolený,','Zákaz vjazdu autobusov,','Jazdný pruh vyhradený pre autobusy.');
INSERT INTO `Questions` VALUES (1126,1126,1,1,'Táto dopravná značka znamená:','p8',2,1,'Hlavná cesta,','Rýchlostná cesta,','vedľajšie cesta.');
INSERT INTO `Questions` VALUES (1127,1127,1,1,'Táto dopravná značka znamená:','ip15b',2,3,'Nebezpečenstvo šmyku,','Zvýšená krajnica,','Parkovisko - parkovacie miesta s pozdĺžnym čiastočným státím na chodníku.');
INSERT INTO `Questions` VALUES (1128,1128,1,1,'Táto dopravná značka informuje o','ii3',2,2,'blízkosti nemocnice,','mieste, kde je umiestnený hasiaci prístroj,','nepretržitom záchrannom systéme.');
INSERT INTO `Questions` VALUES (1129,1129,1,1,'Táto dopravná značka','is3',2,1,'informuje o smeroch k vyznačeným cieľom a o počte a usporiadaní jazdných pruhov,','vyznačuje zníženie počtu jazdných pruhov,','je návesťou pred obchádzkou.');
INSERT INTO `Questions` VALUES (1130,1130,1,1,'Táto dopravná značka znamená:','v17',2,3,'Bezpečná vzdialenosť,','Optická psychologické brzda,','Hmlové body.');
INSERT INTO `Questions` VALUES (1131,1131,2,1,'Vodič červeného vozidla','619',3,1,'je povinný umožniť vodičovi modrého vozidla obídenie prekážky,','má pred vodičom modrého vozidla prednosť, pretože v jeho jazdnom pruhu sa nachádza prekážka,','je povinný umožniť vodičovi modrého vozidla aj vodičovi zeleného vozidla obídenie prekážky.');
INSERT INTO `Questions` VALUES (1132,1132,2,1,'Ako posledné prejde cez križovatku','835',3,3,'modré vozidlo,','zelené vozidlo,','červené vozidlo.');
INSERT INTO `Questions` VALUES (1133,1133,2,1,'Vaše vozidlo prejde cez križovatku ako','377',3,1,'posledné,','prvé,','druhé.');
INSERT INTO `Questions` VALUES (1134,1134,2,1,'Ako prvé prejdú cez križovatku','135',3,2,'vaše vozidlo súčasne s električkou prichádzajúcou sprava,','obidve električky súčasne,','vaše vozidlo súčasne s modrým vozidlom.');
INSERT INTO `Questions` VALUES (1135,1135,0,1,'Jazdnou súpravou sa rozumie','',2,2,'súprava zložená z viac ako dvoch električiek,','súprava zložená z jedného alebo z viacerých motorových vozidiel a z jedného alebo z viacerých prípojných vozidiel,','viac ako 10 vozidiel jazdiacich za sebou vo vzdialenosti kratšej ako 25 metrov.');
INSERT INTO `Questions` VALUES (1136,1136,0,1,'zastavením sa rozumie','',2,1,'uvedenie vozidla do pokoja na čas nevyhnutne potrebný na urýchlene nastúpenie alebo na vystúpenie prepravovaných osôb alebo na urýchlene naloženie alebo na zloženie nákladu,','prerušenie jazdy motorového vozidla z dôvodu nezávislého od vôle vodiča,','len také uvedenie vozidla do pokoja, ktoré nepresiahne čas tri minúty.');
INSERT INTO `Questions` VALUES (1137,1137,0,1,'Vodič nesmie predchádzať, ak','',2,3,'na to v obci neupozornil vodiča predchádzaného vozidla zvukovým výstražným znamením,','pred ním jazdí zvláštne motorové vozidlo,','by pri predchádzaní svojou výrazne nižšou rýchlosťou obmedzil za ním idúce vozidlo, ktoré začalo úkon predchádzania skôr.');
INSERT INTO `Questions` VALUES (1138,1138,0,1,'Predchádza sa','',2,1,'vľavo; vpravo sa predchádza vozidlo, ktoré mení smer jazdy vľavo a ak už nie je pochybnosť o ďalšom smere jeho jazdy ,','vpravo; vľavo sa predchádza len motocykel,','vľavo za každých okolností.');
INSERT INTO `Questions` VALUES (1139,1139,0,1,'Ak je nevyhnutné upozorniť ostatných účastníkov cestnej premávky na hroziace nebezpečenstvo, najmä v prípadoch, keď je potrebné náhle znížiť rýchlosť jazdy alebo zastaviť vozidlo,','',2,3,'dáva vodič svetelné výstražné znamenie prerušovaným zapínaním predných hmlových svetlometov,','použije vodič zvukové výstražné znamenie,','dáva vodič svetelné výstražné znamenie zapnutím výstražnej funkcie smerových svietidiel.');
INSERT INTO `Questions` VALUES (1140,1140,0,1,'Vodič je povinný zaistiť bezpečný vjazd na cestu pomocou spôsobilej a náležite poučenej osoby, ak','',2,2,'je vozidlo značne znečistené,','to vyžadujú okolnosti, najmä nedostatočný rozhľad,','má vozidlo nefunkčné brzdy.');
INSERT INTO `Questions` VALUES (1141,1141,0,1,'Vodič smie cúvať','',2,3,'na železničnom priecestí, ak nie je v blízkosti vlak,','v tuneli,','na jednosmernej ceste, ak je to nevyhnutne potrebné najmä na zaradenie do radu stojacich vozidiel alebo na vyjdenie z neho.');
INSERT INTO `Questions` VALUES (1142,1142,0,1,'Vodič smie zastaviť a stáť len','',2,1,'vpravo v smere jazdy v jednom rade a rovnobežne s okrajom cesty, čo najbližšie k okraju cesty a na jednosmernej ceste vpravo i vľavo,','na jednosmernej ceste,','na krajnici.');
INSERT INTO `Questions` VALUES (1143,1143,0,1,'Motorové vozidlo vlečené pomocou osobitného zariadenia a autobus sa smú vliecť','',2,3,'aj s prepravovanými osobami,','len na diaľnici a rýchlostnej ceste,','len bez prepravovaných osôb; nákladný automobil sa smie vliecť len bez osôb prepravovaných v jeho Iožnom priestore.');
INSERT INTO `Questions` VALUES (1144,1144,0,1,'Vodič motorového vozidla kategórie N, ktorého najväčšia prípustná celková hmotnosť presahuje 7 500 kg alebo vodič jazdnej súpravy, ktorej najväčšia prípustné hmotnosť presahuje 7 500 kg nesmie','',2,1,'pri jazde po diaľnici predchádzať iné motorové vozidlo,','pri jazde po medzinárodnej trase a ceste 1. triedy predchádzať iné motorové vozidlo,','mimo obce na ceste s dvoma alebo viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy použiť na jazdu pravý jazdný pruh.');
INSERT INTO `Questions` VALUES (1145,1145,0,1,'Traktor s nákladným prívesom, v ktorého Iožnom priestore sa prepravujú osoby, smie viesť len vodič starší ako','',2,1,'21 rokov, ktorý má vo vedení traktora najmenej dvojročnú prax,','18 rokov, ktorý má vo vedení traktora najmenej jednoročnú prax,','23 rokov, ktorý sa podrobil špecializovanej príprave.');
INSERT INTO `Questions` VALUES (1146,1146,0,1,'Signál dvoch vedľa seba umiestnených, striedavo prerušovaných červených svetiel','',2,2,'ukladá povinnosť chodcom nevstupovať na vozovku,','znamená pre vodiča povinnosť zastaviť vozidlo pred svetelným signalizačným zariadením,','znamená pre vodiča povinnosť znížiť rýchlosť jazdy.');
INSERT INTO `Questions` VALUES (1147,1147,0,1,'Doba denného odpočinku','',1,3,'je akákoľvek denná doba, počas ktorej môže vodič voľne disponovať svojím časom a zahŕňa „dobu skráteného denného odpočinku",','je akákoľvek denná doba, počas ktorej môže vodič voľne disponovať svojím časom a zahŕňa „dobu pravidelného denného odpočinku“,','je akákoľvek denná doba, počas ktorej môže vodič voľne disponovať svojím časom a zahŕňa „dobu pravidelného denného odpočinku“ a „dobu skráteného denného odpočinku“.');
INSERT INTO `Questions` VALUES (1148,1148,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'niektoré svetelné zariadenie dôležité pre bezpečnosť premávky na pozemných komunikáciách chýba alebo je nesprávne umiestnené, nesvieti alebo nespĺňa ustanovené podmienky, takže hrozí bezprostredne nebezpečenstvo,','nedosahuje na rovine rýchlosť najmenej 100 km/h,','je vybavené platnou tabuľkou alebo tabuľkami s evidenčným číslom iného štátu,');
INSERT INTO `Questions` VALUES (1149,1149,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'niektorá časť systému, komponentu alebo samotnej technickej jednotky vozidla je chybná, poškodená alebo upravená, prípadne chýba úplne,','z miesta vodiča nie je možné nastaviť pravé predné zrkadlo,','je na zadnom skle použitá schválená fólia.');
INSERT INTO `Questions` VALUES (1150,1150,1,1,'Táto dopravná značka znamená:','b2',2,2,'Zákaz vjazdu nemotorových vozidiel,','Zákaz vjazdu všetkých vozidiel,','Zúžená vozovka.');
INSERT INTO `Questions` VALUES (1151,1151,1,1,'Táto dopravná značka znamená:','b19',2,3,'Zákaz státia motorových vozidiel, ktoré nedodržia vyznačený odstup,','Prikázaná jazda vozidiel v kolóne,','Zákaz jazdy motorových vozidiel vo vzdialenosti kratšej ako je vyznačená.');
INSERT INTO `Questions` VALUES (1152,1152,1,1,'Táto dopravná značka znamená:','p10',2,1,'Prednosť protiidúcich vozidiel,','Prednosť pred protiidúcimi vozidlami,','Obojsmerná premávka.');
INSERT INTO `Questions` VALUES (1153,1153,1,1,'Táto dopravná značka znamená:','ip3b',2,2,'Návestná smerová tabula,','Jednosmerná premávka,','Prikázaný smer jazdy.');
INSERT INTO `Questions` VALUES (1154,1154,1,1,'Táto dopravná značka','is14',2,1,'informuje o križovatke, na ktorej je zakázané odbočovať vľavo,','vyznačuje hlavnú cestu,','vyznačuje spôsob radenia sa pred križovatkou.');
INSERT INTO `Questions` VALUES (1155,1155,1,1,'Táto dopravná značka znamená:','is27',2,2,'Vzdialenosť,','Diaľnica,','Rýchlostná cesta.');
INSERT INTO `Questions` VALUES (1156,1156,1,1,'Táto dodatková tabuľka znamená:','e5b',2,2,'Smer a vzdialenosť k miestam, od ktorých platí značka, pod ktorou je tabuľka umiestnená,','Úsek platnosti,','smerové šípy.');
INSERT INTO `Questions` VALUES (1157,1157,1,1,'Táto dopravná značka','v12c',2,1,'vyznačuje úsek, kde je zakázané státie,','vyznačuje úsek, kde je zakázané zastavenie,','oddeľuje kraj vozovky od cestičky pre cyklistov.');
INSERT INTO `Questions` VALUES (1158,1158,2,1,'Ako prvé prejde cez križovatku','187',3,2,'červené vozidlo,','modré vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (1159,1159,2,1,'Ak svieti signál na opustenie križovatky umiestnený v protiľahlom rohu križovatky, prejdú cez križovatku ako prvé','916',3,1,'červené vozidlo súčasne s modrým vozidlom,','protiidúce zelené a žlté vozidlo,','obidve električky.');
INSERT INTO `Questions` VALUES (1160,1160,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','215',3,3,'1. vaše vozidlo, 2. červené súčasne so zeleným,','1. zelené, 2. vaše vozidlo, 3. červené,','1. červené súčasne so zeleným, 2. vaše vozidlo.');
INSERT INTO `Questions` VALUES (1161,1161,2,1,'Vaše vozidlo prejde cez križovatku ako','270',3,3,'druhé,','prvé,','posledné súčasne so žltým vozidlom.');
INSERT INTO `Questions` VALUES (1162,1162,0,1,'zastavením vozidla sa rozumie','',2,2,'každé prerušenie jazdy,','prerušenie jazdy z dôvodu nezávislého od vôle vodiča,','uvedenie motorového vozidla do pokoja na čas nevyhnutne potrebný na urýchlene nastúpenie alebo vystúpenie prepravovaných osôb.');
INSERT INTO `Questions` VALUES (1163,1163,0,1,'Ak jazdné pruhy nie sú na vozovke vyznačené, jazdným pruhom sa rozumie časť vozovky dovoľujúca jazdu vozidiel','',2,2,'najmenej s dvoma kolesami v jazdnom prúde za sebou,','s troma a viacerými kolesami v jazdnom prúde za sebou.','len s dvoma kolesami v jazdnom prúde za sebou.');
INSERT INTO `Questions` VALUES (1164,1164,0,1,'Vodič nesmie predchádzať, ak','',2,1,'by sa nemohol bezpečne zaradiť pred vozidlo alebo pred vozidlá, ktoré chce predísť,','pred ním jazdí zvláštne motorové vozidlo,','na to v obcí neupozornil vodiča predchádzaného vozidla zvukovým výstražným znamením.');
INSERT INTO `Questions` VALUES (1165,1165,0,1,'Vodič motorového vozidla s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg, okrem vodiča autobusu, smie na diaľnici a rýchlostnej ceste jazdiť rýchlosťou najviac','',2,2,'110 km/h,','90 km/h,','130 km/h.');
INSERT INTO `Questions` VALUES (1166,1166,0,1,'Vodič motorového vozidla kategórie N, ktorého najväčšia prípustná celková hmotnosť presahuje 7 500 kg alebo vodič jazdnej súpravy, ktorej najväčšia prípustné hmotnosť presahuje 7 500 kg nesmie','',2,3,'mimo obce na ceste s dvoma alebo viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy použiť na jazdu pravý jazdný pruh,','pri jazde po medzinárodnej trase a ceste 1. triedy predchádzať iné motorové vozidlo,','pri jazde po diaľnici predchádzať iné motorové vozidlo.');
INSERT INTO `Questions` VALUES (1167,1167,0,1,'Pri zastavení a státí vodič je povinný','',2,1,'čo najlepšie využiť parkovacie miesto a nesmie znemožniť ostatným vodičom vyjdenie z parkovacieho miesta,','ponechať bočný odstup od vozidla najmenej 1,5 m,','použiť vždy zariadenie umožňujúce výstražnú funkciu smerových svetiel.');
INSERT INTO `Questions` VALUES (1168,1168,0,1,'Vodič vozidla, ktoré je povinne vybavené prenosným výstražným trojuholníkom, je povinný tento trojuholník použiť počas','',2,2,'prepravy osôb s ťažkým zdravotným postihnutím,','núdzového státia, najmä pri prerušení jazdy pre chybu na vozidle alebo na náklade, v dôsledku dopravnej nehody, ak také vozidlo tvorí prekážku cestnej premávky,','počas jazdy na ceste rýchlosťou nižšou ako 30 km.h''1.');
INSERT INTO `Questions` VALUES (1169,1169,0,1,'Vodič nesmie zastaviť a stáť na zastávke vozidla pravidelnej verejnej dopravy osôb v úseku, ktorý sa začína','',2,3,'vo vzdialenosti 15 m pred označníkom zastávky a končí sa označníkom zastávky,','dopravnou značkou pre zastávku a končí sa pri označníku zastávky,','dopravnou značkou pre zastávku a končí sa 5 m za označníkom zastávky.');
INSERT INTO `Questions` VALUES (1170,1170,0,1,'Pred železničným priecestím vodič je povinný','',2,3,'dávať zvukové výstražné znamenie na upozornenie osoby pribratej na zaistenie bezpečnej prevádzky železničného priecestie,','vždy zastaviť vozidlo,','počínať si mimoriadne opatrne, najmä sa presvedčiť, či môže bezpečne prejsť cez železničné priecestie.');
INSERT INTO `Questions` VALUES (1171,1171,0,1,'Vodič nesmie použiť diaľkové svetlomety, ak','',2,1,'je vozovka dostatočne a súvisle osvetlená alebo ak by mohol byť oslnený vodič protiidúceho vozidla, vodič vozidla idúceho pred nim alebo iný účastník cestnej premávky, stroj vedúci vlaku alebo vodič iného dráhového vozidla, alebo vodič plavidla,','jazdí za zníženej viditeľnosti,','jazdí za zníženej viditeľnosti v obci.');
INSERT INTO `Questions` VALUES (1172,1172,0,1,'Prekážka cestnej premávky sa označuje','',2,1,'najmä zábranou na označenie uzávierky, výstražným svetlom oranžovej farby, za zníženej viditeľnosti aj červeným svetlom alebo reflexnou červenou zastávkou,','len vtedy, ak ju tvorí motorové vozidlo,','len za zníženej viditeľnosti.');
INSERT INTO `Questions` VALUES (1173,1173,0,1,'Ak je nesúlad medzi zvislými dopravnými značkami a vodorovnými dopravnými značkami','',2,3,'vodorovné dopravné značky sú nadradené zvislým dopravným značkám,','nadradená je dopravná značka umiestnená bližšie ku križovatke,','c zvislé dopravné značky sú nadradené vodorovným dopravným značkám.');
INSERT INTO `Questions` VALUES (1174,1174,0,1,'Doba denného odpočinku','',1,3,'sa môže predĺžiť na dobu pravidelného týždenného odpočinku,','sa môže predĺžiť na dobu skráteného týždenného odpočinku,','sa môže predĺžiť na dobu pravidelného týždenného alebo na dobu skráteného týždenného odpočinku.');
INSERT INTO `Questions` VALUES (1175,1175,0,1,'Povinnou výbavou motorového vozidlo s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg a prípojného vozidla s najväčšou prípustnou hmotnosťou prevyšujúcou 750 kg je','',1,1,'aspoň jeden zakladací klin, ktorý účinne zabezpečí vozidlo proti samovoľnému pohybu,','najmenej dvojlitrová zásoba mazivá v osobitnej nádobe,','dvojica diaľkových svetlometov natáčavých súčasne s riadiacim mechanizmom vozidla.');
INSERT INTO `Questions` VALUES (1176,1176,0,1,'Ak je pneumatika alebo disk kolesa nadmerne poškodený','',1,1,'považuje sa takéto vozidlo za technicky nespôsobilé na premávku na pozemných komunikáciách,','možno s takýmto vozidlom jazdiť iba rýchlosťou neprevyšujúcou 60 km/h,','možno také vozidlo používať len na účelových komunikáciách.');
INSERT INTO `Questions` VALUES (1177,1177,1,1,'Táto dopravná značka znamená:','b24',2,1,'Zákaz vjazdu vozidiel, ktorých výška presahuje vyznačenú hranicu; pritom je rozhodujúca okamžitá výška vrátane nákladu,','Zákaz státia vozidiel, ktorých výška presahuje vyznačenú hranicu; pritom je rozhodujúca okamžitá výška vrátane nákladu,','Zákaz vjazdu vozidiel nižších ako 3,5 m.');
INSERT INTO `Questions` VALUES (1178,1178,1,1,'Táto dopravná značka znamená:','b27b',2,2,'Zákaz otáčania,','Zákaz odbočovania vľavo,','Prikázaný smer jazdy vľavo.');
INSERT INTO `Questions` VALUES (1179,1179,1,1,'Táto dopravná značka znamená:','b32a',2,1,'Zákaz zvukových výstražných znamení,','Koniec zákazu zvukových výstražných znamení,','Zákaz vjazdu vozidiel spôsobujúcich nadmerný hluk.');
INSERT INTO `Questions` VALUES (1180,1180,1,1,'Táto dopravná značka znamená:','c18',2,3,'Koniec hlavnej cesty,','Zákaz státia,','Koniec príkazu.');
INSERT INTO `Questions` VALUES (1181,1181,1,1,'Táto dopravná značka znamená:','ii18a',2,1,'Odpočívadlo s objektmi služieb,','Obchodné centrum,','Platené parkovisko.');
INSERT INTO `Questions` VALUES (1182,1182,1,1,'Táto dopravná značka','is16',2,3,'vyznačuje zónu s dopravným obmedzením začínajúcu od tejto dopravnej značky,','informuje o dopravnom obmedzení v časti obce,','informuje o uzávierke cesty alebo o obmedzení cestnej premávky a vyznačuje smer a priebeh obchádzky alebo odklonovej trasy.');
INSERT INTO `Questions` VALUES (1183,1183,1,1,'Táto dopravná značka informuje','ip29',2,1,'o možnosti núdzového zastavenia vozidla v únikovej zóne v prípade technickej poruchy,','o blízkosti odpočívadla so sociálnym zariadením,','pred križovatkou o ceste, ktorá končí, alebo ktorou nemožno ďalej pokračovať v jazde.');
INSERT INTO `Questions` VALUES (1184,1184,1,1,'Táto dopravná značka','v8a',2,3,'je návesťou pred priechodom pre cyklistov,','vyznačuje na cestičke pre cyklistov smer jazdy motocyklov, ktorých najväčšia konštrukčné rýchlosť nepresahuje 45 km. h",','vyznačuje na cestičke pre cyklistov určený smer jazdy cyklistov.');
INSERT INTO `Questions` VALUES (1185,1185,2,1,'V poradí tretie prejde okolo prekážky','511',3,2,'zelené vozidlo,','žlté vozidlo,','červené vozidlo.');
INSERT INTO `Questions` VALUES (1186,1186,2,1,'V poradí druhé prejde cez križovatku:','132',3,2,'zelené vozidlo,','modré vozidlo,','žlté vozidlo.');
INSERT INTO `Questions` VALUES (1187,1187,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','729',3,1,'1. zelené, 2. vaše vozidlo, 3. červené,','1. vaše vozidlo, 2. červené, 3. zelené,','1. červené, 2. zelené, 3. vaše vozidlo.');
INSERT INTO `Questions` VALUES (1188,1188,2,1,'Ako posledné prejdú cez križovatku','594',3,3,'električka č. 1 súčasne s vašim vozidlom,','vaše vozidlo súčasne s električkou č. 2,','električka č. 1 súčasne s električkou č. 2.');
INSERT INTO `Questions` VALUES (1189,1189,0,1,'Prekážkou cestnej premávky sa rozumie','',2,3,'pomaly pohybujúce sa vozidlo vykonávajúce údržbu alebo opravu cesty,','každé vozidlo, ktoré prepravuje náklad, ktorý presahuje celkovú dĺžku alebo šírku takéhoto vozidla,','všetko, čo môže ohroziť alebo obmedziť jazdu vozidiel a pohyb chodcov, za prekážku cestnej premávky sa nepovažuje vozidlo stojace alebo pomaly sa pohybujúce z dôvodov vyvolaných cestnou premávkou, spojených najmä s údržbou a opravou cesty, dopravnou nehod');
INSERT INTO `Questions` VALUES (1190,1190,0,1,'Mimo obce na ceste s troma alebo s viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy smie vodič nákladného automobilu s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg použiť na jazdu','',2,2,'len ľavý jazdný pruh,','výhradne dva jazdné pruhy najbližšie k pravému okraju vozovky; v ostatných jazdných pruhoch vodič smie jazdiť, ak je to potrebné na obchádzanie, otáčanie alebo na odbočovanie,','len pravý jazdný pruh.');
INSERT INTO `Questions` VALUES (1191,1191,0,1,'Ak vodič, ktorý chce zastaviť alebo stáť, zachádza na okraj cesty alebo chodníka,','',2,2,'nie je povinný dávať znamenie o zmene smeru jazdy,','je povinný dávať znamenie o zmene smeru jazdy,','je povinný dávať znamenie o zmene smeru jazdy len v obci.');
INSERT INTO `Questions` VALUES (1192,1192,0,1,'Vodič nesmie zastaviť a stáť vo vzdialenosti kratšej ako','',2,2,'10 m od začiatku a 5 m od konca nástupného ostrovčeka,','5 m od začiatku a 5 m od konca pozdĺžne] súvislej čiary alebo nástupného ostrovčeka tam, kde by medzi touto čiarou alebo nástupným ostrovčekom a vozidlom nezostal voľný aspoň jeden jazdný pruh široký najmenej 3 m,','10 m od začiatku a 10 m od konca pozdĺžnej súvislej čiary alebo nástupného ostrovčeka.');
INSERT INTO `Questions` VALUES (1193,1193,0,1,'Vodič nesmie vchádzať na železničné priecestie, ak','',2,1,'sa dáva výstraha prerušovaným zvukom húkačky alebo zvončeka priecestného zabezpečovacieho zariadenia,','osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva pokyn vodorovným kývaním ruky so žltou zástavkou,','protiidúci vodič dáva zvukové výstražné znamenie.');
INSERT INTO `Questions` VALUES (1194,1194,0,1,'Svetelné výstražné znamenie sa dáva prerušovaným zapínaním','',2,2,'predných svetlometov do hmly,','stretávacích svetlometov alebo diaľkových svetlometov,','parkovacích svietidiel.');
INSERT INTO `Questions` VALUES (1195,1195,0,1,'Vodič motorového vozidla je povinný dodržiavať za vozidlom idúcim pred ním','',2,2,'vzdialenosť najmenej 10 m,','takú vzdialenosť, aby sa predchádzajúce vozidlo mohlo pred neho bezpečne zaradiť,','takú vzdialenosť, aby pri použití diaľkových svetlometov nebol oslnený vodič pred ním idúceho vozidla.');
INSERT INTO `Questions` VALUES (1196,1196,0,1,'Ak ten, kto prekážku cestnej premávky spôsobil, ju bezodkladne neodstráni, je povinný ju označiť','',2,3,'len za zníženej viditeľnosti,','len vtedy, ak prekážku spôsobil na diaľnici alebo na rýchlostnej ceste,','a oznámiť to policajtovi.');
INSERT INTO `Questions` VALUES (1197,1197,0,1,'Náklad musí byť na vozidle riadne umiestnený, rozložený a upevnený,','',2,1,'aby nezakrýval svetlomety a svietidlá vozidla, odrazové sklá, tabuľku s evidenčným číslom a vyznačenie najvyššej povolenej rýchlostí,','môže zakrývať svetlomety a svietidlá vozidla, odrazové sklá, tabuľku s evidenčným číslom len pri jazde na účelovej komunikácii a miestnej komunikácii,','môže zakrývať svetlomety a svietidlá vozidla, odrazové sklá, tabuľku s evidenčným číslom len pri jazde rýchlosťou nižšou ako 30 km/h.');
INSERT INTO `Questions` VALUES (1198,1198,0,1,'Ak prichádza vozidlo s právom prednostnej jazdy, chodec','',2,3,'smie vstupovať na vozovku len na priechode pre chodcov,','má prednosť pred týmto vozidlom, ak prechádza cez priechod pre chodcov,','nesmie vstupovať na vozovku.');
INSERT INTO `Questions` VALUES (1199,1199,0,1,'Účastník dopravnej nehody je povinný','',2,2,'zotrvať na mieste dopravnej nehody až do príchodu odťahovej služby,','zotrvať na mieste dopravnej nehody až do príchodu policajta alebo sa na toto miesto bezodkladne vrátiť po poskytnutí alebo privolaní pomoci, alebo po ohlásení dopravnej nehody,','je povinný zotrvať na mieste dopravnej nehody, to neplatí, ak preukázal svoju totožnosť ostatným účastníkom dopravnej nehody.');
INSERT INTO `Questions` VALUES (1200,1200,0,1,'Znamenie o zmene smeru jazdy vodič nedáva','',2,3,'pri zmene smeru jazdy,','pri prechádzaní z jedného jazdného pruhu do druhého jazdného pruhu,','pri vjazde do kruhového objazdu.');
INSERT INTO `Questions` VALUES (1201,1201,0,1,'Celkový čas vedenia motorového vozidla nesmie presiahnuť','',1,3,'100 hodín v období dvoch po sebe nasledujúcich týždňov,','80 hodín V období dvoch po sebe nasledujúcich týždňov,','90 hodín v období dvoch po sebe nasledujúcich týždňov.');
INSERT INTO `Questions` VALUES (1202,1202,0,1,'Povinnou výbavou motorového vozidla kategórie M a N sú','',1,1,'náhradné elektrické poistky, ak sa v elektrickej inštalácii používajú, a to po jednej z každého používaného druhu,','zakladacie kliny, a to po štyri na každú nápravu,','dve náhradné kolesá, ak sa nejedná o jazdnú súpravu s rovnakým vyhotovením kolies.');
INSERT INTO `Questions` VALUES (1203,1203,0,1,'Ak pneumatika alebo disk kolesa je nadmerne poškodený','',1,1,'považuje sa takéto vozidlo za nespôsobilé na premávku na pozemných komunikáciách,','možno s takýmto vozidlom jazdiť iba rýchlosťou neprevyšujúcou 60 km/h,','možno také vozidlo používať len na účelových komunikáciách.');
INSERT INTO `Questions` VALUES (1204,1204,1,1,'Táto dopravná značka znamená:','b15',2,1,'Zákaz vjazdu záprahových vozidiel,','Cesta pre záprahové vozidlá,','Zákaz vjazdu nemotorových vozidiel.');
INSERT INTO `Questions` VALUES (1205,1205,1,1,'Táto dopravná značka znamená:','b20',2,1,'Zákaz vjazdu vozidiel alebo súprav vozidiel, ktorých dĺžka vrátane nákladu presahuje vyznačenú hranicu na značke,','Zákaz státia vozidiel alebo súprav vozidiel, ktorých dĺžka vrátane nákladu presahuje vyznačenú hranicu na značke,','Zákaz vjazdu nákladných automobilov kratších ako 10 m.');
INSERT INTO `Questions` VALUES (1206,1206,1,1,'Táto dopravná značka znamená:','b28',2,2,'Koniec zákazu otáčania,','Zákaz otáčania,','Prikázaný smer jazdy.');
INSERT INTO `Questions` VALUES (1207,1207,1,1,'Táto dopravná značka znamená:','c11',2,2,'Zákaz vjazdu záprahových vozidiel; značka zakazuje vjazd záprahovým vozidlám vrátane jazdcov na koňoch,','Cestička pre jazdcov na koňoch; značka prikazuje jazdcom na koňoch použiť takto označený pruh alebo cestíčku,','Priechod pre jazdcov na koňoch; značka označuje priechod pre jazdcov na koňoch.');
INSERT INTO `Questions` VALUES (1208,1208,1,1,'Táto dopravná značka znamená:','p11',2,3,'Zákaz predchádzania,','Prednosť protiidúcich vozidiel,','Prednosť pred protiidúcimi vozidlami.');
INSERT INTO `Questions` VALUES (1209,1209,1,1,'Táto dopravná značka informuje','c26',2,1,'najmä o zmene smeru jazdy do protismeru na smerovo rozdelenej ceste,','o mieste, kde možno obchádzať vľavo električku, ktorá stojí na zastávke,','o možnosti jazdy pozdĺž električky vľavo.');
INSERT INTO `Questions` VALUES (1210,1210,1,1,'Táto dopravná značka','v5c',2,1,'vyznačuje miesto, kde je vodič povinný zastaviť vozidlo na príkaz značky Stoj, daj prednosť v jazde!,','vyznačuje parkovisko s pozdĺžnym státím,','prikazuje vodičovi motorového vozidla vypnúť motor.');
INSERT INTO `Questions` VALUES (1211,1211,1,1,'Táto dopravná značka vyznačuje','v12b',2,3,'úsek, kde je dovolené zastavenie a státie vozidlám pravidelnej verejnej dopravy osôb,','nebezpečný úsek cesty, na ktorom treba jazdiť so zvýšenou opatrnosťou,','úsek, kde je zakázané zastavenie a státie.');
INSERT INTO `Questions` VALUES (1212,1212,2,1,'Červené vozidlo prejde cez križovatku ako','402',3,1,'posledné,','prvé súčasne so zeleným vozidlom,','prvé súčasne s modrým vozidlom.');
INSERT INTO `Questions` VALUES (1213,1213,2,1,'Na tento pokyn policajta','646',3,2,'je vodič modrého, vodič červeného a vodič žltého vozidla povinný zastaviť vozidlo pred hranicou Križovatky,','je vodič čierneho a vodič zeleného vozidla povinný zastaviť vozidlo pred hranicou križovatky,','smie vodič čierneho a vodič zeleného vozidla pokračovať v jazde; ak títo vodiči dodržia ustanovenia o odbočovaní, môžu odbočiť vpravo alebo vľavo.');
INSERT INTO `Questions` VALUES (1214,1214,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','809',3,3,'1. modré, 2. zelené, 3. vaše vozidlo,','1. vaše vozidlo, 2. zelené, 3. modré,','všetky tri súčasne.');
INSERT INTO `Questions` VALUES (1215,1215,2,1,'Ako posledné prejde cez križovatku','27',3,2,'električka súčasne s vaším vozidlom,','vaše vozidlo,','žlté vozidlo.');
INSERT INTO `Questions` VALUES (1216,1216,0,1,'Autobusom sa rozumie','',2,2,'motorové a nemotorové vozidlo, ktoré má okrem miesta vodiča viac ako tri miesta na sedenie,','motorové vozidlo na dopravu osôb, ktoré má okrem miesta pre vodiča viac ako osem miest na sedenie,','každé vozidlo určené na prepravu viac ako štyroch osôb.');
INSERT INTO `Questions` VALUES (1217,1217,0,1,'Vodič nesmie','',2,3,'ohroziť chodcov prechádzajúcich cez priechod pre chodcov, len ak je takýto priechod vybavený svetelným signalizačným zariadením,','obchádzať osobu pohybujúcu sa po ľavej krajnici,','ohroziť chodcov prechádzajúcich cez cestu, na ktorú vodič odbočuje, pri odbočovaní na miesto mimo cesty, pri vchádzaní na cestu a pri otáčaní alebo pri cúvaní.');
INSERT INTO `Questions` VALUES (1218,1218,0,1,'Vozidlá môžu ísť súbežne,','',2,1,'ak je na ceste s dvoma alebo s viacerými jazdnými pruhmi v jednom smere jazdy taká hustá premávke, že sa utvoria súvislé prúdy vozidiel, v ktorých vodič motorového vozidla môže jazdiť len takou rýchlosťou, ktorá závisí od rýchlosti vozidiel idúcich pred n','len ak idú po jednosmernej ceste s dvoma jazdnými pruhmi v obci,','len ak idú po diaľnici a rýchlostnej ceste.');
INSERT INTO `Questions` VALUES (1219,1219,0,1,'Na električkový koľajový pás v úrovni vozovky sa smie vojsť','',2,1,'len pri obchádzaní, predchádzaní, odbočovaní, otáčaní, vchádzaní na cestu alebo ak to dovoľuje dopravná značka alebo ak to vyžadujú mimoriadne okolnosti,','len pri obchádzaní a predchádzaní,','za každých okolnosti.');
INSERT INTO `Questions` VALUES (1220,1220,0,1,'Električka, ktorá križuje smer jazdy vozidla idúceho po jej pravej alebo po jej ľavej strane a dáva znamenie o zmene smeru jazdy,','',2,1,'má prednosť vjazde,','nemá prednosť v jazde,','musí dať prednosť v jazde vozidlu idúcemu po jej ľavej strane.');
INSERT INTO `Questions` VALUES (1221,1221,0,1,'Vodič motorového vozidla alebo jazdnej súpravy povinne vybavených zakladacími klinmi, je povinný ich použiť,','',2,1,'ak treba zabezpečiť vozidlo alebo súpravu proti pohybu,','len ak vozidlo stoji v obci,','len ak vozidlo stoji mimo obce.');
INSERT INTO `Questions` VALUES (1222,1222,0,1,'Vodič nesmie zastaviť a stáť','',2,1,'na priechode pre chodcov alebo na priechode pre cyklistov a vo vzdialenosti kratšej ako 5 m pred nimi,','na priechode pre chodcov a vo vzdialenosti kratšej ako 25 m pred ním,','na jednosmernej ceste vľavo.');
INSERT INTO `Questions` VALUES (1223,1223,0,1,'Ak to vyžadujú okolnosti, najmä ak znamenie dávané smerovými svietidlami alebo rukou nie je dostatočne viditeľné, najmä pre šírku nákladu alebo za zníženej viditeľnosti,','',2,3,'nesmie vodič za žiadnych okolnosti uskutočniť zamýšľaný jazdný úkon,','smie vodič uskutočniť zamýšľaný jazdný úkon, aj ak pritom ohrozí iných účastníkov cestnej premávky,','musí dávať znamenie spôsobilá a náležite poučená osoba alebo sa musí použiť iný zreteľný spôsob.');
INSERT INTO `Questions` VALUES (1224,1224,0,1,'Prepravované osoby nesmú','',2,2,'jesť, piť ani fajčiť,','svojím správaním ohrozovať bezpečnosť cestnej premávky najmä obmedzovaním vodiča v bezpečnom ovládaní vozidla, zotrvaním na miestach, kde by boli ohrozené, a vyhadzovaním predmetov z vozidla,','obsluhovať telefónny prístroj.');
INSERT INTO `Questions` VALUES (1225,1225,0,1,'Účastník dopravnej nehody je povinný urobiť vhodné opatrenia, aby','',2,2,'ostatní účastníci dopravnej nehody nemohli požiť alkohol,','nebola ohrozená bezpečnosť cestnej premávky na mieste dopravnej nehody,','ostatní účastníci dopravnej nehody zotrvali na mieste dopravnej nehody až do príchodu policajta.');
INSERT INTO `Questions` VALUES (1226,1226,0,1,'Pred vstupom na vozovku chodec','',2,3,'musí prestať jesť, piť a fajčiť,','sa nemusí presvedčiť, čí tak môže urobiť bez nebezpečenstva, ak vstupuje na vozovku v obci,','sa musí presvedčiť, či tak môže urobiť bez nebezpečenstva.');
INSERT INTO `Questions` VALUES (1227,1227,0,1,'Osoby sa môžu pohybovať po vozovke v tuneli len','',2,3,'v čase od 00.00 hod. do 04.00 hod.','po pravej krajnici,','v súvislosti so zaisťovaním bezpečnosti cestnej premávky, ak majú na sebe reflexný bezpečnostný odev.');
INSERT INTO `Questions` VALUES (1228,1228,0,1,'Vodič motorového vozidla musí mať po uplynutí štyroch a pol hodiny vedenia motorového vozidla prestávku v práci v trvaní najmenej','',1,2,'45 minút, ak sa nezačína nepretržitý denný odpočinok alebo nepretržitý odpočinok v týždni,','45 minút, ak sa nezačína nepretržitý denný odpočinok alebo nepretržitý odpočinok v týždni, pričom prestávku v práci sa môže nahradiť prestávkou trvajúcou najmenej 15 minút, po ktorej nasleduje prestávka trvajúca najmenej 30 minút,','30 minút.');
INSERT INTO `Questions` VALUES (1229,1229,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'je zhodný účinok prevádzkovej brzdy na kolesách tej istej nápravy,','dodatočne namontované svetelné zariadenia narúšajú výhľad z miesta spolujazdca,','niektoré svetelné zariadenie dôležité pre bezpečnosť cestnej premávky chýba alebo je nesprávne umiestnené, nesvieti alebo nespĺňa ustanovené podmienky, takže hrozí bezprostredne nebezpečenstvo.');
INSERT INTO `Questions` VALUES (1230,1230,0,1,'Povinnou výbavou mestských autobusov, špeciálnych vozidiel, ktoré sú prevádzkované na obmedzenom území v operatívnom dosahu servisných služieb svojho prevádzkovateľa nie je','',1,1,'kľuč na matice alebo skrutky kolies,','homologizovaný prenosný výstražný trojuholník,','bezpečnostný odev umiestnený v dosahu zo sedadla vodiča vozidla.');
INSERT INTO `Questions` VALUES (1231,1231,1,1,'Táto dopravná značka zakazuje vjazd','b21',2,3,'obytným automobilom,','skriňovým vozidlám,','vozidlám prepravujúcim výbušniny, ľahko horľavé alebo inak nebezpečné veci.');
INSERT INTO `Questions` VALUES (1232,1232,1,1,'Táto dopravná značka znamená:','b26',2,3,'Zákaz státia vozidiel, ktorých okamžitá hmotnosť pripadajúca na nápravu presahuje vyznačenú hranicu,','Zákaz vjazdu dvojnápravových vozidiel,','Zákaz vjazdu vozidiel, ktorých okamžitá hmotnosť pripadajúca na nápravu presahuje vyznačenú hranicu.');
INSERT INTO `Questions` VALUES (1233,1233,1,1,'Táto dopravná značka umiestnená pred železničným priecestím','p2',2,3,'označuje zastávku železničného vozidla,','označuje železničné priecestie strážené osobou pribratou na zaistenie bezpečnej prevádzky železničného priecestie,','prikazuje vodičovi zastaviť vozidlo na takom mieste, z ktorého má náležitý rozhľad na trať.');
INSERT INTO `Questions` VALUES (1234,1234,1,1,'Táto dopravná značka znamená:','c4b',2,1,'Prikázaný smer jazdy priamo a vpravo,','Zvýšenie počtu jazdných pruhov,','Zákruta vpravo.');
INSERT INTO `Questions` VALUES (1235,1235,1,1,'Táto dopravná značka znamená:','c12',2,3,'Zákaz vstupu chodcov a cyklistov,','Cestička k predajni bicyklov,','Cestička pre chodcov a cyklistov; značka prikazuje chodcom a cyklistom použiť takto označený spoločný pruh alebo cestíčku; chodci a cyklisti sa nesmú navzájom ohroziť.');
INSERT INTO `Questions` VALUES (1236,1236,1,1,'Táto dopravná značka znamená:','ii17b',2,2,'Odpočívadlo,','Sedačková lanovka,','Park.');
INSERT INTO `Questions` VALUES (1237,1237,1,1,'Táto dopravná značka znamená:','is37b',2,1,'Označenie konca obce v jazyku národnostnej menšiny,','Označenie hranice kraja v jazyku národnostnej menšiny,','Označenie hranice okresu v jazyku národnostnej menšiny.');
INSERT INTO `Questions` VALUES (1238,1238,1,1,'Takéto označenie sa musí použiť na','o3',2,1,'autobuse prepravujúcom deti,','vyznačenie úseku cesty so zvýšeným pohybom deti (v blízkosti školských a predškolských zariadení, detských ihrísk a podobne),','osobnom automobile prepravujúcom deti.');
INSERT INTO `Questions` VALUES (1239,1239,2,1,'Vozidlá prejdú okolo prekážky v tomto poradí:','214',3,2,'1. modré, 2. zelené, 3. červené, 4. žlté,','1. červené, 2. modré, 3. žlté, 4. zelené,','1. modré, 2. červené, 3. žlté, 4. zelené.');
INSERT INTO `Questions` VALUES (1240,1240,2,1,'Modré vozidlo prejde cez križovatku ako','132',3,2,'prvé,','druhé,','posledné,');
INSERT INTO `Questions` VALUES (1241,1241,2,1,'Ako prvé prejde cez križovatku','729',3,1,'zelené vozidlo,','vaše vozidlo,','červené vozidlo.');
INSERT INTO `Questions` VALUES (1242,1242,2,1,'Vaše vozidlo prejde cez križovatku ako','621',3,2,'tretie súčasne so zeleným vozidlom,','prvé súčasne so zeleným vozidlom,','posledné.');
INSERT INTO `Questions` VALUES (1243,1243,0,1,'Dať prednosť v jazde sa rozumie povinnosť','',2,3,'účastníka cestnej premávky počínať si tak, aby inému účastníkovi cestnej premávky nevzniklo nijaké nebezpečenstvo,','chodca prechádzajúceho na priechode pre chodcov neobmedziť motorové vozidlá prichádzajúce sprava,','účastníka cestnej premávky počínať si tak, aby ten kto má prednosť v jazde, nemusel zmeniť smer alebo rýchlosť jazdy.');
INSERT INTO `Questions` VALUES (1244,1244,0,1,'Vodič je povinný','',2,2,'venovať sa plne vedeniu vozidla; sledovať situáciu v cestnej premávke je povinný len v niektorých osobitných prípadoch, najmä počas jazdy vyššou rýchlosťou a prepravy nebezpečných vecí,','venovať sa plne vedeniu vozidla a sledovať situáciu v cestnej premávke,','sledovať situáciu v cestnej premávke len počas jazdy na diaľnici, na rýchlostnej ceste a v obci.');
INSERT INTO `Questions` VALUES (1245,1245,0,1,'Prevádzkovateľ vozidla nesmie prikázať ani dovoliť, aby sa na jazdu použilo vozidlo na takej ceste, na ktorej','',2,3,'nedokáže takéto vozidlo dosiahnuť najvyššiu dovolenú rýchlosť,','nie sú najmenej dva jazdné pruhy v jednom smere jazdy,','má takéto vozidlo obmedzenú alebo zakázanú jazdu.');
INSERT INTO `Questions` VALUES (1246,1246,0,1,'Vodič je povinný na vozovke alebo v jazdnom pruhu jazdiť','',2,2,'vpravo vo vzdialenosti najmenej 1,2 m od krajnice,','vpravo pri pravom okraji vozovky alebo jazdného pruhu; to neplatí pri obchádzaní, predchádzaní, otáčaní alebo odbočovaní,','vždy len pri ľavom okraji vozovky.');
INSERT INTO `Questions` VALUES (1247,1247,0,1,'Ak pri súbežnej jazde vodič vozidla idúceho vo voľnom jazdnom pruhu umožňuje vodičovi prvého vozidla nachádzajúceho sa v jazdnom pruhu, v ktorom je prekážka cestnej premávky, jej obídenie, nesmie vodič obchádzajúci prekážku','',2,2,'dávať znamenie o zmene smeru jazdy,','ohroziť vodiča jazdiaceho vo voľnom jazdnom pruhu,','jazdiť za žiadnych okolností rýchlosťou vyššou ako 15 km/h.');
INSERT INTO `Questions` VALUES (1248,1248,0,1,'Vodič nesmie pri predchádzaní ohroziť ani obmedziť vodič vozidla, pred ktoré sa po predídení zaraďuje; pritom je povinný','',2,1,'dávať znamenie o zmene smeru jazdy,','len za zníženej viditeľnosti dávať znamenie o zmene smeru jazdy,','dávať v obci zvukové výstražné znamenie na upozornenie vodiča predchádzaného vozidla.');
INSERT INTO `Questions` VALUES (1249,1249,0,1,'Vodič autobusu smie jazdiť rýchlosťou najviac','',2,2,'90 km/h; na diaľnici a na rýchlostnej ceste smie jazdiť rýchlosťou najviac 130km/h,','90 km/h; na diaľnici a na rýchlostnej ceste jazdiť rýchlosťou najviac 100 km/h,','80 km/h.');
INSERT INTO `Questions` VALUES (1250,1250,0,1,'Na kruhovom objazde je státie','',2,2,'dovolené,','aj zastavenie zakázané,','dovolené, ak je to potrebné na urýchlené nastúpenie alebo vystúpenie prepravovaných osôb.');
INSERT INTO `Questions` VALUES (1251,1251,0,1,'Ak pri jazde vozidla v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným, alebo vznikne dopravná nehoda vrátane požiaru, je vodič po zastavení vozidla povinný bezodkladne','',2,2,'opustiť tunel a dopravnú nehodu oznámiť najbližšiemu policajtovi,','vykonať vhodné opatrenia, aby nebola ohrozená bezpečnosť cestnej premávky v tuneli; ak to okolnosti vyžadujú, je oprávnený zastavovať iné vozidlá,','zariadiť odtiahnutie vozidla z tunela.');
INSERT INTO `Questions` VALUES (1252,1252,0,1,'Pri vlečení motorového vozidla sa smie jazdiť rýchlosťou najviac','',2,1,'60 km/h,','70 km/h,','80 km/h.');
INSERT INTO `Questions` VALUES (1253,1253,0,1,'Preprava osôb je zakázaná','',2,2,'v ložnom priestore nákladného prívesu traktora,','v inom prípojnom vozidle ako vo vozidle, ktoré je určené na prepravu osôb s výnimkou Iožného priestoru nákladného prívesu traktora,','v kabíne vodiča nákladného automobilu.');
INSERT INTO `Questions` VALUES (1254,1254,0,1,'Nákladný automobil, v ktorého ložnom priestore sa prepravuje viac ako šesť osôb, smie viesť len vodič starší ako','',2,2,'23 rokov, ktorý má vo vedení vozidiel najmenej trojročnú prax,','21 rokov, ktorý má vo vedení nákladného automobilu najmenej dvojročnú prax,','25 rokov, ktorý sa podrobil špecializovanej príprave.');
INSERT INTO `Questions` VALUES (1255,1255,0,1,'Denný čas vedenia motorového vozidla nesmie presiahnuť','',1,3,'desať hodín, pričom tento čas možno trikrát v týždni predĺžiť na dvanásť hodín,','osem hodín, pričom tento čas možno dvakrát v týždni predĺžiť na deväť hodín,','deväť hodín, pričom tento čas možno dvakrát v týždni predĺžiť na desať hodín.');
INSERT INTO `Questions` VALUES (1256,1256,0,1,'Povinnou výbavou motorového vozidla kategórie M, N, T a C je','',1,1,'homologizovaný prenosný výstražný trojuholník,','náhradný stierač,','najmenej desaťlitrová zásoba pohonných hmôt v osobitnej nádobe; to neplatí pre jednostopové motorové vozidlá.');
INSERT INTO `Questions` VALUES (1257,1257,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,2,'nie je funkčné počítadlo prejdenej vzdialenosti,','niektorá časť systému, komponentu alebo samotnej technickej jednotky vozidla je chybná, poškodená alebo upravená, prípadne chýba úplne,','je katalyzátor po lehote kalibrácie.');
INSERT INTO `Questions` VALUES (1258,1258,1,1,'Táto dopravná značka upozorňuje na','a3b',2,1,'miesto, kde stúpanie cesty presahuje 10 % alebo kde miestne podmienky robia stúpanie nebezpečným,','miesto, kde priečny sklon vozovky presahuje 10 %,','priklonenú strmú stráň sprava.');
INSERT INTO `Questions` VALUES (1259,1259,1,1,'Tieto dopravné značky upozorňujú na','spec31',2,1,'železničné priecestie so závorami vo vzdialenosti 240 m,','železničné priecestie so závorami vo vzdialenosti 180 m,','železničné priecestie bez závor vo vzdialenosti 200 m.');
INSERT INTO `Questions` VALUES (1260,1260,1,1,'Táto dopravná značka znamená:','b23',2,1,'Zákaz vjazdu vozidiel, ktorých šírka presahuje vyznačenú hranicu; pritom je rozhodujúca okamžitá šírka vrátane nákladu,','Zákaz státia vozidiel, ktorých šírka presahuje vyznačenú hranicu; pritom je rozhodujúca okamžitá šírka vrátane nákladu,','Zákaz vjazdu vozidiel užších ako 2,5 m.');
INSERT INTO `Questions` VALUES (1261,1261,1,1,'Táto dopravná značka znamená:','ip22b',2,1,'Koniec rýchlostnej cesty,','Koniec parkoviska,','Koniec vyhradeného jazdného pruhu.');
INSERT INTO `Questions` VALUES (1262,1262,1,1,'Táto dopravná značka znamená:','is39',2,3,'Smerová tabuľa k turistickému cieľu,','Hranica kraja,','Hranica štátu.');
INSERT INTO `Questions` VALUES (1263,1263,1,1,'Táto dopravná značka znamená:','is36c',2,1,'Miestna časť obce,','Smerová tabuľa ku komunálnemu cieľu,','Smerová tabuľa k inému cieľu.');
INSERT INTO `Questions` VALUES (1264,1264,1,1,'Táto dopravná značka vyznačuje','v13',2,2,'šikmý priechod pre chodcov,','priestor, do ktorého je zakázané vchádzať alebo doň nákladom zasahovať, ak to nie je potrebné na obchádzanie, odbočovanie na miesto ležiace mimo cesty alebo na vchádzanie na cestu z miesta ležiaceho mimo cesty,','priestor, do ktorého je zakázané vchádzať, ak to nie je potrebné na otáčanie vozidiel na križovatke.');
INSERT INTO `Questions` VALUES (1265,1265,1,1,'Takéto označenie sa môže použiť na vozidle','o1',2,1,'vedenom osobou sluchovo postihnutou,','patriacom telekomunikáciám,','vedenom osobou s ťažkým zdravotným postihnutím.');
INSERT INTO `Questions` VALUES (1266,1266,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','159',3,1,'1. červené vojde do križovatky a dá prednosť v jazde protiidúcemu modrému, 2. zelené, 3. modré, 4. červené dokončí odbočovanie vľavo,','1. červené, 2. modré, 3. zelené,','1. modré, 2. červené, 3. zelené.');
INSERT INTO `Questions` VALUES (1267,1267,2,1,'Tento pokyn policajta znamená „Stoj!“ pre vodiča','349',3,1,'zeleného a vodiča čierneho vozidla,','modrého a vodiča červeného vozidla,','modrého a vodiča žltého vozidla.');
INSERT INTO `Questions` VALUES (1268,1268,2,1,'Ako posledné prejde cez križovatku','485',3,1,'červené vozidlo,','vaše vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (1269,1269,2,1,'Vaše vozidlo prejde cez križovatku ako','323',3,2,'druhé,','prvé,','posledné.');
INSERT INTO `Questions` VALUES (1270,1270,0,1,'Vozovkou sa rozumie','',2,1,'spevnená časť cesty určená predovšetkým na premávku motorových vozidiel,','nespevnená časť cesty určená len na premávku nemotorových vozidiel,','cesta vrátane krajnice a chodníka.');
INSERT INTO `Questions` VALUES (1271,1271,0,1,'Ak vodič autobusu alebo trolejbusu vychádza z vyhradeného jazdného pruhu do priľahlého jazdného pruhu, vodič jazdiaci v tomto pruhu','',2,2,'je povinný vždy zastaviť vozidlo,','je povinný dať mu prednosť vjazde,','nie je povinný mu to umožniť.');
INSERT INTO `Questions` VALUES (1272,1272,0,1,'Ak ide vozidlo vo vyhradenom jazdnom pruhu inou rýchlosťou ako ostatné vozidlá idúce rovnakým smerom,','',2,3,'ide o vzájomné predchádzanie,','ide o vzájomné predchádzanie, ak vozidlá vo vyhradenom jazdnom pruhu jazdia rýchlejšie ako ostatné vozidlá,','nejde o vzájomné predchádzanie.');
INSERT INTO `Questions` VALUES (1273,1273,0,1,'Vodič autobusu s prípojným vozidlom, ktorého najväčšia prípustné hmotnosť prevyšuje 750 kg a vodič motorového vozidla s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg, smú jazdiť rýchlosťou najviac','',2,3,'70 km/h,','110km/h,','90 km/h.');
INSERT INTO `Questions` VALUES (1274,1274,0,1,'Vodič je povinný za vozidlom idúcim pred nim','',2,2,'jazdiť vo vzdialenosti najmenej 40 m,','dodržiavať takú vzdialenosť, aby mohol včas znížiť rýchlosť jazdy, prípadne zastaviť vozidlo, ak vodič vozidla jazdiaceho pred ním zníži rýchlosť jazdy alebo zastaví,','dodržiavať takú vzdialenosť, aby zreteľne videl v ňom sediace osoby.');
INSERT INTO `Questions` VALUES (1275,1275,0,1,'Vodič nesmie zastaviť a stáť','',2,2,'v žiadnej zákrute a v jej tesnej blízkosti,','v neprehľadnej zákrute a v jej tesnej blízkosti,','v neprehľadnej zákrute a v žiadnej zákrute v obci.');
INSERT INTO `Questions` VALUES (1276,1276,0,1,'Vodič sa nesmie otáčať a cúvať','',2,1,'na križovatke s riadenou premávkou; otáčať sa smie, ak to dovoľuje dopravná značka alebo dopravné zariadenie,','na žiadnej križovatke,','na parkovisku.');
INSERT INTO `Questions` VALUES (1277,1277,0,1,'Ak je už vidieť alebo počuť prichádzajúci vlak alebo iné dráhové vozidlo, alebo ak je počuť najmä jeho húkanie alebo pískanie, vodič','',2,1,'nesmie vchádzať na železničné priecestie,','smie vchádzať na železničné priecestie, ak nie je dávaná výstraha dvoma červenými striedavo prerušovanými svetlami,','môže vchádzať na železničné priecestie, ak ide o nákladný vlak.');
INSERT INTO `Questions` VALUES (1278,1278,0,1,'Ak vozidlo nie je vybavené smerovými svietidlami alebo ak majú poruchu, dáva sa znamenie o zmene smeru jazdy','',2,2,'predpažením; zapažením sa dáva znamenie o zmene smeru jazdy na opačnú stranu,','upažením; rukou ohnutou v Iakti hore sa dáva znamenie o zmene smeru jazdy na opačnú stranu,','mimo obce svetelným výstražným znamením a v obci zvukovým výstražným znamením počas celého jazdného úkonu.');
INSERT INTO `Questions` VALUES (1279,1279,0,1,'Činná plocha svetlometov a svietidiel','',2,1,'nesmie byť zakrytá alebo nadmerne znečistená s výnimkou svetlometov a svietidiel, ktoré nie sú predpísané,','môže byť čiastočne zakrytá prepravovaným nákladom,','môže byť nadmerne znečistená za hmly, sneženia alebo za dažďa.');
INSERT INTO `Questions` VALUES (1280,1280,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza a v období od novembra do marca môže vodič motorového vozidla kategórie M2, M3, N2 a N; použiť takéto vozidlo v cestnej premávke, len ak','',2,3,'je držiteľom medzinárodnej poisťovacej karty,','je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené aspoň na jednej z hnacích náprav zimnými pneumatikami.');
INSERT INTO `Questions` VALUES (1281,1281,0,1,'Vodič autobusu prepravujúceho deti alebo osoby so zdravotným postihnutím je povinný počas ich nastupovania a vystupovania','',2,3,'dávať svetelné výstražné znamenie prerušovaným zapínaním stretávacích svetlometov alebo diaľkových svetlometov','dávať zvukové výstražné znamenie,','použiť osobitné zariadenie umožňujúce výstražnú funkciu smerových svietidiel.');
INSERT INTO `Questions` VALUES (1282,1282,0,1,'Týždenný čas jazdy','',1,1,'nesmie presiahnuť 56 hodín,','nesmie presiahnuť 40 hodín,','nesmie presiahnuť 48 hodín.');
INSERT INTO `Questions` VALUES (1283,1283,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'nie je oje na pripojenom návese k vozidlu zaistené reťazou dlhou najmenej 1,0 m a najviac 1,5 m,','dodatočne namontované schválené svetelné zariadenia narúšajú výhľad z miesta spolujazdca,','vôľa riadenia je väčšia, než je prípustné alebo je niektorá zo súčastí riadenia poškodená natoľko, že to spôsobuje jeho nespoľahlivú činnosť.');
INSERT INTO `Questions` VALUES (1284,1284,0,1,'Povinnou výbavou motorového vozidla kategórie M, N, T a C je','',1,1,'homologizovaný prenosný výstražný trojuholník,','krieda na vyznačenie postavenia vozidiel po dopravnej nehode,','najmenej dvojlitrová zásoba maziva v osobitnej nádobe; to neplatí pre jednostopové motorové vozidlá.');
INSERT INTO `Questions` VALUES (1285,1285,1,1,'Táto dopravná značka znamená:','a2a',2,1,'Dvojitá zákruta, prvá vpravo,','Spôsob obchádzania prekážky,','Nebezpečenstvo šmyku.');
INSERT INTO `Questions` VALUES (1286,1286,1,1,'Táto dopravná značka znamená:','a11',2,2,'Zákaz státia na krajnici,','Odletujúci štrk,','Nebezpečenstvo poškodenia pneumatík.');
INSERT INTO `Questions` VALUES (1287,1287,1,1,'Táto dopravná značka','a23',2,1,'upozorňuje na úsek cesty, kde sa vytvárajú kolóny vozidiel, najmä pri veľkej intenzite premávky v dlhých stúpaniach, na horských priechodoch a podobne,','zakazuje predchádzanie vozidiel idúcich v kolóne,','zakazuje súbežnú jazdu osobným motorovým vozidlám.');
INSERT INTO `Questions` VALUES (1288,1288,1,1,'Táto dopravná značka znamená:','is38',2,2,'Hranica kraja,','Hraničný priechod,','Hranica štátu.');
INSERT INTO `Questions` VALUES (1289,1289,1,1,'Táto dopravná značka','is35',2,1,'informuje o názve rieky, pohoria, prírodnej rezervácie, kultúrnej a historickej pamiatky, časti obce, územia a podobne,','je návesťou pred križovatkou,','je smerovou tabuľou s diaľkovým cieľom.');
INSERT INTO `Questions` VALUES (1290,1290,1,1,'Táto dodatková tabuľka vyznačuje','e2',2,3,'dĺžku úseku, pre ktorý platí značka, pod ktorou je tabuľka umiestnená,','vzdialenosť od začiatku cesty,','vzdialenosť k miestu, od ktorého platí značka, pod ktorou je tabuľka umiestnená.');
INSERT INTO `Questions` VALUES (1291,1291,1,1,'Ak sú touto značkou oddelené jazdné pruhy s protismernou premávkou,','v3',2,1,'vodič sa riadi významom pravej čiary z tejto dvojice čiar,','vodič sa riadi významom ľavej čiary z tejto dvojice čiar,','riadi sa premávka v jazdných pruhoch svetelnými signálmi.');
INSERT INTO `Questions` VALUES (1292,1292,1,1,'Táto dopravná značka','v8b',2,2,'je návesťou pred priechodom pre cyklistov,','vyznačuje na cestičke pre cyklistov určený smer jazdy cyklistov,','vyznačuje priechod pre cyklistov.');
INSERT INTO `Questions` VALUES (1293,1293,2,1,'V poradí druhé prejde okolo prekážky','214',3,2,'červené vozidlo,','modré vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (1294,1294,2,1,'Červené vozidlo prejde cez križovatku ako','78',3,1,'druhé,','prvé.','posledné.');
INSERT INTO `Questions` VALUES (1295,1295,2,1,'Ako posledné prejde cez križovatku','377',3,1,'vaše vozidlo,','modré vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (1296,1296,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','621',3,3,'1. vaše vozidlo, 2 .električka č. 1 súčasne s električkou č. 2, 3. zelené,','1. zelené, 2. električka č. 1 súčasne s električkou č. 2, 3. vaše vozidlo,','1. vaše vozidlo súčasne so zeleným, 2. električka č. 1 súčasne s električkou č. 2.');
INSERT INTO `Questions` VALUES (1297,1297,0,1,'Chodcom sa rozumie účastník cestnej premávky pohybujúci sa pešo; chodcom je aj','',2,2,'pohonič záprahového vozidla a osoba, ktorá tlačí alebo ťahá ručný vozík s celkovou dĺžkou nepresahujúcou 150 cm,','osoba, ktorá tlačí alebo ťahá ručný vozík s celkovou šírkou nepresahujúcou 600 mm,','vodič každého nemotorového vozidla, ktoré sa pohybuje rýchlosťou menšou ako 30 km.h''1.');
INSERT INTO `Questions` VALUES (1298,1298,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza a v období od novembra do marca môže vodič motorového vozidla kategórie M2, M3, N2 a N3','',2,1,'je toto vybavené aspoň na jednej z hnacích náprav zimnými pneumatikami,','je toto vybavené na všetkých nápravách zimnými pneumatikami, použiť takéto vozidlo v cestnej premávke, len ak','je držiteľom medzinárodnej poisťovacej karty.');
INSERT INTO `Questions` VALUES (1299,1299,0,1,'Vodič nesmie zastaviť a stáť vo vzdialenosti kratšej ako 5 m od začiatku a 5 m od konca pozdĺžnej súvislej čiary alebo nástupného ostrovčeka tam, kde by medzi touto čiarou alebo nástupným ostrovčekom a vozidlom nezostal voľný aspoň jeden jazdný pruh širok','',2,2,'2,5 m,','3 m,','2 m.');
INSERT INTO `Questions` VALUES (1300,1300,0,1,'Pri poruche osvetlenia alebo inej poruche nedovoľujúcej použitie osvetlenia, musia byť na vlečenom vozidle za zníženej viditeľnosti rozsvietené svietidlá','',2,1,'na strane k stredu vozovky vpredu bielym neoslňujúcim svetlom a vzadu aspoň jedným červeným svetlom,','jedným červeným svetlom vpredu aj vzadu,','vo vnútri vozidla.');
INSERT INTO `Questions` VALUES (1301,1301,0,1,'Vodič motorového vozidla nesmie predchádzať iné motorové vozidlo na diaľnici,','',2,2,'ak by pri predchádzaní musel podstatne zvýšiť rýchlosť jazdy,','ak by pri predchádzaní svojou výrazne nižšou rýchlosťou obmedzil iné motorové vozidlo idúce po diaľnici,','ak nemá rozhľad na vzdialenosť 200 metrov.');
INSERT INTO `Questions` VALUES (1302,1302,0,1,'Ak sa vodič motorového vozidla, ktoré je povinne vybavené bezpečnostným odevom, zdržiava na vozovke mimo vozidla počas núdzového státia, najmä pri prerušení jazdy pre chybu na vozidle alebo v dôsledku dopravnej nehody, je povinný','',2,2,'umiestniť 20 m za vozidlo biele neoslňujúce svetlo bielej farby,','mať bezpečnostný odev oblečený,','bezodkladne privolať odťahovú službu.');
INSERT INTO `Questions` VALUES (1303,1303,0,1,'Ak je nevyhnutné upozorniť ostatných účastníkov cestnej premávky na hroziace nebezpečenstvo, najmä v prípadoch, keď je potrebné náhle znížiť rýchlosť jazdy alebo zastaviť vozidlo,','',2,1,'dáva vodič svetelné výstražné znamenie zapnutím výstražnej funkcie smerových svietidiel,','použije vodič zvukové výstražné znamenie,','dáva vodič svetelné výstražné znamenie prerušovaným zapínaním predných svetlometov do hmly.');
INSERT INTO `Questions` VALUES (1304,1304,0,1,'Náklad musí byť na vozidle riadne umiestnený, rozložený a upevnený, aby','',2,1,'nezakrýval svetlomety a svietidlá vozidla, odrazové sklá, tabuľku s evidenčným číslom a vyznačenie najvyššej povolenej rýchlosti,','môže zakrývať svetlomety a svietidlá vozidla, odrazové sklá, tabuľku s evidenčným číslom len pri jazde na účelovej komunikácii a miestnej komunikácii,','môže zakrývať svetlomety a svietidlá vozidla a tabuľku s evidenčným číslom, ak sa na vozidle prepravujú poľnohospodárske produkty.');
INSERT INTO `Questions` VALUES (1305,1305,0,1,'Účastník dopravnej nehody je povinný ohlásiť','',2,1,'dopravnú nehodu policajtovi,','dopravnú nehodu správcovi cesty,','dopravnú nehodu policajtovi len vtedy, ak pri dopravnej nehode došlo k zraneniu osoby.');
INSERT INTO `Questions` VALUES (1306,1306,0,1,'Motorové vozidlo musí mať počas jazdy rozsvietené','',2,1,'stretávacie svetlomety alebo im na roveň postavené osvetlenie,','diaľkové svetlomety,','svetlá vo vnútri vozidla.');
INSERT INTO `Questions` VALUES (1307,1307,0,1,'V obytnej zóne a pešej zóne je státie vozidiel','',2,3,'zakázané len na chodníku,','povolené na akomkoľvek mieste na ceste,','zakázané, ak dopravnou značkou nie je určené inak.');
INSERT INTO `Questions` VALUES (1308,1308,0,1,'Ak situácia na železničnom priecestí alebo za ním nedovoľuje, aby ho bezpečne prešiel a pokračoval v jazde, vodič','',2,3,'smie zastaviť na železničnom priecestí,','smie vojsť na železničné priecestie len, ak nie je vidieť prichádzať dráhové vozidlo,','nesmie vchádzať na železničné priecestie.');
INSERT INTO `Questions` VALUES (1309,1309,0,1,'Doba skráteného denného odpočinku','',1,1,'je akákoľvek doba odpočinku trvajúca najmenej 9 hodín, avšak menej ako 11 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 9 hodín, avšak menej ako 12 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 10 hodín, avšak menej ako 9 hodín.');
INSERT INTO `Questions` VALUES (1310,1310,0,1,'Ak pneumatika alebo disk kolesa je nadmerne poškodený','',1,1,'považuje sa takéto vozidlo za nespôsobilé na premávku na pozemných komunikáciách,','možno s takýmto vozidlom jazdiť iba rýchlosťou neprevyšujúcou 60 km/h,','možno také vozidlo používať len na účelových komunikáciách.');
INSERT INTO `Questions` VALUES (1311,1311,0,1,'Povinnou výbavou motorového vozidlo s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg a prípojného vozidla s najväčšou prípustnou hmotnosťou prevyšujúcou 750 kg je','',1,2,'najmenej dvojlitrová zásoba mazivá v osobitnej nádobe,','aspoň jeden zakladací klin, ktorý účinne zabezpečí vozidlo proti samovoľnému pohybu,','dvojica diaľkových svetlometov natáčavých súčasne s riadiacim mechanizmom vozidla.');
INSERT INTO `Questions` VALUES (1312,1312,1,1,'Táto dopravná značka upozorňuje na','a4b',2,1,'miesto, kde je zúžená vozovka (z jednej strany), kde sa približuje koľaj električky k chodníku a podobne,','pripájací jazdný pruh,','miesto, kde sa znižuje počet jazdných pruhov z jednej strany.');
INSERT INTO `Questions` VALUES (1313,1313,1,1,'Táto dopravná značka znamená:','a5',2,2,'Tunel,','Nerovnosť vozovky,','Zdvíhací most.');
INSERT INTO `Questions` VALUES (1314,1314,1,1,'Táto dopravná značka upozorňuje na','p4',2,1,'križovatku, kde nie je prednosť vjazde upravená značkami,','železničné priecestie bez závor,','kríženie cesty s električkovým koľajovým pásom.');
INSERT INTO `Questions` VALUES (1315,1315,1,1,'Táto dopravná značka upozorňuje na','a28b',2,2,'železničné priecestie vo vzdialenosti 90 m,','železničné priecestie vo vzdialenosti 160 m,','sklon vozovky vľavo.');
INSERT INTO `Questions` VALUES (1316,1316,1,1,'Táto dopravná značka znamená:','ip23b',2,1,'Koniec diaľnice,','Koniec hlavnej cesty,','Zákaz otáčania sa na diaľnici.');
INSERT INTO `Questions` VALUES (1317,1317,1,1,'Táto dopravná značka','is13',2,2,'informuje o uzávierke cesty,','informuje o obmedzení premávky za najbližšou križovatkou a o smere jeho obchádzania,','vyznačuje obmedzenie v jazdnom pruhu.');
INSERT INTO `Questions` VALUES (1318,1318,1,1,'Táto dopravná značka znamená:','is28',2,2,'Cesta l. triedy,','Rýchlostná cesta,','Medzinárodná trasa.');
INSERT INTO `Questions` VALUES (1319,1319,1,1,'Táto zábrana vyznačuje','z2a',2,1,'uzávierku celej šírky cesty,','uzávierku časti šírky cesty,','trvalú prekážku na ceste.');
INSERT INTO `Questions` VALUES (1320,1320,2,1,'Ako prvé prejde cez križovatku','510',3,2,'červené vozidlo,','zelené vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (1321,1321,2,1,'Tento pokyn policajta znamená','403',3,1,'„Voľno“ pre vodiča červeného a vodiča modrého vozidla a „Stoj!“ pre vodiča žltého vozidla; vodič zeleného vozidla smie odbočiť vpravo,','„Voľno“ pre vodiča zeleného a vodiča žltého vozidla a „Stoj!“ pre vodiča modrého a vodiča červeného vozidla,','„Voľno“ pre vodiča červeného a vodiča žltého vozidla a „Stoj!“ pre vodiča modrého a vodiča zeleného vozidla.');
INSERT INTO `Questions` VALUES (1322,1322,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','269',3,2,'1. zelené, 2. modré, 3. vaše vozidlo,','1. modré, 2. vaše vozidlo, 3. zelené,','1. modré, 2. zelené, 3. vaše vozidlo.');
INSERT INTO `Questions` VALUES (1323,1323,2,1,'V poradí druhé prejde cez križovatku','486',3,2,'žlté vozidlo,','vaše vozidlo,','červené vozidlo.');
INSERT INTO `Questions` VALUES (1324,1324,0,1,'Križovatkou sa rozumie','',2,2,'miesto, v ktorom cesta mení smer,','miesto, v ktorom sa cesty pretínajú alebo spájajú,','mimoúrovňové kríženie cesty so železnicou.');
INSERT INTO `Questions` VALUES (1325,1325,0,1,'Ak vozidlo vrátane nákladu alebo jeho upevnenia nespĺňa ustanovené podmienky, prevádzkovateľ vozidla','',2,2,'so súhlasom vodiča môže dovoliť, aby sa použilo na jazdu,','nesmie prikázať ani dovoliť, aby sa použilo na jazdu,','môže prikázať, aby sa použilo na jazdu len v obci.');
INSERT INTO `Questions` VALUES (1326,1326,0,1,'Vodič odbočujúci vľavo je povinný dať prednosť V jazde','',2,3,'len protiidúcim vozidlám,','vozidlám idúcim v oboch smeroch,','protiidúcim motorovým vozidlám i nemotorovým vozidlám, električkám idúcim v oboch smeroch a chodcom prechádzajúcim cez vozovku.');
INSERT INTO `Questions` VALUES (1327,1327,0,1,'Vodič môže zastaviť a stáť na','',2,1,'účelovej komunikácii,','moste,','električkovom koľajovom páse.');
INSERT INTO `Questions` VALUES (1328,1328,0,1,'Ak je nevyhnutné upozorniť ostatných účastníkov cestnej premávky na hroziace nebezpečenstvo, najmä v prípadoch, keď je potrebné náhle znížiť rýchlosť jazdy alebo zastaviť vozidlo,','',2,3,'dáva vodič svetelné výstražné znamenie prerušovaným zapínaním predných svetlometov do hmly,','použije vodič zvukové výstražné znamenie,','dáva vodič svetelné výstražné znamenie zapnutím výstražnej funkcie smerových svietidiel.');
INSERT INTO `Questions` VALUES (1329,1329,0,1,'Vodič nesmie predchádzať, ak','',2,2,'pred ním jazdí zvláštne motorové vozidlo,','by pri predchádzaní svojou výrazne nižšou rýchlosťou obmedzil za nim idúce vozidlo, ktoré začalo úkon predchádzania skôr,','na to v obci neupozornil vodiča predchádzaného vozidla zvukovým výstražným znamením.');
INSERT INTO `Questions` VALUES (1330,1330,0,1,'Náklad musí byť na vozidle riadne umiestnený, rozložený a upevnený, aby','',2,3,'neohrozoval bezpečnosť cestnej premávky a nepoškodzoval cestu; spôsobovať nadmerný hluk nesmie len v nočnej dobe,','neobmedzoval plynulosť cestnej premávky; ak by pritom poškodzoval cestu alebo spôsoboval nadmerný hluk, môže vozidlo isť rýchlosťou najviac 40 km.h''1,','neohrozoval bezpečnosť a plynulosť cestnej premávky, neznečisťoval ani nepoškodzoval cestu ani jej okolie, nespôsoboval nadmerný hluk a neznečisťoval ovzdušie.');
INSERT INTO `Questions` VALUES (1331,1331,0,1,'Vodič motorového vozidla, ktoré je povinne vybavené bezpečnostným odevom, je povinný mať oblečený bezpečnostný odev, ak sa zdržiava','',2,3,'na parkovisku za zníženej viditeľnosti,','na čerpacej stanici,','na vozovke mimo vozidla počas núdzového státia, najmä pri prerušení jazdy pre chybu na vozidle alebo v dôsledku dopravnej nehody.');
INSERT INTO `Questions` VALUES (1332,1332,0,1,'Osoba, ktorá vykonáva na ceste prácu spojenú s jej údržbou, opravou alebo výstavbou, alebo inú pracovnú činnosť, na ktorú je oprávnená,','',2,2,'nemusí dodržiavať žiadne ustanovenia pravidiel cestnej premávky,','nemusí dodržiavať tie ustanovenia pravidiel cestnej premávky, pri ktorých to povaha vykonávanej práce vylučuje,','musí vždy dodržiavať všetky ustanovenia pravidiel cestnej premávky.');
INSERT INTO `Questions` VALUES (1333,1333,0,1,'Vodič je povinný bezodkladne vypnúť motor, a ak je na vykurovanie vozidla použité nezávislé kúrenie, vypnúť aj toto kúrenie, ak','',2,1,'pri jazde vozidla v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným,','vodič zastavil na parkovisku,','zastavil vozidlo pred železničným priecestím, kde sa dáva výstraha dvoma červenými striedavo prerušovanými svetlami priecestného zabezpečovacieho zariadenia.');
INSERT INTO `Questions` VALUES (1334,1334,0,1,'Ak je nesúlad medzi zvislými dopravnými značkami a vodorovnými dopravnými značkami,','',2,1,'zvislé dopravné značky sú nadradené vodorovným dopravným značkám,','vodorovné dopravné značky sú nadradené zvislým dopravným značkám,','účastník cestnej premávky je povinný oznámiť to príslušnému úradu.');
INSERT INTO `Questions` VALUES (1335,1335,0,1,'Policajt v rovnošate dáva z idúceho vozidla znamenie na zastavenie vozidla','',2,2,'striedavým zapínaním diaľkových a tlmených svetlometov,','kývaním ruky hore a dolu alebo vysunutým zastavovacím terčom, prípadne rozsvietením nápisu STOP umiestneného na vozidle,','zvukovým výstražným zariadením alebo zvláštnymi výstražnými svetlami.');
INSERT INTO `Questions` VALUES (1336,1336,0,1,'Doba pravidelného týždenného odpočinku','',1,1,'je akákoľvek doba odpočinku trvajúca najmenej 45 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 40 hodín,','je akákoľvek doba odpočinku trvajúca najmenej 50 hodín.');
INSERT INTO `Questions` VALUES (1337,1337,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'nie je vybavené aspoň jedným hľadacím svetlometom so svetlom bielej farby,','nie je funkčný spínač umožňujúci zapnutie vnútorného osvetlenia vozidla,','niektoré svetelné zariadenie dôležité pre bezpečnosť cestnej premávky chýba alebo je nesprávne umiestnené, nesvieti alebo nespĺňa ustanovené podmienky, takže hrozí bezprostredné nebezpečenstvo.');
INSERT INTO `Questions` VALUES (1338,1338,0,1,'Povinnou výbavou motorového vozidla kategórie M a N sú','',1,3,'protisklzové reťaze,','prostriedky na bezdemontážnu opravu prevádzkovej brzdy,','náhradné elektrické poistky, ak sa v elektrickej inštalácii používajú, a to po jednej z každého používaného druhu.');
INSERT INTO `Questions` VALUES (1339,1339,1,1,'Táto dopravná značka zakazuje vjazd','b6',2,1,'nákladných automobilov vrátane ťahača prívesu, ťahača návesu a špeciálnych automobilov odvodených od nákladného automobilu alebo od autobusu; nezakazuje však vjazd obytným automobilom a nákladným motorovým vozidlám s najvyššou prípustnou celkovou hmotnosť','automobilov s najvyššou prípustnou celkovou hmotnosťou neprevyšujúcou 3 500 kg,','všetkých motorových vozidiel.');
INSERT INTO `Questions` VALUES (1340,1340,1,1,'Táto dopravná značka znamená:','b30b',2,1,'Koniec zákazu predchádzania pre nákladné automobily,','Koniec zákazu predchádzania pre osobné automobily,','Zákaz státia nákladných automobilov v protismere.');
INSERT INTO `Questions` VALUES (1341,1341,1,1,'Táto dopravná značka znamená:','c6a',2,2,'Príkaz na otáčanie,','Prikázaný smer obchádzania vpravo,','Nebezpečné klesanie.');
INSERT INTO `Questions` VALUES (1342,1342,1,1,'Táto dopravná značka znamená:','c7',2,2,'Jednosmerná premávka,','Kruhový objazd; značka prikazuje jazdu po kruhovom objazde v smere šípok zobrazených na značke,','Obchádzka.');
INSERT INTO `Questions` VALUES (1343,1343,1,1,'Táto dopravná značka znamená:','ip8',2,3,'Tunel,','Vyjazdené koľaje,','Spomaľovací prah.');
INSERT INTO `Questions` VALUES (1344,1344,1,1,'Táto dopravná značka znamená:','is36b',2,2,'Koniec viacerých zákazov,','Koniec obce,','Koniec obytnej zóny.');
INSERT INTO `Questions` VALUES (1345,1345,1,1,'Táto dopravná značka znamená:','c28',2,1,'Návesť zmeny smeru jazdy,','Prikázaný smer jazdy,','Vyhradené jazdné pruhy.');
INSERT INTO `Questions` VALUES (1346,1346,1,1,'Toto dopravné zariadenie je','z6a',2,3,'zábrana na označenie uzávierky,','vodiaca tabuľa na označenie nebezpečnej zákruty,','prefabrikovaný spomaľovací prah.');
INSERT INTO `Questions` VALUES (1347,1347,2,1,'Vodič modrého vozidla','52',3,2,'má pred vodičom červeného vozidla prednosť, pretože ide v jazdnom pruhu určenom na predchádzanie,','nesmie ohroziť vodiča červeného vozidla jazdiaceho v priebežnom jazdnom pruhu, do ktorého prechádza,','má pred vodičom červeného vozidla prednosť, pretože ide v jazdnom pruhu pre pomalé vozidlá.');
INSERT INTO `Questions` VALUES (1348,1348,2,1,'Červené vozidlo prejde cez križovatku ako','537',3,2,'prvé,','druhé,','posledné.');
INSERT INTO `Questions` VALUES (1349,1349,2,1,'Vaše vozidlo prejde cez križovatku ako','188',3,3,'prvé,','posledné,','druhé.');
INSERT INTO `Questions` VALUES (1350,1350,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','432',3,2,'1. vaše vozidlo, 2. červené, 3. zelené, 4. modré,','1. vaše vozidlo, 2. červené, 3. modré, 4. zelené,','1. červené, 2. vaše vozidlo, 3. zelené, 4. modré.');
INSERT INTO `Questions` VALUES (1351,1351,0,1,'Chodcom sa rozumie účastník cestnej premávky pohybujúci sa pešo; chodcom je aj osoba, ktorá','',2,1,'tlačí bicykel alebo motocykel,','jazdi na bicykli alebo tlačí bicykel alebo motocykel,','jazdi na bicykli alebo na motocykli.');
INSERT INTO `Questions` VALUES (1352,1352,0,1,'Prekážkou cestnej premávky sa rozumie','',2,2,'každé vozidlo, ktoré prepravuje náklad, ktorý presahuje celkovú dĺžku alebo šírku takéhoto vozidla,','všetko, čo môže ohroziť alebo obmedziť jazdu vozidiel a pohyb chodcov; za prekážku cestnej premávky sa nepovažuje vozidlo stojace alebo pomaly sa pohybujúce z dôvodov vyvolaných cestnou premávkou, spojených najmä s údržbou alebo opravou cesty, dopravnou n','každý účastník cestnej premávky, ktorý porušil pravidlá cestnej premávky.');
INSERT INTO `Questions` VALUES (1353,1353,0,1,'Vodič motocykla je počas jazdy povinný vhodným spôsobom chrániť si zrak','',2,1,'najmä okuliarmi alebo ochranným štítom, ak sa tým nezníži bezpečnosť jazdy, najmä v hmle, pri snežení alebo v daždi,','okuliarmi a ochranným štítom za každých okolností,','okuliarmi len pri snežení alebo v daždi.');
INSERT INTO `Questions` VALUES (1354,1354,0,1,'Ak je pri súbežne] jazde v niektorom jazdnom pruhu prekážka cestnej premávky, vodič vozidla idúceho vo voľnom jazdnom pruhu je povinný umožniť','',2,1,'vodičovi prvého vozidla nachádzajúceho sa v jazdnom pruhu, v ktorom je prekážka, jej obídenie, ak ten dáva znamenie o zmene smeru jazdy,','vodičom všetkých vozidiel nachádzajúcich sa v jazdnom pruhu, v ktorom je prekážka cestnej premávky, jej obídenie,','jej obídenie len vodičom vozidiel pravidelnej verejnej dopravy osôb.');
INSERT INTO `Questions` VALUES (1355,1355,0,1,'Ak vodič autobusu alebo trolejbusu vychádza z vyhradeného jazdného pruhu do priľahlého jazdného pruhu, vodič jazdiaci v tomto pruhu','',2,2,'je povinný vždy zastaviť vozidlo,','je povinný mu dať prednosť vjazde,','nie je povinný mu to umožniť.');
INSERT INTO `Questions` VALUES (1356,1356,0,1,'Ak sa vodič nemôže vyhnúť protiidúcej električke vpravo,','',2,2,'nesmie sa jej vyhýbať vľavo,','vyhýba sa jej vľavo,','môže sa na vyhýbanie použiť aj chodník.');
INSERT INTO `Questions` VALUES (1357,1357,0,1,'Vodič sa nesmie otáčať','',2,3,'na ceste l. triedy,','na žiadnej križovatke,','na jednosmernej ceste.');
INSERT INTO `Questions` VALUES (1358,1358,0,1,'Ak pri jazde vozidla v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným, alebo vznikne dopravná nehoda vrátane požiaru, je vodič po zastavení vozidla povinný bezodkladne','',2,2,'opustiť tunel a dopravnú nehodu oznámiť najbližšiemu policajtovi,','vykonať vhodné opatrenia, aby nebola ohrozená bezpečnosť cestnej premávky v tuneli; ak to okolnosti vyžadujú, je oprávnený zastavovať iné vozidlá,','zariadiť odtiahnutie vozidla z tunela.');
INSERT INTO `Questions` VALUES (1359,1359,0,1,'Vodičovi vozidla pravidelnej verejnej dopravy osôb sú vodiči ostatných vozidiel povinní umožniť vyjdenie zo zastávky alebo zo zastávkového pruhu, a to znížením rýchlosti jazdy, prípadne i zastavením vozidla,','',2,2,'mimo obce,','v obci,','v obci aj mimo obce.');
INSERT INTO `Questions` VALUES (1360,1360,0,1,'Ak svieti na priecestnom zabezpečovacom zariadení prerušované biele svetlo, vodič je povinný','',2,1,'50 m pred železničným priecestím a pri jeho prechádzaní jazdiť rýchlosťou najviac 50 km.h''1,','30 m pred železničným priecestím jazdiť rýchlosťou najviac 50 km.h''1,','zastaviť vozidlo.');
INSERT INTO `Questions` VALUES (1361,1361,0,1,'Osoby prepravované v Iožnom priestore nákladného automobilu nesmú počas jazdy stáť, vykláňať sa, nechať vyčnievať predmety z vozidla ani inak ohrozovať bezpečnosť cestnej premávky; dbá na to','',2,1,'osoba, ktorú z prepravovaných osôb určí prevádzkovateľ vozidla alebo vodič,','osoba, ktorú na to poveril orgán Policajného zboru,','vždy osoba, ktorá je z prepravovaných osôb najstaršia.');
INSERT INTO `Questions` VALUES (1362,1362,0,1,'Ak policajt zdvihne ruku alebo predlaktie pravej ruky so smerovkou, znamená tento pokyn','',2,2,'„Stoj!“ pre smer, ku ktorému stojí čelom alebo chrbtom,','„Pozor!“; vodič vozidla idúceho zo smeru, v ktorom bola predtým premávka zastavaná, je povinný pripraviť sa na jazdu; vodič vozidla idúceho v smere, ktorý bol predtým voľný, je povinný zastaviť vozidlo pred hranicou križovatky; ak je už tak blízko, že by ','„Voľno“ pre smer, ku ktorému stoji bokom.');
INSERT INTO `Questions` VALUES (1363,1363,0,1,'Doba denného odpočinku','',1,1,'je akákoľvek denná doba, počas ktorej môže vodič voľne disponovať svojim časom a zahŕňa „dobu pravidelného denného odpočinku" a „dobu skráteného denného odpočinku“,','je akákoľvek denná doba, počas ktorej môže vodič voľne disponovať svojím časom a zahŕňa „dobu pravidelného denného odpočinku",','je akákoľvek denná doba, počas ktorej môže vodič voľne disponovať svojím časom a zahŕňa „dobu skráteného denného odpočinku“.');
INSERT INTO `Questions` VALUES (1364,1364,0,1,'Povinnou výbavou motorového vozidla kategórie M, N, T a C je','',1,1,'homologizovaný prenosný výstražný trojuholník,','prenosné svietidlo svietiace prerušovaným svetlom červenej farby; to platí aj pre jednostopové motorové vozidlá,','krieda na vyznačenie stôp a postavenia vozidla v prípade dopravnej nehody.');
INSERT INTO `Questions` VALUES (1365,1365,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'je zjavne vážne poškodené pruženie,','nie je na čelnom skle zatemňovací pás, ktorý umožňuje najmenej 50 % priepustnosti svetla,','je výhľad z miesta spolujazdca obmedzený alebo znemožnený smerom dozadu viac ako na 50 %.');
INSERT INTO `Questions` VALUES (1366,1366,1,1,'Táto dopravná značka','a7',2,1,'upozorňuje na zníženú, nespevnenú alebo inak nebezpečnú krajnicu,','upozorňuje na zvýšený alebo inak nebezpečný ľavý obrubník,','umožňuje pozdĺžne parkovanie na chodníku na ľavej strane jednosmernej cesty.');
INSERT INTO `Questions` VALUES (1367,1367,1,1,'Táto dopravná značka znamená:','b25',2,1,'Zákaz vjazdu vozidiel, ktorých okamžitá hmotnosť presahuje vyznačenú hranicu; pri jazdnej súprave sa obmedzenie okamžitej hmotnosti vzťahuje na jednotlivé vozidlá súpravy,','Zákaz státia vozidiel, ktorých okamžitá hmotnosť presahuje vyznačenú hranicu,','Zákaz vjazdu jazdných súprav, ktoré majú 6 a viac náprav.');
INSERT INTO `Questions` VALUES (1368,1368,1,1,'Táto dopravná značka znamená:','b34',2,1,'Zákaz zastavenia,','Státie dovolené v párnych dňoch,','Koniec všetkých zákazov.');
INSERT INTO `Questions` VALUES (1369,1369,1,1,'Táto dopravná značka s dodatkovou tabuľkou označuje','spec87',2,2,'miesto kríženia cesty s diaľnicou,','vedľajšiu cestu, vyznačuje skutočný tvar križovatky a aj hlavnú a vedľajšiu cestu,','prikázaný smer jazdy cez križovatku.');
INSERT INTO `Questions` VALUES (1370,1370,1,1,'Táto dopravná značka znamená:','ip2',2,2,'Jednosmerná premávka,','Zmena smeru okruhu,','Prikázaný smer obchádzania.');
INSERT INTO `Questions` VALUES (1371,1371,1,1,'Táto dopravná značka','is6',2,2,'informuje o názvoch najbližších výjazdov z diaľnice a o vzdialenosti k nim,','poskytuje rozšírené informácie o cieľoch v smere odbočenia,','informuje o smere príjazdu na diaľnicu s uvedením cieľa.');
INSERT INTO `Questions` VALUES (1372,1372,1,1,'Táto dopravná značka znamená:','ip33',2,3,'Obmedzenie v jazdných pruhoch,','Odporúčané rýchlosti,','Všeobecné najvyššie dovolené rýchlosti.');
INSERT INTO `Questions` VALUES (1373,1373,1,1,'Táto dopravná značka znamená:','v6a',2,1,'Priechod pre chodcov,','Priechod pre cyklistov,','Priechod pre jazdcov na koni.');
INSERT INTO `Questions` VALUES (1374,1374,2,1,'Zelené vozidlo prejde cez križovatku ako','483',3,3,'tretie,','druhé,','prvé.');
INSERT INTO `Questions` VALUES (1375,1375,2,1,'V poradí druhé prejde cez križovatku','484',3,2,'zelené vozidlo,','červené vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (1376,1376,2,1,'Ako prvé prejde cez križovatku','485',3,3,'červené vozidlo,','vaše vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (1377,1377,2,1,'Ak má policajt pravú ruku predpaženú a ľavú upaženú, znamená to „Stoj" pre','808',3,2,'vodiča zeleného vozidla,','vodiča červeného a vodič a žltého vozidla,','chodcov prechádzajúcich za chrbtom policajta.');
INSERT INTO `Questions` VALUES (1378,1378,0,1,'Križovatkou sa rozumie','',2,1,'miesto, v ktorom sa cesty pretínajú alebo spájajú,','miesto, v ktorom sa cesty pretínajú; za križovatku sa považuje aj vyústenie poľnej cesty a lesnej cesty na inú cestu,','mimoúrovňové kríženie cesty so železnicou.');
INSERT INTO `Questions` VALUES (1379,1379,0,1,'Neohrozením sa rozumie povinnosť vodiča','',2,2,'počínať si tak, aby inému účastníkovi cestnej premávky nijako neprekážal,','počínať si tak, aby inému účastníkovi cestnej premávky nevzniklo nijaké nebezpečenstvo,','neobchádzať ani nepredchádzať vozidlo prepravujúce nebezpečné veci a jazdiť za takýmto vozidlom vo vzdialenosti najmenej 50 m.');
INSERT INTO `Questions` VALUES (1380,1380,0,1,'Osoba sediaca na sedadle vozidla povinne vybavenom bezpečnostným pásom alebo iným zadržiavacím zariadením je povinná toto zariadenie použiť; to neplatí pre','',2,2,'spolujazdca sediaceho na zadnom sedadle vozidla,','osobu, ktorá nemôže byť pripútaná zo zdravotných dôvodov; takáto osoba sa musí preukázať osvedčením o oslobodení od použitia bezpečnostných systémov vozidla,','vodiča počas jazdy v obci.');
INSERT INTO `Questions` VALUES (1381,1381,0,1,'Pozdĺž električky sa jazdí','',2,2,'vľavo, ak nie je dopravnou značkou povolená jazda vpravo,','vpravo, ak nie je dopravnou značkou povolená jazda vľavo,','za každých okolnosti vľavo.');
INSERT INTO `Questions` VALUES (1382,1382,0,1,'Ak vodič autobusu alebo trolejbusu vychádza z vyhradeného jazdného pruhu do priľahlého jazdného pruhu,','',2,3,'nesmie obmedziť vodičov ostatných vozidiel,','nie je povinný dávať znamenie o zmene smeru jazdy,','je povinný dávať znamenie o zmene smeru jazdy.');
INSERT INTO `Questions` VALUES (1383,1383,0,1,'Vodič motorového vozidla i nemotorového vozidla odbočujúci vpravo je povinný dať prednosť v jazde','',2,2,'protiidúcim vozidlám pravidelnej verejnej dopravy osôb, ak tieto odbočujú vľavo,','električke, ak je povolená jazda pozdĺž električky vľavo,','prvému vozidlu idúcemu za nim.');
INSERT INTO `Questions` VALUES (1384,1384,0,1,'Vodič je povinný prenosný výstražný trojuholník umiestniť na okraji vozovky tak, aby ho prichádzajúci vodiči včas a zreteľne videli, a to vo vzdialenosti najmenej','',2,3,'30 m za vozidlom mimo obce,','30 m za vozidlom a na diaľnici a rýchlostnej ceste najmenej 60 m za vozidlom; v obci môže byť táto vzdialenosť, ak to vyžadujú okolnosti, kratšia,','50 m za vozidlom a na diaľnici a rýchlostnej ceste najmenej 100 m za vozidlom; v obci môže byť táto vzdialenosť, ak to vyžadujú okolnosti, kratšia.');
INSERT INTO `Questions` VALUES (1385,1385,0,1,'Vodič nesmie zastaviť a stáť na priechode pre chodcov alebo na priechode pre cyklistov a vo vzdialenosti kratšej ako','',2,3,'5 m za nimi,','5 m pred nim a 5 m za nimi,','5 m pred nimi.');
INSERT INTO `Questions` VALUES (1386,1386,0,1,'Vo vzdialenosti 50 m pred železničným priecestím a pri jeho prechádzaní vodič je povinný jazdiť rýchlosťou najviac','',2,3,'20 km/h,','40 km/h,','30 km/h.');
INSERT INTO `Questions` VALUES (1387,1387,0,1,'Znamenie o zmene smeru jazdy dávané smerovými svietidlami vodič ponechá len v čase, kým','',2,3,'nezačal meniť smer jazdy,','nezačal vybočovať zo smeru jazdy,','mení smer jazdy, vybočuje z neho alebo kým vozidlo nezaujme miesto v jazdnom pruhu, do ktorého prechádza.');
INSERT INTO `Questions` VALUES (1388,1388,0,1,'Osoby mladšie ako 15 rokov sa smú prepravovať v ložnom priestore nákladného automobilu a nákladného prívesu traktora len v sprievode osoby staršej ako','',2,1,'18 rokov,','21 rokov,','23 rokov.');
INSERT INTO `Questions` VALUES (1389,1389,0,1,'Pri riadení cestnej premávky na križovatke znamená pre vodiča signál so žltým svetlom „Pozor!“','',2,2,'povinnosť dať prednosť chodcom prechádzajúcim cez priechod,','povinnosť zastaviť vozidlo pred priečnou súvislou čiarou, a kde taká čiara nie je, pred svetelným signalizačným zariadením; ak je však vozidlo pri rozsvietení tohto signálu už tak blízko, že by vodič nemohol vozidlo bezpečne zastaviť, smie pokračovať v ja','možnosť zastaviť vozidlo pred priechodom pre chodcov, pred priečnou prerušovanou čiarou alebo pred električkovým koľajovým pásom.');
INSERT INTO `Questions` VALUES (1390,1390,0,1,'Doba denného odpočinku','',1,1,'sa môže predĺžiť na dobu pravidelného týždenného alebo na dobu skráteného týždenného odpočinku,','sa môže predĺžiť na dobu skráteného týždenného odpočinku,','sa môže predĺžiť na dobu pravidelného týždenného odpočinku.');
INSERT INTO `Questions` VALUES (1391,1391,0,1,'Povinnou výbavou motorového vozidla kategórie M a N sú','',1,3,'najmenej tri zakladacie kliny pre každú nápravu motorového vozidla,','odrazové sklá oranžovej farby, ktoré je možné umiestniť na vozovku v prípade núdzového státia,','náhradné elektrické poistky, ak sa v elektrickej inštalácii používajú, a to po jednej z každého používaného druhu.');
INSERT INTO `Questions` VALUES (1392,1392,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'je zjavne vážne poškodené pruženie,','sa nedá uviesť do činnosti osvetlenie batožinového priestoru,','je zhodný účinok prevádzkovej brzdy na kolesách tej istej nápravy.');
