INSERT INTO `Questions` VALUES (1397,1397,1,1,'Táto dopravná značka','ii1a',2,3,'upozorňuje vodičov na zákaz telefonovania,','označuje miesto, kde možno dostať najmä turistické informácie,','informuje o mieste, kde je na ceste umiestnený telefón núdzového volania.');
INSERT INTO `Questions` VALUES (1398,1398,1,1,'Táto dopravná značka znamená:','is20a',2,3,'Rýchlostná cesta,','Zákaz vjazdu osobných automobilov,','Smerová tabuľa pre príjazd k rýchlostnej ceste.');
INSERT INTO `Questions` VALUES (1399,1399,1,1,'Táto dopravná značka znamená:','c23a',2,2,'Jazdný pruh vyhradený pre nákladné automobily,','Obmedzenie v jazdných pruhoch,','Prikázaný smer jazdy pre vyznačené vozidlá.');
INSERT INTO `Questions` VALUES (1400,1400,1,1,'Táto dopravná značka','v9a',2,3,'vyznačuje jazdné pruhy vyhradené pre pomalé vozidlá,','je predbežnou značkou pre zmenu smeru jazdy,','vyznačuje spôsob radenia do jazdných pruhov a určený smer jazdy križovatkou.');
INSERT INTO `Questions` VALUES (1401,1401,2,1,'Ako druhé vojde do križovatky','24',3,3,'modré vozidlo,','červené vozidlo,','zelené vozidlo.');
