INSERT INTO `Questions` VALUES (1405,1405,0,1,'zastavením vozidla sa rozumie','',2,2,'každé prerušenie jazdy,','prerušenie jazdy z dôvodu nezávislého od vôle vodiča,','uvedenie motorového vozidla do pokoja na čas nevyhnutne potrebný na urýchlene nastúpenie alebo vystúpenie prepravovaných osôb.');
INSERT INTO `Questions` VALUES (1406,1406,0,1,'Nemotorovým vozidlom sa rozumie','',2,3,'vozidlo pohybujúce sa pomocou ľudskej sily alebo zvieracej sily, električka a trolejbus,','aj motorové vozidlo, ktorého pohotovostné hmotnosť nepresahuje 400 kg,','prípojné vozidlo, vozidlo pohybujúce sa pomocou ľudskej sily alebo zvieracej sily.');
INSERT INTO `Questions` VALUES (1407,1407,0,1,'Mimo obce na ceste s dvoma alebo s viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy sa jazdí','',2,3,'v tom jazdnom pruhu, ktorý vodičovi najviac vyhovuje,','vždy v ľavom jazdnom pruhu; v ostatných jazdných pruhoch sa smie jazdiť len pri predchádzaní,','v pravom jazdnom pruhu; v ostatných jazdných pruhoch sa smie jazdiť, ak je to potrebné na obchádzanie, predchádzanie, otáčanie alebo na odbočovanie.');
INSERT INTO `Questions` VALUES (1408,1408,0,1,'Pri vchádzaní na električkový koľajový pás a pri jeho prechádzaní vodič','',2,2,'môže podľa okolností obmedziť električku vjazde, nesmie ju však ohroziť,','nesmie ohroziť ani obmedziť električku vjazde,','môže prekážať vjazde električke len v rozsahu nevyhnutnom na vykonanie jazdného úkonu.');
INSERT INTO `Questions` VALUES (1409,1409,0,1,'Vodič motorového vozidla s najväčšou prípustnou celkovou hmotnosťou neprevyšujúcou 3 500 kg s prípojným vozidlom, ktorého najväčšia prípustné hmotnosť prevyšuje 750 kg, smie jazdiť rýchlosťou najviac','',2,1,'90 km/h,','110 km/h,','130 km/h.');
INSERT INTO `Questions` VALUES (1410,1410,0,1,'Vodič, ktorý prichádza do križovatky po ceste neoznačenej dopravnou značkou ako vedľajšia cesta alebo ako hlavná cesta, je povinný dať prednosť v jazde vozidlám prichádzajúcim','',2,2,'zľava,','sprava,','po jednosmernej ceste.');
INSERT INTO `Questions` VALUES (1411,1411,0,1,'Vodič nesmie zastaviť a stáť na zastávke vozidla pravidelnej verejnej dopravy osôb v úseku, ktorý sa začína dopravnou značkou pre zastávku a končí sa','',2,2,'20 m za označníkom zastávky,','5 m za označníkom zastávky , a tam, kde taká dopravná značka nie je, vo vzdialenosti kratšej ako 30 m pred označníkom zastávky a 5 m za nim; ak je priestor zastávky vyznačený príslušnou vodorovnou dopravnou značkou, platí tento zákaz len pre nástupište a ','10 m za označníkom zastávky.');
INSERT INTO `Questions` VALUES (1412,1412,0,1,'Ak situácia na železničnom priecestí a za nim nedovoľuje, aby ho bezpečne prešiel a pokračoval vjazde, vodič','',2,2,'smie zastaviť na železničnom priecestí na čas,','nesmie vchádzať na železničné priecestie,','smie vchádzať na železničné priecestie, len ak nie je vidieť prichádzajúce dráhové vozidlo.');
INSERT INTO `Questions` VALUES (1413,1413,0,1,'Vozidlo musí mať počas jazdy rozsvietené','',2,2,'aj za nezníženej viditeľnosti predné svetlomety do hmly a zadné svietidlá do hmly,','stretávacie svetlomety alebo im na roveň postavené osvetlenie,','vnútorné osvetlenie vozidla.');
INSERT INTO `Questions` VALUES (1414,1414,0,1,'Pred vjazdom do priebežných jazdných pruhov na diaľnici vodič','',2,3,'je povinný použiť pripájací jazdný pruh; tam, kde pripájací jazdný pruh nie je, vodič má prednosť v jazde pred vozidlami idúcimi v priebežných jazdných pruhoch,','osobného motorového vozidla nemusí použiť existujúci pripájací jazdný pruh,','je povinný použiť pripájací jazdný pruh; tam, kde pripájací jazdný pruh nie je, vodič je povinný dať prednosť vjazde vozidlám idúcim v priebežných jazdných pruhoch.');
INSERT INTO `Questions` VALUES (1415,1415,0,1,'Vodič vchádzajúci do kruhového objazdu','',2,3,'môže ohroziť vodičov jazdiacich po kruhovom objazde,','má vždy prednosť v jazde,','má prednosť v jazde, ak dopravnou značkou nie je ustanovené inak.');
INSERT INTO `Questions` VALUES (1416,1416,0,1,'Pri riadení cestnej premávky na križovatke znamená pre vodiča signál so zeleným plným kruhovým svetlom „voľno“','',2,3,'povinnosť opustiť križovatku; pritom smie ísť len priamo,','povinnosť zastaviť vozidlo; to neplatí ak ide cez križovatku priamo,','možnosť pokračovať v jazde, a ak dodrží ustanovenia o odbočovaní a také odbočovanie nie je zakázané dopravnou značkou, môže odbočiť” vpravo alebo vľavo.');
INSERT INTO `Questions` VALUES (1417,1417,0,1,'Celkový čas vedenia motorového vozidla nesmie presiahnuť','',1,2,'80 hodín v období dvoch po sebe nasledujúcich týždňov,','90 hodín v období dvoch po sebe nasledujúcich týždňov,','100 hodín v období dvoch po sebe nasledujúcich týždňov.');
INSERT INTO `Questions` VALUES (1418,1418,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'sú prekročené emisné limity motora určené výrobcom,','mazivo používané vo vozidle nie je schválené výrobcom,','nie je vybavené klimatizačným systémom.');
INSERT INTO `Questions` VALUES (1419,1419,0,1,'Povinnou výbavou motorového vozidla kategórie M a N je','',1,1,'bezpečnostný odev (bezpečnostná reflexná vesta, overal, nohavice, bunda alebo pláštenkumiestneným v dosahu zo sedadla vodiča vozidla,','najmenej dvojlitrová zásoba maziva v osobitnej nádoba,','náhradný stierač,');
INSERT INTO `Questions` VALUES (1420,1420,1,1,'Táto dopravná značka','a15',2,2,'zakazuje vstup detí,','upozorňuje na miesto alebo na úsek cesty, na ktorej je zvýšený pohyb detí a kde sa dá predpokladať zvýšené riziko ich neočakávaného vstupu do vozovky, napríklad v blízkosti školy, detského ihriska a podobne,','upozorňuje vopred na miesto, kde sú dovolené hry detí na ceste.');
INSERT INTO `Questions` VALUES (1421,1421,1,1,'Táto dopravná značka upozorňuje na','a29b',2,1,'železničné priecestie vo vzdialenosti 80 m,','železničné priecestie vo vzdialenosti 140 m,','sklon vozovky vpravo.');
INSERT INTO `Questions` VALUES (1422,1422,1,1,'Táto dopravná značka znamená:','b27a',2,1,'Zákaz odbočovania vpravo,','Zákaz otáčania,','Prikázaný smer jazdy vpravo.');
INSERT INTO `Questions` VALUES (1423,1423,1,1,'Táto dopravná značka znamená:','c2',2,2,'Zákruta vpravo.','Prikázaný smer jazdy vpravo,','Jednosmerná premávka.');
INSERT INTO `Questions` VALUES (1424,1424,1,1,'Táto dopravná značka:','ip21a',2,2,'upozorňuje na povinnosť pred vjazdom do tunela zapnúť stretávacie svetlomety,','označuje blízkosť vjazdu do tunela, kde platia pravidlá cestnej premávky pre správanie sa v tuneli,','označuje blízkosť vjazdu do tunela pre Koľajové vozidlá.');
INSERT INTO `Questions` VALUES (1425,1425,1,1,'Táto dopravná značka znamená:','is18a',2,2,'Diaľková návesť,','Smerová tabuľa (s dvoma cieľmi),','Návesť pred križovatkou.');
INSERT INTO `Questions` VALUES (1426,1426,1,1,'Táto dopravná značka znamená:','c24b',2,3,'Zníženie počtu jazdných pruhov,','Koniec zákazu vjazdu autobusom,','Koniec vyhradeného jazdného pruhu.');
INSERT INTO `Questions` VALUES (1427,1427,1,1,'Ak sú touto značkou vyznačené jazdné pruhy v jednom smere jazdy,','v3',2,2,'vodič sa riadi významom vzdialenejšej čiary,','vodič sa riadi významom bližšej čiary,','je zakázané túto značku prechádzať alebo presahovať nákladom.');
INSERT INTO `Questions` VALUES (1428,1428,2,1,'Vodič modrého vozidla','726',3,1,'má pred vodičom červeného vozidla prednosť v jazde, pretože prichádza na križovatku po ceste označenej ako hlavná,','má pred vodičom červeného vozidla prednosť vjazde, pretože ide po kruhovom objazde,','musí dať prednosť v jazde vodičovi červeného vozidla, ktorý prichádza na križovatku sprava.');
INSERT INTO `Questions` VALUES (1429,1429,2,1,'V poradí druhé prejde cez križovatku','105',3,1,'zelené vozidlo,','červené vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (1430,1430,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','242',3,3,'1. červené, 2. modré, 3. vaše vozidlo,','1. vaše vozidlo, 2. červené, 3. modré,','1. modré, 2. vaše vozidlo, 3. červené.');
INSERT INTO `Questions` VALUES (1431,1431,2,1,'Ako posledné prejde cez križovatku','405',3,3,'žlté vozidlo,','zelené vozidlo,','vaše vozidlo.');
INSERT INTO `Questions` VALUES (1432,1432,0,1,'Zníženou viditeľnosťou sa rozumie','',2,1,'viditeľnosť, pri ktorej sa účastníci cestnej premávky dostatočne zreteľne navzájom nevidia, ani Keď nevidia predmety na ceste, najmä od súmraku do svitania, za hmly, sneženia, dažďa a v tuneli,','taká viditeľnosť, keď vodič motorového vozidla z dôvodu znečistenia alebo poškodenia skiel nevidí dostatočne zreteľne ostatných účastníkov cestnej premávky,','viditeľnosť v čase od 18.00 do 7.00 hodiny a od 1. júla do 31. augusta len od 20.00 do 6.00 hodiny.');
INSERT INTO `Questions` VALUES (1433,1433,0,1,'Neobmedzením sa rozumie povinnosť','',2,1,'účastníka cestnej premávky počínať si tak, aby inému účastníkovi cestnej premávky nijako neprekážal,','spolujazdca nerozptyľovať pozornosť vodiča hlasitým hovorom, telefonovaním, pitím nápojov alebo inou obdobnou činnosťou,','vodiča za žiadnych okolností nevyrušovať vodiča predchádzaného vozidla dávaním zvukového výstražného znamenia alebo svetelného výstražného znamenia.');
INSERT INTO `Questions` VALUES (1434,1434,0,1,'Na krajnicu smie vodič motorového vozidla vojsť','',2,1,'len pri zastavení a státí alebo pri obchádzaní a vyhýbaní sa prekážke cestnej premávky,','pri predchádzaní,','vždy, ak je to potrebné na vykonanie akéhokoľvek jazdného úkonu.');
INSERT INTO `Questions` VALUES (1435,1435,0,1,'Ak by vozidlá idúce v obci súčasne vo všetkých jazdných pruhoch bránili vjazde rýchlejšie idúcemu vozidlu,','',2,1,'vodič, ktorý jazdí v ľavom jazdnom pruhu, je povinný tento čo najskôr uvoľniť; to neplatí, ak vodič používa ľavý jazdný pruh na obchádzanie, odbočovanie, otáčanie alebo predchádzania,','vodič, ktorý jazdí v pravom jazdnom pruhu, je povinný tento čo najskôr uvoľniť,','vodiči, ktorí jazdia v ľavom jazdnom pruhu, sú povinní okamžite zastaviť vozidlo.');
INSERT INTO `Questions` VALUES (1436,1436,0,1,'Vodič autobusu smie jazdiť rýchlosťou najviac','',2,1,'90 km/h; na diaľnici a na rýchlostnej ceste smie jazdiť rýchlosťou najviac 100 km/h,','80 km/h; na diaľnici a na rýchlostnej ceste smie jazdiť rýchlosťou najviac 110 km/h,','70 km/h.');
INSERT INTO `Questions` VALUES (1437,1437,0,1,'Vodič, ktorý prichádza do križovatky po vedľajšej ceste označenej dopravnou značkou „Daj prednosť v jazde!" alebo „Stoj, daj prednosť V jazde!",','',2,2,'nie je povinný dať prednosť v jazde vozidlám a ostatným účastníkom cestnej premávky prichádzajúcim po hlavnej ceste,','je povinný dať prednosť vjazde vozidlám prichádzajúcim po hlavnej ceste,','nie je povinný dať prednosť v jazde nemotorovým vozidlám prichádzajúcim po hlavnej ceste.');
INSERT INTO `Questions` VALUES (1438,1438,0,1,'Na pripájacom alebo na odbočovacom pruhu vodič','',2,1,'nesmie zastaviť a stáť,','môže zastaviť a stáť,','môže len zastaviť; nesmie však stáť.');
INSERT INTO `Questions` VALUES (1439,1439,0,1,'Ak osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva znamenie za zníženej viditeľnosti krúžením červeným svetlom v hornom polkruhu, vodič','',2,1,'nesmie vchádzať na železničné priecestie,','smie vchádzať na železničné priecestie,','je povinný vchádzať na železničné priecestie zvýšenou rýchlosťou.');
INSERT INTO `Questions` VALUES (1440,1440,0,1,'Na upozornenie vodiča predchádzaného vozidla v obci vodič smie dávať','',2,3,'zvukové výstražné znamenie,','zvukové výstražné znamenie a svetelné výstražné znamenie,','svetelné výstražné znamenie.');
INSERT INTO `Questions` VALUES (1441,1441,0,1,'Nákladný automobil, v ktorého ložnom priestore sa prepravuje viac ako šesť osôb, smie viesť len vodič starší ako','',2,1,'21 rokov, ktorý má vo vedení nákladného automobilu najmenej dvojročnú prax,','23 rokov, ktorý má vo vedení vozidiel najmenej trojročnú prax,','25 rokov, ktorý sa podrobil špecializovanej príprave.');
INSERT INTO `Questions` VALUES (1442,1442,0,1,'Účastník škodovej udalosti je povinný','',2,1,'preukázať svoju totožnosť inému účastníkovi škodovej udalosti,','oznámiť vznik škodovej udalosti v obci príslušníkovi obecnej polície,','povinný poskytnúť odbornú zdravotnú pomoc osobám zraneným pri škodovej udalosti.');
INSERT INTO `Questions` VALUES (1443,1443,0,1,'Pri riadení cestnej premávky na križovatke znamená pre vodiča signál so zelenou smerovou šípkou alebo signál s kombinovanými zelenými smerovými šípkami rôznych smerov','',2,1,'možnosť pokračovať vjazde len V smere, ktorým uvedená šípka alebo šípky ukazujú,','možnosť pokračovať vjazde ktorýmkoľvek smerom,','povinnosť opustiť križovatku; to neplatí ak ide cez križovatku priamo.');
INSERT INTO `Questions` VALUES (1444,1444,0,1,'Vodič motorového vozidla musí mať po uplynutí štyroch a pol hodiny vedenia motorového vozidla prestávku v práci v trvaní najmenej','',1,1,'45 minút, ak sa nezačína nepretržitý denný odpočinok alebo nepretržitý odpočinok v týždni, pričom prestávku v práci sa môže nahradiť prestávkou trvajúcou najmenej 15 minút, po ktorej nasleduje prestávka trvajúca najmenej 30 minút,','30 minút,','45 minút, ak sa nezačína nepretržitý denný odpočinok alebo nepretržitý odpočinok v týždni.');
INSERT INTO `Questions` VALUES (1445,1445,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, kým sa poruchy neodstránia, ak','',1,1,'niektorá časť systému, komponentu alebo samotnej technickej jednotky vozidla je chybná, poškodená alebo upravená, prípadne chýba úplne,','z miesta vodiča nie je možné nastaviť pravé predné zrkadlo,','nie sú aspoň kolesá prednej nápravy vybavené účinnými krytmi (blatníkmi, podbehmi).');
INSERT INTO `Questions` VALUES (1446,1446,0,1,'Činná plocha pneumatiky v prevádzke musí mať po celom obvode a celej šírke vrchného behúňa dezén s hĺbkou dezénových drážok','',1,3,'u vozidiel kategórie L1 a L2 najmenej 1,5 mm,','u všetkých kategórii vozidiel 1,6 mm,','u vozidiel kategórie L1 a L2 najmenej 1,0 mm.');
INSERT INTO `Questions` VALUES (1447,1447,1,1,'Táto dopravná značka upozorňuje vodiča na','a12',2,1,'miesto, kde je premávke riadená svetelnými signálmi, ktoré by inak neočakával, alebo kde nie sú z dostatočnej vzdialenosti viditeľné,','priechod pre chodcov v obci,','každú križovatku, kde je premávke riadená svetelnými signálmi.');
INSERT INTO `Questions` VALUES (1448,1448,1,1,'Táto dopravná značka označuje','a30b',2,3,'dve železničné priecestie vo vzdialenosti 80 m,','miesto, kde sú v tesnej blízkosti dve križovatky,','c železničné priecestie viackoľejové.');
INSERT INTO `Questions` VALUES (1449,1449,1,1,'Táto dopravná značka zakazuje vodičovi','b29a',2,2,'predchádzať motorové vozidlo vľavo aj vpravo,','predchádzať motorové vozidlo vľavo; motocykel bez postranného vozíka možno predchádzať,','obchádzať akékoľvek vozidlo.');
INSERT INTO `Questions` VALUES (1450,1450,1,1,'Táto dopravná značka zakazuje vodičovi','b37',2,3,'vojsť do takto označeného úseku,','zastaviť v takto označenom úseku,','prejsť takto označeným úsekom bez toho, aby jazdu prerušil (s cieľom naložiť alebo zložiť náklad a podobne)');
INSERT INTO `Questions` VALUES (1451,1451,1,1,'Táto dopravná značka znamená:','c3',2,3,'Jednosmerná premávke,','Zákruta vľavo,','Prikázaný smer jazdy vľavo.');
INSERT INTO `Questions` VALUES (1452,1452,1,1,'Táto dopravná značka znamená:','ip11',2,2,'Odstavná plocha pre vozidla'' s nadrozmerným nákladom,','Núdzová odstavná plocha,','Parkovisko.');
INSERT INTO `Questions` VALUES (1453,1453,1,1,'Táto dopravná značka','c23a',2,1,'vyznačuje obmedzenie platné v príslušnom jazdnom pruhu,','vyznačuje jazdný pruh pre vozidlá podľa ich maximálnej konštrukčnej rýchlosti,','určuje najnižšiu dovolenú rýchlosť, ktorými smú jazdiť vozidlá v príslušnom jazdnom pruhu.');
INSERT INTO `Questions` VALUES (1454,1454,1,1,'Táto dopravná značka znamená:','v10c',2,3,'Zákaz státia,','Zastávka autobusov alebo trolejbusov,','Parkovacie mieste s pozdĺžnym státím.');
INSERT INTO `Questions` VALUES (1455,1455,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','186',3,2,'1. červené, 2.modré, 3. zelené,','1. zelené, 2. modré, 3. červené,','1. zelené, 2. červené, 3. modré.');
INSERT INTO `Questions` VALUES (1456,1456,2,1,'Ako prvé prejde cez križovatku:','537',3,1,'žlté vozidlo,','červené vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (1457,1457,2,1,'Ako posledné prejde cez križovatku','80',3,2,'zelené vozidlo,','vaše vozidlo,','červené vozidlo.');
INSERT INTO `Questions` VALUES (1458,1458,2,1,'Ako prvé prejde cez križovatku','783',3,1,'vaše vozidlo,','červené vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (1459,1459,0,1,'Hranicou križovatky sa rozumie','',2,2,'kolmica na os vozovky vedená stredom priechodu pre chodcov,','miesto vyznačené príslušnou vodorovnou dopravnou značkou; kde takáto vodorovné dopravná značka nie je, hranicu križovatky tvorí kolmica na os vozovky v mieste, kde sa pre križovatku začína zakrivenie vozovky,','kolmica na os vozovky vo vzdialenosti desať metrov od miesta, kde sa pre križovatku začína zakrivenie vozovky.');
INSERT INTO `Questions` VALUES (1460,1460,0,1,'Motorové vozidlo musí mať počas jazdy rozsvietené','',2,2,'diaľkové svetlomety,','stretávacie svetlomety alebo im na roveň postavené osvetlenie,','svetlá vo vnútri vozidla.');
INSERT INTO `Questions` VALUES (1461,1461,0,1,'Vodič','',2,2,'môže počas vedenia vozidla používať telefónny prístroj,','nesmie počas vedenia vozidla používať telefónny prístroj okrem telefonovanie s použitím systému „voľné ruky“,','nesmie počas vedenia vozidla počúvať rádio.');
INSERT INTO `Questions` VALUES (1462,1462,0,1,'Tam, kde sa dva jazdné pruhy zbiehajú do jedného jazdného pruhu tak, že nie je zrejmé, ktorý z nich je priebežný,','',2,3,'vodič jazdiaci v pravom jazdnom pruhu nesmie ohroziť vodiča jazdiaceho v ľavom jazdnom pruhu,','má prednosť vjazde vždy vodič vozidla s vyššou najväčšou prípustnou celkovou hmotnosťou,','vodič jazdiaci v ľavom jazdnom pruhu je povinný dať prednosť v jazde vodičovi v pravom jazdnom pruhu.');
INSERT INTO `Questions` VALUES (1463,1463,0,1,'Vodič nesmie predchádzať, ak','',2,1,'nemá pred sebou rozhľad na takú vzdialenosť, ktorá je potrebná na bezpečné predchádzanie,','by bol pritom nútený vojsť na električkový koľajový pás v úrovni vozovky,','pred ním jazdí vozidlo pravidelnej verejnej dopravy osôb.');
INSERT INTO `Questions` VALUES (1464,1464,0,1,'Vodiči protiidúcich vozidiel sa vyhýbajú','',2,3,'vľavo a tak, aby bola medzi vozidlami vzdialenosť najmenej 1 m ,','vždy vľavo,','vpravo, včas a v dostatočnej miere.');
INSERT INTO `Questions` VALUES (1465,1465,0,1,'Vodič sa nesmie otáčať','',2,2,'na železničnom priecestí a vo vzdialenosti 500 m pred ním,','na železničnom priecestí a v jeho tesnej blízkosti,','na žiadnej križovatke.');
INSERT INTO `Questions` VALUES (1466,1466,0,1,'Ak nie je ohrozená bezpečnosť a plynulosť cestnej premávky, vodič smie v obci','',2,2,'stáť v druhom rade,','zastaviť v druhom rade,','zastaviť a stáť na priechode pre chodcov.');
INSERT INTO `Questions` VALUES (1467,1467,0,1,'Vlečenie motorového vozidla s prívesom je','',2,1,'zakázané; smie sa však vliecť motorové vozidlo s návesom,','dovolené, ak najväčšia prípustné celkové hmotnosť vlečeného vozidla a prívesu neprevyšuje 3 500 kg,','zakázané; vliecť sa nesmie ani motorové vozidlo s návesom.');
INSERT INTO `Questions` VALUES (1468,1468,0,1,'Na diaľnici mimo obce a na rýchlostnej ceste mimo obce smie vodič motorového vozidla jazdiť rýchlosťou najmenej','',2,3,'60 km/h,','90 km/h,','80 km/h.');
INSERT INTO `Questions` VALUES (1469,1469,0,1,'Osoba mladšia ako 12 rokov sa nesmie prepravovať','',2,1,'vo zvláštnom motorovom vozidle a na motocykli,','v osobnom automobile,','vo vozidle pravidelnej verejnej dopravy osôb.');
INSERT INTO `Questions` VALUES (1470,1470,0,1,'Ak policajt pri riadení premávky dáva pokyn kývaním ruky hore a dolu, znamená to','',2,2,'zastaviť vozidlo,','spomaliť jazdu,','zrýchliť jazdu.');
INSERT INTO `Questions` VALUES (1471,1471,0,1,'Denný čas vedenia motorového vozidla nesmie presiahnuť','',1,2,'osem hodín, pričom tento čas možno dvakrát v týždni predĺžiť na deväť hodín,','deväť hodín, pričom tento čas možno dvakrát v týždni predĺžiť na desať hodín,','desať hodín, pričom tento čas možno trikrát v týždni predĺžiť na dvanásť hodín.');
INSERT INTO `Questions` VALUES (1472,1472,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'vyhotovenie, umiestnenie, poškodenie alebo deformácie ovládacích, regulačných a rozvádzacích prvkov plynového zariadenia alebo tlakovej nádoby bezprostredne ohrozuje bezpečnosť cestnej premávky na pozemných komunikáciách,','je na zadnom skle použitá schválené fólia,','sú poškodené ostrekovače zadného skla, dôsledkom čoho došlo k zhoršeniu výhľadu vodiča z kabíny vozidla.');
INSERT INTO `Questions` VALUES (1473,1473,0,1,'Povinnou výbavou osobného automobilu, nákladného automobilu a autobusu je','',1,3,'protisklzová reťaz,','krieda na vyznačenie stôp a postavenia vozidla v prípade dopravnej nehody,','v závislosti od kategórie vozidla predpísané autolekárnička.');
INSERT INTO `Questions` VALUES (1474,1474,1,1,'Táto dopravná značka s dodatkovou tabuľkou znamená:','spec6',2,3,'Spôsob obchádzania štyroch prekážok,','Nebezpečenstvo šmyku v úseku 4 km,','Štyri zákruty, prvá vpravo.');
INSERT INTO `Questions` VALUES (1475,1475,1,1,'Táto dopravná značka zakazuje vjazd','b22',2,1,'vjazd vozidlám prepravujúcim náklad, ktorý môže spôsobiť znečistenie vody, napríklad prepravujúci ropu, ropné materiály alebo iné látky,','cisternovým vozidlám,','nákladným motorovým vozidlám s návesom.');
INSERT INTO `Questions` VALUES (1476,1476,1,1,'Táto dopravná značka','b35',2,2,'zakazuje zastavenie za značkou v párnych dňoch v mesiaci,','zakazuje státie v nepárnych kalendárnych dňoch v mesiaci,','umožňuje státie v nepárnych dňoch v mesiaci.');
INSERT INTO `Questions` VALUES (1477,1477,1,1,'Táto dopravná značka','c14',2,2,'prikazuje vodičom na takto označenom úseku cesty používať pneumatiky so zimným dezénom,','prikazuje vodičom na takto označenom úseku cesty použiť pri jazde protisklzové reťaze; reťaze sa musia použiť minimálne na dvoch kolesách hnacej nápravy,','informuje vodičov o blízkosti opravovne pneumatík.');
INSERT INTO `Questions` VALUES (1478,1478,1,1,'Táto dopravná značka označuje','ip1',2,2,'hlavnú cestu, a to najmä v obci,','okruh zriadený na obchádzanie obce alebo jej časti,','stĺpy verejného osvetlenia, ktoré sú v blízkosti okraja vozovky.');
INSERT INTO `Questions` VALUES (1479,1479,1,1,'Táto dopravná značka','is7b',2,2,'prikazuje jazdu smerom, ktorým šípka ukazuje,','informuje o čísle výjazdu, odbočenia z diaľnice alebo rýchlostnej cesty na inú cestu,','informuje na diaľnici alebo rýchlostnej ceste o vzdialenosti v kilometroch k najbližšej križovatke.');
INSERT INTO `Questions` VALUES (1480,1480,1,1,'Táto dopravná značka znamená:','c22a',2,3,'Jazdný pruh pre pomalé vozidlá,','Zastávkový pruh,','Zvýšenie počtu jazdných pruhov.');
INSERT INTO `Questions` VALUES (1481,1481,1,1,'Táto dopravná značka vyznačuje','v12a',2,2,'priestor, kde je zakázané zastavenie,','priestor, kde je zakázané státie,','zastávku vozidiel pravidelnej verejnej dopravy osôb.');
INSERT INTO `Questions` VALUES (1482,1482,2,1,'Prednosť v jazde má vodič','321',3,3,'modrého vozidla, pretože prichádza zľava,','modrého vozidla, pretože ide po kruhovom objazde,','červeného vozidla, pretože vchádza do kruhového objazdu.');
INSERT INTO `Questions` VALUES (1483,1483,2,1,'Ako prvé prejde cez križovatku','133',3,2,'modré vozidlo,','zelené vozidlo,','červené vozidlo.');
INSERT INTO `Questions` VALUES (1484,1484,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','485',3,2,'1. červené, 2. zelené, 3. vaše vozidlo,','1. zelené, 2. vaše vozidlo, 3. červené,','1. vaše vozidlo. 2. červené. 3. zelené.');
INSERT INTO `Questions` VALUES (1485,1485,2,1,'Ako posledné prejde cez križovatku','567',3,2,'červené vozidlo,','zelené vozidlo,','vaše vozidlo.');
INSERT INTO `Questions` VALUES (1486,1486,0,1,'Krajnicou sa rozumie','',2,1,'časť cesty od kraja vozovky po kraj cesty,','miesto mimo cesty, na ktoré smie vojsť len vodič nemotorového vozidla,','časť cesty vyhradená na premávku vozidiel s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg.');
INSERT INTO `Questions` VALUES (1487,1487,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza a v období od novembra do marca môže vodič motorového vozidla kategórie M2, M3, N2 a N3; použiť takéto vozidlo v cestnej premávke, len ak','',2,2,'je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené aspoň na jednej z hnacích náprav zimnými pneumatikami,','je držiteľom medzinárodnej poisťovacej karty.');
INSERT INTO `Questions` VALUES (1488,1488,0,1,'Vodič','',2,2,'môže viesť vozidlo najviac 30 minút po požití alkoholu,','nesmie viesť vozidlo v takom čase po požití alkoholu alebo inej návykovej látky, keď sa alkohol alebo iná návyková látka ešte môžu nachádzať v jeho organizme,','môže viesť vozidlo bezprostredne po požití alkoholu alebo inej návykovej látky, ak to dovoľuje situácia v cestnej premávke najmä v nočnej dobe.');
INSERT INTO `Questions` VALUES (1489,1489,0,1,'Jazdiť zo svahu vždy so zaradeným rýchlostným stupňom sú povinní','',2,1,'vodič motorového vozidla s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg a vodič jazdnej súpravy alebo zvláštneho motorového vozidla,','vodič motorového vozidla s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 7 500 kg a vodič motocykla,','vodiči všetkých motorových vozidiel.');
INSERT INTO `Questions` VALUES (1490,1490,0,1,'Vodič nesmie predchádzať, ak','',2,3,'na to v obci neupozornil vodiča predchádzaného vozidla zvukovým výstražným znamením,','pred ním jazdí zvláštne motorové vozidlo,','by pri predchádzaní svojou výrazne nižšou rýchlosťou obmedzil za nim idúce vozidlo, ktoré začalo úkon predchádzania skôr.');
INSERT INTO `Questions` VALUES (1491,1491,0,1,'Vodič motorového vozidla, ktoré je povinne vybavené bezpečnostným odevom, je povinný mať bezpečnostný odev oblečený, ak sa zdržiava','',2,1,'na vozovke mimo vozidla počas núdzového státia, najmä pri prerušení jazdy pre chybu na vozidle alebo v dôsledku dopravnej nehody,','na čerpacej stanici,','na parkovisku za zníženej viditeľnosti.');
INSERT INTO `Questions` VALUES (1492,1492,0,1,'Vodič musí zaistiť bezpečné odbočenie pomocou spôsobilej a náležite poučenej osoby,','',2,1,'ak to vyžadujú okolnosti, najmä pri preprave dlhého nákladu,','vždy pri odbočovaní na miesto mimo cesty,','ak vedie motorové vozidlo s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 7 500 kg.');
INSERT INTO `Questions` VALUES (1493,1493,0,1,'Vodič nesmie pri cúvaní','',2,1,'ohroziť ostatných účastníkov cestnej premávky,','obmedziť vodičov motorových vozidiel,','jazdiť bez pripútania sa bezpečnostným pásom.');
INSERT INTO `Questions` VALUES (1494,1494,0,1,'Pri zastavení a státí vodič je povinný','',2,1,'čo najlepšie využiť parkovacie miesto a nesmie znemožniť ostatným vodičom vyjdenie z parkovacieho miesta,','ponechať bočný odstup od vozidla najmenej 1,5 m,','použiť vždy prenosný výstražný trojuholník.');
INSERT INTO `Questions` VALUES (1495,1495,0,1,'Vodič nesmie zastaviť a stáť na mieste, kde by vozidlo zakrývalo','',2,3,'akúkoľvek vodorovnú dopravnú značku,','stĺp verejného osvetlenia,','vodorovnú dopravnú značku vyznačujúcu spôsob radenia do jazdných pruhov a určený smer jazdy cez križovatku alebo vyjadrujúcu doplňujúci údaj nápisom.');
INSERT INTO `Questions` VALUES (1496,1496,0,1,'Ak sa spúšťajú, ak sú spustené alebo ak sa zdvíhajú závory, vodič','',2,2,'smie vchádzať na železničné priecestie, ak to rozmery jeho vozidla dovoľujú,','nesmie vchádzať na železničné priecestie,','smie vchádzať na železničné priecestie, ak nie je vidieť vlak.');
INSERT INTO `Questions` VALUES (1497,1497,0,1,'Preprava osôb v prípojnom vozidle nákladného automobilu je','',2,2,'povolená,','zakázaná,','povolená, ak sú prepravované osoby staršie ako 21 rokov.');
INSERT INTO `Questions` VALUES (1498,1498,0,1,'Celkový čas vedenia motorového vozidla nesmie presiahnuť','',1,1,'90 hodín v období dvoch po sebe nasledujúcich týždňov,','80 hodín v období dvoch po sebe nasledujúcich týždňov,','100 hodín v období dvoch po sebe nasledujúcich týždňov.');
INSERT INTO `Questions` VALUES (1499,1499,0,1,'Prevádzkovateľ vozidla nesmie v premávke na pozemných komunikáciách prevádzkovať vozidlo, ktoré','',1,2,'je prihlásené do evidencie vozidiel iného štátu,','poškodzuje pozemné komunikácie nad prípustnú mieru,','je vybavené platnou tabuľkou so zvláštnym evidenčným číslom.');
INSERT INTO `Questions` VALUES (1500,1500,0,1,'Plášť pneumatiky nesmie mať na svojom vonkajšom obvode (oblasť koruny, boku a pätky plášťa)','',1,3,'trhliny ani poškodenia, ktoré narúšajú kordovú kostru; jej obnaženie však nie je závadou,','trhliny, ktoré obnažujú kordovú kostru; jej poškodenie však nie je závadou,','trhliny ani poškodenia, ktoré obnažujú kordovú kostru alebo ju narúšajú.');
INSERT INTO `Questions` VALUES (1501,1501,1,1,'Táto dopravná značka s dodatkovou tabuľkou','spec86',2,2,'prikazuje vodičovi zastaviť vozidlo do vzdialenosti 150 m,','vyznačuje vzdialenosť k značke „Stoj, daj prednosť v jazde!“, pre ktorú je zároveň predbežnou značkou,','upozorňuje vodiča, že vo vzdialenosti 150 m bude mať prednosť v jazde.');
INSERT INTO `Questions` VALUES (1502,1502,1,1,'Táto dopravná značka znamená:','c6c',2,1,'Prikázaný smer obchádzania vpravo a vľavo,','Jazdné pruhy pred križovatkou,','Nerovnosť vozovky.');
INSERT INTO `Questions` VALUES (1503,1503,1,1,'Táto dopravná značka znamená:','c15',2,3,'Najvyššia dovolená rýchlosť,','Odporúčaná rýchlosť,','Najnižšia dovolená rýchlosť.');
INSERT INTO `Questions` VALUES (1504,1504,1,1,'Táto dopravná značka znamená:','c19',2,1,'Prikázaný smer prepravy vyznačených vozidiel a vecí,','Prikázaný smer jazdy obytných automobilov,','Dovolené predchádzanie vľavo.');
INSERT INTO `Questions` VALUES (1505,1505,1,1,'Táto dopravná značka znamená:','p9',2,2,'Koniec rýchlostnej cesty,','Koniec hlavnej cesty; značka informuje o tom, že na najbližšej križovatke táto cesta už nie je hlavná,','Koniec vedľajšej cesty; značka upozorňuje na to, že na najbližšej križovatke má vodič prednosť v jazde.');
INSERT INTO `Questions` VALUES (1506,1506,1,1,'Táto dopravná značka','is17b',2,2,'prikazuje odbočiť vpravo,','informuje o smere a vzdialenosti v kilometroch k vyznačenému cieľu (obci),','vyznačuje cestu s jednosmernou premávkou.');
INSERT INTO `Questions` VALUES (1507,1507,1,1,'Prechádzať túto značku alebo ju nákladom presahovať','v1a',2,3,'je zakázané, ak to nie je potrebné na otáčanie,','je vždy zakázané,','je zakázané, ak to nie je potrebné na obchádzanie, odbočovanie na miesto ležiace mimo cesty alebo na vchádzanie na cestu z miesta ležiaceho mimo cesty.');
INSERT INTO `Questions` VALUES (1508,1508,1,1,'Táto dopravná značka vyznačuje','v9b',2,1,'blížiaci sa prechod pozdĺžnej prerušovanej čiary do súvislej čiary,','prikázaný smer jazdy cez križovatku,','prikázaný smer jazdy vpravo.');
INSERT INTO `Questions` VALUES (1509,1509,2,1,'V poradí druhé prejde okolo prekážky','915',3,1,'červené vozidlo,','žlté vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (1510,1510,2,1,'Ak má policajt pravú ruku predpaženú a ľavú upaženú, znamená to „Stoj!“ pre','295',3,2,'vodiča zeleného vozidla,','vodiča žltého vozidla,','chodcov prechádzajúcich za chrbtom policajta.');
INSERT INTO `Questions` VALUES (1511,1511,2,1,'V poradí druhé prejde cez križovatku','512',3,2,'červené vozidlo odbočujúce vľavo,','vaše vozidlo odbočujúce vľavo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (1512,1512,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','567',3,3,'1. červené, 2. zelené, 3. vaše vozidlo súčasne s modrým,','1. modré, 2. červené, 3. zelené, 4. vaše vozidlo,','1. červené, 2. vaše vozidlo súčasne s modrým, 3. zelené.');
INSERT INTO `Questions` VALUES (1513,1513,0,1,'zastavením sa rozumie','',2,3,'prerušenie jazdy motorového vozidla z dôvodu nezávislého od vôle vodiča,','len také uvedenie vozidla do pokoja, ktoré nepresiahne čas tri minúty,','uvedenie vozidla do pokoja na čas nevyhnutne potrebný na urýchlené nastúpenie alebo na vystúpenie prepravovaných osôb alebo na urýchlene naloženie alebo na zloženie nákladu.');
INSERT INTO `Questions` VALUES (1514,1514,0,1,'Osoba sediaca na sedadle vozidla povinne vybavenom bezpečnostným pásom alebo iným zadržiavacím zariadením','',2,2,'je povinná toto zariadenie použiť len počas jazdy mimo obce,','je povinná toto zariadenie použiť,','nie je povinná toto zariadenie použiť, ak sedí na zadnom sedadle.');
INSERT INTO `Questions` VALUES (1515,1515,0,1,'Vodič je povinný rýchlosť jazdy prispôsobiť','',2,1,'najmä svojim schopnostiam, vlastnostiam vozidla a nákladu, poveternostným podmienkam, stavu a povahe vozovky a iným okolnostiam, ktoré možno predvídať,','svojim schopnostiam; vlastnostiam nákladu je vodič povinný rýchlosť jazdy prispôsobiť len vtedy, ak sú vo vozidle prepravované živé zvieratá alebo nebezpečný náklad,','len poveternostným podmienkam.');
INSERT INTO `Questions` VALUES (1516,1516,0,1,'Vodič motorového vozidla kategórie N, ktorého najväčšia prípustné celková hmotnosť presahuje 7 500 kg alebo vodič jazdnej súpravy, ktorej najväčšia prípustná hmotnosť presahuje 7 500 kg nesmie','',2,2,'pri jazde po medzinárodnej trase a ceste 1. triedy predchádzať iné motorové vozidlo,','pri jazde po diaľnici predchádzať iné motorové vozidlo,','mimo obce na ceste s dvoma alebo viacerými jazdnými pruhmi vyznačenými na vozovke v jednom smere jazdy použiť na jazdu pravý jazdný pruh.');
INSERT INTO `Questions` VALUES (1517,1517,0,1,'Vodič nesmie zastaviť a stáť','',2,3,'na železničnom priecestí a v tuneli a vo vzdialenosti kratšej ako 80 m pred nimi,','kolmo na okraj cesty v obci,','na železničnom priecestí, v podjazde a v tuneli a vo vzdialenosti kratšej ako 15 m pred nimi a 15 m za nimi.');
INSERT INTO `Questions` VALUES (1518,1518,0,1,'Vodič nesmie použiť diaľkové svetlomety, ak','',2,2,'by mohol byť oslnený vodič protiidúceho vozidla; na prípadné oslnenie vodiča idúceho pred ním nemusí brať ohľad,','by mohol byť oslnený vodič protiidúceho vozidla alebo vodič vozidla idúceho pred ním,','s tým nevyslovili súhlas všetci jeho spolucestujúci.');
INSERT INTO `Questions` VALUES (1519,1519,0,1,'Na diaľnici mimo obce smie vodič motorového vozidla jazdiť rýchlosťou najmenej','',2,2,'60 km/h,','80 km/h,','90 km/h.');
INSERT INTO `Questions` VALUES (1520,1520,0,1,'Ak pri jazde vozidla v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným, alebo ak vznikne dopravná nehoda vrátane požiaru, je vodič po zastavení vozidla povinný bezodkladne','',2,2,'vypnúť stretávacie svetlomety,','vypnúť motor, a ak je na vykurovanie vozidla použité nezávislé kúrenie, vypnúť aj toto kúrenie,','oznámiť zastavenie vozidla príslušnému obvodnému úradu.');
INSERT INTO `Questions` VALUES (1521,1521,0,1,'Vodič podľa svojich možností nesmie pripustiť','',2,1,'porušenie povinností ustanovených prepravovaným osobám,','fajčenie prepravovaných osôb,','používanie telefónneho prístroja prepravovanými osobami.');
INSERT INTO `Questions` VALUES (1522,1522,0,1,'Pri preprave osôb v ložnom priestore nákladného prívesu traktora rýchlosť jazdy nesmie prekročiť','',2,3,'15 km/h,','10 km/h,','20 km/h.');
INSERT INTO `Questions` VALUES (1523,1523,0,1,'Účastník dopravnej nehody je','',2,3,'len osoba, ktorá dopravnú nehodu zavinila,','len vodič, ktorý sa zúčastnil na dopravnej nehode,','osoba, ktorá sa priamo aktívne alebo pasívne zúčastnila na dopravnej nehode.');
INSERT INTO `Questions` VALUES (1524,1524,0,1,'V obytnej zóne, pešej zóne a školskej zóne vodič smie jazdiť rýchlosťou najviac','',2,1,'20 km/h,','30 km/h,','50 km/h.');
INSERT INTO `Questions` VALUES (1525,1525,0,1,'Vodič motorového vozidla musí mať po uplynutí štyroch a pol hodiny vedenia motorového vozidla prestávku v práci v trvaní najmenej','',1,2,'45 minút, ak sa nezačína nepretržitý denný odpočinok alebo nepretržitý odpočinok v týždni,','45 minút, ak sa nezačína nepretržitý denný odpočinok alebo nepretržitý odpočinok v týždni, pričom prestávku v práci sa môže nahradiť prestávkou trvajúcou najmenej 15 minút, po ktorej nasleduje prestávka trvajúca najmenej 30 minút,','30 minút.');
INSERT INTO `Questions` VALUES (1526,1526,0,1,'Povinnou výbavou motorového vozidlo s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg a prípojného vozidla s najväčšou prípustnou hmotnosťou prevyšujúcou 750 kg je','',1,2,'najmenej dvojlitrová zásoba maziva v osobitnej nádobe,','aspoň jeden zakladací klin, ktorý účinne zabezpečí vozidlo proti samovoľnému pohybu,','dvojica diaľkových svetlometov natáčavých súčasne s riadiacim mechanizmom vozidla.');
INSERT INTO `Questions` VALUES (1527,1527,0,1,'Prevádzkovateľ vozidla nesmie v premávke na pozemných komunikáciách prevádzkovať vozidlo, ktoré','',1,3,'je vybavené platnou tabuľkou s osobitným evidenčným číslom,','poškodzuje pozemné komunikácie nad 50 % prípustnej miery,','je dodatočne vybavené neschváleným systémom, komponentom alebo samostatnou technickou jednotkou.');
INSERT INTO `Questions` VALUES (1528,1528,1,1,'Tieto dopravné značky upozorňujú na','spec32',2,3,'železničné priecestie bez závor vo vzdialenosti 180 m,','železničné priecestie so závorami vo vzdialenosti 200 m,','železničné priecestie bez závor vo vzdialenosti 240 m.');
INSERT INTO `Questions` VALUES (1529,1529,1,1,'Táto dopravná značka znamená:','b3',2,2,'Vjazd osobným automobilom a motocyklom povolený,','Zákaz vjazdu všetkých motorových vozidiel,','Zákaz vjazdu osobných automobilov a motocyklov.');
INSERT INTO `Questions` VALUES (1530,1530,1,1,'Táto dopravná značka znamená:','ip4',2,1,'Slepá cesta,','Zákaz vjazdu,','Križovatka tvaru „T“.');
INSERT INTO `Questions` VALUES (1531,1531,1,1,'Táto dopravná značka znamená:','ip17a',2,3,'Zákaz parkovania v párnych dňoch,','Parkovisko - parkovacie miesta s vyhradeným státím,','Parkovisko - parkovacie miesta s plateným státím.');
INSERT INTO `Questions` VALUES (1532,1532,1,1,'Táto dopravná značka vyznačuje','c25',2,2,'jazdné pruhy pre pomalé vozidlá,','spôsob radenia do jazdných pruhov a určený smer jazdy cez križovatku,','zvýšenie počtu jazdných pruhov.');
INSERT INTO `Questions` VALUES (1533,1533,1,1,'Táto dopravná značka znamená:','is15',2,3,'Zastávkový jazdný pruh,','Obmedzenie v jazdnom pruhu,','Návesť pred obchádzkou (odklonom).');
INSERT INTO `Questions` VALUES (1534,1534,1,1,'Táto dopravná značka znamená:','is26',2,1,'Smerová tabuľa na vyznačenie obchádzky,','Iné nebezpečenstvo,','Prikázaný smer jazdy.');
INSERT INTO `Questions` VALUES (1535,1535,1,1,'Táto vodiaca tabuľa označuje','z3a',2,2,'úsek cesty s nebezpečným stúpaním,','najmä nebezpečnú zákrutu,','úplnú uzávierku cesty.');
INSERT INTO `Questions` VALUES (1536,1536,2,1,'Vodič modrého vozidla','699',3,3,'má pred vodičom červeného a vodičom žltého vozidla prednosť, pretože v ich jazdnom pruhu sa nachádza prekážka,','je povinný umožniť vodičovi červeného a vodičovi žltého vozidla obídenie prekážky,','je povinný umožniť vodičovi červeného vozidla obídenie prekážky.');
INSERT INTO `Questions` VALUES (1537,1537,2,1,'Ako posledné prejde cez križovatku','402',3,1,'červené vozidlo,','zelené vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (1538,1538,2,1,'Vaše vozidlo prejde cez križovatku ako','539',3,3,'druhé,','posledné,','prvé.');
INSERT INTO `Questions` VALUES (1539,1539,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','702',3,3,'1. vaše vozidlo, 2. červené, 3. žlté, 4. zelené,','1. žlté, 2. zelené, 3. červené, 4. vaše vozidlo,','1 červené, 2. vaše vozidlo, 3. žlté, 4. zelené.');
INSERT INTO `Questions` VALUES (1540,1540,0,1,'Dať prednosť vjazde sa rozumie povinnosť','',2,1,'účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť vjazde, nemusel zmeniť smer alebo rýchlosť jazdy,','účastníka cestnej premávky počínať si tak, aby inému účastníkovi cestnej premávky nijako neprekážal,','chodca prechádzajúceho na priechode pre chodcov neobmedziť motorové vozidlá prichádzajúce sprava.');
INSERT INTO `Questions` VALUES (1541,1541,0,1,'Pri jazde v pripájacom jazdnom pruhu alebo v odbočovacom jazdnom pruhu sa','',2,3,'nesmie vpravo predchádzať vozidlo idúce v priebežnom pruhu,','nesmie jazdiť vyššou rýchlosťou, akou jazdia vozidlá v priebežnom pruhu,','smie vpravo predchádzať aj vozidlo idúce v priebežnom jazdnom pruhu.');
INSERT INTO `Questions` VALUES (1542,1542,0,1,'Vodič autobusu alebo trolejbusu pri vychádzaní zo zastávky alebo zo zastávkového pruhu','',2,3,'nedáva znamenie o zmene smeru jazdy,','nedáva znamenie o zmene smeru jazdy v obci,','nesmie ohroziť vodičov ostatných vozidiel.');
INSERT INTO `Questions` VALUES (1543,1543,0,1,'Vodič motorového vozidla nesmie predchádzať iné motorové vozidlo na diaľnici,','',2,1,'ak by pri predchádzaní svojou výrazne nižšou rýchlosťou obmedzil iné vozidlo idúce po diaľnici,','ak by pri predchádzaní neobmedzil iné vozidlo idúce po diaľnici,','ak nemá rozhľad na vzdialenosť 200 metrov.');
INSERT INTO `Questions` VALUES (1544,1544,0,1,'Vodič je povinný bezodkladne vypnúť motor, a ak je na vykurovanie vozidla použité nezávislé kúrenie, vypnúť aj toto kúrenie, ak','',2,1,'pri jazde vozidla v tuneli vznikne porucha vozidla, pre ktorú sa toto vozidlo stane nepojazdným,','vodič zastavil na parkovisku,','zastavil vozidlo pred železničným priecestím, kde sa dáva výstraha dvoma červenými striedavo prerušovanými svetlami priecestného zabezpečovacieho zariadenia.');
INSERT INTO `Questions` VALUES (1545,1545,0,1,'Vodič nesmie vchádzať na železničné priecestie, ak za zníženej viditeľnosti','',2,2,'osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestie dáva znamenie kývaním ruky s bielym svetlom cez stred tela,','osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestie dáva znamenie krúžením červeným svetlom v hornom polkruhu,','svieti prerušované biele svetlo.');
INSERT INTO `Questions` VALUES (1546,1546,0,1,'Ak je vozovka dostatočne a súvisle osvetlená, vodič','',2,2,'smie použiť diaľkové svetlomety,','nesmie použiť diaľkové svetlomety,','smie použiť diaľkové svetlomety, ak vo vzdialenosti najmenej 50 m pred ním nejde žiadne vozidlo.');
INSERT INTO `Questions` VALUES (1547,1547,0,1,'Vlečenie motorového vozidla s prívesom je','',2,2,'zakázané; vliecť sa nesmie ani motorové vozidlo s návesom,','zakázané; smie sa však vliecť motorové vozidlo s návesom,','dovolené, ak najväčšia prípustná celková hmotnosť vlečeného vozidla s prívesom nepresahuje 3 500 kg,');
INSERT INTO `Questions` VALUES (1548,1548,0,1,'Na diaľnici a na rýchlostnej ceste je vodičovi zastavenie a státie','',2,3,'dovolené všade tam, kde priamo neohrozí vodičov ostatných vozidiel,','dovolené na parkovisku a na pripájacom alebo na odbočovacom pruhu,','zakázané na inom mieste než na mieste označenom ako parkovisko s výnimkou núdzového státia,');
INSERT INTO `Questions` VALUES (1549,1549,0,1,'Preprava osôb v prípojnom vozidle nákladného automobilu je','',2,2,'dovolená,','zakázaná,','dovolená rýchlosťou najviac 60 km/h.');
INSERT INTO `Questions` VALUES (1550,1550,0,1,'Náklad musí byť na vozidle riadne umiestnený, rozložený a upevnený, aby','',2,3,'nezakrýval názov a sídlo držiteľa vozidla uvedeného na vozidle,','nezakrýval svetlomety a svietidlá vozidla a tabuľku s evidenčným číslom; to neplatí pri jazde na diaľnici a rýchlostnej ceste,','nezakrýval svetlomety a svietidlá vozidla, odrazové sklá, tabuľku s evidenčným číslom a vyznačenie najvyššej povolenej rýchlosti.');
INSERT INTO `Questions` VALUES (1551,1551,0,1,'V obytnej, pešej zóne a školskej zóne chodci','',2,1,'sú povinní umožniť vozidlám jazdu; to platí aj pre deti, ktoré sa hrajú v obytnej zóne,','nie sú povinní umožniť vozidlám jazdu,','sú povinní umožniť jazdu len vozidlám pravidelnej verejnej dopravy osôb; to platí aj pre deti, ktoré sa hrajú na ceste.');
INSERT INTO `Questions` VALUES (1552,1552,0,1,'Denný čas vedenia motorového vozidla nesmie presiahnuť','',1,3,'desať hodín, pričom tento čas možno trikrát v týždni predĺžiť na dvanásť hodín,','osem hodín, pričom tento čas možno dvakrát v týždni predĺžiť na deväť hodín,','deväť hodín, pričom tento čas možno dvakrát v týždni predĺžiť na desať hodín.');
INSERT INTO `Questions` VALUES (1553,1553,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'ťažné oje návesu nie je zaistené 1,5 m dlhou reťazou,','mazivo používané vo vozidle nie je schválené výrobcom,','vôľa riadenia je väčšia, než je prípustné alebo je niektorá zo súčastí riadenia poškodená natoľko, že to spôsobuje jeho nespoľahlivú činnosť.');
INSERT INTO `Questions` VALUES (1554,1554,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,3,'je na zadnom skle použitá schválená fólia,','nie je možné uviesť do činnosti osvetlenie batožinového priestoru,','pneumatika alebo disk kolesa je nadmerne poškodený.');
INSERT INTO `Questions` VALUES (1555,1555,1,1,'Táto dopravná značka znamená:','c6b',2,3,'Nebezpečné stúpanie,','Príkaz na otáčanie,','Prikázaný smer obchádzania vľavo.');
INSERT INTO `Questions` VALUES (1556,1556,1,1,'Táto dopravná značka','c13',2,3,'označuje priechod pre chodcov a cyklistov; značka informuje o spoločnom priechode pre chodcov a cyklistov,','označuje koniec cestičky pre chodcov a cyklistov,','prikazuje chodcom a cyklistom použiť v predmetnom smere takto označený spoločný pruh alebo cestičku, ale iba vyznačeným spôsobom vyznačeným spôsobom; chodci a cyklisti sa nesmú navzájom ohroziť.');
INSERT INTO `Questions` VALUES (1557,1557,1,1,'Táto dopravná značka znamená:','c30',2,2,'Dopravná nehoda,','Striedavé radenie,','Zníženie počtu jazdných pruhov.');
INSERT INTO `Questions` VALUES (1558,1558,1,1,'Táto dopravná značka znamená:','ip7',2,2,'Cestička pre cyklistov,','Priechod pre cyklistov,','Obytná zóna.');
INSERT INTO `Questions` VALUES (1559,1559,1,1,'Táto dopravná značka','is9',2,3,'vyznačuje križovatku s vedľajšou cestou,','informuje o zvýšení počtu jazdných pruhov,','informuje o smere k vyznačeným cieľom z najbližšej križovatky.');
INSERT INTO `Questions` VALUES (1560,1560,1,1,'Táto dopravná značka znamená:','is36a',2,2,'Obytná zóna,','Obec,','Smerová tabuľa k miestnemu cieľu.');
INSERT INTO `Questions` VALUES (1561,1561,1,1,'Táto dodatková tabuľka','e9',2,1,'obmedzuje platnosť značky, pod ktorou je umiestnená, na nepriaznivé poveternostné podmienky, napr. na podmienky mokrej vozovky,','obmedzuje platnosť značky, pod ktorou je umiestnená, na podmienky zníženej viditeľnosti,','upozorňuje na nerovnosť vozovky.');
INSERT INTO `Questions` VALUES (1562,1562,1,1,'Táto dopravná značka znamená:','v7',2,3,'Miesto vjazdu vozidiel na cestu z miesta ležiaceho mimo cesty,','Dovolené zastavenie a státie kolmo alebo šikmo na okraj vozovky,','Priechod pre cyklistov.');
INSERT INTO `Questions` VALUES (1563,1563,2,1,'Prednosť vjazde má vodič','726',3,1,'modrého vozidla, pretože prichádza na križovatku po ceste označenej ako hlavná,','modrého vozidla, pretože ide po kruhovom objazde,','červeného vozidla, pretože prichádza na križovatku sprava.');
INSERT INTO `Questions` VALUES (1564,1564,2,1,'Ak svieti signál na opustenie križovatky umiestnený v protiľahlom rohu križovatky,','700',3,3,'vodič červeného vozidla odbočujúceho vľavo je povinný dať prednosť vjazde protiidúcemu zelenému a žltému vozidlu a električkám idúcim z obidvoch smerov,','vodiči protiidúceho zeleného a žltého vozidla a protiidúcej električky majú prednosť pred červeným vozidlom,','vodič červeného vozidla odbočujúceho vľavo má prednosť vjazde pred protiidúcim zeleným a žltým vozidlom a obidvoma električkami.');
INSERT INTO `Questions` VALUES (1565,1565,2,1,'Ako prvé prejde cez križovatku','458',3,2,'červené vozidlo,','žlté vozidlo,','vaše vozidlo.');
INSERT INTO `Questions` VALUES (1566,1566,2,1,'V poradí druhé prejde cez križovatku','324',3,2,'červené vozidlo,','zelené vozidlo,','vaše vozidlo súčasne so žltým vozidlom.');
INSERT INTO `Questions` VALUES (1567,1567,0,1,'Dať prednosť v jazde sa rozumie','',2,3,'povinnosť účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde nemusel zmeniť rýchlosť jazdy, môže však zmeniť smer jazdy,','povinnosť účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde nemusel zmeniť smer jazdy, môže však zmeniť rýchlosť jazdy,','povinnosť účastníka cestnej premávky počínať si tak, aby ten, kto má prednosť v jazde nemusel zmeniť smer alebo rýchlosť jazdy.');
INSERT INTO `Questions` VALUES (1568,1568,0,1,'Vodič motorového vozidla s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg a vodič jazdnej súpravy alebo zvláštneho motorového vozidla sú povinní','',2,3,'pri jazde zo svahu použiť osobitné zariadenie umožňujúce výstražnú funkciu smerových svietidiel,','počas jazdy používať na hlave riadne upevnenú ochrannú prilbu určenú pre motocyklistov,','jazdiť zo svahu vždy so zaradeným rýchlostným stupňom.');
INSERT INTO `Questions` VALUES (1569,1569,0,1,'Vodič je povinný pribrať potrebný počet spôsobilých osôb, ak','',2,1,'to vyžaduje bezpečnosť cestnej premávky, a na tento účel ich náležite poučiť,','sa pri preprave nákladu prekročila najväčšia celková prípustné hmotnosť vozidla,','v potrebnom rozsahu neovláda predpisy o cestnej premávke.');
INSERT INTO `Questions` VALUES (1570,1570,0,1,'Ak vodič prechádza z jedného jazdného pruhu do druhého jazdného pruhu,','',2,1,'je povinný dávať znamenie o zmene smeru jazdy,','nie je povinný dávať znamenie o zmene smeru jazdy,','môže ohroziť vodiča jazdiaceho v jazdnom pruhu, do ktorého prechádza.');
INSERT INTO `Questions` VALUES (1571,1571,0,1,'Vodič, ktorý pri obchádzaní vozidla, ktoré zastavilo alebo stojí, prekážky cestnej premávky alebo chodca vybočuje zo smeru svojej jazdy,','',2,1,'nesmie ohroziť ani obmedziť vodiča protiidúceho vozidla,','môže ohroziť vodiča jazdiaceho za ním,','nie je povinný dávať znamenie o zmene smeru jazdy.');
INSERT INTO `Questions` VALUES (1572,1572,0,1,'Vodič nesmie predchádzať, ak vodič pred ním idúceho vozidla dáva znamenie o zmene smeru jazdy','',2,2,'vpravo,','vľavo a ak ho nemožno predísť vpravo, prípadne ak ho nemožno predísť v ďalšom voľnom jazdnom pruhu vtom istom smere jazdy vyznačenom na vozovke,','vľavo a to za žiadnych okolností.');
INSERT INTO `Questions` VALUES (1573,1573,0,1,'Ak sa vodiči protiidúcich vozidiel nemôžu bezpečne vyhnúť, prednosť v jazde je povinný dať ten vodič,','',2,1,'na ktorého strane jazdy je prekážka alebo zúžená vozovke,','na ktorého strane nie je zúžená vozovke,','ktorý je mladší.');
INSERT INTO `Questions` VALUES (1574,1574,0,1,'Pri vchádzaní na cestu z miesta mimo cesty vodič','',2,2,'nie je povinný dať prednosť v jazde vozidlu idúcemu po ceste,','je povinný dať prednosť v jazde vozidlu idúcemu po ceste,','je povinný dať prednosť v jazde len vozidlu idúcemu po ceste zľava.');
INSERT INTO `Questions` VALUES (1575,1575,0,1,'Pri zastavení musí zostať voľný aspoň jeden jazdný pruh široký najmenej','',2,3,'3 m pre každý smer jazdy,','2 m,','3 m pre oba smery jazdy.');
INSERT INTO `Questions` VALUES (1576,1576,0,1,'Ak sa vodič motorového vozidla, ktoré je povinne vybavené bezpečnostným odevom, zdržiava na vozovke mimo vozidla počas núdzového státia, najmä pri prerušení jazdy pre chybu na vozidle alebo v dôsledku dopravnej nehody, je povinný','',2,1,'mať bezpečnostný odev oblečený,','umiestniť 20 m za vozidlo biele neoslňujúce svetlo bielej farby,','bezodkladne privolať odťahovú službu.');
INSERT INTO `Questions` VALUES (1577,1577,0,1,'Pri preprave nákladu sa','',2,3,'môže prekročiť najväčšia prípustná celková hmotnosť vozidla najviac o 10 %,','môže prekročiť najväčšia prípustná celková hmotnosť vozidla len na miestnych komunikáciách,','nesmie prekročiť najväčšia prípustná celková hmotnosť vozidla,');
INSERT INTO `Questions` VALUES (1578,1578,0,1,'Účastník dopravnej nehody môže premiestniť vozidlá,','',2,1,'ak je to nevyhnutné na uvoľnenie alebo ošetrenie zranenej osoby alebo na obnovenie cestnej premávky, pritom je však povinný vyznačiť postavenie vozidiel po dopravnej nehode, situáciu a stopy,','ak je to potrebné na vyloženie prepravovaných vecí z vozidla,','ak je to nevyhnutné na obnovenie premávky, pritom nie je povinný vyznačiť postavenie vozidiel po dopravnej nehode, situáciu a stopy.');
INSERT INTO `Questions` VALUES (1579,1579,0,1,'Týždenný čas jazdy','',1,1,'nesmie presiahnuť 56 hodín,','nesmie presiahnuť 40 hodín,','nesmie presiahnuť 48 hodín.');
INSERT INTO `Questions` VALUES (1580,1580,0,1,'Činná plocha plášťa pneumatiky na nákladnom automobile a autobuse musí mať po celom obvode a celej šírke vrchného behúňa dezén s hĺbkou dezénových drážok','',1,1,'najmenej 1,6 mm,','najmenej 3 mm,','najviac 4 mm.');
INSERT INTO `Questions` VALUES (1581,1581,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'je zjavne vážne poškodené pruženie,','nie je vybavené klimatizačným systémom,','je katalyzátor výfukových plynov po lehote kalibrácie.');
INSERT INTO `Questions` VALUES (1582,1582,1,1,'Táto dopravná značka upozorňuje na','a21',2,1,'úsek cesty, kde je na rozdiel od predchádzajúceho úseku v príslušnej častí vozovky dočasná alebo trvalá premávka v oboch smeroch,','úsek cesty, kde je premávka riadená striedavo,','miesto, kde má vodič prednosť pred protiidúcim vodičom.');
INSERT INTO `Questions` VALUES (1583,1583,1,1,'Táto dopravná značka','c17',2,2,'označuje úsek cesty, kde je zakázané používať diaľkové svetlomety,','prikazuje vodičoví na takto označenom úseku cesty rozsvietiť na idúcom vozidle ustanovené osvetlenie,','informuje vodiča o úseku cesty na ktorom môžu mať protiidúce vozidlá rozsvietené stretávacie svetlomety.');
INSERT INTO `Questions` VALUES (1584,1584,1,1,'Táto dopravná značka znamená:','ip22a',2,1,'Rýchlostná cesta,','Jazdný pruh vyhradený pre osobné automobily,','Parkovisko (pozdĺžne státie).');
INSERT INTO `Questions` VALUES (1585,1585,1,1,'Táto dopravná značka informuje','is21',2,2,'o smere a dĺžke obchádzky,','o smere a prípadne o vzdialenosti k časti obce,','o názve najbližšej križovatky.');
INSERT INTO `Questions` VALUES (1586,1586,1,1,'Táto dopravná značka znamená:','is31',2,3,'Najvyššia dovolená rýchlosť,','Cesta II. triedy,','Medzinárodná trasa.');
INSERT INTO `Questions` VALUES (1587,1587,1,1,'Táto dodatková tabuľka označuje','e7',2,2,'prikázaný smer obchádzania,','smer k miestu, kde platí značka, pod ktorou je tabuľka umiestnená,','jednosmernú premávku.');
INSERT INTO `Questions` VALUES (1588,1588,1,1,'Táto dodatková tabuľka','e10',2,2,'vyznačuje druh vozidla, na ktoré sa nevzťahuje značka, pod ktorou je tabuľka umiestnená,','obmedzuje platnosť značky, pod ktorou je umiestnená, na vyznačený druh vozidla,','vyznačuje parkovisko pre nákladné automobily.');
INSERT INTO `Questions` VALUES (1589,1589,1,1,'Táto dopravná značka vyznačuje','v5b',2,2,'začiatok vedľajšej cesty,','hranicu križovatky; to neplatí, ak sa táto značka použije ako pomocná čiara na zastavenie vozidla v priestore križovatky,','miesto, kde musí vodič vždy zastaviť vozidlo.');
INSERT INTO `Questions` VALUES (1590,1590,2,1,'V poradí druhé prejde cez križovatku:','78',3,2,'Žlté vozidlo,','červené vozidlo,','zelené vozidlo.');
INSERT INTO `Questions` VALUES (1591,1591,2,1,'Ak svieti signál na opustenie križovatky umiestnený v protiľahlom rohu križovatky','106',3,2,'vodiči obidvoch električiek majú prednosť pred ostatnými vozidlami,','vodič červeného vozidla odbočujúceho vľavo má prednosť v jazde pred protiidúcim zeleným a žltým vozidlom a obidvoma električkami,','vodič červeného vozidla odbočujúceho vľavo je povinný dať prednosť protiidúcemu zelenému a žltému vozidlu a obidvom električkám.');
INSERT INTO `Questions` VALUES (1592,1592,2,1,'Ako posledné prejde cez križovatku','539',3,2,'vaše vozidlo,','červené vozidlo,','modré vozidlo.');
INSERT INTO `Questions` VALUES (1593,1593,2,1,'Vaše vozidlo prejde cez križovatku ako','540',3,1,'prvé súčasne s modrým vozidlom,','štvrté súčasne so zeleným vozidlom,','tretie.');
INSERT INTO `Questions` VALUES (1594,1594,0,1,'Križovatkou s riadenou premávkou sa rozumie','',2,1,'križovatka, na ktorej je premávka riadená dopravnými zariadeniami alebo policajtom, prípadne inou oprávnenou osobou,','každé miesto, na ktorom je prednosť v jazde upravená dopravnými značkami,','miesto, na ktorom je premávka riadená policajtom alebo každou inou osobou oprávnenou dávať pokyny na zastavenie vozidla.');
INSERT INTO `Questions` VALUES (1595,1595,0,1,'Vodič nesmie predchádzať, ak','',2,1,'by ohrozil alebo obmedzil vodiča jazdiaceho v protismere alebo ohrozil iného účastníka cestnej premávky,','by pritom musel jazdiť rýchlosťou vyššou ako 85 km.h''1,','pred ním ide autobus prepravujúci deti.');
INSERT INTO `Questions` VALUES (1596,1596,0,1,'Ak vodiči protiidúcich vozidiel odbočujú vľavo, vyhýbajú sa','',2,3,'vpravo,','s odstupom najmenej 1 m,','vľavo.');
INSERT INTO `Questions` VALUES (1597,1597,0,1,'Vodič je povinný zaistiť bezpečné otáčanie alebo cúvanie pomocou spôsobilej a náležite poučenej osoby, ak','',2,2,'sa otáča alebo cúva v tuneli a v jeho tesnej blízkosti,','to vyžadujú okolnosti, najmä nedostatočný rozhľad,','sa otáča alebo cúva na priechode pre chodcov alebo na priechode pre cyklistov.');
INSERT INTO `Questions` VALUES (1598,1598,0,1,'Vodič, ktorý sa chce vzdialiť od vozidla tak, že v nebude môcť okamžite zasiahnuť, je povinný','',2,1,'urobiť také opatrenia, aby vozidlo nemohlo ohroziť bezpečnosť a plynulosť cestnej premávky a aby ho nemohla neoprávnene použiť iná osoba,','stáť vždy na stráženom parkovisku,','vyložiť z vozidla v ňom prepravované veci.');
INSERT INTO `Questions` VALUES (1599,1599,0,1,'Vodič vozidla, ktoré je povinne vybavené prenosným výstražným trojuholníkom, je povinný tento trojuholník použiť počas','',2,3,'prepravy nebezpečného nákladu,','jazdy na diaľnici rýchlosťou nižšou ako 50 km/h,','núdzového státia, najmä pri prerušení jazdy pre chybu na vozidle alebo na náklade, v dôsledku dopravnej nehody, ak také vozidlo tvorí prekážku v cestnej premávke.');
INSERT INTO `Questions` VALUES (1600,1600,0,1,'Vodič nesmie zastaviť a stáť','',2,2,'na križovatke a vo vzdialenosti kratšej ako 15 m pred hranicou križovatky a 10 m za ňou,','na križovatke a vo vzdialenosti kratšej ako 5 m pred hranicou križovatky a 5 m za ňou,','v obci na križovatke tvaru „T“ na náprotivnej strane vyúsťujúcej cesty.');
INSERT INTO `Questions` VALUES (1601,1601,0,1,'Ak osoba pribratá na zaistenie bezpečnej prevádzky železničného priecestia dáva pokyn na jazdu cez železničné priecestie vodorovným kývaním ruky s červenou alebo so žltou zástavkou a za zníženej viditeľnosti bielym svetlom cez stred tela, vodič','',2,3,'nie je povinný ju poslúchnuť,','je povinný pred vojdením na železničné priecestie vždy zastaviť pri tejto osobe,','je povinný ju poslúchnuť.');
INSERT INTO `Questions` VALUES (1602,1602,0,1,'Ak na stojacom vozidle svieti zvláštne výstražné svetlo modrej alebo červenej farby, prípadne ich kombinácia musí vodič iného vozidla','',2,1,'zvýšiť opatrnosť, znížiť rýchlosť jazdy, prípadne zastaviť vozidlo,','zvýšiť rýchlosť jazdy,','bezodkladne zastaviť vozidlo.');
INSERT INTO `Questions` VALUES (1603,1603,0,1,'Ak sa na vozovke nachádza súvislá snehová vrstva, ľad alebo námraza a v období od novembra do marca môže vodič motorového vozidla kategórie M2, M3, N2 a N3 použiť takéto vozidlo v cestnej premávke, len ak','',2,3,'je držiteľom medzinárodnej poisťovacej karty,','je toto vybavené na všetkých nápravách zimnými pneumatikami,','je toto vybavené aspoň na jednej z hnacích náprav zimnými pneumatikami.');
INSERT INTO `Questions` VALUES (1604,1604,0,1,'Vodič','',2,1,'nesmie pripustiť, aby sa prekročil povolený počet prepravovaných osôb,','môže pripustiť, aby sa prekročil povolený počet prepravovaných osôb, ak s tým vopred vyslovili súhlas všetky prepravované osoby,','môže pripustiť, aby sa prekročil povolený počet prepravovaných osôb, najviac však o 20 %.');
INSERT INTO `Questions` VALUES (1605,1605,0,1,'Použiť osobitné zariadenie umožňujúce výstražnú funkciu smerových svietidiel je povinný vodič','',2,1,'autobusu prepravujúceho deti alebo osoby so zdravotným postihnutím počas ich nastupovania a vystupovania','každého vozidla prepravujúceho deti alebo zdravotne postihnuté osoby počas ich vystupovania,','vozidla prepravujúceho nebezpečný náklad.');
INSERT INTO `Questions` VALUES (1606,1606,0,1,'Vodič je povinný mať','',1,3,'pri sebe vyplnené Záznamové listy alebo výtlačky zo záznamového zariadenia za prebiehajúci deň a za predchádzajúcich 7 dni a potvrdenie podľa osobitného predpisy, že bol práceneschopný, čerpal dovolenku alebo že za predchádzajúcich 7 dni viedol iné vozidl','pri sebe vyplnené záznamové listy alebo výtlačky zo záznamového zariadenia za prebiehajúci deň a za predchádzajúcich 15 dní a potvrdenie podľa osobitného predpisy, že bol práceneschopný, čerpal dovolenku alebo že za predchádzajúcich 15 dní viedol iné vozi','pri sebe vyplnené záznamové listy alebo výtlačky zo záznamového zariadenia za prebiehajúci deň a za predchádzajúcich 28 dní a potvrdenie podľa osobitného predpisy, že bol práceneschopný, čerpal dovolenku alebo že za predchádzajúcich 28 dni viedol iné vozi');
INSERT INTO `Questions` VALUES (1607,1607,0,1,'Plášť pneumatiky nesmie mať na svojom vonkajšom obvode (oblasť koruny, boku a pätky plášťa)','',1,2,'trhliny ani poškodenia, ktoré narúšajú kordovú kostru; jej obnaženie však nie je závadou,','trhliny ani poškodenia, ktoré obnažujú kordovú kostru alebo ju narúšajú,','trhliny, ktoré obnažujú kordovú kostru; jej poškodenie však nie je závadou.');
INSERT INTO `Questions` VALUES (1608,1608,0,1,'Vozidlo sa považuje za technicky nespôsobilé na premávku na pozemných komunikáciách, ak','',1,1,'niektorá časť systému, komponentu alebo samotnej technickej jednotky vozidla je chybná, poškodená alebo upravená, pripadne chýba úplne,','nie sú aspoň kolesá prednej nápravy vybavené účinnými krytmi (blatníkmi, podbehmi),','sú poškodené Iapače nečistôt.');
INSERT INTO `Questions` VALUES (1609,1609,1,1,'Táto dopravná značka s dodatkovou tabuľkou znamená:','spec5',2,2,'Klzká vozovka v úseku 2 km,','Zákruty v úseku 2 km, prvá vpravo,','Spôsob obchádzania prekážok na mieste vzdialenom 2 km.');
INSERT INTO `Questions` VALUES (1610,1610,1,1,'Táto dopravná značka znamená:','b1',2,3,'Slepá cesta,','Zákaz vjazdu motorových vozidiel,','Zákaz vjazdu všetkých vozidiel (v oboch smeroch).');
INSERT INTO `Questions` VALUES (1611,1611,1,1,'Táto dopravná značka','c1',2,3,'označuje jednosmernú premávku,','prikazuje obchádzať prekážku v smere, ktorým šípka ukazuje,','prikazuje jazdu smerom, ktorým šípka ukazuje.');
INSERT INTO `Questions` VALUES (1612,1612,1,1,'Táto dopravná značka znamená:','ip3a',2,3,'Okruh,','Smerová tabuľa na označenie obchádzky,','Jednosmerná premávka.');
INSERT INTO `Questions` VALUES (1613,1613,1,1,'Táto dopravná značka znamená:','ip10',2,1,'Odporúčaná rýchlosť; vyjadruje číslom alebo číslami uvedenými na značke odporúčanú rýchlosť v kilometroch za hodinu za normálnych podmienok,','Obmedzenie najvyššej dovolenej rýchlosti; vyjadruje číslom na značke najvyššiu dovolenú rýchlosť na mokrej vozovke,','Cesta 1. triedy; informuje o čísle cesty 1. triedy.');
INSERT INTO `Questions` VALUES (1614,1614,1,1,'Táto dopravná značka znamená:','ip9',2,1,'Podchod alebo nadchod,','Priechod pre chodcov,','Metro.');
INSERT INTO `Questions` VALUES (1615,1615,1,1,'Táto dopravná značka vyznačuje','ip24a',2,2,'oblasť, v ktorej platia ustanovenia o premávke v obytnej zóne,','oblasť (časť obce a podobne), kde platí zákaz státia,','vyznačuje územie, v ktorom platia ustanovenia o premávke v pešej zóne.');
INSERT INTO `Questions` VALUES (1616,1616,1,1,'Táto dopravná značka vyznačuje','v4',2,1,'okraj vozovky,','hranicu križovatky,','únikovú cestíčku.');
INSERT INTO `Questions` VALUES (1617,1617,2,1,'Vozidlá prejdú cez križovatku v tomto poradí:','537',3,1,'1. žlté, 2. červené, 3. zelené,','1. červené, 2. žlté, 3. zelené,','1. zelené, 2. červené, 3. žlté.');
INSERT INTO `Questions` VALUES (1618,1618,2,1,'Ak má policajt pravú ruku predpaženú a ľavú upaženú, znamená to „Stoj!“ pre','808',3,3,'vodiča zeleného vozidla,','chodcov prechádzajúcich za chrbtom policajta,','vodiča červeného a vodiča žltého vozidla.');
INSERT INTO `Questions` VALUES (1619,1619,2,1,'Ako prvé prejde cez križovatku','944',3,1,'vaše vozidlo,','modré vozidlo,','červené vozidlo.');
INSERT INTO `Questions` VALUES (1620,1620,2,1,'Vaše vozidlo prejde cez križovatku ako','405',3,1,'posledné,','druhé,','prvé.');
